function hardCodedDrawingDefaults() {
  return {
    pipeSizeNb: 25,
    pipeSpec: "carbon40",
    stepLength: 1000,
    angleDegrees: 45,
    anglePlane: "xy",
    flangeMode: "single",
    reducerType: "concentric",
    previewMode: "tricolor",
    show3dLabels: true,
    gridScale: 42,
    drawingDetail: "callouts",
    showDimensions: true,
    dimensionStyle: "numbered",
    pipeLabelMode: "auto",
    showLiftingPoints: false,
    liftingSlingAngleDegrees: 60,
  };
}

function normalizeDrawingDefaults(defaults = {}) {
  const base = hardCodedDrawingDefaults();
  const pipeSpecKey = normalizePipeSpec(defaults.pipeSpec ?? base.pipeSpec);
  const requestedPipeSize = normalizePipeSize(defaults.pipeSizeNb ?? base.pipeSizeNb);
  return {
    pipeSizeNb: pipeSizeMatchesSpec(PIPE_SIZES.find((size) => size.nb === requestedPipeSize), pipeSpecKey)
      ? requestedPipeSize
      : closestPipeSizeNbForSpec(requestedPipeSize, pipeSpecKey),
    pipeSpec: pipeSpecKey,
    stepLength: normalizeLength(defaults.stepLength ?? base.stepLength),
    angleDegrees: normalizeAngle(defaults.angleDegrees ?? base.angleDegrees),
    anglePlane: normalizeAnglePlane(defaults.anglePlane ?? base.anglePlane),
    flangeMode: normalizeFlangeMode(defaults.flangeMode ?? base.flangeMode),
    flangeStandard: normalizeFlangeStandard(defaults.flangeStandard ?? base.flangeStandard),
    reducerType: normalizeReducerType(defaults.reducerType ?? base.reducerType),
    previewMode: normalizePreviewMode(defaults.previewMode ?? base.previewMode),
    show3dLabels: defaults.show3dLabels !== false,
    gridScale: clampNumber(Number(defaults.gridScale) || base.gridScale, 24, 72),
    drawingDetail: normalizeDrawingDetail(defaults.drawingDetail ?? base.drawingDetail),
    showDimensions: defaults.showDimensions !== false,
    dimensionStyle: normalizeDimensionStyle(defaults.dimensionStyle ?? base.dimensionStyle),
    pipeLabelMode: normalizePipeLabelMode(defaults.pipeLabelMode ?? base.pipeLabelMode),
    showLiftingPoints: defaults.showLiftingPoints === true,
    liftingSlingAngleDegrees: normalizeLiftingSlingAngle(defaults.liftingSlingAngleDegrees ?? base.liftingSlingAngleDegrees),
  };
}

function numberedDimensionDefaultApplied() {
  try {
    return localStorage.getItem(NUMBERED_DIMENSION_DEFAULT_KEY) === "true";
  } catch {
    return true;
  }
}

function markNumberedDimensionDefaultApplied() {
  try {
    localStorage.setItem(NUMBERED_DIMENSION_DEFAULT_KEY, "true");
  } catch {
    // Defaults still work without localStorage; the marker only prevents repeat migration.
  }
}

function triColor3dDefaultApplied() {
  try {
    return localStorage.getItem(TRICOLOR_3D_DEFAULT_KEY) === "true";
  } catch {
    return true;
  }
}

function markTriColor3dDefaultApplied() {
  try {
    localStorage.setItem(TRICOLOR_3D_DEFAULT_KEY, "true");
  } catch {
    // The tri-colour style still works without localStorage.
  }
}

function shouldUseTriColor3dDefault(source) {
  const mode = String(source?.previewMode ?? "").trim();
  return !mode || ["illustrated", "carbon", "workshop", "black", "stainless", "red", "cad"].includes(mode);
}

function applyTriColor3dDefault(target) {
  if (target && typeof target === "object") target.previewMode = "tricolor";
  return target;
}

function migrateTriColor3dDrawingDefaults() {
  try {
    const rawDefaults = JSON.parse(localStorage.getItem(USER_DRAWING_DEFAULTS_KEY)) ?? {};
    if (shouldUseTriColor3dDefault(rawDefaults)) {
      localStorage.setItem(
        USER_DRAWING_DEFAULTS_KEY,
        JSON.stringify({ ...rawDefaults, previewMode: "tricolor" }),
      );
    }
  } catch {
    // A missing drawing-defaults record does not prevent the current drawing migration.
  }
}

function shouldUseNumberedDimensionDefault(rawDefaults) {
  if (!rawDefaults || typeof rawDefaults !== "object") return true;
  return rawDefaults.dimensionStyle === undefined || normalizeDimensionStyle(rawDefaults.dimensionStyle) === "labels";
}

function applyNumberedDimensionDefault(target) {
  if (!target || typeof target !== "object") return target;
  target.drawingDetail = "callouts";
  target.showDimensions = true;
  target.dimensionStyle = "numbered";
  target.pipeLabelMode = "auto";
  return target;
}

function readUserDrawingDefaults() {
  try {
    const rawDefaults = JSON.parse(localStorage.getItem(USER_DRAWING_DEFAULTS_KEY)) ?? {};
    const defaults = normalizeDrawingDefaults(rawDefaults);
    const triColorAlreadyApplied = triColor3dDefaultApplied();
    if (!triColorAlreadyApplied && shouldUseTriColor3dDefault(rawDefaults)) {
      applyTriColor3dDefault(defaults);
      migrateTriColor3dDrawingDefaults();
      markTriColor3dDefaultApplied();
    } else if (!triColorAlreadyApplied) {
      markTriColor3dDefaultApplied();
    }
    const alreadyApplied = numberedDimensionDefaultApplied();
    if (!alreadyApplied && shouldUseNumberedDimensionDefault(rawDefaults)) {
      markNumberedDimensionDefaultApplied();
      return normalizeDrawingDefaults(applyNumberedDimensionDefault({ ...defaults }));
    }
    if (!alreadyApplied) markNumberedDimensionDefaultApplied();
    return defaults;
  } catch {
    markTriColor3dDefaultApplied();
    markNumberedDimensionDefaultApplied();
    return normalizeDrawingDefaults();
  }
}

function drawingDefaultsFromState(source = state) {
  return normalizeDrawingDefaults({
    pipeSizeNb: source?.pipeSizeNb,
    pipeSpec: source?.pipeSpec,
    stepLength: source?.stepLength,
    angleDegrees: source?.angleDegrees,
    anglePlane: source?.anglePlane,
    flangeMode: source?.flangeMode,
    flangeStandard: source?.flangeStandard,
    reducerType: source?.reducerType,
    previewMode: source?.previewMode,
    show3dLabels: source?.show3dLabels !== false,
    gridScale: source?.gridScale,
    drawingDetail: normalizeDrawingDetail(source?.drawingDetail),
    showDimensions: source?.showDimensions,
    dimensionStyle: source?.dimensionStyle,
    pipeLabelMode: source?.pipeLabelMode,
    showLiftingPoints: source?.showLiftingPoints,
    liftingSlingAngleDegrees: source?.liftingSlingAngleDegrees,
  });
}

function persistUserDrawingDefaults(source = state) {
  try {
    localStorage.setItem(USER_DRAWING_DEFAULTS_KEY, JSON.stringify(drawingDefaultsFromState(source)));
  } catch (error) {
    console.warn("Could not save user drawing defaults.", error);
  }
}

function blankState(options = {}) {
  const defaults = options.userDefaults === false ? hardCodedDrawingDefaults() : readUserDrawingDefaults();
  return {
    points: [{ x: 0, y: 0, z: 0 }],
    edges: [],
    fittings: [],
    activeTool: "draw",
    selectedSegment: null,
    selectedSegments: [],
    selectedFitting: null,
    selectedNote: null,
    selectedMeasurement: null,
    selectedPoint: 0,
    activePoint: 0,
    notes: [],
    measurements: [],
    nodeTypes: {},
    reducerSideOverrides: {},
    reducerTypeOverrides: {},
    dimensionOffsets: {},
    hoveredSegment: null,
    pointer: null,
    previewCandidate: null,
    pipeSizeNb: defaults.pipeSizeNb,
    pipeSpec: defaults.pipeSpec,
    stepLength: defaults.stepLength,
    angleDegrees: defaults.angleDegrees,
    anglePlane: defaults.anglePlane,
    flangeMode: defaults.flangeMode,
    flangeStandard: defaults.flangeStandard,
    reducerType: defaults.reducerType,
    previewMode: defaults.previewMode,
    show3dLabels: defaults.show3dLabels,
    gridScale: defaults.gridScale,
    drawingDetail: defaults.drawingDetail,
    showDimensions: defaults.showDimensions,
    dimensionStyle: defaults.dimensionStyle,
    pipeLabelMode: defaults.pipeLabelMode,
    showLiftingPoints: defaults.showLiftingPoints,
    liftingSlingAngleDegrees: defaults.liftingSlingAngleDegrees,
    projectId: null,
    workflowKind: "managed",
    projectInfoPrompted: false,
    projectStatus: "draft",
    checkedBy: "",
    checkedAt: "",
    issuedBy: "",
    issuedAt: "",
    locked: false,
    revisionHistory: [],
    spoolUid: createTraceabilityId("SPL"),
    bigSpool: defaultBigSpoolPlan(),
    weldRegister: [],
    productionInfo: defaultProductionInfo(),
    productionMessages: [],
    productionActivity: [],
    healthAcknowledgements: {},
    issueAudits: [],
    projectInfo: defaultProjectInfo(defaults.pipeSpec),
    history: [],
    redoHistory: [],
  };
}

function loadState() {
  for (const key of [STORAGE_KEY, ...LEGACY_STORAGE_KEYS]) {
    try {
      const saved = JSON.parse(localStorage.getItem(key));
      const legacyUnits = key === "isospool-studio-state-v2" || key === "isospool-studio-state-v1";
      const applyNewDefaults = key !== STORAGE_KEY;
      const restored = stateFromPayload(saved, { legacyUnits, applyNewDefaults });
      if (!restored) continue;

      if (saved?.points?.length) {
        try {
          localStorage.setItem(LAST_SESSION_RECOVERY_KEY, JSON.stringify({
            createdAt: new Date().toISOString(),
            sourceKey: key,
            state: saved,
          }));
        } catch {
          // The current drawing still loads if recovery storage is unavailable.
        }
      }

      const alreadyApplied = numberedDimensionDefaultApplied();
      if (!alreadyApplied && shouldUseNumberedDimensionDefault(saved)) {
        applyNumberedDimensionDefault(restored);
        markNumberedDimensionDefaultApplied();
      } else if (!alreadyApplied) {
        markNumberedDimensionDefaultApplied();
      }
      const triColorAlreadyApplied = triColor3dDefaultApplied();
      if (!triColorAlreadyApplied && shouldUseTriColor3dDefault(saved)) {
        applyTriColor3dDefault(restored);
        migrateTriColor3dDrawingDefaults();
        markTriColor3dDefaultApplied();
      } else if (!triColorAlreadyApplied) {
        markTriColor3dDefaultApplied();
      }
      setNextIdsFromState(restored);
      return restored;
    } catch {
      continue;
    }
  }

  return null;
}

function statePayload(options = {}) {
  synchronizeWeldRegister(state);
  return {
    appVersion: APP_VERSION,
    points: state.points,
    edges: state.edges,
    fittings: state.fittings.map((fitting) => ({
      ...fitting,
      t: normalizeFittingPosition(fitting.type, fitting.t),
    })),
    notes: state.notes,
    measurements: normalizeMeasurements(state.measurements),
    nodeTypes: normalizeNodeTypes(state.nodeTypes, state.points.length),
    reducerSideOverrides: normalizeReducerSideOverrides(state.reducerSideOverrides, state.points.length),
    reducerTypeOverrides: normalizeReducerTypeOverrides(state.reducerTypeOverrides, state.points.length),
    dimensionOffsets: normalizeDimensionOffsets(state.dimensionOffsets, state.edges.length),
    activePoint: state.activePoint,
    selectedPoint: state.selectedPoint,
    selectedSegments: selectedSegmentIndexes(),
    selectedMeasurement: state.selectedMeasurement,
    pipeSizeNb: state.pipeSizeNb,
    pipeSpec: normalizePipeSpec(state.pipeSpec),
    stepLength: state.stepLength,
    angleDegrees: state.angleDegrees,
    anglePlane: state.anglePlane,
    flangeMode: state.flangeMode,
    flangeStandard: normalizeFlangeStandard(state.flangeStandard),
    reducerType: normalizeReducerType(state.reducerType),
    previewMode: state.previewMode,
    show3dLabels: state.show3dLabels !== false,
    gridScale: state.gridScale,
    drawingDetail: normalizeDrawingDetail(state.drawingDetail),
    showDimensions: state.showDimensions,
    dimensionStyle: normalizeDimensionStyle(state.dimensionStyle),
    pipeLabelMode: normalizePipeLabelMode(state.pipeLabelMode),
    showLiftingPoints: state.showLiftingPoints,
    liftingSlingAngleDegrees: normalizeLiftingSlingAngle(state.liftingSlingAngleDegrees),
    projectId: state.projectId,
    workflowKind: normalizeWorkflowKind(state.workflowKind),
    projectInfoPrompted: state.projectInfoPrompted === true,
    projectStatus: normalizeProjectStatus(state.projectStatus),
    checkedBy: String(state.checkedBy ?? "").trim().slice(0, 64),
    checkedAt: String(state.checkedAt ?? "").trim(),
    issuedBy: String(state.issuedBy ?? "").trim().slice(0, 64),
    issuedAt: String(state.issuedAt ?? "").trim(),
    locked: state.locked === true,
    revisionHistory: options.includeRevisionHistory === false ? [] : normalizeRevisionHistory(state.revisionHistory),
    spoolUid: normalizeTraceabilityId(state.spoolUid) || createTraceabilityId("SPL"),
    bigSpool: normalizeBigSpoolPlan(state.bigSpool, state.edges),
    weldRegister: normalizeWeldRegister(state.weldRegister, state.fittings),
    productionInfo: normalizeProductionInfo(state.productionInfo),
    productionMessages: normalizeProductionMessages(state.productionMessages),
    productionActivity: normalizeProductionActivity(state.productionActivity),
    healthAcknowledgements: normalizeHealthAcknowledgements(state.healthAcknowledgements),
    issueAudits: normalizeIssueAudits(state.issueAudits),
    projectInfo: normalizeProjectInfo(state.projectInfo, state.pipeSpec),
  };
}

function persistState() {
  persistUserDrawingDefaults();
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(statePayload()));
    autoSaveCurrentBrowserProject();
    maybeCreateProjectBackup();
  } catch (error) {
    console.warn("Could not save spool state in this browser.", error);
  }
  markCloudSaveDirty();
  queueCloudAutosave();
  captureCurrentSpoolWorkspaceTab();
}

function stateFromPayload(payload, options = {}) {
  const saved = payload?.state && typeof payload.state === "object" ? payload.state : payload;
  if (!saved || !Array.isArray(saved.points) || saved.points.length === 0) return null;

  const legacyUnits = options.legacyUnits === true;
  const applyNewDefaults = options.applyNewDefaults === true;
  const points = saved.points.map((point) => {
    const cloned = clonePoint(point);
    return legacyUnits
      ? {
          x: Math.round(cloned.x * MM_PER_GRID),
          y: Math.round(cloned.y * MM_PER_GRID),
          z: Math.round(cloned.z * MM_PER_GRID),
        }
      : cloned;
  });
  const edges = normalizeEdges(saved.edges, points.length);
  const selectedSegments = normalizeSelectedSegments(saved.selectedSegments, edges.length);
  const savedShowDimensions = saved.showDimensions !== false;
  const savedDimensionStyle = normalizeDimensionStyle(saved.dimensionStyle);
  const savedDrawingDetail = saved.drawingDetail
    ? normalizeDrawingDetail(saved.drawingDetail)
    : drawingDetailFromDimensionSettings(savedShowDimensions, savedDimensionStyle);

  return {
    ...blankState({ userDefaults: false }),
    points,
    edges,
    fittings: normalizeFittings(saved.fittings, edges.length),
    notes: normalizeNotes(saved.notes),
    measurements: normalizeMeasurements(saved.measurements),
    nodeTypes: normalizeNodeTypes(saved.nodeTypes, points.length),
    reducerSideOverrides: normalizeReducerSideOverrides(saved.reducerSideOverrides, points.length),
    reducerTypeOverrides: normalizeReducerTypeOverrides(saved.reducerTypeOverrides, points.length),
    dimensionOffsets: normalizeDimensionOffsets(saved.dimensionOffsets, edges.length),
    pipeSizeNb: defaultPipeSizeFromSaved(saved, edges, selectedSegments),
    pipeSpec: normalizePipeSpec(saved.pipeSpec),
    stepLength: normalizeLength(legacyUnits ? Number(saved.stepLength) * MM_PER_GRID : saved.stepLength),
    angleDegrees: normalizeAngle(saved.angleDegrees),
    anglePlane: normalizeAnglePlane(saved.anglePlane),
    flangeMode: applyNewDefaults ? "single" : normalizeFlangeMode(saved.flangeMode),
    flangeStandard: applyNewDefaults ? "ansi150" : normalizeFlangeStandard(saved.flangeStandard),
    reducerType: normalizeReducerType(saved.reducerType),
    previewMode: normalizePreviewMode(saved.previewMode),
    show3dLabels: saved.show3dLabels !== false,
    selectedSegments,
    activePoint: Number.isInteger(saved.activePoint) && saved.activePoint >= 0 && saved.activePoint < points.length ? saved.activePoint : points.length - 1,
    selectedPoint: Number.isInteger(saved.selectedPoint) && saved.selectedPoint >= 0 && saved.selectedPoint < points.length ? saved.selectedPoint : null,
    selectedMeasurement: Number.isInteger(saved.selectedMeasurement) ? saved.selectedMeasurement : null,
    gridScale: Number(saved.gridScale) || 42,
    drawingDetail: savedDrawingDetail,
    showDimensions: savedShowDimensions,
    dimensionStyle: savedDimensionStyle,
    pipeLabelMode: normalizePipeLabelMode(saved.pipeLabelMode),
    showLiftingPoints: applyNewDefaults ? false : saved.showLiftingPoints === true,
    liftingSlingAngleDegrees: normalizeLiftingSlingAngle(saved.liftingSlingAngleDegrees),
    projectId: normalizeProjectId(saved.projectId),
    workflowKind: normalizeWorkflowKind(saved.workflowKind),
    projectInfoPrompted: saved.projectInfoPrompted === true || hasProjectInfo(saved.projectInfo),
    projectStatus: normalizeProjectStatus(saved.projectStatus),
    checkedBy: String(saved.checkedBy ?? "").trim().slice(0, 64),
    checkedAt: String(saved.checkedAt ?? "").trim(),
    issuedBy: String(saved.issuedBy ?? "").trim().slice(0, 64),
    issuedAt: String(saved.issuedAt ?? "").trim(),
    locked: saved.locked === true,
    revisionHistory: normalizeRevisionHistory(saved.revisionHistory),
    spoolUid: normalizeTraceabilityId(saved.spoolUid) || createTraceabilityId("SPL"),
    bigSpool: normalizeBigSpoolPlan(saved.bigSpool, edges),
    weldRegister: normalizeWeldRegister(saved.weldRegister, normalizeFittings(saved.fittings, edges.length)),
    productionInfo: normalizeProductionInfo(saved.productionInfo),
    productionMessages: normalizeProductionMessages(saved.productionMessages),
    productionActivity: normalizeProductionActivity(saved.productionActivity),
    healthAcknowledgements: normalizeHealthAcknowledgements(saved.healthAcknowledgements),
    issueAudits: normalizeIssueAudits(saved.issueAudits),
    projectInfo: normalizeProjectInfo(saved.projectInfo, saved.pipeSpec),
    history: [],
    redoHistory: [],
  };
}

function defaultPipeSizeFromSaved(saved, edges, selectedSegments) {
  const savedNb = normalizePipeSize(saved?.pipeSizeNb);
  if (savedNb !== 25) return savedNb;

  const selectedEdge = edges[selectedSegments[selectedSegments.length - 1]];
  const selectedNb = selectedEdge ? normalizePipeSize(selectedEdge.pipeSizeNb) : 25;
  if (selectedNb !== 25) return selectedNb;

  const edgeSizes = [...new Set(edges.map((edge) => normalizePipeSize(edge.pipeSizeNb)))];
  if (edgeSizes.length === 1 && edgeSizes[0] !== 25) return edgeSizes[0];

  return savedNb;
}

function setNextIdsFromState(sourceState) {
  nextFittingId =
    Math.max(0, ...sourceState.fittings.map((fitting) => Number(fitting.id) || 0)) + 1;
  nextNoteId =
    Math.max(0, ...sourceState.notes.map((note) => Number(note.id) || 0)) + 1;
  nextMeasurementId =
    Math.max(0, ...(sourceState.measurements ?? []).map((measurement) => Number(measurement.id) || 0)) + 1;
}

function normalizeNodeTypes(nodeTypes, pointCount) {
  if (!nodeTypes || typeof nodeTypes !== "object") return {};

  const normalized = {};
  for (const [key, type] of Object.entries(nodeTypes)) {
    const index = Number(key);
    if (
      Number.isInteger(index) &&
      index >= 0 &&
      index < pointCount &&
      NODE_CONNECTION_TYPES.has(type)
    ) {
      normalized[index] = type;
    }
  }
  return normalized;
}

function normalizeHealthAcknowledgements(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const normalized = {};
  for (const [rawKey, rawEntry] of Object.entries(value).slice(-80)) {
    const key = String(rawKey ?? "").trim().slice(0, 180);
    if (!key || !rawEntry || typeof rawEntry !== "object") continue;
    const reason = String(rawEntry.reason ?? "").trim().slice(0, 500);
    if (!reason) continue;
    normalized[key] = {
      title: String(rawEntry.title ?? "Drawing check").trim().slice(0, 120),
      reason,
      by: String(rawEntry.by ?? "").trim().slice(0, 80),
      at: String(rawEntry.at ?? "").trim().slice(0, 40),
    };
  }
  return normalized;
}

function normalizeIssueAuditFinding(value) {
  if (!value || typeof value !== "object") return null;
  const title = String(value.title ?? "").trim().slice(0, 140);
  if (!title) return null;
  const severity = value.severity === "blocker" ? "blocker" : "warning";
  return {
    severity,
    category: String(value.category ?? "Drawing").trim().slice(0, 48),
    title,
    detail: String(value.detail ?? "").trim().slice(0, 300),
  };
}

function normalizeIssueAudit(value) {
  if (!value || typeof value !== "object") return null;
  const revision = String(value.revision ?? "").trim().slice(0, 16);
  const createdAt = String(value.createdAt ?? "").trim().slice(0, 40);
  if (!revision && !createdAt) return null;
  const findings = (Array.isArray(value.findings) ? value.findings : [])
    .map(normalizeIssueAuditFinding)
    .filter(Boolean)
    .slice(0, 40);
  const result = value.result === "overridden" ? "overridden" : "ready";
  return {
    id: String(value.id ?? "").trim().slice(0, 80) || `audit-${Date.now().toString(36)}`,
    revision,
    revisionUid: normalizeTraceabilityId(value.revisionUid),
    createdAt,
    result,
    issuedBy: String(value.issuedBy ?? "").trim().slice(0, 80),
    checkedBy: String(value.checkedBy ?? "").trim().slice(0, 80),
    checkedAt: String(value.checkedAt ?? "").trim().slice(0, 40),
    overrideReason: String(value.overrideReason ?? "").trim().slice(0, 700),
    findings,
  };
}

function normalizeIssueAudits(value) {
  if (!Array.isArray(value)) return [];
  return value.map(normalizeIssueAudit).filter(Boolean).slice(0, 24);
}

function normalizeReducerSideOverrides(overrides, pointCount) {
  if (!overrides || typeof overrides !== "object") return {};

  const normalized = {};
  for (const [key, value] of Object.entries(overrides)) {
    const index = Number(key);
    if (
      Number.isInteger(index) &&
      index >= 0 &&
      index < pointCount &&
      REDUCER_SIDE_OPTIONS.has(value)
    ) {
      normalized[index] = value;
    }
  }
  return normalized;
}

function normalizeReducerType(value) {
  return REDUCER_TYPE_OPTIONS.has(value) ? value : "concentric";
}

function reducerTypeLabel(value) {
  return normalizeReducerType(value) === "eccentric" ? "Eccentric" : "Concentric";
}

function reducerTypeCode(value) {
  return normalizeReducerType(value) === "eccentric" ? "ECC" : "CONC";
}

function normalizeReducerTypeOverrides(overrides, pointCount) {
  if (!overrides || typeof overrides !== "object") return {};

  const normalized = {};
  for (const [key, value] of Object.entries(overrides)) {
    const index = Number(key);
    if (
      Number.isInteger(index) &&
      index >= 0 &&
      index < pointCount &&
      REDUCER_TYPE_OPTIONS.has(value)
    ) {
      normalized[index] = value;
    }
  }
  return normalized;
}

function normalizeDimensionOffsets(offsets, edgeCount) {
  if (!offsets || typeof offsets !== "object") return {};

  const normalized = {};
  for (const [key, value] of Object.entries(offsets)) {
    const index = Number(key);
    if (!Number.isInteger(index) || index < 0 || index >= edgeCount) continue;

    const raw = typeof value === "object" && value !== null
      ? value
      : { offset: Number(value), side: 1 };
    const side = Number(raw.side) < 0 ? -1 : 1;
    const offset = clampNumber(Number(raw.offset) || 0, 0, 520);
    if (offset <= 0.5) continue;
    normalized[index] = { side, offset: Math.round(offset) };
  }
  return normalized;
}

function nodeConnectionType(nodeIndex) {
  return state.nodeTypes?.[nodeIndex] === "branch" ? "branch" : "tee";
}

function setNodeConnectionType(nodeIndex, type, options = {}) {
  if (!Number.isInteger(nodeIndex) || nodeIndex < 0 || nodeIndex >= state.points.length) return;
  if (!NODE_CONNECTION_TYPES.has(type)) return;

  state.nodeTypes = normalizeNodeTypes(state.nodeTypes, state.points.length);
  state.nodeTypes[nodeIndex] = type;
  if (options.update !== false) updateAll();
}

function reindexNodeTypesAfterPointRemoval(removedIndex) {
  if (!state.nodeTypes || typeof state.nodeTypes !== "object") return;

  const next = {};
  for (const [key, type] of Object.entries(state.nodeTypes)) {
    const index = Number(key);
    if (!Number.isInteger(index) || index === removedIndex || !NODE_CONNECTION_TYPES.has(type)) continue;
    next[index > removedIndex ? index - 1 : index] = type;
  }
  state.nodeTypes = next;
}

function reindexReducerSideOverridesAfterPointRemoval(removedIndex) {
  if (!state.reducerSideOverrides || typeof state.reducerSideOverrides !== "object") return;

  const next = {};
  for (const [key, value] of Object.entries(state.reducerSideOverrides)) {
    const index = Number(key);
    if (!Number.isInteger(index) || index === removedIndex || !REDUCER_SIDE_OPTIONS.has(value)) continue;
    next[index > removedIndex ? index - 1 : index] = value;
  }
  state.reducerSideOverrides = next;
}

function reindexReducerTypeOverridesAfterPointRemoval(removedIndex) {
  if (!state.reducerTypeOverrides || typeof state.reducerTypeOverrides !== "object") return;

  const next = {};
  for (const [key, value] of Object.entries(state.reducerTypeOverrides)) {
    const index = Number(key);
    if (!Number.isInteger(index) || index === removedIndex || !REDUCER_TYPE_OPTIONS.has(value)) continue;
    next[index > removedIndex ? index - 1 : index] = value;
  }
  state.reducerTypeOverrides = next;
}

function reindexDimensionOffsetsAfterSegmentSplit(splitIndex) {
  state.dimensionOffsets = normalizeDimensionOffsets(state.dimensionOffsets, state.edges.length);
  const next = {};
  for (const [key, value] of Object.entries(state.dimensionOffsets)) {
    const index = Number(key);
    if (!Number.isInteger(index)) continue;
    if (index < splitIndex) {
      next[index] = value;
    } else if (index === splitIndex) {
      next[index] = value;
      next[index + 1] = { ...value };
    } else {
      next[index + 1] = value;
    }
  }
  state.dimensionOffsets = normalizeDimensionOffsets(next, state.edges.length);
}

function reindexDimensionOffsetsAfterSegmentRemoval(removedIndex) {
  if (!state.dimensionOffsets || typeof state.dimensionOffsets !== "object") return;

  const next = {};
  for (const [key, value] of Object.entries(state.dimensionOffsets)) {
    const index = Number(key);
    if (!Number.isInteger(index) || index === removedIndex) continue;
    next[index > removedIndex ? index - 1 : index] = value;
  }
  state.dimensionOffsets = normalizeDimensionOffsets(next, state.edges.length);
}

function reindexBigSpoolCutsAfterSegmentSplit(splitIndex, splitDistanceMm) {
  const plan = currentBigSpoolPlan();
  plan.cuts = plan.cuts.map((cut) => {
    if (cut.segmentIndex < splitIndex) return cut;
    if (cut.segmentIndex > splitIndex) return { ...cut, segmentIndex: cut.segmentIndex + 1 };
    if (cut.distanceFromStartMm < splitDistanceMm) return cut;
    return {
      ...cut,
      segmentIndex: splitIndex + 1,
      distanceFromStartMm: Math.max(1, Math.round(cut.distanceFromStartMm - splitDistanceMm)),
    };
  });
}

function reindexBigSpoolCutsAfterSegmentRemoval(removedIndex) {
  const plan = currentBigSpoolPlan();
  plan.cuts = plan.cuts
    .filter((cut) => cut.segmentIndex !== removedIndex)
    .map((cut) => cut.segmentIndex > removedIndex ? { ...cut, segmentIndex: cut.segmentIndex - 1 } : cut);
}

function normalizeEdges(edges, pointCount) {
  if (Array.isArray(edges) && edges.length) {
    return edges
      .map((edge) => ({
        from: Number(edge.from),
        to: Number(edge.to),
        pipeSizeNb: normalizePipeSize(edge.pipeSizeNb ?? 25),
        ...normalizeOffsetEdgeMeta(edge),
      }))
      .filter((edge) =>
        Number.isInteger(edge.from) &&
        Number.isInteger(edge.to) &&
        edge.from >= 0 &&
        edge.to >= 0 &&
        edge.from < pointCount &&
        edge.to < pointCount &&
        edge.from !== edge.to,
      );
  }

  const linearEdges = [];
  for (let i = 0; i < pointCount - 1; i += 1) {
    linearEdges.push({ from: i, to: i + 1, pipeSizeNb: 25 });
  }
  return linearEdges;
}

function normalizeOffsetEdgeMeta(edge) {
  const setMm = Math.round(Number(edge?.offsetSetMm));
  const travelMm = Math.round(Number(edge?.offsetTravelMm));
  const angleDeg = normalizeAngle(edge?.offsetAngleDeg);
  const plane = normalizeAnglePlane(edge?.offsetPlane);
  if (!Number.isFinite(setMm) || setMm <= 0 || !Number.isFinite(travelMm) || travelMm <= 0) {
    return {};
  }
  return {
    offsetSetMm: setMm,
    offsetTravelMm: travelMm,
    offsetAngleDeg: angleDeg,
    offsetPlane: plane,
    offsetDirection: Number(edge?.offsetDirection) < 0 ? -1 : 1,
  };
}

function normalizeFittings(fittings, edgeCount) {
  if (!Array.isArray(fittings)) return [];
  return fittings
    .map((fitting) => {
      const type = String(fitting.type ?? "");
      const normalized = {
        id: Number(fitting.id) || nextFittingId++,
        type,
        segmentIndex: Number(fitting.segmentIndex),
        t: normalizeFittingPosition(type, fitting.t),
      };

      if (type === "flange") {
        normalized.flangeMode = normalizeFlangeMode(fitting.flangeMode);
        normalized.flangeStandard = normalizeFlangeStandard(fitting.flangeStandard);
      }
      if (type === "socket") {
        normalized.socketSizeNb = normalizePipeSize(fitting.socketSizeNb ?? SOCKET_SIZE_NB);
        normalized.socketAngle = normalizeSocketAngle(fitting.socketAngle);
      }
      if (type === "reducer") {
        normalized.reducerType = normalizeReducerType(fitting.reducerType);
      }

      const weightKg = Number(fitting.weightKg);
      if (type !== "rollGroove" && Number.isFinite(weightKg) && weightKg >= 0) {
        normalized.weightKg = Math.round(weightKg * 10) / 10;
      }

      return normalized;
    })
    .filter((fitting) =>
      FITTING_TOOLS.has(fitting.type) &&
      Number.isInteger(fitting.segmentIndex) &&
      fitting.segmentIndex >= 0 &&
      fitting.segmentIndex < edgeCount,
    );
}

function defaultFittingDataProfileForSpec(specKey = "carbon40") {
  return isTubePipeSpec(specKey) ? "as1528Supplier" : "atlasAsmeB169";
}

function normalizeFittingDataProfile(value, specKey = "carbon40") {
  const profile = String(value ?? "").trim();
  return FITTING_DATA_PROFILE_KEYS.has(profile) ? profile : defaultFittingDataProfileForSpec(specKey);
}

function fittingDataProfileInfo(source = state) {
  const project = normalizeProjectInfo(source?.projectInfo, source?.pipeSpec);
  const key = normalizeFittingDataProfile(project.fittingProfile, source?.pipeSpec);
  return {
    key,
    ...FITTING_DATA_PROFILES[key],
    reference: project.fittingProfileReference,
  };
}

function syncFittingDataProfileForSpec(previousSpec, nextSpec) {
  const project = normalizeProjectInfo(state.projectInfo, previousSpec);
  const previousDefault = defaultFittingDataProfileForSpec(previousSpec);
  if (!project.fittingProfile || project.fittingProfile === previousDefault) {
    project.fittingProfile = defaultFittingDataProfileForSpec(nextSpec);
  }
  state.projectInfo = normalizeProjectInfo(project, nextSpec);
}

function defaultProjectInfo(specKey = "carbon40") {
  return {
    ...PROJECT_INFO_DEFAULT,
    fittingProfile: defaultFittingDataProfileForSpec(specKey),
  };
}

function normalizeWeldGapMm(value) {
  const gapMm = Number(value);
  return WELD_GAP_CHOICES_MM.has(gapMm) ? gapMm : DEFAULT_WELD_GAP_MM;
}

function projectWeldGapMm(source = state) {
  return normalizeWeldGapMm(source?.projectInfo?.weldGapMm);
}

function createTraceabilityId(prefix = "ID") {
  const random = globalThis.crypto?.randomUUID?.().replace(/-/g, "").slice(0, 16)
    || `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 10)}`;
  return `${String(prefix).toUpperCase()}-${random.toUpperCase()}`;
}

function normalizeTraceabilityId(value) {
  return String(value ?? "").trim().toUpperCase().replace(/[^A-Z0-9_-]/g, "").slice(0, 48);
}

function ensureSpoolUid(source = state) {
  const existing = normalizeTraceabilityId(source?.spoolUid);
  if (existing) return existing;
  const created = createTraceabilityId("SPL");
  if (source && typeof source === "object") source.spoolUid = created;
  return created;
}

function currentRevisionUid(source = state) {
  const spoolUid = ensureSpoolUid(source);
  const revision = normalizeProjectInfo(source?.projectInfo).revision || "UNSET";
  const revisionKey = revision.toUpperCase().replace(/[^A-Z0-9_-]/g, "-").slice(0, 16) || "UNSET";
  return `${spoolUid}-REV-${revisionKey}`;
}

const WELD_STATUSES = new Set(["pending", "welded", "visual", "ndt", "accepted", "repair"]);

function normalizeWeldStatus(value) {
  const status = String(value ?? "pending").trim().toLowerCase();
  return WELD_STATUSES.has(status) ? status : "pending";
}

function normalizeWeldRegister(records, fittings = state?.fittings ?? []) {
  const existing = new Map((Array.isArray(records) ? records : []).map((record) => [Number(record?.fittingId), record]));
  return (Array.isArray(fittings) ? fittings : [])
    .filter((fitting) => fitting?.type === "weld")
    .sort((first, second) => Number(first.segmentIndex) - Number(second.segmentIndex) || Number(first.t) - Number(second.t) || Number(first.id) - Number(second.id))
    .map((fitting, index) => {
      const source = existing.get(Number(fitting.id)) ?? {};
      return {
        fittingId: Number(fitting.id),
        number: `W${String(index + 1).padStart(2, "0")}`,
        welderId: String(source.welderId ?? "").trim().slice(0, 40),
        wps: String(source.wps ?? "").trim().slice(0, 48),
        status: normalizeWeldStatus(source.status),
        inspectionType: String(source.inspectionType ?? "").trim().slice(0, 40),
        inspectedBy: String(source.inspectedBy ?? "").trim().slice(0, 64),
        completedAt: String(source.completedAt ?? "").trim().slice(0, 32),
        repairHistory: String(source.repairHistory ?? "").trim().slice(0, 400),
        notes: String(source.notes ?? "").trim().slice(0, 240),
      };
    });
}

function synchronizeWeldRegister(source = state) {
  if (!source || typeof source !== "object") return [];
  source.spoolUid = ensureSpoolUid(source);
  source.weldRegister = normalizeWeldRegister(source.weldRegister, source.fittings);
  return source.weldRegister;
}

function weldRecordForFitting(fittingId, source = state) {
  return synchronizeWeldRegister(source).find((record) => record.fittingId === Number(fittingId)) ?? null;
}

function defaultProductionInfo() {
  return {
    assignee: "",
    dueDate: "",
    dueTime: "",
    priority: "normal",
    hold: false,
    holdReason: "",
    completedAt: "",
    removeAfter: "",
    lastUpdatedBy: "",
    lastUpdatedAt: "",
    materialChecklist: defaultMaterialChecklist(),
  };
}

function defaultMaterialChecklist() {
  return {
    items: [],
    checkedBy: "",
    checkedAt: "",
    overrideBy: "",
    overrideAt: "",
    overrideReason: "",
  };
}

function normalizeMaterialCheckStatus(value) {
  const status = String(value ?? "pending").trim().toLowerCase();
  return MATERIAL_CHECK_STATUSES.has(status) ? status : "pending";
}

function normalizeMaterialChecklist(checklist) {
  const source = checklist && typeof checklist === "object" ? checklist : {};
  const seen = new Set();
  const items = (Array.isArray(source.items) ? source.items : [])
    .map((item, index) => {
      const label = String(item?.label ?? "").trim().slice(0, 120);
      if (!label) return null;
      const custom = item?.custom === true;
      const key = String(item?.key ?? (custom ? `custom:${item?.id ?? index}` : label)).trim().slice(0, 160);
      let id = String(item?.id ?? "").trim().slice(0, 120);
      if (!id) id = `gear-${key.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 80) || index}`;
      if (seen.has(id)) id = `${id}-${index}`;
      seen.add(id);
      return {
        id,
        key,
        label,
        quantity: String(item?.quantity ?? "").trim().slice(0, 48),
        detail: String(item?.detail ?? "").trim().slice(0, 160),
        status: normalizeMaterialCheckStatus(item?.status),
        note: String(item?.note ?? "").trim().slice(0, 180),
        custom,
      };
    })
    .filter(Boolean)
    .slice(0, 80);
  return {
    items,
    checkedBy: String(source.checkedBy ?? "").trim().slice(0, 120),
    checkedAt: String(source.checkedAt ?? "").trim(),
    overrideBy: String(source.overrideBy ?? "").trim().slice(0, 120),
    overrideAt: String(source.overrideAt ?? "").trim(),
    overrideReason: String(source.overrideReason ?? "").trim().slice(0, 400),
  };
}

function normalizeProjectInfo(info, specKey = "carbon40") {
  const source = info && typeof info === "object" ? info : {};
  return Object.fromEntries(
    Object.keys(PROJECT_INFO_DEFAULT).map((key) => [
      key,
      key === "fittingProfile"
        ? normalizeFittingDataProfile(source[key], specKey)
        : key === "weldGapMm"
        ? String(normalizeWeldGapMm(source[key]))
        : String(source[key] ?? "").trim().slice(
            0,
            key === "client" ? 56 : key === "fittingProfileReference" ? 80 : 32,
          ),
    ]),
  );
}

function normalizeProductionPriority(value) {
  const priority = String(value ?? "normal").trim().toLowerCase();
  return PRODUCTION_PRIORITIES.has(priority) ? priority : "normal";
}

function normalizeFabSheetTemplate(value) {
  const template = String(value ?? "workshop").trim().toLowerCase();
  return FAB_SHEET_TEMPLATE_KEYS.has(template) ? template : "workshop";
}

function loadFabSheetTemplate() {
  try {
    return normalizeFabSheetTemplate(localStorage.getItem(FAB_SHEET_TEMPLATE_KEY));
  } catch {
    return "workshop";
  }
}

function storeFabSheetTemplate(value) {
  fabSheetTemplate = normalizeFabSheetTemplate(value);
  try {
    localStorage.setItem(FAB_SHEET_TEMPLATE_KEY, fabSheetTemplate);
  } catch {
    // The current session still uses the selected template if storage is blocked.
  }
}

function productionPriorityLabel(value) {
  const priority = normalizeProductionPriority(value);
  if (priority === "low") return "Low";
  if (priority === "high") return "High";
  if (priority === "urgent") return "Urgent";
  return "Normal";
}

function normalizeProductionDueDate(value) {
  const text = String(value ?? "").trim().slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : "";
}

function normalizeProductionDueTime(value) {
  const text = String(value ?? "").trim().slice(0, 5);
  return /^\d{2}:\d{2}$/.test(text) ? text : "";
}

function formatProductionDate(value) {
  const date = normalizeProductionDueDate(value);
  if (!date) return "";
  const parsed = new Date(`${date}T00:00:00`);
  return Number.isNaN(parsed.getTime()) ? date : parsed.toLocaleDateString();
}

function formatProductionDue(production) {
  const info = normalizeProductionInfo(production);
  if (!info.dueDate) return "";
  return `${formatProductionDate(info.dueDate)}${info.dueTime ? ` ${info.dueTime}` : ""}`;
}

function isoDaysFromNow(days) {
  const date = new Date();
  date.setDate(date.getDate() + days);
  return date.toISOString();
}

function activeProductionMessages(messages) {
  const now = Date.now();
  return normalizeProductionMessages(messages).filter((message) => {
    if (!message.removeAfter) return true;
    const removeTime = new Date(message.removeAfter).getTime();
    return Number.isNaN(removeTime) || removeTime > now;
  });
}

function normalizeProductionInfo(info) {
  const source = info && typeof info === "object" ? info : {};
  return {
    assignee: String(source.assignee ?? "").trim().slice(0, 80),
    dueDate: normalizeProductionDueDate(source.dueDate),
    dueTime: normalizeProductionDueTime(source.dueTime),
    priority: normalizeProductionPriority(source.priority),
    hold: source.hold === true,
    holdReason: String(source.holdReason ?? "").trim().slice(0, 140),
    completedAt: String(source.completedAt ?? "").trim(),
    removeAfter: String(source.removeAfter ?? "").trim(),
    lastUpdatedBy: String(source.lastUpdatedBy ?? "").trim().slice(0, 80),
    lastUpdatedAt: String(source.lastUpdatedAt ?? "").trim(),
    materialChecklist: normalizeMaterialChecklist(source.materialChecklist),
  };
}

function normalizeProductionMessages(messages) {
  if (!Array.isArray(messages)) return [];
  const now = Date.now();
  return messages
    .map((message) => {
      const body = String(message?.body ?? "").trim().slice(0, 240);
      if (!body) return null;
      const removeAfter = String(message?.removeAfter ?? "").trim();
      if (removeAfter) {
        const removeTime = new Date(removeAfter).getTime();
        if (!Number.isNaN(removeTime) && removeTime < now) return null;
      }
      return {
        id: String(message?.id ?? "").trim().slice(0, 80) || `msg-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
        body,
        author: String(message?.author ?? "").trim().slice(0, 80),
        createdAt: String(message?.createdAt ?? "").trim() || new Date().toISOString(),
        completed: message?.completed === true,
        completedAt: String(message?.completedAt ?? "").trim(),
        removeAfter,
      };
    })
    .filter(Boolean)
    .slice(-40);
}

function normalizeProductionActivity(entries) {
  if (!Array.isArray(entries)) return [];
  return entries
    .map((entry) => {
      const text = String(entry?.text ?? "").trim().slice(0, 220);
      if (!text) return null;
      return {
        id: String(entry?.id ?? "").trim().slice(0, 80) || `act-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
        type: String(entry?.type ?? "update").trim().slice(0, 32) || "update",
        text,
        actor: String(entry?.actor ?? "").trim().slice(0, 80),
        createdAt: String(entry?.createdAt ?? "").trim() || new Date().toISOString(),
      };
    })
    .filter(Boolean)
    .slice(-240);
}

function productionActivityActor() {
  return checkerName() || cloudUser?.email || "Team member";
}

function addProductionActivity(activity, type, text, createdAt = new Date().toISOString()) {
  const body = String(text ?? "").trim();
  if (!body) return normalizeProductionActivity(activity);
  return normalizeProductionActivity([
    ...normalizeProductionActivity(activity),
    {
      id: `act-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
      type,
      text: body,
      actor: productionActivityActor(),
      createdAt,
    },
  ]);
}

function formatProductionActivityTime(value) {
  const date = new Date(String(value ?? ""));
  if (Number.isNaN(date.getTime())) return "";
  return date.toLocaleString();
}

function nextSpoolNumber(value) {
  const text = String(value ?? "").trim();
  const match = text.match(/(\d+)(?!.*\d)/);
  if (!match) return text;

  const current = match[1];
  const next = String(Number(current) + 1).padStart(current.length, "0");
  return `${text.slice(0, match.index)}${next}${text.slice(match.index + current.length)}`;
}

function nextProjectInfoForNewSpool(info) {
  const project = normalizeProjectInfo(info);
  return normalizeProjectInfo({
    ...project,
    spoolNumber: nextSpoolNumber(project.spoolNumber),
  });
}

function normalizeProjectId(value) {
  const text = String(value ?? "").trim();
  return text ? text.slice(0, 80) : null;
}

function normalizeUuid(value) {
  const text = String(value ?? "").trim();
  return text ? text.slice(0, 80) : null;
}

function normalizeCompany(row) {
  if (!row || typeof row !== "object") return null;
  const id = normalizeUuid(row.id);
  if (!id) return null;
  return {
    id,
    name: String(row.name ?? "SpoolMate Company").trim().slice(0, 80) || "SpoolMate Company",
    inviteCode: String(row.invite_code ?? "").trim().toUpperCase().slice(0, 16),
    createdBy: normalizeUuid(row.created_by),
    licenseStatus: String(row.license_status ?? "full").trim().toLowerCase(),
    trialStartedAt: String(row.trial_started_at ?? ""),
    trialEndsAt: String(row.trial_ends_at ?? ""),
    graceEndsAt: String(row.grace_ends_at ?? ""),
    includedSeats: Math.max(1, Math.floor(Number(row.included_seats) || BUSINESS_INCLUDED_SEATS)),
    extraSeats: Math.max(0, Math.floor(Number(row.extra_seats) || 0)),
    createdAt: String(row.created_at ?? ""),
    updatedAt: String(row.updated_at ?? ""),
  };
}

function normalizeCompanyMember(row) {
  if (!row || typeof row !== "object") return null;
  const companyId = normalizeUuid(row.company_id);
  const userId = normalizeUuid(row.user_id);
  if (!companyId || !userId) return null;
  const role = ["owner", "admin", "designer", "checker", "workshop", "viewer", "member"].includes(row.role) ? row.role : "workshop";
  const status = ["pending", "invited", "approved", "suspended", "rejected"].includes(row.status) ? row.status : "pending";
  return {
    companyId,
    userId,
    email: String(row.email ?? "").trim().slice(0, 120),
    role,
    status,
    createdAt: String(row.created_at ?? ""),
    updatedAt: String(row.updated_at ?? ""),
  };
}

function normalizeProjectComment(row) {
  if (!row || typeof row !== "object") return null;
  const id = normalizeUuid(row.id);
  const projectId = normalizeProjectId(row.project_id);
  const body = String(row.body ?? "").trim().slice(0, 1000);
  if (!id || !projectId || !body) return null;
  return {
    id,
    projectId,
    companyId: normalizeUuid(row.company_id),
    authorId: normalizeUuid(row.author_id),
    authorEmail: String(row.author_email ?? "").trim().slice(0, 120),
    body,
    mentions: Array.isArray(row.mentions)
      ? row.mentions.map((mention) => String(mention ?? "").trim().toLowerCase().slice(0, 80)).filter(Boolean).slice(0, 24)
      : [],
    photoPath: String(row.photo_path ?? "").trim().slice(0, 500),
    resolved: row.resolved === true,
    resolvedAt: String(row.resolved_at ?? ""),
    resolvedBy: normalizeUuid(row.resolved_by),
    createdAt: String(row.created_at ?? ""),
    updatedAt: String(row.updated_at ?? ""),
  };
}

