function regressionAutoCheckBigSpool(segmentData, quantities, definition) {
  const plan = currentBigSpoolPlan();
  plan.cuts = suggestedBigSpoolCuts(plan.maxTransportLengthMm, plan.clearanceMm, plan.defaultJointType);
  refineBigSpoolCutsForConstraints(plan);
  const layout = bigSpoolLayout(segmentData);
  const withinLimit = layout.pieces.every((piece) => piece.maxOverallMm <= plan.maxTransportLengthMm + 1);
  const stableIds = layout.pieces.every((piece, index) => piece.childId === `SP-BIG-${bigSpoolPieceLabel(index)}`);
  const validJoints = layout.cuts.length === layout.pieces.length - 1
    && layout.cuts.every((cut, index) => cut.jointId === `J${String(index + 1).padStart(2, "0")}`
      && cut.distanceFromStartMm >= plan.clearanceMm
      && cut.distanceFromStartMm <= cut.lengthMm - plan.clearanceMm
      && Object.hasOwn(BIG_SPOOL_JOINT_TYPES, cut.jointType)
      && Object.hasOwn(BIG_SPOOL_JOINT_STATUSES, cut.status));
  const childStates = layout.pieces.map((piece) => bigSpoolChildState(piece));
  const childStatesValid = childStates.every((child, index) =>
    child?.projectInfo?.spoolNumber === layout.pieces[index].childId
    && child.edges.length === layout.pieces[index].fragments.length);
  const engineeringValid = layout.pieces.every((piece) => piece.weightKg >= 0
    && (!piece.weightKg || piece.cogPoint)
    && piece.transportLengthMm >= piece.transportWidthMm
    && piece.transportWidthMm >= piece.transportHeightMm);
  const childWeightKg = layout.pieces.reduce((sum, piece) => sum + piece.weightKg, 0);
  const childFabWeightKg = childStates.reduce((sum, child) =>
    sum + (child ? withTemporaryState(child, () => quantitySummary().totalWeightKg) : 0), 0);
  const weightBalanced = Math.abs(childWeightKg - childFabWeightKg) <= Math.max(0.1, childFabWeightKg * 0.001);
  const passed = layout.pieces.length > 1 && withinLimit && stableIds && validJoints
    && childStatesValid && engineeringValid && weightBalanced;
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    `${layout.pieces.length} child spools and ${layout.cuts.length} field joints; ${formatMass(childWeightKg)} kg reconciled to child fab sheets; largest ${formatLength(Math.max(...layout.pieces.map((piece) => piece.maxOverallMm)))} mm against ${formatLength(plan.maxTransportLengthMm)} mm limit.`,
  );
}

function regressionCheckResult(title, sampleKey, passed, detail) {
  const sample = regressionSampleByKey(sampleKey);
  return {
    title,
    sampleKey,
    sampleTitle: sample?.title ?? "Test spool",
    passed: passed === true,
    detail: String(detail ?? "").trim(),
  };
}

function withRegressionSampleState(sampleKey, callback) {
  const sample = regressionSampleByKey(sampleKey);
  const previousState = state;
  const previousNextFittingId = nextFittingId;
  const previousNextNoteId = nextNoteId;
  const previousNextMeasurementId = nextMeasurementId;

  try {
    state = sample.build();
    normalizeEdgePipeSizesForState();
    normalizeStateFittingPositions();
    normalizeConnectionTrustState();
    setNextIdsFromState(state);
    const segmentData = segments();
    const quantities = quantitySummary(segmentData);
    return callback({ sample, segmentData, quantities });
  } finally {
    state = previousState;
    nextFittingId = previousNextFittingId;
    nextNoteId = previousNextNoteId;
    nextMeasurementId = previousNextMeasurementId;
  }
}

function runRegressionAutoCheck(definition) {
  try {
    return withRegressionSampleState(definition.sampleKey, ({ segmentData, quantities }) =>
      definition.run(segmentData, quantities, definition),
    );
  } catch (error) {
    return regressionCheckResult(
      definition.title,
      definition.sampleKey,
      false,
      error?.message || "The check could not run.",
    );
  }
}

function runRegressionAutoChecks() {
  return REGRESSION_AUTO_CHECKS.map(runRegressionAutoCheck);
}

function regressionAutoCheckTeeReducer(segmentData, quantities, definition) {
  const reducers = quantities.reducers.filter((reducer) =>
    reducer.kind === "tee" &&
    reducer.nodeIndex === 1 &&
    reducer.largeNb === 150 &&
    reducer.smallNb === 80,
  );
  const tee = quantities.tees[0];
  const lineSize = PIPE_SIZES.find((size) => size.nb === 150);
  const expectedTeeTakeoff = teeTakeoffMm(lineSize);
  const expectedTeeWeight = atlasButtweldWeight(lineSize, "tee");
  const teeTakeoffsExact = tee?.connections?.length === 3 && tee.connections.every((connection) =>
    Math.abs(Number(connection.takeoffMm) - expectedTeeTakeoff) < 0.001,
  );
  const teeWeightExact = Number.isFinite(expectedTeeWeight) &&
    Math.abs(Number(tee?.weightKg) - expectedTeeWeight) < 0.001;
  const reducer = reducers[0];
  const reducerLengthExact = Number(reducer?.lengthMm) === REDUCER_LENGTH_MM[150];
  const stainlessReducerWeightsExact =
    atlasStainless10ReducerWeightForSizes({ nb: 100 }, { nb: 40 }) === 0.68 &&
    atlasStainless10ReducerWeightForSizes({ nb: 300 }, { nb: 250 }) === 7.98;
  const takeoffRows = takeoffCountRows(quantities);
  const bomSeparatesTeeAndReducer =
    takeoffRows.some((row) => row.key === "tee:150:equal" && row.quantity === 1) &&
    takeoffRows.some((row) => row.key === "reducer:auto:concentric:150:80" && row.quantity === 1) &&
    !takeoffRows.some((row) => row.label.startsWith("Reducing tee"));
  const passed =
    reducers.length >= 1 &&
    quantities.tees.length === 1 &&
    quantities.branches.length === 0 &&
    teeTakeoffsExact &&
    teeWeightExact &&
    reducerLengthExact &&
    stainlessReducerWeightsExact &&
    bomSeparatesTeeAndReducer;
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    `${reducers.length} tee reducer; ${formatLength(expectedTeeTakeoff)} mm line-size tee take-off on all legs; ` +
      `${formatMass(expectedTeeWeight)} kg tee; ${formatLength(reducer?.lengthMm ?? 0)} mm reducer.`,
  );
}

function regressionAutoCheckLargeOutletTee(segmentData, quantities, definition) {
  const reducers = quantities.reducers
    .filter((reducer) => reducer.kind === "tee" && reducer.nodeIndex === 1)
    .sort((a, b) => a.smallNb - b.smallNb);
  const reducedSegments = reducers.map((reducer) => reducer.smallSegment.index).sort((a, b) => a - b);
  const sizePairs = reducers.map((reducer) => `${reducer.largeNb}:${reducer.smallNb}`).sort();
  const tee = quantities.tees.find((item) => item.nodeIndex === 1);
  const teeSize = PIPE_SIZES.find((size) => size.nb === 150);
  const expectedTakeoff = teeTakeoffMm(teeSize);
  const takeoffRows = takeoffCountRows(quantities);
  const passed =
    reducers.length === 2 &&
    reducedSegments.join(",") === "0,1" &&
    sizePairs.join(",") === "150:100,150:80" &&
    tee?.nb === 150 &&
    tee?.connections?.length === 3 &&
    tee.connections.every((connection) => Math.abs(Number(connection.takeoffMm) - expectedTakeoff) < 0.001) &&
    takeoffRows.some((row) => row.key === "tee:150:equal" && row.quantity === 1) &&
    takeoffRows.some((row) => row.key === "reducer:auto:concentric:150:100" && row.quantity === 1) &&
    takeoffRows.some((row) => row.key === "reducer:auto:concentric:150:80" && row.quantity === 1);
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    `${reducers.length} reducers (${sizePairs.join(", ") || "none"}); NB ${tee?.nb ?? 0} equal tee body.`,
  );
}

function regressionAutoCheckBranchNoReducer(segmentData, quantities, definition) {
  const nodeReducers = quantities.reducers.filter((reducer) => reducer.nodeIndex === 1);
  const branchInfo = branchNodeInfo(1, nodeConnections(segmentData).get(1) ?? [], segmentData);
  const mainIndexes = (branchInfo?.mainPair ?? []).map((entry) => entry.segment.index).sort((a, b) => a - b);
  const branchIndexes = (branchInfo?.branchEntries ?? []).map((entry) => entry.segment.index).sort((a, b) => a - b);
  const branch = quantities.branches.find((item) => item.nodeIndex === 1);
  const linkedFromFirstMain = branchMainLinkedSegmentIndexes([mainIndexes[0]], segmentData);
  const mainSizePropagationExact =
    mainIndexes.length === 2 &&
    mainIndexes.every((index) => linkedFromFirstMain.includes(index)) &&
    branchIndexes.every((index) => !linkedFromFirstMain.includes(index));
  const mergedMainRow = (quantities.cutSegments ?? []).find((row) =>
    Array.isArray(row.segment?.mergedIndexes) &&
    row.segment.mergedIndexes.includes(0) &&
    row.segment.mergedIndexes.includes(1)
  );
  const branchTakeoffOnlyOnOutlet =
    branch?.connections?.length === 1 &&
    branch.connections[0].segmentIndex === branchIndexes[0] &&
    Number(branch.connections[0].takeoffMm) > 0;
  const branchOutletQuantity = quantities.segments.find((row) => row.segment.index === branchIndexes[0])?.quantity;
  const branchOutletHasOneWeldGap =
    Number(branchOutletQuantity?.weldEndCount) === 1 &&
    Math.abs(Number(branchOutletQuantity?.weldGapMm) - projectWeldGapMm()) < 0.001;
  const mainTakeoffsAreZero = mainIndexes.every((index) =>
    Math.abs(Number(quantities.segments.find((row) => row.segment.index === index)?.quantity.bendTakeoffMm)) < 0.001
  );
  const expectedMainWeldGap = projectWeldGapMm() * 2;
  const mergedMainIsFullLength =
    Math.abs(Number(mergedMainRow?.quantity.centrelineMm) - 8400) < 0.001 &&
    Number(mergedMainRow?.quantity.weldEndCount) === 2 &&
    Math.abs(Number(mergedMainRow?.quantity.weldGapMm) - expectedMainWeldGap) < 0.001 &&
    Math.abs(Number(mergedMainRow?.quantity.cutLengthMm) - (8400 - expectedMainWeldGap)) < 0.001;
  const passed =
    nodeConnectionType(1) === "branch" &&
    quantities.branches.length === 1 &&
    quantities.tees.length === 0 &&
    nodeReducers.length === 0 &&
    Boolean(mergedMainRow) &&
    branchTakeoffOnlyOnOutlet &&
    branchOutletHasOneWeldGap &&
    mainTakeoffsAreZero &&
    mergedMainIsFullLength &&
    mainSizePropagationExact;
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    `${nodeConnectionType(1)} node, ${quantities.tees.length} tees, ${nodeReducers.length} reducers; ` +
      `continuous main cut ${formatLength(mergedMainRow?.quantity.cutLengthMm ?? 0)} mm with ${formatWeldGapMm(expectedMainWeldGap)} mm for two end-flange Weld gaps; outlet-only branch take-off ${branchTakeoffOnlyOnOutlet ? "confirmed" : "failed"}.`,
  );
}

function regressionAutoCheckFlangeFlush(segmentData, quantities, definition) {
  const flanges = state.fittings.filter((fitting) => fitting.type === "flange");
  const flushFlanges = flanges.filter((fitting) => {
    const segment = segmentData.find((item) => item.index === fitting.segmentIndex);
    if (!segment) return false;
    const t = fittingDisplayT(segment, fitting);
    const expectedPoint = t <= 0.5 ? segment.start : segment.end;
    return (t === 0 || t === 1) && almostSamePoint(fittingDisplayPoint(segment, fitting), expectedPoint);
  });
  const flangeEndsHaveOneGap = flushFlanges.every((fitting) => {
    const quantity = quantities.segments.find((row) => row.segment.index === fitting.segmentIndex)?.quantity;
    return Number(quantity?.weldEndCount) >= 1 && Number(quantity?.weldGapMm) >= projectWeldGapMm();
  });
  const passed = flanges.length > 0 && flushFlanges.length === flanges.length && flangeEndsHaveOneGap;
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    `${flushFlanges.length}/${flanges.length} flange${flanges.length === 1 ? "" : "s"} snapped to pipe ends with one Weld gap per welded flange connection.`,
  );
}

function regressionAutoCheckFlangeDrilling(segmentData, quantities, definition) {
  const representativeRows = [
    ["ansi150", 100, 228.6, 190.5, 19.1, 8],
    ["ansi300", 150, 317.5, 269.7, 22.4, 12],
    ["ansi600", 300, 558.8, 489, 35.1, 20],
    ["tableE", 150, 280, 235, 22, 8],
    ["pn16", 200, 340, 295, 22, 12],
    ["jis10k", 300, 445, 400, 25, 16],
  ];
  const rowMatches = representativeRows.every(([standard, nb, odMm, pcdMm, holeMm, holes]) => {
    const drilling = flangeDrillingDimensions(standard, { nb, kind: "pipe" }, 0.05);
    return drilling.exactSize &&
      Math.abs(drilling.odMm - odMm) < 0.001 &&
      Math.abs(drilling.pcdMm - pcdMm) < 0.001 &&
      Math.abs(drilling.holeMm - holeMm) < 0.001 &&
      drilling.boltCount === holes;
  });
  const allRowsValid = Object.values(FLANGE_DRILLING_TABLES).every((table) =>
    table.every(([nb, odMm, thicknessMm, pcdMm, holeMm, holes]) =>
      nb > 0 && odMm > pcdMm && pcdMm > holeMm && thicknessMm > 0 &&
      Number.isInteger(holes) && holes >= 4 && holes % 4 === 0,
    ),
  );
  const dinAliasMatches =
    flangeDrillingDimensions("din10", { nb: 100, kind: "pipe" }, 0.05).boltCircleRadius ===
      flangeDrillingDimensions("pn10", { nb: 100, kind: "pipe" }, 0.05).boltCircleRadius &&
    flangeDrillingDimensions("din16", { nb: 200, kind: "pipe" }, 0.05).boltCount ===
      flangeDrillingDimensions("pn16", { nb: 200, kind: "pipe" }, 0.05).boltCount;
  const scaledPreview = flangeDrillingDimensions("ansi150", { nb: 100, od: 114.3, kind: "pipe" }, 0.15);
  const visualScaleMatches = Math.abs((scaledPreview.outerRadius / 0.15) - (228.6 / 114.3)) < 0.0001;
  const passed = rowMatches && allRowsValid && dinAliasMatches && visualScaleMatches;
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    `${Object.keys(FLANGE_DRILLING_TABLES).length} drilling tables cover ${Object.keys(FLANGE_STANDARDS).length} menu standards and were checked for OD, thickness, PCD, hole size and hole count.`,
  );
}

function regressionAutoCheck45Offset(segmentData, quantities, definition) {
  const offsetSegment = segmentData.find((segment) => Number.isFinite(segment.offsetTravelMm));
  const setMm = Number(offsetSegment?.offsetSetMm);
  const angle = normalizeAngle(offsetSegment?.offsetAngleDeg);
  const expectedTravel = offsetTravelLengthMm(setMm, angle);
  const actualTravel = pointLength(offsetSegment?.vector ?? { x: 0, y: 0, z: 0 });
  const offsetQuantity = quantities.segments.find((row) => row.segment.index === offsetSegment?.index)?.quantity;
  const offsetElbows = quantities.elbows.filter((elbow) =>
    elbow.firstSegmentIndex === offsetSegment?.index || elbow.secondSegmentIndex === offsetSegment?.index
  );
  const offsetSize = offsetSegment ? pipeSizeForSegment(offsetSegment) : null;
  const atlasElbowTakeoff = offsetSize ? ELBOW_45_TAKEOFF_MM[offsetSize.nb] : null;
  const expectedTakeoff = Number.isFinite(atlasElbowTakeoff) ? atlasElbowTakeoff * 2 : 0;
  const expectedWeldGap = projectWeldGapMm() * 2;
  const expectedCutLength = Math.max(0, actualTravel - expectedTakeoff - expectedWeldGap);
  const measurementCount = Array.isArray(state.measurements) ? state.measurements.length : 0;
  const passed =
    Boolean(offsetSegment) &&
    Math.abs(angle - 45) < 0.001 &&
    Math.abs(setMm - 1000) <= 1 &&
    Math.abs(actualTravel - expectedTravel) <= 2 &&
    Number.isFinite(atlasElbowTakeoff) &&
    offsetElbows.length === 2 &&
    offsetElbows.every((elbow) => Math.abs(elbow.bend - 45) < 0.01) &&
    offsetElbows.every((elbow) => {
      const takeoff = elbow.firstSegmentIndex === offsetSegment.index
        ? elbow.firstTakeoffMm
        : elbow.secondTakeoffMm;
      return Math.abs(Number(takeoff) - atlasElbowTakeoff) < 0.001;
    }) &&
    Math.abs(Number(offsetQuantity?.centrelineMm) - actualTravel) < 0.001 &&
    Math.abs(Number(offsetQuantity?.bendTakeoffMm) - expectedTakeoff) < 0.001 &&
    Number(offsetQuantity?.weldEndCount) === 2 &&
    Math.abs(Number(offsetQuantity?.weldGapMm) - expectedWeldGap) < 0.001 &&
    Math.abs(Number(offsetQuantity?.cutLengthMm) - expectedCutLength) < 0.001 &&
    measurementCount >= 1;
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    `Set ${formatLength(setMm)} mm; true travel ${formatLength(actualTravel)} mm; ` +
      `two Atlas 45 deg B take-offs ${formatLength(expectedTakeoff)} mm; Weld gap ${formatWeldGapMm(expectedWeldGap)} mm; angled cut ${formatLength(offsetQuantity?.cutLengthMm ?? 0)} mm.`,
  );
}

function regressionAutoCheck45OffsetSizeMatrix(segmentData, quantities, definition) {
  const setMm = 1000;
  const travelMm = setMm * Math.SQRT2;
  const weldGapMm = projectWeldGapMm() * 2;
  const atlasCases = [
    [25, 22],
    [50, 35],
    [100, 64],
    [150, 95],
    [300, 190],
  ];
  const rows = atlasCases.map(([nb, expectedB]) => {
    const actualB = bendTakeoffMm({ pipeSizeNb: nb }, 45);
    const cutMm = travelMm - actualB * 2 - weldGapMm;
    return {
      nb,
      expectedB,
      actualB,
      cutMm,
      passed:
        ELBOW_45_TAKEOFF_MM[nb] === expectedB &&
        Math.abs(actualB - expectedB) < 0.001 &&
        Math.abs(cutMm - (travelMm - expectedB * 2 - weldGapMm)) < 0.001 &&
        cutMm > 0,
    };
  });
  const passed = rows.every((row) => row.passed);
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    rows.map((row) => `DN${row.nb}: B ${formatLength(row.actualB)} mm / cut ${formatLength(row.cutMm)} mm`).join("; "),
  );
}

function regressionAutoCheckSocketDimensions(segmentData, quantities, definition) {
  const socketFittings = state.fittings
    .filter((fitting) => fitting.type === "socket")
    .sort((first, second) => first.t - second.t);
  const segment = segmentData.find((item) => item.index === socketFittings[0]?.segmentIndex);
  const lengthMm = pointLength(segment?.vector ?? { x: 0, y: 0, z: 0 });
  const positions = socketFittings.map((fitting) => lengthMm * fitting.t);
  const gaps = positions.slice(1).map((position, index) => position - positions[index]);
  const expectedAngles = [0, 90, 180];
  const anglesStepBy90 = socketFittings.every((fitting, index) =>
    fittingSocketAngle(fitting) === expectedAngles[index],
  );
  const evenGaps = gaps.length >= 2 && gaps.every((gap) => Math.abs(gap - gaps[0]) <= 1);
  const passed = socketFittings.length === 3 && anglesStepBy90 && evenGaps;
  const firstPosition = positions[0] ?? 0;
  const firstGap = gaps[0] ?? 0;
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    `First socket ${formatLength(firstPosition)} mm from end, then SOCK C/C ${formatLength(firstGap)} mm between sockets.`,
  );
}

function regressionAutoCheckPreparedEnds(segmentData, quantities, definition) {
  const groove = state.fittings.find((fitting) => fitting.type === "rollGroove");
  const flange = state.fittings.find((fitting) => fitting.type === "flange");
  const grooveSegment = segmentData.find((segment) => segment.index === groove?.segmentIndex);
  const flangeSegment = segmentData.find((segment) => segment.index === flange?.segmentIndex);
  const groovePointIndex = endpointSnappedFittingT(grooveSegment, groove) <= 0.5 ? grooveSegment?.from : grooveSegment?.to;
  const flangePointIndex = endpointSnappedFittingT(flangeSegment, flange) <= 0.5 ? flangeSegment?.from : flangeSegment?.to;
  const threadedSegment = segmentData.find((segment) => segment.index === 2);
  const threaded = { id: -1, type: "threadedEnd", segmentIndex: threadedSegment?.index, t: 1 };
  state.fittings.push(threaded);
  const grooveFinished = Boolean(grooveSegment) && endpointHasFinish(grooveSegment, groovePointIndex);
  const flangeFinished = Boolean(flangeSegment) && endpointHasFinish(flangeSegment, flangePointIndex);
  const threadedFinished = Boolean(threadedSegment) && endpointHasFinish(threadedSegment, threadedSegment.to);
  state.fittings.pop();
  const passed = grooveFinished && flangeFinished && threadedFinished;
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    passed
      ? "Roll-grooved, flanged and threaded endpoints are excluded from open-end warnings."
      : "A prepared roll-grooved, flanged or threaded endpoint was incorrectly classified as open.",
  );
}

function regressionAutoCheckStateRoundTrip(segmentData, quantities, definition) {
  const payload = statePayload();
  const restored = stateFromPayload(JSON.parse(JSON.stringify(payload)));
  const same = (first, second) => JSON.stringify(first) === JSON.stringify(second);
  const passed = Boolean(restored) &&
    same(restored.points, payload.points) &&
    same(restored.edges, payload.edges) &&
    same(restored.fittings, payload.fittings) &&
    same(restored.measurements, payload.measurements) &&
    same(restored.nodeTypes, payload.nodeTypes) &&
    same(restored.reducerSideOverrides, payload.reducerSideOverrides) &&
    same(restored.reducerTypeOverrides, payload.reducerTypeOverrides) &&
    same(restored.dimensionOffsets, payload.dimensionOffsets) &&
    same(restored.projectInfo, payload.projectInfo) &&
    restored.pipeSpec === payload.pipeSpec &&
    restored.dimensionStyle === payload.dimensionStyle;
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    `${payload.points.length} points, ${payload.edges.length} runs, ${payload.fittings.length} fittings and ${payload.measurements.length} manual measurements restored.`,
  );
}

function regressionAutoCheckStainlessTubeMaterial(segmentData, quantities, definition) {
  state.previewMode = "carbon";
  state.pipeSpec = "carbon40";
  const carbonStyle = previewViewStyle();
  const carbonFallback = fallbackPreviewStyle();
  state.pipeSpec = "stainlessTube";
  const tubeStyle = previewViewStyle();
  const tubeFallback = fallbackPreviewStyle();
  const passed =
    tubeStyle.physical === true &&
    tubeStyle.colors.pipe === 0xfbfcfc &&
    tubeStyle.colors.pipe !== carbonStyle.colors.pipe &&
    tubeFallback.pipeStops.includes("#ffffff") &&
    !carbonFallback.pipeStops.includes("#ffffff");
  return regressionCheckResult(
    definition.title,
    definition.sampleKey,
    passed,
    "Stainless Sch 10S and stainless tube use the silver physical/fallback material path instead of carbon black.",
  );
}

function normalizeTeamMessage(row) {
  if (!row || typeof row !== "object") return null;
  const id = normalizeUuid(row.id);
  const companyId = normalizeUuid(row.company_id);
  const body = String(row.body ?? "").trim().slice(0, 500);
  if (!id || !companyId || !body) return null;
  const removeAfter = String(row.remove_after ?? "").trim();
  if (removeAfter) {
    const removeTime = new Date(removeAfter).getTime();
    if (!Number.isNaN(removeTime) && removeTime < Date.now()) return null;
  }
  return {
    id,
    companyId,
    authorId: normalizeUuid(row.author_id),
    authorEmail: String(row.author_email ?? "").trim().slice(0, 120),
    body,
    pinned: row.pinned === true,
    completed: row.completed === true,
    completedAt: String(row.completed_at ?? ""),
    removeAfter,
    createdAt: String(row.created_at ?? ""),
    updatedAt: String(row.updated_at ?? ""),
  };
}

function hasProjectInfo(info = state.projectInfo) {
  return Object.values(normalizeProjectInfo(info)).some(Boolean);
}

function hasDrawingContent() {
  return Boolean(state.edges.length || state.fittings.length || state.notes.length || state.measurements?.length);
}

function projectDisplayName(info = state.projectInfo) {
  const project = normalizeProjectInfo(info);
  const parts = [
    project.jobNumber ? `Job ${project.jobNumber}` : "",
    project.spoolNumber ? `Spool ${project.spoolNumber}` : "",
    project.client,
  ].filter(Boolean);
  return parts.join(" - ") || "Untitled project";
}

function normalizeProjectStatus(value) {
  const raw = String(value ?? "draft").trim().toLowerCase();
  const compact = raw.replace(/[\s_-]+/g, "");
  const status = PROJECT_STATUS_ALIASES[raw] ?? PROJECT_STATUS_ALIASES[compact] ?? compact;
  return PROJECT_STATUSES.has(status) ? status : "draft";
}

function projectStatusLabel(value = state.projectStatus) {
  const status = normalizeProjectStatus(value);
  return PROJECT_STATUS_LABELS[status] ?? "Draft";
}

function projectStatusIndex(value) {
  const status = normalizeProjectStatus(value);
  return PROJECT_STATUS_FLOW.findIndex(([key]) => key === status);
}

function projectStatusAtLeast(value, minimum) {
  return projectStatusIndex(value) >= projectStatusIndex(minimum);
}

function normalizeRevisionHistory(history) {
  if (!Array.isArray(history)) return [];
  return history
    .map((entry) => ({
      id: String(entry?.id ?? "").trim().slice(0, 80) || `rev-${Date.now().toString(36)}`,
      revision: String(entry?.revision ?? "").trim().slice(0, 16),
      createdAt: String(entry?.createdAt ?? "").trim(),
      status: normalizeProjectStatus(entry?.status),
      note: String(entry?.note ?? "").trim().slice(0, 120),
      checkedBy: String(entry?.checkedBy ?? entry?.state?.checkedBy ?? "").trim().slice(0, 120),
      checkedAt: String(entry?.checkedAt ?? entry?.state?.checkedAt ?? "").trim(),
      issuedBy: String(entry?.issuedBy ?? entry?.state?.issuedBy ?? "").trim().slice(0, 120),
      issuedAt: String(entry?.issuedAt ?? entry?.state?.issuedAt ?? "").trim(),
      issueAudit: normalizeIssueAudit(entry?.issueAudit ?? entry?.state?.issueAudits?.[0]),
      state: entry?.state && typeof entry.state === "object" ? entry.state : null,
    }))
    .filter((entry) => entry.revision || entry.state)
    .slice(0, 12);
}

function projectCornerLabelLines(info = state.projectInfo) {
  const project = normalizeProjectInfo(info);
  return [`Job ${project.jobNumber || "-"} / Spool ${project.spoolNumber || "-"}`];
}

function projectCornerTagHeight(fontSize = 12, pressureRating = weakestPressureEstimate(segments())) {
  const lineHeight = Math.round(fontSize * 1.35);
  const titleHeight = lineHeight + 14;
  const bodyHeight = pressureRating ? lineHeight * 2 + 27 : 0;
  return titleHeight + bodyHeight;
}

function drawProjectCornerTag(ctx, width, height, options = {}) {
  const padding = options.padding ?? 14;
  const fontSize = options.fontSize ?? 12;
  const lineHeight = Math.round(fontSize * 1.35);
  const availableWidth = Math.max(72, width - padding * 2);
  const maxBoxWidth = Math.min(options.maxWidth ?? 320, availableWidth);
  const contentWidth = Math.max(52, maxBoxWidth - 24);
  const dark = isDarkAppTheme();
  const pressureRating = options.pressureRating === false
    ? null
    : options.pressureRating ?? weakestPressureEstimate(segments());

  ctx.save();
  ctx.font = `900 ${fontSize}px Inter, system-ui, sans-serif`;
  const title = fitCanvasText(ctx, projectCornerLabelLines(options.projectInfo)[0], contentWidth);
  const pressureTitle = pressureRating ? "Weakest pressure note" : "";
  const pressureValue = pressureRating ? formatPressureStandard(pressureRating.pressureBar) : "";
  const pressureDetail = pressureRating
    ? `${pipeSizeDisplayLabel(pressureRating.size)} pipe wall estimate`
    : "";
  const measuredTexts = [title];
  if (pressureRating) measuredTexts.push(pressureTitle, pressureValue, pressureDetail);
  const tagWidth = Math.min(
    availableWidth,
    Math.max(...measuredTexts.map((line) => ctx.measureText(line).width)) + 24,
  );
  const titleHeight = lineHeight + 14;
  const tagHeight = projectCornerTagHeight(fontSize, pressureRating);
  const x = Math.max(padding, width - padding - tagWidth);
  const y = padding;

  roundRect(ctx, x, y, tagWidth, tagHeight, 9);
  ctx.fillStyle = options.fill ?? (dark ? "rgba(4, 17, 27, 0.92)" : "rgba(255, 253, 248, 0.95)");
  ctx.fill();
  ctx.strokeStyle = options.stroke ?? (dark ? "rgba(18, 216, 255, 0.38)" : "rgba(8, 125, 115, 0.24)");
  ctx.lineWidth = 1;
  ctx.stroke();

  roundRect(ctx, x, y, tagWidth, titleHeight, 9);
  ctx.fillStyle = options.headerFill ?? (dark ? "rgba(0, 174, 255, 0.16)" : "rgba(224, 247, 247, 0.92)");
  ctx.fill();
  ctx.strokeStyle = dark ? "rgba(18, 216, 255, 0.18)" : "rgba(8, 125, 115, 0.16)";
  ctx.beginPath();
  ctx.moveTo(x, y + titleHeight);
  ctx.lineTo(x + tagWidth, y + titleHeight);
  ctx.stroke();

  ctx.fillStyle = options.color ?? (dark ? "#ecfeff" : "#123a40");
  ctx.textAlign = "left";
  ctx.textBaseline = "top";
  ctx.font = `950 ${fontSize}px Inter, system-ui, sans-serif`;
  ctx.fillText(title, x + 12, y + 8);

  if (pressureRating) {
    const bodyY = y + titleHeight + 10;
    ctx.font = `900 ${Math.max(9, fontSize - 2)}px Inter, system-ui, sans-serif`;
    ctx.fillStyle = dark ? "#ffd166" : "#92400e";
    ctx.fillText(pressureTitle, x + 12, bodyY);
    ctx.font = `950 ${Math.max(10, fontSize - 1)}px Inter, system-ui, sans-serif`;
    ctx.fillStyle = dark ? "#fff7d6" : "#1f3438";
    ctx.fillText(fitCanvasText(ctx, pressureValue, tagWidth - 24), x + 12, bodyY + lineHeight);
    ctx.font = `850 ${Math.max(9, fontSize - 3)}px Inter, system-ui, sans-serif`;
    ctx.fillStyle = dark ? "#9cc8d8" : "#607174";
    ctx.fillText(fitCanvasText(ctx, pressureDetail, tagWidth - 24), x + 12, bodyY + lineHeight * 2);
  }
  ctx.restore();
}

function createProjectId() {
  return `project-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function normalizeFittingPosition(type, value) {
  const fallback = Number.isFinite(Number(value)) ? Number(value) : 0.5;
  if (type === "flange" || type === "rollGroove" || type === "threadedEnd") {
    const clamped = clampNumber(fallback, 0, 1);
    return clamped <= 0.5 ? 0 : 1;
  }
  return clampNumber(fallback, 0.04, 0.96);
}

function endpointSnappedFittingTForLength(fitting, lengthMm) {
  const t = normalizeFittingPosition(fitting?.type, fitting?.t);
  if (fitting?.type !== "flange" && fitting?.type !== "rollGroove" && fitting?.type !== "threadedEnd") return t;
  return t <= 0.5 ? 0 : 1;
}

function endpointSnappedFittingT(segment, fitting) {
  const lengthMm = pointLength(segment?.vector ?? { x: 0, y: 0, z: 0 });
  return endpointSnappedFittingTForLength(fitting, lengthMm);
}

function fittingDisplayT(segment, fitting) {
  const t = endpointSnappedFittingT(segment, fitting);
  if (fitting?.type !== "rollGroove") return t;
  if (!segment) return t;
  const lengthMm = pointLength(segment?.vector);
  if (!Number.isFinite(lengthMm) || lengthMm <= 0) return t;
  const insetT = Math.min(ROLL_GROOVE_SETBACK_MM / lengthMm, 0.45);
  if (t <= 0.000001) return insetT;
  if (t >= 0.999999) return 1 - insetT;
  return t;
}

function fittingDisplayPoint(segment, fitting) {
  return lerpPoint(segment.start, segment.end, fittingDisplayT(segment, fitting));
}

function normalizeStateFittingPositions() {
  const segmentByIndex = new Map(segments().map((segment) => [segment.index, segment]));
  state.fittings = state.fittings.filter((fitting) =>
    FITTING_TOOLS.has(fitting.type) &&
    Number.isInteger(fitting.segmentIndex) &&
    segmentByIndex.has(fitting.segmentIndex),
  );
  for (const fitting of state.fittings) {
    const current = Number(fitting.t);
    const segment = segmentByIndex.get(fitting.segmentIndex);
    const normalized = isEndpointFittingType(fitting.type) && segment
      ? endpointSnappedFittingT(segment, fitting)
      : normalizeFittingPosition(fitting.type, fitting.t);
    if (!Number.isFinite(current) || Math.abs(normalized - current) > 0.000001) {
      fitting.t = normalized;
    }
  }
}

function normalizeEdgePipeSizesForState() {
  const specKey = normalizePipeSpec(state.pipeSpec);
  state.pipeSizeNb = pipeSizeNbForSpec(state.pipeSizeNb, specKey);
  state.edges = state.edges.map((edge) => ({
    ...edge,
    pipeSizeNb: pipeSizeNbForSpec(edge.pipeSizeNb ?? state.pipeSizeNb, specKey),
  }));
}

function bendReducerExistsAtNode(nodeIndex, connected, segmentByIndex) {
  if (!Number.isInteger(nodeIndex) || connected.length !== 2) return false;
  const joint = state.points[nodeIndex];
  const firstSegment = segmentByIndex.get(connected[0].segmentIndex);
  const secondSegment = segmentByIndex.get(connected[1].segmentIndex);
  if (!joint || !firstSegment || !secondSegment) return false;

  const firstVector = subtractPoints(state.points[connected[0].other], joint);
  const secondVector = subtractPoints(state.points[connected[1].other], joint);
  if (pointLength(firstVector) <= 0.001 || pointLength(secondVector) <= 0.001) return false;

  const bend = Math.abs(180 - bendAngle(firstVector, secondVector));
  if (bend < 0.5) return false;
  return Boolean(autoReducerForConnection(nodeIndex, connected[0], connected[1], firstSegment, secondSegment, { bend }));
}

function branchMarkCanPersistAtNode(nodeIndex, connected) {
  if (!Number.isInteger(nodeIndex) || connected.length < 2) return false;
  if (connected.length >= 3) return true;

  const joint = state.points[nodeIndex];
  if (!joint || connected.length !== 2) return false;
  const firstOther = state.points[connected[0].other];
  const secondOther = state.points[connected[1].other];
  if (!firstOther || !secondOther) return false;

  const firstVector = subtractPoints(firstOther, joint);
  const secondVector = subtractPoints(secondOther, joint);
  if (pointLength(firstVector) <= 0.001 || pointLength(secondVector) <= 0.001) return false;

  // A branch tool starts by splitting a straight main run, then the user draws the branch leg.
  // Keep that branch intent on a straight split so it does not become a tee before the next click.
  const straightness = Math.abs(180 - bendAngle(firstVector, secondVector));
  return straightness < 2;
}

function normalizeConnectionTrustState() {
  const segmentData = segments();
  const connections = nodeConnections(segmentData);
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));

  state.nodeTypes = normalizeNodeTypes(state.nodeTypes, state.points.length);
  for (const key of Object.keys(state.nodeTypes)) {
    const nodeIndex = Number(key);
    const connected = connections.get(nodeIndex) ?? [];
    if (state.nodeTypes[key] === "tee") {
      if (connected.length < 3 && !branchMarkCanPersistAtNode(nodeIndex, connected)) delete state.nodeTypes[key];
      continue;
    }
    if (!branchMarkCanPersistAtNode(nodeIndex, connected)) {
      delete state.nodeTypes[key];
    }
  }

  state.reducerSideOverrides = normalizeReducerSideOverrides(state.reducerSideOverrides, state.points.length);
  for (const key of Object.keys(state.reducerSideOverrides)) {
    const nodeIndex = Number(key);
    const connected = connections.get(nodeIndex) ?? [];
    if (!bendReducerExistsAtNode(nodeIndex, connected, segmentByIndex)) {
      delete state.reducerSideOverrides[key];
    }
  }

  const reducerNodes = new Set(autoReducerTransitions(segmentData).map((reducer) => reducer.nodeIndex));
  state.reducerTypeOverrides = normalizeReducerTypeOverrides(state.reducerTypeOverrides, state.points.length);
  for (const key of Object.keys(state.reducerTypeOverrides)) {
    if (!reducerNodes.has(Number(key))) delete state.reducerTypeOverrides[key];
  }
}

function normalizeDrawingTrustState() {
  normalizeEdgePipeSizesForState();
  normalizeStateFittingPositions();
  normalizeConnectionTrustState();
  setSelectedSegments(selectedSegmentIndexes());

  if (Number.isInteger(state.selectedFitting) && !state.fittings.some((fitting) => fitting.id === state.selectedFitting)) {
    state.selectedFitting = null;
  }
  if (Number.isInteger(state.selectedPoint) && (state.selectedPoint < 0 || state.selectedPoint >= state.points.length)) {
    state.selectedPoint = null;
  }
  if (!Number.isInteger(state.activePoint) || state.activePoint < 0 || state.activePoint >= state.points.length) {
    state.activePoint = Math.max(0, state.points.length - 1);
  }
}

function normalizeSelectedSegments(values, edgeCount) {
  if (!Array.isArray(values)) return [];
  return [...new Set(values.map((value) => Number(value)))]
    .filter((value) =>
      Number.isInteger(value) &&
      value >= 0 &&
      value < edgeCount,
    );
}

function normalizeNoteColour(value) {
  return NOTE_COLOUR_KEYS.has(value) ? value : DEFAULT_NOTE_COLOUR;
}

function noteColourStyle(value) {
  return noteColourByKey.get(normalizeNoteColour(value)) ?? noteColourByKey.get(DEFAULT_NOTE_COLOUR);
}

function defaultNoteLabelPoint(anchorPoint, projection = getProjection()) {
  const anchor = projectIso(anchorPoint, projection);
  return unprojectIsoAtZ(
    {
      x: anchor.x + NOTE_LABEL_DEFAULT_OFFSET.x,
      y: anchor.y + NOTE_LABEL_DEFAULT_OFFSET.y,
    },
    Number(anchorPoint.z) || 0,
    false,
  );
}

function noteLabelPoint(note, projection = getProjection()) {
  if (!note.labelPoint) {
    note.labelPoint = defaultNoteLabelPoint(note.point, projection);
  }
  return note.labelPoint;
}

function normalizeNotes(notes) {
  if (!Array.isArray(notes)) return [];
  return notes
    .map((note) => {
      const point = clonePoint(note.point ?? {});
      return {
        id: Number(note.id) || nextNoteId++,
        text: String(note.text ?? "").slice(0, 80),
        point,
        labelPoint: note.labelPoint ? clonePoint(note.labelPoint) : null,
        colour: normalizeNoteColour(note.colour ?? note.color),
      };
    })
    .filter((note) => note.text.trim());
}

function normalizeMeasurements(measurements) {
  if (!Array.isArray(measurements)) return [];
  return measurements
    .map((measurement) => ({
      id: Number(measurement.id) || nextMeasurementId++,
      start: clonePoint(measurement.start ?? {}),
      end: clonePoint(measurement.end ?? {}),
      label: String(measurement.label ?? "").trim().slice(0, 64),
    }))
    .filter((measurement) => pointLength(subtractPoints(measurement.end, measurement.start)) >= 1);
}

function normalizePipeSize(value) {
  const requested = Number(value);
  if (Number.isFinite(requested) && PIPE_SIZES.some((size) => size.nb === requested)) {
    return requested;
  }
  return defaultPipeSizeNbForSpec("carbon40");
}

function pipeSizeFromText(value) {
  const match = String(value).trim().match(/\d+/);
  if (!match) return null;
  const requested = Number(match[0]);
  return PIPE_SIZES.some((size) => size.nb === requested) ? requested : null;
}

function normalizePipeSpec(value) {
  return PIPE_SPEC_KEYS.has(value) ? value : "carbon40";
}

function pipeSpecForKey(value) {
  return PIPE_SPECS[normalizePipeSpec(value)] ?? PIPE_SPECS.carbon40;
}

function isTubePipeSpec(value = "carbon40") {
  return pipeSpecForKey(value).sizeType === "tube";
}

function isTubePipeSize(size) {
  return size?.kind === "tube";
}

function pipeSizeMatchesSpec(size, specKey = "carbon40") {
  return isTubePipeSpec(specKey) ? isTubePipeSize(size) : !isTubePipeSize(size);
}

function pipeSizesForSpec(specKey = "carbon40") {
  return PIPE_SIZES.filter((size) => pipeSizeMatchesSpec(size, specKey));
}

function defaultPipeSizeNbForSpec(specKey = "carbon40") {
  return pipeSizesForSpec(specKey)[0]?.nb ?? 25;
}

function closestPipeSizeNbForSpec(nb, specKey = "carbon40") {
  const requested = Number(nb);
  const current = PIPE_SIZES.find((size) => size.nb === requested);
  const options = pipeSizesForSpec(specKey);
  if (!options.length) return 25;
  if (!current) return options[0].nb;
  const closest = options.reduce((best, size) =>
    Math.abs(size.od - current.od) < Math.abs(best.od - current.od) ? size : best,
  options[0]);
  return closest.nb;
}

function pipeSizeNbForSpec(nb, specKey = "carbon40") {
  const requested = normalizePipeSize(nb);
  const size = PIPE_SIZES.find((item) => item.nb === requested);
  return pipeSizeMatchesSpec(size, specKey) ? requested : closestPipeSizeNbForSpec(requested, specKey);
}

function normalizeFlangeMode(value) {
  return FLANGE_MODES.has(value) ? value : "double";
}

function normalizeFlangeStandard(value) {
  return FLANGE_STANDARD_KEYS.has(value) ? value : "ansi150";
}

function flangeStandardInfo(value) {
  return FLANGE_STANDARDS[normalizeFlangeStandard(value)] ?? FLANGE_STANDARDS.ansi150;
}

function flangeStandardLabel(value) {
  return flangeStandardInfo(value).label;
}

function flangeStandardKeyFromText(value) {
  const text = String(value ?? "").trim().toLowerCase().replace(/[\s_-]+/g, "");
  if (!text) return null;
  if (text.includes("tabled") || text.includes("as2129d")) return "tableD";
  if (text.includes("tablee") || text.includes("as2129e")) return "tableE";
  if (text.includes("tablef") || text.includes("as2129f")) return "tableF";
  if (text.includes("tableh") || text.includes("as2129h")) return "tableH";
  if (text.includes("din10")) return "din10";
  if (text.includes("din16")) return "din16";
  if (text.includes("pn10")) return "pn10";
  if (text.includes("pn16")) return "pn16";
  if (text.includes("pn25")) return "pn25";
  if (text.includes("pn40") || text.includes("class40")) return "pn40";
  if (text.includes("jis10k") || text.includes("jis")) return "jis10k";
  if (text.includes("300")) return "ansi300";
  if (text.includes("600")) return "ansi600";
  if (text.includes("ansi") || text.includes("asme") || text.includes("150")) return "ansi150";
  return FLANGE_STANDARD_KEYS.has(text) ? text : null;
}

function normalizePreviewMode(value) {
  const mapped = LEGACY_PREVIEW_MODE_MAP[value] ?? value;
  return PREVIEW_MODES.has(mapped) ? mapped : "tricolor";
}

function normalizeDrawingDetail(value) {
  return DRAWING_DETAIL_MODES.has(value) ? value : "full";
}

function drawingDetailFromDimensionSettings(showDimensions = state.showDimensions, dimensionStyle = state.dimensionStyle) {
  if (showDimensions === false) return "clean";
  const style = normalizeDimensionStyle(dimensionStyle);
  if (style === "numbered") return "callouts";
  if (style === "redline" || style === "chain") return "fab";
  return "full";
}

function normalizeDimensionStyle(value) {
  return DIMENSION_STYLES.has(value) ? value : "labels";
}

function normalizePipeLabelMode(value) {
  return PIPE_LABEL_MODES.has(value) ? value : "auto";
}

function normalizeAppMode(value) {
  return APP_MODES.has(value) ? value : "draw";
}

function isLineDimensionStyle(value = state.dimensionStyle) {
  const style = normalizeDimensionStyle(value);
  return style === "redline" || style === "numbered" || style === "chain";
}

function activeDrawingDetail() {
  return normalizeDrawingDetail(state.drawingDetail ?? drawingDetailFromDimensionSettings(state.showDimensions, state.dimensionStyle));
}

function drawingDimensionsVisible() {
  const detail = activeDrawingDetail();
  return state.showDimensions !== false && detail !== "clean" && detail !== "sizes";
}

function drawingPipeLabelMode() {
  return normalizePipeLabelMode(state.pipeLabelMode);
}

function drawingPipeSizeLabelsVisible(options = {}) {
  const mode = drawingPipeLabelMode();
  if (options.export === true && mode === "export") return true;
  if (mode === "off" || mode === "export") return false;
  if (mode === "key" || mode === "all") return true;
  const detail = activeDrawingDetail();
  return detail === "sizes" || detail === "callouts" || detail === "full";
}

function drawingPipeSizeLabelMode(options = {}) {
  const mode = drawingPipeLabelMode();
  if (mode === "all") return "all";
  if (mode === "key" || (options.export === true && mode === "export")) return "compact";
  return activeDrawingDetail() === "full" ? "all" : "compact";
}

function applyDrawingDetailPreset(value) {
  const detail = normalizeDrawingDetail(value);
  state.drawingDetail = detail;
  if (detail === "clean") {
    state.showDimensions = false;
    state.dimensionStyle = "labels";
  } else if (detail === "fab") {
    state.showDimensions = true;
    state.dimensionStyle = "redline";
  } else if (detail === "sizes") {
    state.showDimensions = false;
    state.dimensionStyle = "labels";
  } else if (detail === "callouts") {
    state.showDimensions = true;
    state.dimensionStyle = "numbered";
  } else {
    state.showDimensions = true;
    state.dimensionStyle = "redline";
  }
}

function dimensionLinePalette() {
  const style = normalizeDimensionStyle(state.dimensionStyle);
  const dark = isDarkAppTheme();
  if (style === "chain") {
    return {
      line: dark ? "#c7d4d8" : "#1f2a2f",
      halo: dark ? "rgba(6, 16, 24, 0.9)" : "rgba(255, 253, 248, 0.94)",
      text: dark ? "#e8f1f3" : "#1f2a2f",
      fill: dark ? "rgba(6, 18, 28, 0.95)" : "rgba(255, 253, 248, 0.96)",
      border: dark ? "rgba(199, 212, 216, 0.3)" : "rgba(31, 42, 47, 0.28)",
      shadow: dark ? "rgba(0, 0, 0, 0.28)" : "rgba(31, 42, 47, 0.08)",
    };
  }
  if (style === "redline") {
    return {
      line: dark ? "#ff6f78" : "#c1121f",
      halo: dark ? "rgba(6, 16, 24, 0.9)" : "rgba(255, 253, 248, 0.9)",
      text: dark ? "#ff9aa1" : "#c1121f",
      fill: dark ? "rgba(6, 18, 28, 0.95)" : "rgba(255, 253, 248, 0.96)",
      border: dark ? "rgba(255, 111, 120, 0.38)" : "rgba(193, 18, 31, 0.28)",
      shadow: dark ? "rgba(0, 0, 0, 0.3)" : "rgba(31, 42, 47, 0.12)",
    };
  }
  return {
    line: dark ? "#88c9d3" : "#526c78",
    halo: dark ? "rgba(6, 16, 24, 0.9)" : "rgba(247, 245, 239, 0.92)",
    text: dark ? "#bce4ea" : "#415b66",
    fill: dark ? "rgba(6, 18, 28, 0.95)" : "rgba(251, 252, 250, 0.97)",
    border: dark ? "rgba(136, 201, 211, 0.34)" : "rgba(82, 108, 120, 0.3)",
    shadow: dark ? "rgba(0, 0, 0, 0.3)" : "rgba(31, 42, 47, 0.09)",
  };
}

function normalizeLiftingSlingAngle(value) {
  const numeric = Math.round(Number(value));
  return LIFTING_SLING_ANGLES.has(numeric) ? numeric : 60;
}

function fittingFlangeMode(fitting) {
  return normalizeFlangeMode(fitting?.flangeMode);
}

function fittingFlangeStandard(fitting) {
  return normalizeFlangeStandard(fitting?.flangeStandard);
}

function fittingSocketSizeNb(fitting) {
  return normalizePipeSize(fitting?.socketSizeNb ?? SOCKET_SIZE_NB);
}

function normalizeSocketAngle(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 0;
  const stepped = Math.round(numeric / SOCKET_ROTATION_STEP_DEG) * SOCKET_ROTATION_STEP_DEG;
  return ((stepped % 360) + 360) % 360;
}

function fittingSocketAngle(fitting) {
  return normalizeSocketAngle(fitting?.socketAngle);
}

function selectedSegmentIndexes() {
  const edgeCount = state.edges.length;
  const values = Array.isArray(state.selectedSegments) && state.selectedSegments.length
    ? state.selectedSegments
    : Number.isInteger(state.selectedSegment)
    ? [state.selectedSegment]
    : [];
  return normalizeSelectedSegments(values, edgeCount);
}

function setSelectedSegments(indexes) {
  const selected = normalizeSelectedSegments(indexes, state.edges.length);
  state.selectedSegments = selected;
  state.selectedSegment = selected.length ? selected[selected.length - 1] : null;
  syncDefaultPipeSizeFromSelection();
}

function clearSelectedSegments() {
  setSelectedSegments([]);
}

function selectSingleSegment(index) {
  setSelectedSegments([index]);
}

function syncDefaultPipeSizeFromSelection() {
  const selected = selectedSegmentsData();
  if (!selected.length) return;

  const sizes = [...new Set(selected.map((segment) => pipeSizeForSegment(segment).nb))];
  if (sizes.length === 1) {
    state.pipeSizeNb = normalizePipeSize(sizes[0]);
  }
}

function toggleSelectedSegment(index) {
  const selected = new Set(selectedSegmentIndexes());
  if (selected.has(index)) {
    selected.delete(index);
  } else {
    selected.add(index);
  }
  setSelectedSegments([...selected]);
}

function isSegmentSelected(index) {
  return selectedSegmentIndexes().includes(index);
}

function dimensionOffsetForSegment(segmentIndex) {
  const normalized = normalizeDimensionOffsets(state.dimensionOffsets, state.edges.length);
  const value = normalized[segmentIndex];
  return value ?? { side: 1, offset: 0 };
}

function setDimensionOffsetForSegment(segmentIndex, value) {
  if (!Number.isInteger(segmentIndex) || segmentIndex < 0 || segmentIndex >= state.edges.length) return;
  const next = normalizeDimensionOffsets(state.dimensionOffsets, state.edges.length);
  const offset = clampNumber(Number(value?.offset) || 0, 0, 520);
  if (offset <= 0.5) {
    delete next[segmentIndex];
  } else {
    next[segmentIndex] = {
      side: Number(value?.side) < 0 ? -1 : 1,
      offset: Math.round(offset),
    };
  }
  state.dimensionOffsets = next;
}

function resetDimensionHitTargets() {
  dimensionHitTargets = [];
}

function addDimensionHitTarget(target) {
  if (!target || !Number.isInteger(target.segmentIndex)) return;
  dimensionHitTargets.push(target);
}

function chooseSegmentFromPointer(event, index) {
  if (event.shiftKey || event.ctrlKey || event.metaKey) {
    toggleSelectedSegment(index);
    return;
  }
  selectSingleSegment(index);
}

function selectedPipeSize() {
  const selected = selectedSegmentsData();
  return selected.length ? pipeSizeForSegment(selected[0]) : pipeSizeByNb(state.pipeSizeNb);
}

function pipeSpec() {
  return pipeSpecForKey(state.pipeSpec);
}

function pipeSpecShortLabel() {
  return pipeSpec().shortLabel;
}

function pipeSizeByNb(nb, specKey = state.pipeSpec) {
  const requested = Number(nb);
  const exact = PIPE_SIZES.find((size) => size.nb === requested && pipeSizeMatchesSpec(size, specKey));
  if (exact) return exact;
  const fallbackNb = closestPipeSizeNbForSpec(Number.isFinite(requested) ? requested : defaultPipeSizeNbForSpec(specKey), specKey);
  return PIPE_SIZES.find((size) => size.nb === fallbackNb) ?? PIPE_SIZES.find((size) => size.nb === 25);
}

function pipeSizeForSegment(segment) {
  return pipeSizeByNb(segment?.pipeSizeNb ?? state.pipeSizeNb);
}

function pipeMassPerMetre(segment) {
  return pipeMassPerMetreForSize(pipeSizeForSegment(segment));
}

function pipeWallForSize(size) {
  const spec = pipeSpec();
  return Number(size[spec.wallKey]) || Number(size.wall40) || Number(size.wallTube) || 1.6;
}

function pipeMassPerMetreForSize(size) {
  const spec = pipeSpec();
  if (spec.kgPerMKey && Number.isFinite(size[spec.kgPerMKey])) {
    return size[spec.kgPerMKey];
  }
  const wall = pipeWallForSize(size);
  const coefficient = Number(spec.weightCoefficient) || DEFAULT_PIPE_WEIGHT_COEFFICIENT;
  return coefficient * wall * (size.od - wall);
}

function pressureRatingAssumption(specKey = state.pipeSpec) {
  return PRESSURE_RATING_ASSUMPTIONS[normalizePipeSpec(specKey)] ?? PRESSURE_RATING_ASSUMPTIONS.carbon40;
}

function pipePressureEstimateForSize(size, specKey = state.pipeSpec) {
  if (!size) return null;
  const assumption = pressureRatingAssumption(specKey);
  const allowableStressMpa = Number(assumption.allowableStressMpa);
  const wallMm = Number(size[pipeSpecForKey(specKey).wallKey]) || Number(size.wall40) || Number(size.wallTube);
  const odMm = Number(size.od);
  if (!Number.isFinite(allowableStressMpa) || !Number.isFinite(wallMm) || !Number.isFinite(odMm)) return null;

  const effectiveWallMm = wallMm * PRESSURE_WALL_TOLERANCE_FACTOR;
  const denominator = odMm - 2 * PRESSURE_Y_COEFFICIENT * effectiveWallMm;
  if (effectiveWallMm <= 0 || denominator <= 0) return null;

  const pressureMpa = (2 * allowableStressMpa * effectiveWallMm) / denominator;
  const pressureBar = pressureMpa * 10;
  return {
    size,
    pressureMpa,
    pressureBar,
    wallMm,
    effectiveWallMm,
    odMm,
    allowableStressMpa,
    assumption,
  };
}

function pressureEstimateForSegment(segment) {
  const rating = pipePressureEstimateForSize(pipeSizeForSegment(segment), state.pipeSpec);
  return rating
    ? {
        ...rating,
        segment,
      }
    : null;
}

function weakestPressureEstimate(segmentData = segments()) {
  const ratings = segmentData
    .map(pressureEstimateForSegment)
    .filter(Boolean)
    .sort((first, second) => first.pressureBar - second.pressureBar);
  if (!ratings.length) return null;
  const weakest = ratings[0];
  const matchingSegmentIndexes = ratings
    .filter((rating) => Math.abs(rating.pressureBar - weakest.pressureBar) < 0.05)
    .map((rating) => rating.segment.index);
  return {
    ...weakest,
    matchingSegmentIndexes,
  };
}

function pressureEstimateDetail(rating) {
  if (!rating) return "";
  const sizeLabel = pipeSizeDisplayLabel(rating.size);
  return `${sizeLabel} run ${rating.segment.index + 1}: ${formatPressureStandard(rating.pressureBar)} estimated pipe wall only.`;
}

function tubeOdText(size) {
  const od = Number(size?.od);
  if (!Number.isFinite(od)) return "";
  return od % 1 === 0 ? String(Math.round(od)) : od.toFixed(1);
}

function pipeSizeDisplayLabel(size) {
  if (!size) return "Pipe size";
  if (isTubePipeSize(size)) return size.label ?? `Tube OD ${tubeOdText(size)}`;
  return `NB ${size.nb}`;
}

function pipeSizeDisplayLabelByNb(nb, specKey = state.pipeSpec) {
  return pipeSizeDisplayLabel(pipeSizeByNb(nb, specKey));
}

function pipeSizeSpecLabel(size) {
  return `${pipeSizeDisplayLabel(size)} ${pipeSpec().schedule}`;
}

function pipeSizeOptionText(size) {
  if (isTubePipeSize(size)) {
    return `${pipeSizeDisplayLabel(size)} / ${size.nps} tube / wall ${Number(size.wallTube).toFixed(1)} mm`;
  }
  return `NB ${size.nb} / NPS ${size.nps} / OD ${size.od.toFixed(1)} mm`;
}

function pipeSizeReadoutNoun() {
  return isTubePipeSpec(state.pipeSpec) ? "tube OD" : "NB size";
}

function maxPipeOdMm() {
  return Math.max(...PIPE_SIZES.map((size) => size.od));
}

function selectedSegmentsData() {
  const selected = selectedSegmentIndexes();
  return segments().filter((segment) => selected.includes(segment.index));
}

function activePointIndex() {
  if (Number.isInteger(state.activePoint) && state.activePoint >= 0 && state.activePoint < state.points.length) {
    return state.activePoint;
  }
  return Math.max(0, state.points.length - 1);
}

function activePoint() {
  return state.points[activePointIndex()];
}

function normalizeLength(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return 1000;
  }
  return Math.max(MIN_LENGTH_MM, Math.min(MAX_LENGTH_MM, Math.round(numeric / LENGTH_INCREMENT_MM) * LENGTH_INCREMENT_MM));
}

function normalizeAngle(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return 45;
  }
  return Math.max(1, Math.min(89, numeric));
}

function normalizeBendAngle(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return 90;
  }
  return Math.max(1, Math.min(179, Math.round(numeric * 10) / 10));
}

function normalizeAnglePlane(value) {
  return ["xy", "xz", "yz"].includes(value) ? value : "xy";
}

function clonePoint(point) {
  return {
    x: Number(point.x) || 0,
    y: Number(point.y) || 0,
    z: Number(point.z) || 0,
  };
}

function addPoints(a, b, scale = 1) {
  return {
    x: a.x + b.x * scale,
    y: a.y + b.y * scale,
    z: a.z + b.z * scale,
  };
}

function subtractPoints(a, b) {
  return {
    x: a.x - b.x,
    y: a.y - b.y,
    z: a.z - b.z,
  };
}

function scalePoint(point, scale) {
  return {
    x: point.x * scale,
    y: point.y * scale,
    z: point.z * scale,
  };
}

function dotPoints(a, b) {
  return a.x * b.x + a.y * b.y + a.z * b.z;
}

function crossPoints(a, b) {
  return {
    x: a.y * b.z - a.z * b.y,
    y: a.z * b.x - a.x * b.z,
    z: a.x * b.y - a.y * b.x,
  };
}

function lerpPoint(a, b, t) {
  return {
    x: a.x + (b.x - a.x) * t,
    y: a.y + (b.y - a.y) * t,
    z: a.z + (b.z - a.z) * t,
  };
}

function pointLength(point) {
  return Math.hypot(point.x, point.y, point.z);
}

function normalizePoint(point) {
  const length = pointLength(point) || 1;
  return { x: point.x / length, y: point.y / length, z: point.z / length };
}

function almostSamePoint(a, b) {
  return Math.abs(a.x - b.x) < 0.001 && Math.abs(a.y - b.y) < 0.001 && Math.abs(a.z - b.z) < 0.001;
}

function segments() {
  const list = [];
  const edges = state.edges?.length ? state.edges : normalizeEdges(null, state.points.length);
  for (let i = 0; i < edges.length; i += 1) {
    const edge = edges[i];
    const start = state.points[edge.from];
    const end = state.points[edge.to];
    if (!almostSamePoint(start, end)) {
      list.push({
        index: i,
        from: edge.from,
        to: edge.to,
        pipeSizeNb: normalizePipeSize(edge.pipeSizeNb ?? state.pipeSizeNb),
        ...normalizeOffsetEdgeMeta(edge),
        start,
        end,
        vector: subtractPoints(end, start),
      });
    }
  }
  return list;
}

function defaultBigSpoolPlan() {
  return {
    enabled: false,
    maxTransportLengthMm: BIG_SPOOL_DEFAULT_MAX_LENGTH_MM,
    maxTransportWidthMm: 0,
    maxTransportHeightMm: 0,
    maxTransportWeightKg: 0,
    clearanceMm: BIG_SPOOL_DEFAULT_CLEARANCE_MM,
    preset: "custom",
    transportNote: "",
    defaultJointType: "fieldWeld",
    cuts: [],
    updatedAt: "",
  };
}

function normalizeBigSpoolPlan(source, edges = []) {
  const input = source && typeof source === "object" ? source : {};
  const maxTransportLengthMm = clampNumber(
    Math.round(Number(input.maxTransportLengthMm) || BIG_SPOOL_DEFAULT_MAX_LENGTH_MM),
    BIG_SPOOL_MIN_TRANSPORT_LENGTH_MM,
    MAX_LENGTH_MM,
  );
  const clearanceMm = clampNumber(
    Math.round(Number(input.clearanceMm) || BIG_SPOOL_DEFAULT_CLEARANCE_MM),
    50,
    2000,
  );
  const optionalLimit = (value, maximum) => {
    const numeric = Number(value);
    return Number.isFinite(numeric) && numeric > 0 ? clampNumber(Math.round(numeric), 1, maximum) : 0;
  };
  const maxTransportWidthMm = optionalLimit(input.maxTransportWidthMm, MAX_LENGTH_MM);
  const maxTransportHeightMm = optionalLimit(input.maxTransportHeightMm, MAX_LENGTH_MM);
  const maxTransportWeightKg = optionalLimit(input.maxTransportWeightKg, 100000);
  const preset = Object.hasOwn(BIG_SPOOL_PRESETS, input.preset) ? input.preset : "custom";
  const defaultJointType = BIG_SPOOL_PRIMARY_JOINT_TYPES.has(input.defaultJointType)
    ? input.defaultJointType
    : "fieldWeld";
  const cuts = Array.isArray(input.cuts)
    ? input.cuts
      .map((cut, index) => ({
        id: String(cut?.id || `CUT-${index + 1}`).replace(/[^a-z0-9_-]/gi, "").slice(0, 48) || `CUT-${index + 1}`,
        segmentIndex: Math.round(Number(cut?.segmentIndex)),
        distanceFromStartMm: Math.round(Number(cut?.distanceFromStartMm)),
        source: cut?.source === "manual" ? "manual" : "auto",
        jointType: Object.hasOwn(BIG_SPOOL_JOINT_TYPES, cut?.jointType) ? cut.jointType : "fieldWeld",
        status: Object.hasOwn(BIG_SPOOL_JOINT_STATUSES, cut?.status) ? cut.status : "planned",
        notes: String(cut?.notes ?? "").trim().slice(0, 120),
      }))
      .filter((cut) => Number.isInteger(cut.segmentIndex)
        && cut.segmentIndex >= 0
        && (!edges.length || cut.segmentIndex < edges.length)
        && Number.isFinite(cut.distanceFromStartMm)
        && cut.distanceFromStartMm > 0)
    : [];
  return {
    enabled: input.enabled === true,
    maxTransportLengthMm,
    maxTransportWidthMm,
    maxTransportHeightMm,
    maxTransportWeightKg,
    clearanceMm,
    preset,
    transportNote: String(input.transportNote ?? "").trim().slice(0, 120),
    defaultJointType,
    cuts,
    updatedAt: String(input.updatedAt ?? "").trim(),
  };
}

function currentBigSpoolPlan() {
  const normalized = normalizeBigSpoolPlan(state.bigSpool, state.edges);
  if (state.bigSpool && typeof state.bigSpool === "object" && !Array.isArray(state.bigSpool)) {
    for (const key of Object.keys(state.bigSpool)) {
      if (!Object.hasOwn(normalized, key)) delete state.bigSpool[key];
    }
    Object.assign(state.bigSpool, normalized);
  } else {
    state.bigSpool = normalized;
  }
  return state.bigSpool;
}

function bigSpoolJointPreparationText(cut, source = state) {
  const jointType = Object.hasOwn(BIG_SPOOL_JOINT_TYPES, cut?.jointType) ? cut.jointType : "fieldWeld";
  const weldGapMm = projectWeldGapMm(source);
  if (jointType === "groove") return "Roll groove on both child ends · rejoin on site with 1 grooved coupling · no weld-gap deduction";
  if (jointType === "flange") {
    return `Single flange on both child ends · rejoin with gasket and bolt set · Weld gap ${formatWeldGapMm(weldGapMm)} mm deducted from each pipe cut`;
  }
  if (jointType === "thread") return "Thread preparation on both child ends · no weld-gap deduction";
  return `Field weld · Weld gap ${formatWeldGapMm(weldGapMm)} mm deducted from each child pipe cut (${formatWeldGapMm(weldGapMm * 2)} mm total)`;
}

function bigSpoolJointShortLabel(cut) {
  if (cut?.jointType === "groove") return "RG/RG";
  if (cut?.jointType === "flange") return "FLG/FLG";
  if (cut?.jointType === "thread") return "THD/THD";
  return "WELD";
}

function bigSpoolJointRejoinItemText(cut) {
  if (cut?.jointType === "groove") return "1 grooved coupling (Victaulic-compatible system to project specification)";
  if (cut?.jointType === "flange") return "1 flange gasket and matching bolt set";
  return "";
}

function bigSpoolSplitDisplayInsetMm(cut, segment) {
  if (cut?.jointType !== "groove" || !segment) return 0;
  const lengthMm = pointLength(segment.vector);
  const pipeOdMm = Number(pipeSizeForSegment(segment)?.od) || 0;
  return clampNumber(Math.max(75, pipeOdMm * 0.8, lengthMm * 0.008), 75, Math.min(300, lengthMm * 0.2));
}

function bigSpoolFragmentDisplayGeometry(fragment) {
  const start = clonePoint(fragment.start);
  const end = clonePoint(fragment.end);
  const vector = subtractPoints(fragment.segment.end, fragment.segment.start);
  const lengthMm = pointLength(vector);
  if (lengthMm <= 0.001) return { start, end };
  const direction = scalePoint(vector, 1 / lengthMm);
  const fragmentLengthMm = pointLength(subtractPoints(end, start));
  const maximumInsetMm = Math.max(0, fragmentLengthMm * 0.22);
  const startInsetMm = Math.min(maximumInsetMm, bigSpoolSplitDisplayInsetMm(fragment.startCut, fragment.segment));
  const endInsetMm = Math.min(maximumInsetMm, bigSpoolSplitDisplayInsetMm(fragment.endCut, fragment.segment));
  return {
    start: startInsetMm ? addPoints(start, direction, startInsetMm) : start,
    end: endInsetMm ? addPoints(end, direction, -endInsetMm) : end,
  };
}

function bigSpoolFragmentScreenGeometry(fragment, projectPoint, minimumHalfGapPx = 18) {
  const display = bigSpoolFragmentDisplayGeometry(fragment);
  const start = projectPoint(display.start);
  const end = projectPoint(display.end);
  const segmentStart = projectPoint(fragment.segment.start);
  const segmentEnd = projectPoint(fragment.segment.end);
  const along = normalizeScreenVector({ x: segmentEnd.x - segmentStart.x, y: segmentEnd.y - segmentStart.y });
  if (fragment.startCut?.jointType === "groove") {
    const cut = projectPoint(fragment.start);
    if (Math.hypot(start.x - cut.x, start.y - cut.y) < minimumHalfGapPx) {
      start.x = cut.x + along.x * minimumHalfGapPx;
      start.y = cut.y + along.y * minimumHalfGapPx;
    }
  }
  if (fragment.endCut?.jointType === "groove") {
    const cut = projectPoint(fragment.end);
    if (Math.hypot(end.x - cut.x, end.y - cut.y) < minimumHalfGapPx) {
      end.x = cut.x - along.x * minimumHalfGapPx;
      end.y = cut.y - along.y * minimumHalfGapPx;
    }
  }
  return { start, end, along };
}

function bigSpoolJointEndFitting(cut, segmentIndex, endpointT, source = state, id = 0) {
  if (!cut || !Number.isInteger(Number(segmentIndex))) return null;
  const jointType = Object.hasOwn(BIG_SPOOL_JOINT_TYPES, cut.jointType) ? cut.jointType : "fieldWeld";
  const base = {
    id: Number(id) || 0,
    segmentIndex: Number(segmentIndex),
    bigSpoolFieldJoint: true,
    bigSpoolCutId: cut.id,
    bigSpoolJointType: jointType,
    fieldJointEnd: endpointT === 0 ? "start" : "end",
  };
  if (jointType === "groove") return { ...base, type: "rollGroove", t: endpointT };
  if (jointType === "flange") {
    return {
      ...base,
      type: "flange",
      t: endpointT,
      flangeMode: "single",
      flangeStandard: normalizeFlangeStandard(source?.flangeStandard),
    };
  }
  if (jointType === "thread") return { ...base, type: "threadedEnd", t: endpointT };
  return {
    ...base,
    type: "weld",
    t: endpointT === 0 ? 0.04 : 0.96,
    weldGapMm: projectWeldGapMm(source),
  };
}

function bigSpoolPieceLabel(index) {
  return pointLabel(index);
}

function bigSpoolPieceColour(index) {
  return BIG_SPOOL_PIECE_COLOURS[Math.max(0, Number(index) || 0) % BIG_SPOOL_PIECE_COLOURS.length];
}

function bigSpoolChildId(index) {
  const base = normalizeProjectInfo(state.projectInfo).spoolNumber || "SP-MASTER";
  return `${base}-${bigSpoolPieceLabel(index)}`;
}

function validBigSpoolCuts(segmentData = segments()) {
  const byIndex = new Map(segmentData.map((segment) => [segment.index, segment]));
  const seen = new Set();
  return currentBigSpoolPlan().cuts
    .map((cut) => {
      const segment = byIndex.get(cut.segmentIndex);
      const lengthMm = segment ? pointLength(segment.vector) : 0;
      if (!segment || lengthMm <= 1) return null;
      const distanceFromStartMm = clampNumber(Number(cut.distanceFromStartMm), 1, lengthMm - 1);
      const key = `${cut.segmentIndex}:${Math.round(distanceFromStartMm)}`;
      if (seen.has(key)) return null;
      seen.add(key);
      return {
        ...cut,
        distanceFromStartMm,
        t: distanceFromStartMm / lengthMm,
        lengthMm,
        point: lerpPoint(segment.start, segment.end, distanceFromStartMm / lengthMm),
      };
    })
    .filter(Boolean)
    .sort((a, b) => a.segmentIndex - b.segmentIndex || a.distanceFromStartMm - b.distanceFromStartMm);
}

function bigSpoolRouteDistances(segmentData = segments()) {
  const adjacency = new Map();
  for (const segment of segmentData) {
    const lengthMm = pointLength(segment.vector);
    if (!adjacency.has(segment.from)) adjacency.set(segment.from, []);
    if (!adjacency.has(segment.to)) adjacency.set(segment.to, []);
    adjacency.get(segment.from).push({ node: segment.to, lengthMm });
    adjacency.get(segment.to).push({ node: segment.from, lengthMm });
  }
  const startNode = segmentData[0]?.from ?? 0;
  const distances = new Map([...adjacency.keys()].map((node) => [node, Number.POSITIVE_INFINITY]));
  distances.set(startNode, 0);
  const open = new Set(adjacency.keys());
  while (open.size) {
    let current = null;
    let best = Number.POSITIVE_INFINITY;
    for (const node of open) {
      const distance = distances.get(node) ?? Number.POSITIVE_INFINITY;
      if (distance < best) {
        current = node;
        best = distance;
      }
    }
    if (current === null || !Number.isFinite(best)) break;
    open.delete(current);
    for (const neighbour of adjacency.get(current) ?? []) {
      const next = best + neighbour.lengthMm;
      if (next < (distances.get(neighbour.node) ?? Number.POSITIVE_INFINITY)) distances.set(neighbour.node, next);
    }
  }
  return distances;
}

function bigSpoolDistanceToFragment(point, fragment) {
  const vector = subtractPoints(fragment.end, fragment.start);
  const lengthSquared = dotPoints(vector, vector);
  if (lengthSquared <= 0.001) return pointLength(subtractPoints(point, fragment.start));
  const t = clampNumber(dotPoints(subtractPoints(point, fragment.start), vector) / lengthSquared, 0, 1);
  return pointLength(subtractPoints(point, lerpPoint(fragment.start, fragment.end, t)));
}

function bigSpoolPieceForPoint(layout, point) {
  let bestPiece = null;
  let bestDistance = Number.POSITIVE_INFINITY;
  for (const piece of layout.pieces) {
    for (const fragment of piece.fragments) {
      const distance = bigSpoolDistanceToFragment(point, fragment);
      if (distance < bestDistance) {
        bestDistance = distance;
        bestPiece = piece;
      }
    }
  }
  return bestPiece;
}

function addBigSpoolPieceComponent(piece, weightKg, point, type) {
  if (!piece || !Number.isFinite(weightKg) || Math.abs(weightKg) < 0.0000001 || !point) return;
  piece.weightComponents.push({ weightKg, point: clonePoint(point), type });
}

function applyBigSpoolPieceEngineering(layout, segmentData = segments()) {
  const quantities = quantitySummary(segmentData);
  const quantityBySegment = new Map(quantities.segments.map((entry) => [entry.segment.index, entry.quantity]));
  for (const piece of layout.pieces) piece.weightComponents = [];

  for (const piece of layout.pieces) {
    for (const fragment of piece.fragments) {
      const quantity = quantityBySegment.get(fragment.segmentIndex);
      const segmentLength = pointLength(fragment.segment.vector);
      const fraction = segmentLength > 0 ? fragment.lengthMm / segmentLength : 0;
      addBigSpoolPieceComponent(
        piece,
        (Number(quantity?.pipeWeightKg) || 0) * fraction,
        lerpPoint(fragment.start, fragment.end, 0.5),
        "pipe",
      );
    }
  }

  const addNearest = (weightKg, point, type) => addBigSpoolPieceComponent(bigSpoolPieceForPoint(layout, point), weightKg, point, type);
  for (const elbow of quantities.elbows) addNearest(elbow.weightKg, state.points[elbow.nodeIndex], "elbow");
  for (const reducer of quantities.reducers) addNearest(reducer.weightKg, reducerCentrePoint(reducer), "reducer");
  for (const tee of quantities.tees) addNearest(tee.weightKg, state.points[tee.nodeIndex], "tee");
  for (const branch of quantities.branches) addNearest(branch.weightKg, state.points[branch.nodeIndex], "branch");
  for (const fitting of quantities.fittings) addNearest(fitting.weightKg, fitting.point, fitting.fitting.type);

  for (const piece of layout.pieces) {
    for (const fragment of piece.fragments) {
      for (const [cut, endpointT, point] of [
        [fragment.startCut, 0, fragment.start],
        [fragment.endCut, 1, fragment.end],
      ]) {
        const fitting = bigSpoolJointEndFitting(cut, fragment.segmentIndex, endpointT, state, -1);
        if (!fitting) continue;
        addBigSpoolPieceComponent(piece, fittingWeightKg(fitting, fragment.segment), point, `split-${fitting.type}`);
        if (fitting.type === "weld" || fitting.type === "flange") {
          const gapWeightKg = (projectWeldGapMm() / 1000) * pipeMassPerMetre(fragment.segment);
          addBigSpoolPieceComponent(piece, -gapWeightKg, point, "split-weld-gap");
        }
      }
    }
  }

  for (const piece of layout.pieces) {
    piece.weightKg = piece.weightComponents.reduce((sum, component) => sum + component.weightKg, 0);
    if (piece.weightKg > 0) {
      piece.cogPoint = piece.weightComponents.reduce((sum, component) => ({
        x: sum.x + component.point.x * component.weightKg / piece.weightKg,
        y: sum.y + component.point.y * component.weightKg / piece.weightKg,
        z: sum.z + component.point.z * component.weightKg / piece.weightKg,
      }), { x: 0, y: 0, z: 0 });
    } else {
      piece.cogPoint = null;
    }
    delete piece.weightComponents;
  }
  return layout;
}

function bigSpoolPieceViolations(piece, plan = currentBigSpoolPlan()) {
  const violations = [];
  if (piece.transportLengthMm > plan.maxTransportLengthMm + 1) violations.push("length");
  if (plan.maxTransportWidthMm > 0 && piece.transportWidthMm > plan.maxTransportWidthMm + 1) violations.push("width");
  if (plan.maxTransportHeightMm > 0 && piece.transportHeightMm > plan.maxTransportHeightMm + 1) violations.push("height");
  if (plan.maxTransportWeightKg > 0 && piece.weightKg > plan.maxTransportWeightKg + 0.01) violations.push("weight");
  return violations;
}

function bigSpoolPieceReady(piece, plan = currentBigSpoolPlan()) {
  return bigSpoolPieceViolations(piece, plan).length === 0;
}

function safeBigSpoolSplitDistance(segment, requestedDistanceMm, clearanceMm) {
  const lengthMm = pointLength(segment.vector);
  if (lengthMm <= clearanceMm * 2 + 10) return null;
  const fittingDistances = state.fittings
    .filter((fitting) => fitting.segmentIndex === segment.index)
    .map((fitting) => normalizeFittingPosition(fitting.type, fitting.t) * lengthMm);
  const allowed = (distance) => distance >= clearanceMm
    && distance <= lengthMm - clearanceMm
    && fittingDistances.every((fittingDistance) => Math.abs(distance - fittingDistance) >= clearanceMm);
  const requested = clampNumber(requestedDistanceMm, clearanceMm, lengthMm - clearanceMm);
  if (allowed(requested)) return Math.round(requested);
  const step = Math.max(25, Math.min(100, clearanceMm / 3));
  for (let offset = step; offset <= lengthMm; offset += step) {
    const after = requested + offset;
    const before = requested - offset;
    if (allowed(after)) return Math.round(after);
    if (allowed(before)) return Math.round(before);
  }
  return null;
}

function suggestedBigSpoolCuts(
  maxTransportLengthMm = currentBigSpoolPlan().maxTransportLengthMm,
  clearanceMm = currentBigSpoolPlan().clearanceMm,
  jointType = currentBigSpoolPlan().defaultJointType,
) {
  const segmentData = segments();
  const envelopeAllowanceMm = Math.max(...segmentData.map((segment) => Number(pipeSizeForSegment(segment)?.od) || 0), 0);
  const targetRouteLengthMm = Math.max(BIG_SPOOL_MIN_TRANSPORT_LENGTH_MM, maxTransportLengthMm - envelopeAllowanceMm);
  const distances = bigSpoolRouteDistances(segmentData);
  const suggestions = [];
  const occupied = new Set();
  for (const segment of segmentData) {
    const lengthMm = pointLength(segment.vector);
    const fromDistance = distances.get(segment.from);
    const toDistance = distances.get(segment.to);
    if (!Number.isFinite(fromDistance) || !Number.isFinite(toDistance) || lengthMm <= 1) continue;
    const low = Math.min(fromDistance, toDistance);
    const high = Math.max(fromDistance, toDistance);
    if (high - low < 1) continue;
    let threshold = (Math.floor(low / targetRouteLengthMm) + 1) * targetRouteLengthMm;
    while (threshold < high - 1) {
      const requested = toDistance >= fromDistance ? threshold - fromDistance : fromDistance - threshold;
      const safeDistance = safeBigSpoolSplitDistance(segment, requested, clearanceMm);
      const key = `${segment.index}:${safeDistance}`;
      if (safeDistance !== null && !occupied.has(key)) {
        occupied.add(key);
        suggestions.push({
          id: `AUTO-${segment.index + 1}-${Math.round(safeDistance)}`,
          segmentIndex: segment.index,
          distanceFromStartMm: safeDistance,
          source: "auto",
          jointType: BIG_SPOOL_PRIMARY_JOINT_TYPES.has(jointType) ? jointType : "fieldWeld",
        });
      }
      threshold += targetRouteLengthMm;
    }
  }
  return suggestions;
}

function refineBigSpoolCutsForConstraints(plan = currentBigSpoolPlan()) {
  const maximumIterations = Math.min(80, Math.max(12, state.edges.length * 5));
  let added = 0;
  for (let iteration = 0; iteration < maximumIterations; iteration += 1) {
    const layout = bigSpoolLayout();
    const violating = layout.pieces
      .map((piece) => ({ piece, violations: bigSpoolPieceViolations(piece, plan) }))
      .filter((entry) => entry.violations.length)
      .sort((first, second) => {
        const firstRatio = Math.max(
          first.piece.transportLengthMm / Math.max(1, plan.maxTransportLengthMm),
          plan.maxTransportWidthMm ? first.piece.transportWidthMm / plan.maxTransportWidthMm : 0,
          plan.maxTransportHeightMm ? first.piece.transportHeightMm / plan.maxTransportHeightMm : 0,
          plan.maxTransportWeightKg ? first.piece.weightKg / plan.maxTransportWeightKg : 0,
        );
        const secondRatio = Math.max(
          second.piece.transportLengthMm / Math.max(1, plan.maxTransportLengthMm),
          plan.maxTransportWidthMm ? second.piece.transportWidthMm / plan.maxTransportWidthMm : 0,
          plan.maxTransportHeightMm ? second.piece.transportHeightMm / plan.maxTransportHeightMm : 0,
          plan.maxTransportWeightKg ? second.piece.weightKg / plan.maxTransportWeightKg : 0,
        );
        return secondRatio - firstRatio;
      })[0];
    if (!violating) break;

    const candidates = violating.piece.fragments
      .filter((fragment) => fragment.lengthMm > plan.clearanceMm * 2 + 20)
      .map((fragment) => {
        const segmentLength = pointLength(fragment.segment.vector);
        const requested = segmentLength * (fragment.t0 + fragment.t1) * 0.5;
        const distanceFromStartMm = safeBigSpoolSplitDistance(fragment.segment, requested, plan.clearanceMm);
        if (distanceFromStartMm === null) return null;
        if (distanceFromStartMm <= segmentLength * fragment.t0 + 2 || distanceFromStartMm >= segmentLength * fragment.t1 - 2) return null;
        if (plan.cuts.some((cut) => cut.segmentIndex === fragment.segmentIndex && Math.abs(cut.distanceFromStartMm - distanceFromStartMm) < 2)) return null;
        const vector = subtractPoints(fragment.end, fragment.start);
        const axisSpread = Math.max(Math.abs(vector.x), Math.abs(vector.y), Math.abs(vector.z));
        return { fragment, distanceFromStartMm, score: fragment.lengthMm + axisSpread * 0.6 };
      })
      .filter(Boolean)
      .sort((a, b) => b.score - a.score);
    const candidate = candidates[0];
    if (!candidate) break;
    plan.cuts.push({
      id: `AUTO-C-${candidate.fragment.segmentIndex + 1}-${Math.round(candidate.distanceFromStartMm)}`,
      segmentIndex: candidate.fragment.segmentIndex,
      distanceFromStartMm: candidate.distanceFromStartMm,
      source: "auto",
      jointType: BIG_SPOOL_PRIMARY_JOINT_TYPES.has(plan.defaultJointType) ? plan.defaultJointType : "fieldWeld",
      status: "planned",
      notes: "",
    });
    added += 1;
  }
  return added;
}

function bigSpoolLayout(segmentData = segments()) {
  const cuts = validBigSpoolCuts(segmentData);
  const cutsBySegment = new Map();
  for (const cut of cuts) {
    if (!cutsBySegment.has(cut.segmentIndex)) cutsBySegment.set(cut.segmentIndex, []);
    cutsBySegment.get(cut.segmentIndex).push(cut);
  }
  const fragments = [];
  for (const segment of segmentData) {
    const segmentCuts = cutsBySegment.get(segment.index) ?? [];
    const stops = [0, ...segmentCuts.map((cut) => cut.t), 1];
    for (let index = 0; index < stops.length - 1; index += 1) {
      const t0 = stops[index];
      const t1 = stops[index + 1];
      const startCut = index > 0 ? segmentCuts[index - 1] : null;
      const endCut = index < segmentCuts.length ? segmentCuts[index] : null;
      fragments.push({
        id: `${segment.index}:${index}`,
        segmentIndex: segment.index,
        segment,
        t0,
        t1,
        start: lerpPoint(segment.start, segment.end, t0),
        end: lerpPoint(segment.start, segment.end, t1),
        lengthMm: pointLength(segment.vector) * (t1 - t0),
        startKey: t0 === 0 ? `N:${segment.from}` : `C:${startCut?.id}:after`,
        endKey: t1 === 1 ? `N:${segment.to}` : `C:${endCut?.id}:before`,
        startCut,
        endCut,
      });
    }
  }

  const parent = new Map();
  const find = (key) => {
    if (!parent.has(key)) parent.set(key, key);
    let root = key;
    while (parent.get(root) !== root) root = parent.get(root);
    let cursor = key;
    while (parent.get(cursor) !== cursor) {
      const next = parent.get(cursor);
      parent.set(cursor, root);
      cursor = next;
    }
    return root;
  };
  const union = (a, b) => {
    const rootA = find(a);
    const rootB = find(b);
    if (rootA !== rootB) parent.set(rootB, rootA);
  };
  for (const fragment of fragments) union(fragment.startKey, fragment.endKey);

  const routeDistances = bigSpoolRouteDistances(segmentData);
  const groups = new Map();
  for (const fragment of fragments) {
    const root = find(fragment.startKey);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(fragment);
  }
  const pieces = [...groups.values()].map((pieceFragments) => {
    const points = pieceFragments.flatMap((fragment) => [fragment.start, fragment.end]);
    const xs = points.map((point) => point.x);
    const ys = points.map((point) => point.y);
    const zs = points.map((point) => point.z);
    const extents = {
      x: Math.max(...xs) - Math.min(...xs),
      y: Math.max(...ys) - Math.min(...ys),
      z: Math.max(...zs) - Math.min(...zs),
    };
    const largestOdMm = Math.max(...pieceFragments.map((fragment) => Number(pipeSizeForSegment(fragment.segment)?.od) || 0), 0);
    const transportDimensions = [extents.x + largestOdMm, extents.y + largestOdMm, extents.z + largestOdMm].sort((a, b) => b - a);
    const routeStartMm = Math.min(...pieceFragments.map((fragment) => {
      const fromDistance = routeDistances.get(fragment.segment.from) ?? 0;
      const toDistance = routeDistances.get(fragment.segment.to) ?? fromDistance + pointLength(fragment.segment.vector);
      return fromDistance + (toDistance - fromDistance) * fragment.t0;
    }));
    return {
      fragments: pieceFragments,
      centrelineMm: pieceFragments.reduce((sum, fragment) => sum + fragment.lengthMm, 0),
      extents,
      maxOverallMm: transportDimensions[0],
      transportLengthMm: transportDimensions[0],
      transportWidthMm: transportDimensions[1],
      transportHeightMm: transportDimensions[2],
      largestOdMm,
      routeStartMm,
    };
  }).sort((a, b) => a.routeStartMm - b.routeStartMm);

  for (const [pieceIndex, piece] of pieces.entries()) {
    piece.index = pieceIndex;
    piece.label = bigSpoolPieceLabel(pieceIndex);
    piece.childId = bigSpoolChildId(pieceIndex);
    piece.colour = bigSpoolPieceColour(pieceIndex);
    for (const fragment of piece.fragments) fragment.pieceIndex = pieceIndex;
  }
  applyBigSpoolPieceEngineering({ pieces, fragments, cuts }, segmentData);
  const fragmentById = new Map(fragments.map((fragment) => [fragment.id, fragment]));
  const resolvedCuts = cuts.map((cut, cutIndex) => {
    const segmentCuts = cutsBySegment.get(cut.segmentIndex) ?? [];
    const localIndex = segmentCuts.findIndex((item) => item.id === cut.id);
    const before = fragmentById.get(`${cut.segmentIndex}:${localIndex}`);
    const after = fragmentById.get(`${cut.segmentIndex}:${localIndex + 1}`);
    return {
      ...cut,
      jointNumber: cutIndex + 1,
      jointId: `J${String(cutIndex + 1).padStart(2, "0")}`,
      beforePieceIndex: before?.pieceIndex ?? null,
      afterPieceIndex: after?.pieceIndex ?? null,
    };
  });
  return { fragments, pieces, cuts: resolvedCuts };
}

function bigSpoolFragmentsForSegment(segmentIndex, layout = bigSpoolLayout()) {
  return layout.fragments.filter((fragment) => fragment.segmentIndex === segmentIndex);
}

function bigSpoolPlanActive() {
  return currentBigSpoolPlan().enabled === true;
}

function bigSpoolChildState(piece, masterState = state) {
  if (!piece) return null;
  const child = {
    ...masterState,
    points: [],
    edges: [],
    fittings: [],
    notes: [],
    measurements: [],
    nodeTypes: {},
    reducerSideOverrides: {},
    reducerTypeOverrides: {},
    dimensionOffsets: {},
    selectedSegments: [],
    selectedSegment: null,
    selectedFitting: null,
    selectedNote: null,
    selectedMeasurement: null,
    selectedPoint: null,
    history: [],
    redoHistory: [],
    bigSpool: { ...defaultBigSpoolPlan(), enabled: false },
    projectInfo: { ...normalizeProjectInfo(masterState.projectInfo, masterState.pipeSpec), spoolNumber: piece.childId },
    spoolUid: normalizeTraceabilityId(`${normalizeTraceabilityId(masterState.spoolUid) || "SPL"}-${piece.label}`),
  };
  const pointIndexByKey = new Map();
  const addPoint = (point) => {
    const key = `${Math.round(point.x * 1000)}:${Math.round(point.y * 1000)}:${Math.round(point.z * 1000)}`;
    if (pointIndexByKey.has(key)) return pointIndexByKey.get(key);
    const index = child.points.length;
    child.points.push(clonePoint(point));
    pointIndexByKey.set(key, index);
    return index;
  };
  const edgeByFragmentId = new Map();
  for (const fragment of piece.fragments) {
    const from = addPoint(fragment.start);
    const to = addPoint(fragment.end);
    const edgeIndex = child.edges.length;
    child.edges.push({
      from,
      to,
      pipeSizeNb: normalizePipeSize(fragment.segment.pipeSizeNb),
      ...normalizeOffsetEdgeMeta(fragment.segment),
    });
    edgeByFragmentId.set(fragment.id, edgeIndex);
  }
  for (const fitting of masterState.fittings ?? []) {
    const fittingT = normalizeFittingPosition(fitting.type, fitting.t);
    const candidates = piece.fragments.filter((fragment) => fragment.segmentIndex === fitting.segmentIndex
      && fittingT >= fragment.t0 - 0.000001
      && fittingT <= fragment.t1 + 0.000001);
    const fragment = candidates.find((candidate) => fittingT < candidate.t1 - 0.000001) ?? candidates[candidates.length - 1];
    if (!fragment) continue;
    const span = Math.max(0.000001, fragment.t1 - fragment.t0);
    const localT = clampNumber((fittingT - fragment.t0) / span, 0, 1);
    child.fittings.push({
      ...fitting,
      segmentIndex: edgeByFragmentId.get(fragment.id),
      t: normalizeFittingPosition(fitting.type, localT),
    });
  }
  let generatedFittingId = child.fittings.reduce((maximum, fitting) => Math.max(maximum, Number(fitting.id) || 0), 0) + 1;
  const addSplitEndPreparation = (fragment, cut, endpointT) => {
    if (!cut) return;
    const segmentIndex = edgeByFragmentId.get(fragment.id);
    if (!Number.isInteger(segmentIndex)) return;
    const fitting = bigSpoolJointEndFitting(cut, segmentIndex, endpointT, masterState, generatedFittingId);
    generatedFittingId += 1;
    if (fitting) child.fittings.push(fitting);
  };
  for (const fragment of piece.fragments) {
    addSplitEndPreparation(fragment, fragment.startCut, 0);
    addSplitEndPreparation(fragment, fragment.endCut, 1);
  }
  for (const [originalNode, type] of Object.entries(masterState.nodeTypes ?? {})) {
    const point = masterState.points?.[Number(originalNode)];
    if (!point) continue;
    const childIndex = pointIndexByKey.get(`${Math.round(point.x * 1000)}:${Math.round(point.y * 1000)}:${Math.round(point.z * 1000)}`);
    if (Number.isInteger(childIndex)) child.nodeTypes[childIndex] = type;
  }
  child.activePoint = Math.max(0, child.points.length - 1);
  child.selectedPoint = child.activePoint;
  child.weldRegister = normalizeWeldRegister([], child.fittings);
  return child.points.length && child.edges.length ? child : null;
}

function bigSpoolPieceLiftData(piece) {
  const child = bigSpoolChildState(piece);
  if (!child) return null;
  return withTemporaryState(child, () => {
    const quantities = quantitySummary();
    const cog = centreOfGravityData(quantities);
    const lugs = suggestedLugPlan(quantities, cog);
    return { quantities, cog, lugs };
  });
}

function runLabelForVector(vector) {
  const normalized = normalizePoint(vector);
  let best = AXES[0];
  let bestScore = -Infinity;
  for (const axis of AXES) {
    const score =
      normalized.x * axis.vector.x +
      normalized.y * axis.vector.y +
      normalized.z * axis.vector.z;
    if (score > bestScore) {
      best = axis;
      bestScore = score;
    }
  }

  if (bestScore > 0.999) {
    return best.label;
  }

  const abs = {
    x: Math.abs(vector.x),
    y: Math.abs(vector.y),
    z: Math.abs(vector.z),
  };

  if (abs.z < 0.001 && abs.x > 0.001 && abs.y > 0.001) {
    return `${formatAngle(Math.atan2(vector.y, vector.x) * 180 / Math.PI)} XY`;
  }
  if (abs.y < 0.001 && abs.x > 0.001 && abs.z > 0.001) {
    return `${formatAngle(Math.atan2(vector.z, vector.x) * 180 / Math.PI)} XZ`;
  }
  if (abs.x < 0.001 && abs.y > 0.001 && abs.z > 0.001) {
    return `${formatAngle(Math.atan2(vector.z, vector.y) * 180 / Math.PI)} YZ`;
  }

  return "Angled";
}

function resizeCanvas(canvas) {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const width = Math.max(1, Math.round(rect.width * dpr));
  const height = Math.max(1, Math.round(rect.height * dpr));

  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }

  const ctx = canvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { ctx, width: rect.width, height: rect.height, dpr };
}

function rawIso(point, scale = state.gridScale) {
  const x = point.x / MM_PER_GRID;
  const y = point.y / MM_PER_GRID;
  const z = point.z / MM_PER_GRID;
  return {
    x: (x - y) * ISO_COS * scale,
    y: (x + y) * ISO_SIN * scale - z * scale,
  };
}

function getProjection() {
  const rect = drawCanvas.getBoundingClientRect();
  const relevantPoints = state.previewCandidate
    ? [...state.points, state.previewCandidate.point]
    : state.points;
  const rawPoints = relevantPoints.map((point) => rawIso(point));
  const minX = Math.min(...rawPoints.map((point) => point.x));
  const maxX = Math.max(...rawPoints.map((point) => point.x));
  const minY = Math.min(...rawPoints.map((point) => point.y));
  const maxY = Math.max(...rawPoints.map((point) => point.y));

  return {
    offsetX: rect.width * 0.5 - (minX + maxX) * 0.5 + drawingViewOffset.x,
    offsetY: rect.height * 0.55 - (minY + maxY) * 0.5 + drawingViewOffset.y,
  };
}

function fitDrawingToViewport({ announce = true } = {}) {
  const rect = drawCanvas.getBoundingClientRect();
  const points = state.points.length ? state.points : [{ x: 0, y: 0, z: 0 }];
  const rawPoints = points.map((point) => rawIso(point, 1));
  const rawWidth = Math.max(1, Math.max(...rawPoints.map((point) => point.x)) - Math.min(...rawPoints.map((point) => point.x)));
  const rawHeight = Math.max(1, Math.max(...rawPoints.map((point) => point.y)) - Math.min(...rawPoints.map((point) => point.y)));
  const phone = document.body.classList.contains("phone-layout") || rect.width <= 640;
  const availableWidth = Math.max(120, rect.width - (phone ? 76 : 112));
  const availableHeight = Math.max(120, rect.height - (phone ? 96 : 120));
  state.gridScale = clampNumber(Math.min(56, availableWidth / rawWidth, availableHeight / rawHeight), 10, 72);
  drawingViewOffset = { x: 0, y: 0 };
  state.previewCandidate = null;
  updateAll();
  if (announce) {
    cursorReadout.textContent = "Whole spool fitted";
    showAppNotice("Whole spool fitted. Drag empty space to move it, or use two fingers to pan and zoom.");
  }
}

function projectIso(point, projection = getProjection()) {
  const raw = rawIso(point);
  return {
    x: raw.x + projection.offsetX,
    y: raw.y + projection.offsetY,
  };
}

function drawIso() {
  const { ctx, width, height } = resizeCanvas(drawCanvas);
  const projection = getProjection();
  ctx.clearRect(0, 0, width, height);
  drawGrid(ctx, width, height, projection);
  drawEndpointGuides(ctx, projection);
  resetDimensionHitTargets();
  drawSpool2d(ctx, projection);
  drawMeasurements2d(ctx, projection);
  drawNotes2d(ctx, projection);
  if (state.showLiftingPoints) {
    drawSuggestedLugs2d(ctx, projection);
    drawLiftPoint2d(ctx, projection);
  }
  drawPreviewRun(ctx, projection);
  drawSocketDragDimension(ctx, projection);
  drawBoxSelectOverlay(ctx);
  drawProjectCornerTag(ctx, width, height);
  drawHealthIssueCallout(ctx, projection);
}

function drawGrid(ctx, width, height, projection) {
  ctx.save();
  const darkTheme = isDarkAppTheme();
  ctx.fillStyle = darkTheme ? "#061018" : "#f7f5ef";
  ctx.fillRect(0, 0, width, height);

  const bounds = worldBounds(8);
  const range = Math.min(34, Math.max(8, Math.ceil(Math.max(bounds.maxAbsX, bounds.maxAbsY) + 8)));

  ctx.lineWidth = 1;
  ctx.strokeStyle = darkTheme ? "rgba(0, 174, 255, 0.1)" : "rgba(112, 124, 116, 0.055)";

  for (let i = -range; i <= range; i += 1) {
    drawLine(
      ctx,
      projectIso({ x: i * MM_PER_GRID, y: -range * MM_PER_GRID, z: 0 }, projection),
      projectIso({ x: i * MM_PER_GRID, y: range * MM_PER_GRID, z: 0 }, projection),
    );
    drawLine(
      ctx,
      projectIso({ x: -range * MM_PER_GRID, y: i * MM_PER_GRID, z: 0 }, projection),
      projectIso({ x: range * MM_PER_GRID, y: i * MM_PER_GRID, z: 0 }, projection),
    );
  }

  drawIsoPaperDots(ctx, width, height, projection, range);

  const origin = projectIso({ x: 0, y: 0, z: 0 }, projection);
  drawAxis(ctx, origin, projectIso({ x: 3000, y: 0, z: 0 }, projection), darkTheme ? "#13d8ff" : "#0f766e", "X");
  drawAxis(ctx, origin, projectIso({ x: 0, y: 3000, z: 0 }, projection), darkTheme ? "#2b77ff" : "#2563eb", "Y");
  drawAxis(ctx, origin, projectIso({ x: 0, y: 0, z: 3000 }, projection), darkTheme ? "#f9734f" : "#b95436", "Z");
  ctx.restore();
}

function drawIsoPaperDots(ctx, width, height, projection, range) {
  ctx.save();
  for (let x = -range; x <= range; x += 1) {
    for (let y = -range; y <= range; y += 1) {
      const dot = projectIso({ x: x * MM_PER_GRID, y: y * MM_PER_GRID, z: 0 }, projection);
      if (dot.x < -8 || dot.x > width + 8 || dot.y < -8 || dot.y > height + 8) {
        continue;
      }

      const major = x % 5 === 0 && y % 5 === 0;
      ctx.beginPath();
      ctx.fillStyle = isDarkAppTheme()
        ? major ? "rgba(35, 190, 255, 0.42)" : "rgba(0, 132, 255, 0.2)"
        : major ? "rgba(38, 80, 78, 0.24)" : "rgba(72, 86, 82, 0.12)";
      ctx.arc(dot.x, dot.y, major ? 1.7 : 1.05, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawEndpointGuides(ctx, projection) {
  if (state.activeTool !== "draw") return;

  const start = activePoint();
  const startScreen = projectIso(start, projection);

  ctx.save();
  ctx.lineWidth = 2;
  ctx.setLineDash([4, 8]);
  ctx.lineCap = "round";

  const guideAxes = shiftAngleSnap ? shiftAngleSnapAxes() : AXES;
  const guideLength = shiftAngleSnap ? offsetTravelLengthMm(state.stepLength, SHIFT_ANGLE_SNAP_DEGREES) : state.stepLength;
  for (const axis of guideAxes) {
    const endScreen = projectIso(addPoints(start, axis.vector, guideLength), projection);
    ctx.strokeStyle = axis.color;
    ctx.globalAlpha = axis.shiftAngle ? 0.22 : 0.28;
    drawLine(ctx, startScreen, endScreen);
    ctx.globalAlpha = 0.74;
    ctx.beginPath();
    ctx.fillStyle = axis.color;
    ctx.arc(endScreen.x, endScreen.y, 3.5, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.restore();
}

function drawAxis(ctx, from, to, color, label) {
  ctx.save();
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = 2;
  drawLine(ctx, from, to);
  const angle = Math.atan2(to.y - from.y, to.x - from.x);
  ctx.beginPath();
  ctx.moveTo(to.x, to.y);
  ctx.lineTo(to.x - Math.cos(angle - 0.42) * 9, to.y - Math.sin(angle - 0.42) * 9);
  ctx.lineTo(to.x - Math.cos(angle + 0.42) * 9, to.y - Math.sin(angle + 0.42) * 9);
  ctx.closePath();
  ctx.fill();
  ctx.font = "800 12px Inter, system-ui, sans-serif";
  ctx.fillText(label, to.x + 8, to.y + 4);
  ctx.restore();
}

function drawingPipePalette() {
  if (isDarkAppTheme()) {
    return {
      pipe: "#2bd4e4",
      selected: "#ff8a5c",
      hovered: "#4fc3ff",
      highlight: "rgba(229, 253, 255, 0.88)",
      shadow: "rgba(16, 216, 255, 0.18)",
      tee: "#2bd4e4",
      branch: "#ff8a5c",
    };
  }

  return {
    pipe: "#174e59",
    selected: "#b95436",
    hovered: "#2563eb",
    highlight: "#fffdf8",
    shadow: "rgba(31, 42, 47, 0.1)",
    tee: "#174e59",
    branch: "#b95436",
  };
}

function worldBounds(padding = 0) {
  const xs = state.points.map((point) => point.x / MM_PER_GRID);
  const ys = state.points.map((point) => point.y / MM_PER_GRID);
  const zs = state.points.map((point) => point.z / MM_PER_GRID);
  return {
    minX: Math.min(...xs) - padding,
    maxX: Math.max(...xs) + padding,
    minY: Math.min(...ys) - padding,
    maxY: Math.max(...ys) + padding,
    minZ: Math.min(...zs) - padding,
    maxZ: Math.max(...zs) + padding,
    maxAbsX: Math.max(...xs.map(Math.abs)),
    maxAbsY: Math.max(...ys.map(Math.abs)),
    maxAbsZ: Math.max(...zs.map(Math.abs)),
  };
}

function dimensionViewport(ctx, padding = 18) {
  const rect = ctx?.canvas?.getBoundingClientRect?.();
  const width = rect?.width || ctx?.canvas?.width || 0;
  const height = rect?.height || ctx?.canvas?.height || 0;
  const safeRight = Math.max(padding, width - padding);
  const safeBottom = Math.max(padding, height - padding);
  return {
    left: padding,
    top: padding,
    right: safeRight,
    bottom: safeBottom,
  };
}

function drawSpool2d(ctx, projection, options = {}) {
  const pipeWidth = 5;
  const segmentListForDraw = segments();
  const connections = nodeConnections(segmentListForDraw);
  const viewport = options.viewport ?? dimensionViewport(ctx, 18);
  const dimensionLayout = {
    labels: [],
    lines: [],
    viewport,
    exportMode: options.export === true,
    compactNumbered: options.export === true && normalizeDimensionStyle(state.dimensionStyle) === "numbered",
    pipes: segmentListForDraw.map((segment) => ({
      index: segment.index,
      start: projectIso(segment.start, projection),
      end: projectIso(segment.end, projection),
    })),
  };

  ctx.save();
  ctx.lineCap = "butt";
  ctx.lineJoin = "round";
  const palette = drawingPipePalette();

  for (const segment of segmentListForDraw) {
    const start = projectIso(segment.start, projection);
    const end = projectIso(segment.end, projection);
    const selected = isSegmentSelected(segment.index);
    const hovered = state.hoveredSegment === segment.index;

    ctx.shadowColor = palette.shadow;
    ctx.shadowBlur = 4;
    ctx.shadowOffsetY = 2;
    ctx.strokeStyle = selected ? palette.selected : hovered ? palette.hovered : palette.pipe;
    ctx.lineWidth = selected || hovered ? 7 : pipeWidth;
    drawLine(ctx, start, end);

    if (selected || hovered) {
      ctx.shadowColor = "transparent";
      ctx.strokeStyle = palette.highlight;
      ctx.lineWidth = 2;
      drawLine(ctx, start, end);
    }

  }

  drawFlushEndCaps2d(ctx, projection, segmentListForDraw, connections, pipeWidth);

  if (drawingDimensionsVisible()) {
    const dimensionSegments = segmentListForDraw
      .map((segment) => ({
        segment,
        start: projectIso(segment.start, projection),
        end: projectIso(segment.end, projection),
      }))
      .sort((a, b) => Math.hypot(b.end.x - b.start.x, b.end.y - b.start.y) - Math.hypot(a.end.x - a.start.x, a.end.y - a.start.y));
    for (const item of dimensionSegments) {
      drawDimension(ctx, item.segment, item.start, item.end, dimensionLayout);
    }
    drawOffsetSetDimensions(ctx, projection, segmentListForDraw, dimensionLayout);
    if (isLineDimensionStyle()) {
      drawSocketPositionDimensions(ctx, projection, segmentListForDraw, dimensionLayout);
    }
  }

  if (drawingDimensionsVisible()) {
    drawBendAngles(ctx, projection);
  }

  const exportMode = options.export === true;
  if (drawingPipeSizeLabelsVisible({ export: exportMode })) {
    drawPipeSizeLabels2d(ctx, projection, segmentListForDraw, dimensionLayout, { export: exportMode });
  }

  for (const fitting of state.fittings) {
    const segment = segmentListForDraw.find((item) => item.index === fitting.segmentIndex);
    if (!segment) continue;
    drawFitting2d(ctx, projection, fitting, segment, pipeWidth);
  }

  drawAutoReducers2d(ctx, projection, segmentListForDraw);
  drawTeeMarkers2d(ctx, projection, segmentListForDraw, connections, pipeWidth);
  drawPipePointMarkers(ctx, projection, connections);
  drawNumberedDimensionLegend(ctx, dimensionLayout);

  ctx.restore();
}

function drawBigSpoolBreaks2d(ctx, projection, layout = bigSpoolLayout(), pipeWidth = 5) {
  if (!layout.cuts.length) return;
  ctx.save();
  ctx.textAlign = "center";
  ctx.textBaseline = "bottom";
  ctx.font = "900 11px Inter, system-ui, sans-serif";
  for (const cut of layout.cuts) {
    const segment = segments().find((item) => item.index === cut.segmentIndex);
    if (!segment) continue;
    const point = projectIso(cut.point, projection);
    const start = projectIso(segment.start, projection);
    const end = projectIso(segment.end, projection);
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const length = Math.max(1, Math.hypot(dx, dy));
    const normal = { x: -dy / length, y: dx / length };
    ctx.strokeStyle = "#111827";
    ctx.lineWidth = 3;
    drawLine(ctx, { x: point.x - normal.x * 10, y: point.y - normal.y * 10 }, { x: point.x + normal.x * 10, y: point.y + normal.y * 10 });
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = "#ffffff";
    drawLine(ctx, { x: point.x - normal.x * 8, y: point.y - normal.y * 8 }, { x: point.x + normal.x * 8, y: point.y + normal.y * 8 });
    const label = `${cut.jointId} ${bigSpoolPieceLabel(cut.beforePieceIndex ?? 0)}/${bigSpoolPieceLabel(cut.afterPieceIndex ?? 0)} ${bigSpoolJointShortLabel(cut)}`;
    ctx.lineWidth = 4;
    ctx.strokeStyle = "rgba(255,255,255,0.95)";
    ctx.fillStyle = "#111827";
    const labelOffset = cut.jointType === "groove" ? 34 : 18;
    ctx.strokeText(label, point.x + normal.x * labelOffset, point.y + normal.y * labelOffset);
    ctx.fillText(label, point.x + normal.x * labelOffset, point.y + normal.y * labelOffset);
    if (cut.jointType === "groove") {
      const matchingFragments = layout.fragments.filter((fragment) => fragment.startCut?.id === cut.id || fragment.endCut?.id === cut.id);
      for (const fragment of matchingFragments) {
        const display = bigSpoolFragmentScreenGeometry(fragment, (worldPoint) => projectIso(worldPoint, projection));
        const atStart = fragment.startCut?.id === cut.id;
        const endpoint = atStart ? display.start : display.end;
        const inward = atStart ? 1 : -1;
        const grooveCentre = {
          x: endpoint.x + display.along.x * inward * 5,
          y: endpoint.y + display.along.y * inward * 5,
        };
        const grooveNormal = { x: -display.along.y, y: display.along.x };
        ctx.lineCap = "butt";
        ctx.strokeStyle = "#4d5754";
        ctx.lineWidth = 2.8;
        for (const offset of [-3, 3]) {
          const centre = {
            x: grooveCentre.x + display.along.x * offset,
            y: grooveCentre.y + display.along.y * offset,
          };
          drawLine(ctx,
            { x: centre.x - grooveNormal.x * Math.max(8, pipeWidth * 1.4), y: centre.y - grooveNormal.y * Math.max(8, pipeWidth * 1.4) },
            { x: centre.x + grooveNormal.x * Math.max(8, pipeWidth * 1.4), y: centre.y + grooveNormal.y * Math.max(8, pipeWidth * 1.4) });
        }
        const labelSide = atStart ? -1 : 1;
        const rgLabel = {
          x: endpoint.x + grooveNormal.x * labelSide * 17,
          y: endpoint.y + grooveNormal.y * labelSide * 17,
        };
        ctx.font = "900 8px Inter, system-ui, sans-serif";
        ctx.lineWidth = 3;
        ctx.strokeStyle = "rgba(255, 253, 248, 0.95)";
        ctx.fillStyle = "#526067";
        ctx.strokeText("RG", rgLabel.x, rgLabel.y);
        ctx.fillText("RG", rgLabel.x, rgLabel.y);
      }
    }
  }
  ctx.restore();
}

function drawLiftPoint2d(ctx, projection, quantities = quantitySummary()) {
  const liftPoint = centreOfGravityData(quantities);
  if (!liftPoint) return;

  const point = projectIso(liftPoint.point, projection);

  ctx.save();
  ctx.shadowColor = "rgba(31, 42, 47, 0.18)";
  ctx.shadowBlur = 5;
  ctx.shadowOffsetY = 2;
  ctx.strokeStyle = "#c1121f";
  ctx.lineWidth = 4;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(point.x - 11, point.y - 11);
  ctx.lineTo(point.x + 11, point.y + 11);
  ctx.moveTo(point.x + 11, point.y - 11);
  ctx.lineTo(point.x - 11, point.y + 11);
  ctx.stroke();

  ctx.shadowColor = "transparent";
  ctx.font = "900 12px Inter, system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.lineWidth = 5;
  ctx.strokeStyle = "rgba(255, 253, 248, 0.96)";
  ctx.fillStyle = "#c1121f";
  ctx.strokeText("COG", point.x, point.y - 24);
  ctx.fillText("COG", point.x, point.y - 24);
  ctx.restore();
}

function drawSuggestedLugs2d(ctx, projection, quantities = quantitySummary()) {
  const lugPlan = suggestedLugPlan(quantities);
  if (!lugPlan) return;
  const segmentData = quantities.segments.map(({ segment }) => segment);
  const dimensionLayout = {
    labels: [],
    lines: [],
    viewport: dimensionViewport(ctx, 18),
    pipes: segmentData.map((segment) => ({
      index: segment.index,
      start: projectIso(segment.start, projection),
      end: projectIso(segment.end, projection),
    })),
  };

  for (const [index, lug] of lugPlan.points.entries()) {
    drawLugPositionDimension2d(ctx, projection, lug, dimensionLayout, index);
  }

  ctx.save();
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.font = "900 11px Inter, system-ui, sans-serif";

  for (const lug of lugPlan.points) {
    const point = projectIso(lug.point, projection);
    ctx.fillStyle = "#0f766e";
    ctx.strokeStyle = "#fffdf8";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(point.x, point.y - 11);
    ctx.lineTo(point.x + 11, point.y);
    ctx.lineTo(point.x, point.y + 11);
    ctx.lineTo(point.x - 11, point.y);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    const label = `LUG ${lug.number}`;
    ctx.lineWidth = 5;
    ctx.strokeStyle = "rgba(255, 253, 248, 0.96)";
    ctx.fillStyle = "#0f766e";
    ctx.strokeText(label, point.x, point.y - 25);
    ctx.fillText(label, point.x, point.y - 25);
  }

  ctx.restore();
}

function healthTargetPointIndexes(target) {
  if (!target) return [];
  const values = [];
  if (Number.isInteger(target.pointIndex)) values.push(target.pointIndex);
  if (Number.isInteger(target.nodeIndex)) values.push(target.nodeIndex);
  if (Array.isArray(target.pointIndexes)) values.push(...target.pointIndexes);
  return [...new Set(values)].filter((index) => Number.isInteger(index) && state.points[index]);
}

function healthTargetSegmentIndexes(target) {
  if (!target) return [];
  if (target.pointOnly === true) return [];
  const values = [];
  if (Number.isInteger(target.segmentIndex)) values.push(target.segmentIndex);
  if (Array.isArray(target.segmentIndexes)) values.push(...target.segmentIndexes);
  for (const pointIndex of healthTargetPointIndexes(target)) {
    for (const segment of segments()) {
      if (segment.from === pointIndex || segment.to === pointIndex) values.push(segment.index);
    }
  }
  return normalizeSelectedSegments([...new Set(values)], state.edges.length);
}

function healthTargetScreenPoints(target, projection) {
  const points = healthTargetPointIndexes(target).map((index) => projectIso(state.points[index], projection));
  const pointKeySet = new Set(points.map((point) => `${Math.round(point.x)}:${Math.round(point.y)}`));
  for (const index of healthTargetSegmentIndexes(target)) {
    const segment = segments().find((item) => item.index === index);
    if (!segment) continue;
    const midpoint = projectIso(lerpPoint(segment.start, segment.end, 0.5), projection);
    const key = `${Math.round(midpoint.x)}:${Math.round(midpoint.y)}`;
    if (!pointKeySet.has(key)) {
      points.push(midpoint);
      pointKeySet.add(key);
    }
  }
  return points;
}

function drawHealthIssueCallout(ctx, projection) {
  if (!healthHighlight) return;
  const now = performance.now();
  if (now > healthHighlight.expiresAt) {
    healthHighlight = null;
    return;
  }

  const target = healthHighlight.target;
  const points = healthTargetScreenPoints(target, projection);
  const segmentIndexes = healthTargetSegmentIndexes(target);
  if (!points.length && !segmentIndexes.length) return;

  const progress = clampNumber((now - healthHighlight.startedAt) / Math.max(1, healthHighlight.expiresAt - healthHighlight.startedAt), 0, 1);
  const pulse = Math.sin(progress * Math.PI * 8) * 0.5 + 0.5;
  const calloutColor = isDarkAppTheme() ? "#13d8ff" : "#c1121f";
  const washColor = isDarkAppTheme() ? "rgba(19, 216, 255, 0.18)" : "rgba(193, 18, 31, 0.16)";
  const glowColor = isDarkAppTheme() ? "rgba(19, 216, 255, 0.48)" : "rgba(193, 18, 31, 0.38)";

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.shadowColor = glowColor;
  ctx.shadowBlur = 16 + pulse * 8;

  for (const index of segmentIndexes) {
    const segment = segments().find((item) => item.index === index);
    if (!segment) continue;
    const start = projectIso(segment.start, projection);
    const end = projectIso(segment.end, projection);
    ctx.strokeStyle = washColor;
    ctx.lineWidth = Math.max(14, visualPipeWidth(segment) + 12);
    drawLine(ctx, start, end);
    ctx.setLineDash([10, 8]);
    ctx.strokeStyle = calloutColor;
    ctx.lineWidth = 3;
    drawLine(ctx, start, end);
    ctx.setLineDash([]);
  }

  for (const point of points) {
    const radius = 18 + pulse * 9;
    ctx.fillStyle = washColor;
    ctx.strokeStyle = calloutColor;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(point.x, point.y, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(point.x, point.y, 5, 0, Math.PI * 2);
    ctx.fillStyle = calloutColor;
    ctx.fill();
  }

  const anchor = points[0];
  if (anchor && healthHighlight.label) {
    const label = healthHighlight.label.length > 42
      ? `${healthHighlight.label.slice(0, 39)}...`
      : healthHighlight.label;
    ctx.shadowBlur = 10;
    ctx.font = "950 12px Inter, system-ui, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    const metrics = ctx.measureText(label);
    const width = metrics.width + 20;
    const height = 28;
    const x = clampNumber(anchor.x + 18, 12, Math.max(12, ctx.canvas.getBoundingClientRect().width - width - 12));
    const y = clampNumber(anchor.y - 32, 18, Math.max(18, ctx.canvas.getBoundingClientRect().height - height - 12));
    ctx.fillStyle = isDarkAppTheme() ? "rgba(3, 15, 25, 0.92)" : "rgba(255, 253, 248, 0.96)";
    ctx.strokeStyle = calloutColor;
    ctx.lineWidth = 2;
    roundRect(ctx, x, y - height * 0.5, width, height, 8);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = calloutColor;
    ctx.fillText(label, x + 10, y + 1);
  }

  ctx.restore();
}

function drawAutoReducers2d(ctx, projection, segmentData) {
  const reducers = autoReducerTransitions(segmentData);
  if (!reducers.length) return;

  ctx.save();
  ctx.lineCap = "butt";
  ctx.lineJoin = "round";
  ctx.strokeStyle = "#7a4dc2";
  ctx.fillStyle = "#f1ebff";
  ctx.lineWidth = 3;

  for (const reducer of reducers) {
    const joint = projectIso(state.points[reducer.nodeIndex], projection);
    const largeOther = projectIso(state.points[reducer.largeOtherIndex], projection);
    const smallOther = projectIso(state.points[reducer.smallOtherIndex], projection);
    const placementOther = reducerPlacementSide(reducer) === "large" ? largeOther : smallOther;
    const startsAtJoint = reducerStartsAtJoint(reducer);
    const startsAfterBend = reducer.kind === "bend";
    const along = startsAtJoint || startsAfterBend
      ? normalizeScreenVector({ x: placementOther.x - joint.x, y: placementOther.y - joint.y })
      : normalizeScreenVector({ x: smallOther.x - largeOther.x, y: smallOther.y - largeOther.y });
    const length = 26;
    const largeWidth = Math.max(14, visualPipeWidth(reducer.largeSegment) * 1.45);
    const smallWidth = Math.max(8, visualPipeWidth(reducer.smallSegment) * 0.95);
    const startWidth = startsAfterBend && reducerPlacementSide(reducer) === "large" ? smallWidth : largeWidth;
    const endWidth = startsAfterBend && reducerPlacementSide(reducer) === "large" ? largeWidth : smallWidth;
    let start;
    let end;
    if (startsAfterBend) {
      const offset = reducerScreenOffsetPixels(reducer, joint, placementOther, length);
      start = { x: joint.x + along.x * offset, y: joint.y + along.y * offset };
      end = { x: start.x + along.x * length, y: start.y + along.y * length };
    } else if (startsAtJoint) {
      start = { x: joint.x + along.x * 2, y: joint.y + along.y * 2 };
      end = { x: joint.x + along.x * length, y: joint.y + along.y * length };
    } else {
      start = { x: joint.x - along.x * length * 0.5, y: joint.y - along.y * length * 0.5 };
      end = { x: joint.x + along.x * length * 0.5, y: joint.y + along.y * length * 0.5 };
    }

    drawReducerProfile2d(ctx, start, end, startWidth, endWidth, reducer.reducerType, {
      label: normalizeReducerType(reducer.reducerType) === "eccentric"
        ? `ECC e${formatLength(reducer.eccentricOffsetMm)}`
        : "CONC",
      labelColor: "#59358f",
    });
  }

  ctx.restore();
}

function reducerProfile2d(start, end, startWidth, endWidth, reducerType = "concentric") {
  const along = normalizeScreenVector({ x: end.x - start.x, y: end.y - start.y });
  const normal = { x: -along.y, y: along.x };
  const startCentre = { ...start };
  const endCentre = { ...end };
  if (normalizeReducerType(reducerType) === "eccentric") {
    const shift = Math.abs(startWidth - endWidth) * 0.5;
    if (startWidth >= endWidth) {
      endCentre.x += normal.x * shift;
      endCentre.y += normal.y * shift;
    } else {
      startCentre.x += normal.x * shift;
      startCentre.y += normal.y * shift;
    }
  }
  return {
    normal,
    startCentre,
    endCentre,
    points: [
      { x: startCentre.x - normal.x * startWidth * 0.5, y: startCentre.y - normal.y * startWidth * 0.5 },
      { x: endCentre.x - normal.x * endWidth * 0.5, y: endCentre.y - normal.y * endWidth * 0.5 },
      { x: endCentre.x + normal.x * endWidth * 0.5, y: endCentre.y + normal.y * endWidth * 0.5 },
      { x: startCentre.x + normal.x * startWidth * 0.5, y: startCentre.y + normal.y * startWidth * 0.5 },
    ],
  };
}

function drawReducerProfile2d(ctx, start, end, startWidth, endWidth, reducerType = "concentric", options = {}) {
  const profile = reducerProfile2d(start, end, startWidth, endWidth, reducerType);
  ctx.beginPath();
  ctx.moveTo(profile.points[0].x, profile.points[0].y);
  for (const point of profile.points.slice(1)) ctx.lineTo(point.x, point.y);
  ctx.closePath();
  if (options.fill !== false) ctx.fill();
  ctx.stroke();

  if (options.label) {
    const centre = {
      x: (profile.startCentre.x + profile.endCentre.x) * 0.5,
      y: (profile.startCentre.y + profile.endCentre.y) * 0.5,
    };
    const offset = Math.max(startWidth, endWidth) * 0.78 + 9;
    const labelX = centre.x - profile.normal.x * offset;
    const labelY = centre.y - profile.normal.y * offset;
    ctx.save();
    ctx.font = "950 9px Inter, system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.lineWidth = 4;
    ctx.strokeStyle = "rgba(255, 253, 248, 0.97)";
    ctx.strokeText(options.label, labelX, labelY);
    ctx.fillStyle = options.labelColor ?? "#59358f";
    ctx.fillText(options.label, labelX, labelY);
    ctx.restore();
  }
}

function drawFlushEndCaps2d(ctx, projection, segmentData, connections, pipeWidth) {
  ctx.save();
  ctx.shadowColor = "transparent";
  ctx.lineCap = "butt";
  const palette = drawingPipePalette();

  for (const segment of segmentData) {
    const selected = isSegmentSelected(segment.index);
    const hovered = state.hoveredSegment === segment.index;
    const width = selected || hovered ? 7 : pipeWidth;
    const color = selected ? palette.selected : hovered ? palette.hovered : palette.pipe;

    for (const [nodeIndex, otherIndex] of [[segment.from, segment.to], [segment.to, segment.from]]) {
      if ((connections.get(nodeIndex)?.length ?? 0) !== 1) continue;
      const end = projectIso(state.points[nodeIndex], projection);
      const other = projectIso(state.points[otherIndex], projection);
      const angle = Math.atan2(end.y - other.y, end.x - other.x);
      const normal = { x: -Math.sin(angle), y: Math.cos(angle) };
      const capHalf = width * 0.62;

      ctx.strokeStyle = color;
      ctx.lineWidth = Math.max(2, width * 0.48);
      drawLine(
        ctx,
        { x: end.x + normal.x * capHalf, y: end.y + normal.y * capHalf },
        { x: end.x - normal.x * capHalf, y: end.y - normal.y * capHalf },
      );
    }
  }

  ctx.restore();
}

function drawTeeMarkers2d(ctx, projection, segmentData, connections, pipeWidth) {
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));

  ctx.save();
  const palette = drawingPipePalette();
  ctx.shadowColor = palette.shadow;
  ctx.shadowBlur = 3;
  ctx.lineCap = "butt";
  ctx.lineJoin = "round";

  for (const [nodeIndex, connected] of connections.entries()) {
    if (connected.length < 3) continue;

    const joint = projectIso(state.points[nodeIndex], projection);
    if (nodeConnectionType(nodeIndex) === "branch") {
      const info = branchNodeInfo(nodeIndex, connected, segmentData);
      const branchEntries = info?.branchEntries?.length ? info.branchEntries : [];
      ctx.shadowColor = palette.shadow;
      ctx.strokeStyle = palette.branch;
      ctx.lineWidth = Math.max(3, pipeWidth * 0.42);

      for (const entry of branchEntries) {
        const other = projectIso(state.points[entry.other], projection);
        const vector = normalizeScreenVector({ x: other.x - joint.x, y: other.y - joint.y });
        const normal = { x: -vector.y, y: vector.x };
        const weldHalf = Math.max(6, visualPipeWidth(entry.segment) * 0.7);
        const weldOffset = Math.max(4, visualPipeWidth(entry.segment) * 0.28);

        drawLine(
          ctx,
          { x: joint.x + vector.x * weldOffset + normal.x * -weldHalf, y: joint.y + vector.y * weldOffset + normal.y * -weldHalf },
          { x: joint.x + vector.x * weldOffset + normal.x * weldHalf, y: joint.y + vector.y * weldOffset + normal.y * weldHalf },
        );
        drawLine(
          ctx,
          { x: joint.x + vector.x * 2, y: joint.y + vector.y * 2 },
          { x: joint.x + vector.x * 18, y: joint.y + vector.y * 18 },
        );
      }

      ctx.shadowColor = "transparent";
      ctx.fillStyle = isDarkAppTheme() ? "#061018" : "#fffdf8";
      ctx.strokeStyle = palette.branch;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(joint.x, joint.y, Math.max(4, pipeWidth * 0.45), 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      continue;
    }

    ctx.strokeStyle = palette.tee;
    ctx.lineWidth = pipeWidth + 4;

    for (const connection of connected) {
      const segment = segmentByIndex.get(connection.segmentIndex);
      if (!segment) continue;
      const other = projectIso(state.points[connection.other], projection);
      const vector = normalizeScreenVector({ x: other.x - joint.x, y: other.y - joint.y });
      drawLine(
        ctx,
        { x: joint.x - vector.x * 2, y: joint.y - vector.y * 2 },
        { x: joint.x + vector.x * 18, y: joint.y + vector.y * 18 },
      );
    }

    ctx.shadowColor = "transparent";
    ctx.strokeStyle = palette.highlight;
    ctx.lineWidth = 2;
    for (const connection of connected) {
      const other = projectIso(state.points[connection.other], projection);
      const vector = normalizeScreenVector({ x: other.x - joint.x, y: other.y - joint.y });
      drawLine(
        ctx,
        { x: joint.x, y: joint.y },
        { x: joint.x + vector.x * 15, y: joint.y + vector.y * 15 },
      );
    }
  }

  ctx.restore();
}

function drawPipePointMarkers(ctx, projection, connections = nodeConnections(segments())) {
  const activeIndex = activePointIndex();
  for (const [index, point] of state.points.entries()) {
    const isCurrent = index === activeIndex;
    const isSelected = index === state.selectedPoint;
    const connectionCount = connections.get(index)?.length ?? 0;
    if (!isCurrent && !isSelected && (connectionCount <= 1 || connectionCount >= 3)) {
      continue;
    }

    const screen = projectIso(point, projection);
    ctx.beginPath();
    ctx.fillStyle = isCurrent ? "#f6c45c" : isSelected ? "#d8f1ed" : "#fff";
    ctx.strokeStyle = isSelected ? "#0f766e" : "#1e2a2f";
    ctx.lineWidth = isSelected ? 3 : 2;
    ctx.arc(screen.x, screen.y, isCurrent || isSelected ? 5 : 3.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    if (state.showDimensions && (connectionCount !== 2 || isCurrent || isSelected)) {
      const label = pointLabel(index);
      ctx.font = "900 10px Inter, system-ui, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.lineWidth = 4;
      ctx.strokeStyle = "rgba(255, 253, 248, 0.96)";
      ctx.fillStyle = isSelected ? "#0f766e" : "#263538";
      ctx.strokeText(label, screen.x, screen.y - 16);
      ctx.fillText(label, screen.x, screen.y - 16);
    }
  }
}

function drawNotes2d(ctx, projection) {
  if (!state.notes.length) return;

  ctx.save();
  ctx.font = "900 12px Inter, system-ui, sans-serif";
  ctx.textBaseline = "middle";

  for (const note of state.notes) {
    const point = projectIso(note.point, projection);
    const labelPoint = projectIso(noteLabelPoint(note, projection), projection);
    const text = note.text.trim();
    const metrics = ctx.measureText(text);
    const selected = state.selectedNote === note.id;
    const colour = noteColourStyle(note.colour);
    const paddingX = 8;
    const width = Math.max(44, Math.min(280, metrics.width + paddingX * 2));
    const height = 24;
    const x = labelPoint.x - width / 2;
    const y = labelPoint.y - height / 2;
    const labelCenter = { x: labelPoint.x, y: labelPoint.y };
    const dx = labelCenter.x - point.x;
    const dy = labelCenter.y - point.y;
    const lineLength = Math.hypot(dx, dy) || 1;
    const edgeInset = {
      x: dx / lineLength * Math.min(width / 2, Math.max(10, width * 0.42)),
      y: dy / lineLength * Math.min(height / 2, 10),
    };
    const labelEdge = {
      x: labelCenter.x - edgeInset.x,
      y: labelCenter.y - edgeInset.y,
    };

    ctx.strokeStyle = selected ? colour.line : colour.border;
    ctx.fillStyle = colour.fill;
    ctx.lineWidth = selected ? 2 : 1;
    roundRect(ctx, x, y, width, height, 6);
    ctx.fill();
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(point.x, point.y);
    ctx.lineTo(labelEdge.x, labelEdge.y);
    ctx.strokeStyle = colour.line;
    ctx.lineWidth = selected ? 2.2 : 1.5;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(point.x, point.y, selected ? 4.5 : 3.5, 0, Math.PI * 2);
    ctx.fillStyle = colour.line;
    ctx.fill();

    ctx.fillStyle = colour.text;
    ctx.fillText(text, x + paddingX, labelCenter.y + 1);
  }

  ctx.restore();
}

function drawMeasurements2d(ctx, projection) {
  const measurements = Array.isArray(state.measurements) ? state.measurements : [];
  if (!measurements.length && !measurementDraft) return;

  ctx.save();
  for (const measurement of measurements) {
    drawMeasurement2d(ctx, projection, measurement, state.selectedMeasurement === measurement.id);
  }

  if (measurementDraft && state.pointer) {
    const picked = measurePointFromPointer(state.pointer);
    const previewMeasurement = {
      id: 0,
      start: measurementDraft.start,
      end: picked.point,
      label: "",
    };
    if (measurementLengthMm(previewMeasurement) >= 1) {
      drawMeasurement2d(ctx, projection, previewMeasurement, true, { preview: true });
    }
  }
  ctx.restore();
}

function drawMeasurement2d(ctx, projection, measurement, selected = false, options = {}) {
  const start = projectIso(measurement.start, projection);
  const end = projectIso(measurement.end, projection);
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const screenLength = Math.hypot(dx, dy);
  if (screenLength < 8) return;

  const along = { x: dx / screenLength, y: dy / screenLength };
  const normal = { x: -along.y, y: along.x };
  const midpoint = { x: (start.x + end.x) * 0.5, y: (start.y + end.y) * 0.5 };
  const label = measurementLabel(measurement);
  const tick = 8;
  const color = selected ? "#008fb3" : "#526c78";
  const labelFill = selected ? "rgba(216, 241, 237, 0.96)" : "rgba(255, 253, 248, 0.96)";
  let labelAngle = Math.atan2(dy, dx);
  if (labelAngle > Math.PI / 2 || labelAngle < -Math.PI / 2) {
    labelAngle += Math.PI;
  }

  ctx.save();
  ctx.setLineDash(options.preview ? [8, 5] : []);
  ctx.lineCap = "butt";
  ctx.lineJoin = "miter";
  for (const stroke of [
    { color: "rgba(255, 253, 248, 0.92)", width: 5 },
    { color, width: selected ? 3 : 2 },
  ]) {
    ctx.strokeStyle = stroke.color;
    ctx.lineWidth = stroke.width;
    drawLine(ctx, start, end);
    for (const point of [start, end]) {
      drawLine(
        ctx,
        { x: point.x + normal.x * tick, y: point.y + normal.y * tick },
        { x: point.x - normal.x * tick, y: point.y - normal.y * tick },
      );
    }
  }
  ctx.setLineDash([]);

  ctx.font = "950 12px Inter, system-ui, sans-serif";
  const labelWidth = ctx.measureText(label).width + 22;
  const labelHeight = 24;
  ctx.translate(midpoint.x + normal.x * 18, midpoint.y + normal.y * 18);
  ctx.rotate(labelAngle);
  roundRect(ctx, -labelWidth * 0.5, -labelHeight * 0.5, labelWidth, labelHeight, 6);
  ctx.fillStyle = labelFill;
  ctx.fill();
  ctx.strokeStyle = selected ? "rgba(0, 143, 179, 0.55)" : "rgba(82, 108, 120, 0.28)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = color;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(label, 0, 0.5);
  ctx.restore();
}

function roundRect(ctx, x, y, width, height, radius) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + width - radius, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
  ctx.lineTo(x + width, y + height - radius);
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
  ctx.lineTo(x + radius, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
}

function drawDimension(ctx, segment, start, end, dimensionLayout = []) {
  const dimensionStyle = normalizeDimensionStyle(state.dimensionStyle);
  if (isLineDimensionStyle(dimensionStyle)) {
    drawRedCentreDimension(ctx, segment, start, end, dimensionLayout);
    return;
  }

  const midpoint = {
    x: (start.x + end.x) * 0.5,
    y: (start.y + end.y) * 0.5,
  };
  const angle = Math.atan2(end.y - start.y, end.x - start.x);
  const normal = { x: -Math.sin(angle), y: Math.cos(angle) };
  const text = offsetDimensionText(segment) ?? `C/C ${formatLength(pointLength(segment.vector))} mm`;
  const x = midpoint.x + normal.x * 20;
  const y = midpoint.y + normal.y * 20;

  ctx.save();
  ctx.font = "800 12px Inter, system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.lineWidth = 5;
  ctx.strokeStyle = "rgba(255, 253, 248, 0.92)";
  ctx.strokeText(text, x, y);
  ctx.fillStyle = "#42505a";
  ctx.fillText(text, x, y);
  ctx.restore();
}

function drawRedCentreDimension(ctx, segment, start, end, dimensionLayout = []) {
  const layoutState = Array.isArray(dimensionLayout)
    ? { labels: dimensionLayout, lines: [], pipes: [] }
    : dimensionLayout;
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const screenLength = Math.hypot(dx, dy);
  if (screenLength < 8) return;

  const along = { x: dx / screenLength, y: dy / screenLength };
  const baseNormal = { x: -along.y, y: along.x };
  const pipeGap = 9;
  const tick = 6;
  const fullText = offsetDimensionText(segment, { short: true }) ?? `${formatLength(pointLength(segment.vector))} mm`;
  const legendText = segmentOffsetMeta(segment)
    ? `Run ${segment.index + 1}: ${offsetDimensionText(segment)} / factor ${offsetTravelMultiplier(segment.offsetAngleDeg).toFixed(3)}`
    : `Run ${segment.index + 1}: C/C ${fullText}`;
  const text = dimensionLabelText(layoutState, fullText, legendText, "D", {
    type: "segment",
    segmentIndex: segment.index,
  });
  const compactNumbered = layoutState.compactNumbered === true;
  const baseOffset = compactNumbered
    ? Math.min(42, Math.max(28, screenLength * 0.045))
    : Math.min(64, Math.max(42, screenLength * 0.065));
  const manualOffset = dimensionOffsetForSegment(segment.index);
  let labelAngle = Math.atan2(along.y, along.x);
  if (labelAngle > Math.PI / 2 || labelAngle < -Math.PI / 2) {
    labelAngle += Math.PI;
  }

  ctx.save();
  ctx.font = "900 13px Inter, system-ui, sans-serif";
  const metrics = ctx.measureText(text);
  const labelWidth = metrics.width + 20;
  const labelHeight = 23;
  const layout = redDimensionLayout(start, end, baseNormal, baseOffset, pipeGap, labelWidth, labelHeight, labelAngle, layoutState, segment.index, {
    manual: manualOffset.offset > 0.5 ? manualOffset : null,
  });
  const { lineStart, lineEnd, midpoint, normal } = layout;
  const { extensionStart, extensionEnd } = layout;
  const palette = dimensionLinePalette();

  ctx.shadowColor = palette.shadow;
  ctx.shadowBlur = 2;
  ctx.lineCap = "butt";
  ctx.lineJoin = "miter";

  for (const stroke of [
    { color: palette.halo, width: 5 },
    { color: palette.line, width: 2 },
  ]) {
    ctx.strokeStyle = stroke.color;
    ctx.lineWidth = stroke.width;
    drawLine(ctx, lineStart, lineEnd);
    drawLine(ctx, extensionStart, lineStart);
    drawLine(ctx, extensionEnd, lineEnd);
    for (const point of [lineStart, lineEnd]) {
      drawLine(
        ctx,
        { x: point.x + normal.x * tick + along.x * -tick, y: point.y + normal.y * tick + along.y * -tick },
        { x: point.x + normal.x * -tick + along.x * tick, y: point.y + normal.y * -tick + along.y * tick },
      );
    }
  }

  ctx.shadowColor = "transparent";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.translate(midpoint.x, midpoint.y);
  ctx.rotate(labelAngle);
  roundRect(ctx, -labelWidth * 0.5, -labelHeight * 0.5, labelWidth, labelHeight, 6);
  ctx.fillStyle = palette.fill;
  ctx.fill();
  ctx.strokeStyle = palette.border;
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = palette.text;
  ctx.fillText(text, 0, 0.5);
  layoutState.labels.push(layout.bounds);
  layoutState.lines.push(...layout.lines);
  addDimensionHitTarget({
    type: "segment",
    segmentIndex: segment.index,
    bounds: layout.bounds,
    lines: layout.lines,
    normal,
    side: layout.side,
    offset: layout.offset,
    baseOffset,
  });
  ctx.restore();
}

function offsetSetDimensionPoints(segment) {
  const meta = segmentOffsetMeta(segment);
  if (!meta) return null;

  const setEnd = { ...segment.start };
  if (meta.plane === "xy") {
    setEnd.y = segment.end.y;
  } else {
    setEnd.z = segment.end.z;
  }

  if (pointLength(subtractPoints(setEnd, segment.start)) < 1) return null;
  return {
    meta,
    start: segment.start,
    end: setEnd,
    travelEnd: segment.end,
  };
}

function drawOffsetSetDimensions(ctx, projection, segmentData, dimensionLayout = []) {
  for (const segment of segmentData) {
    const points = offsetSetDimensionPoints(segment);
    if (!points) continue;
    drawOffsetSetDimension(
      ctx,
      segment,
      projectIso(points.start, projection),
      projectIso(points.end, projection),
      points.meta,
      dimensionLayout,
      projectIso(points.travelEnd, projection),
    );
  }
}

function drawOffsetSetDimension(ctx, segment, start, end, meta, dimensionLayout = [], travelEnd = null) {
  const layoutState = Array.isArray(dimensionLayout)
    ? { labels: dimensionLayout, lines: [], pipes: [] }
    : dimensionLayout;
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const screenLength = Math.hypot(dx, dy);
  if (screenLength < 10) return;

  const along = { x: dx / screenLength, y: dy / screenLength };
  const baseNormal = { x: -along.y, y: along.x };
  const pipeGap = 13;
  const fullText = `C/C ${formatLength(meta.setMm)} mm`;
  const legendText = `Run ${segment.index + 1}: offset C/C ${formatLength(meta.setMm)} mm / travel ${formatLength(meta.travelMm)} mm / ${formatAngle(meta.angleDeg)} deg`;
  const text = dimensionLabelText(layoutState, fullText, legendText, "O", {
    type: "offset-set",
    segmentIndex: segment.index,
  });
  const compactNumbered = layoutState.compactNumbered === true;
  const baseOffset = compactNumbered
    ? Math.min(68, Math.max(40, screenLength * 0.09))
    : Math.min(104, Math.max(58, screenLength * 0.14));
  const manualOffset = dimensionOffsetForSegment(segment.index);
  let labelAngle = Math.atan2(along.y, along.x);
  if (labelAngle > Math.PI / 2 || labelAngle < -Math.PI / 2) {
    labelAngle += Math.PI;
  }

  ctx.save();
  ctx.font = "950 12px Inter, system-ui, sans-serif";
  const metrics = ctx.measureText(text);
  const labelWidth = metrics.width + 22;
  const labelHeight = 24;
  const layout = redDimensionLayout(start, end, baseNormal, baseOffset, pipeGap, labelWidth, labelHeight, labelAngle, layoutState, segment.index, {
    manual: manualOffset.offset > 0.5 ? manualOffset : null,
  });
  const { lineStart, lineEnd, midpoint, normal } = layout;
  const { extensionStart, extensionEnd } = layout;
  const lineAngle = Math.atan2(lineEnd.y - lineStart.y, lineEnd.x - lineStart.x);
  const palette = dimensionLinePalette();

  ctx.shadowColor = palette.shadow;
  ctx.shadowBlur = 3;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  for (const stroke of [
    { color: palette.halo, width: 6 },
    { color: palette.line, width: 2.4 },
  ]) {
    ctx.strokeStyle = stroke.color;
    ctx.lineWidth = stroke.width;
    drawLine(ctx, lineStart, lineEnd);
    drawLine(ctx, extensionStart, lineStart);
    drawLine(ctx, extensionEnd, lineEnd);
    drawArrowHead(ctx, lineStart, lineAngle, stroke.width);
    drawArrowHead(ctx, lineEnd, lineAngle + Math.PI, stroke.width);
  }

  ctx.shadowColor = "transparent";
  const witnessDistance = travelEnd ? Math.hypot(travelEnd.x - end.x, travelEnd.y - end.y) : 0;
  if (witnessDistance > 8) {
    ctx.setLineDash([5, 5]);
    for (const stroke of [
      { color: palette.halo, width: 5 },
      { color: "rgba(31, 42, 47, 0.58)", width: 1.7 },
    ]) {
      ctx.strokeStyle = stroke.color;
      ctx.lineWidth = stroke.width;
      drawLine(ctx, end, travelEnd);
    }
    ctx.setLineDash([]);
  }

  for (const point of [start, end]) {
    ctx.beginPath();
    ctx.arc(point.x, point.y, 5, 0, Math.PI * 2);
    ctx.fillStyle = palette.fill;
    ctx.fill();
    ctx.strokeStyle = palette.line;
    ctx.lineWidth = 2;
    ctx.stroke();
    drawLine(ctx, { x: point.x - 7, y: point.y }, { x: point.x + 7, y: point.y });
    drawLine(ctx, { x: point.x, y: point.y - 7 }, { x: point.x, y: point.y + 7 });
  }

  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.translate(midpoint.x, midpoint.y);
  ctx.rotate(labelAngle);
  roundRect(ctx, -labelWidth * 0.5, -labelHeight * 0.5, labelWidth, labelHeight, 6);
  ctx.fillStyle = palette.fill;
  ctx.fill();
  ctx.strokeStyle = palette.border;
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = palette.text;
  ctx.fillText(text, 0, 0.5);
  layoutState.labels.push(layout.bounds);
  layoutState.lines.push(...layout.lines);
  addDimensionHitTarget({
    type: "offset-set",
    segmentIndex: segment.index,
    bounds: layout.bounds,
    lines: layout.lines,
    normal,
    side: layout.side,
    offset: layout.offset,
    baseOffset,
  });
  ctx.restore();
}

function compactPipeSizeLabelIndexes(segmentData) {
  const byIndex = new Map(segmentData.map((segment) => [segment.index, segment]));
  const byNode = new Map();
  for (const segment of segmentData) {
    for (const nodeIndex of [segment.from, segment.to]) {
      const list = byNode.get(nodeIndex) ?? [];
      list.push(segment);
      byNode.set(nodeIndex, list);
    }
  }

  const selected = new Set();
  const visited = new Set();
  for (const segment of segmentData) {
    if (visited.has(segment.index)) continue;
    const nb = pipeSizeForSegment(segment).nb;
    const group = [];
    const stack = [segment.index];
    visited.add(segment.index);
    while (stack.length) {
      const index = stack.pop();
      const current = byIndex.get(index);
      if (!current) continue;
      group.push(current);
      for (const nodeIndex of [current.from, current.to]) {
        for (const next of byNode.get(nodeIndex) ?? []) {
          if (visited.has(next.index)) continue;
          if (pipeSizeForSegment(next).nb !== nb) continue;
          visited.add(next.index);
          stack.push(next.index);
        }
      }
    }
    const best = group.sort((first, second) => pointLength(second.vector) - pointLength(first.vector))[0];
    if (best) selected.add(best.index);
  }

  for (const connected of byNode.values()) {
    const sizes = new Map();
    for (const segment of connected) {
      const nb = pipeSizeForSegment(segment).nb;
      const current = sizes.get(nb);
      if (!current || pointLength(segment.vector) > pointLength(current.vector)) {
        sizes.set(nb, segment);
      }
    }
    if (sizes.size > 1) {
      for (const segment of sizes.values()) {
        selected.add(segment.index);
      }
    }
  }

  return selected;
}

function drawPipeSizeLabels2d(ctx, projection, segmentData, dimensionLayout = [], options = {}) {
  const layoutState = Array.isArray(dimensionLayout)
    ? { labels: dimensionLayout, pipes: [] }
    : dimensionLayout;
  const labels = layoutState.labels ?? [];
  const pipes = layoutState.pipes ?? [];
  const viewport = layoutState.viewport ?? dimensionViewport(ctx, 18);
  const compactLabels = drawingPipeSizeLabelMode(options) === "compact" ? compactPipeSizeLabelIndexes(segmentData) : null;

  ctx.save();
  ctx.font = "900 10.5px Inter, system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";

  for (const segment of segmentData) {
    if (compactLabels && !compactLabels.has(segment.index)) continue;
    const start = projectIso(segment.start, projection);
    const end = projectIso(segment.end, projection);
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const screenLength = Math.hypot(dx, dy);
    if (screenLength < 64) continue;

    const along = { x: dx / screenLength, y: dy / screenLength };
    const normal = { x: -along.y, y: along.x };
    const text = pipeSizeSpecLabel(pipeSizeForSegment(segment));
    const labelWidth = ctx.measureText(text).width + 14;
    const labelHeight = 19;
    const midpoint = { x: (start.x + end.x) * 0.5, y: (start.y + end.y) * 0.5 };
    const candidates = [];
    for (const side of [-1, 1]) {
      for (const level of [0, 1, 2, 3]) {
        const offset = 18 + level * 20;
        const center = {
          x: midpoint.x + normal.x * offset * side,
          y: midpoint.y + normal.y * offset * side,
        };
        const rawBounds = {
          left: center.x - labelWidth * 0.5,
          right: center.x + labelWidth * 0.5,
          top: center.y - labelHeight * 0.5,
          bottom: center.y + labelHeight * 0.5,
        };
        const shift = dimensionLabelShiftForViewport(rawBounds, viewport);
        const bounds = shiftBounds(rawBounds, shift.x, shift.y);
        const overlapPenalty = labels.reduce((sum, existing) => sum + boundsOverlapArea(bounds, existing), 0) * 80;
        const pipePenalty = pipes.reduce((sum, pipe) => (
          pipe.index === segment.index || segmentIntersectsBounds(pipe.start, pipe.end, inflateBounds(bounds, 2))
            ? sum + 1600
            : sum
        ), 0);
        candidates.push({ center: { x: center.x + shift.x, y: center.y + shift.y }, bounds, score: overlapPenalty + pipePenalty + level * 10 });
      }
    }
    candidates.sort((a, b) => a.score - b.score);
    const chosen = candidates[0];
    if (!chosen) continue;

    ctx.shadowColor = isDarkAppTheme() ? "rgba(0, 0, 0, 0.32)" : "rgba(31, 42, 47, 0.1)";
    ctx.shadowBlur = 4;
    roundRect(ctx, chosen.bounds.left, chosen.bounds.top, labelWidth, labelHeight, 6);
    ctx.fillStyle = isDarkAppTheme() ? "rgba(7, 24, 36, 0.88)" : "rgba(239, 250, 247, 0.94)";
    ctx.fill();
    ctx.shadowColor = "transparent";
    ctx.strokeStyle = isDarkAppTheme() ? "rgba(19, 216, 255, 0.4)" : "rgba(15, 118, 110, 0.22)";
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = isDarkAppTheme() ? "#dffbff" : "#0f5f62";
    ctx.fillText(text, chosen.center.x, chosen.center.y + 0.5);
    labels.push(inflateBounds(chosen.bounds, 3));
  }

  ctx.restore();
}

function drawWeakestPressureCallout2d(ctx, projection, segmentData, dimensionLayout = [], options = {}) {
  const rating = weakestPressureEstimate(segmentData);
  if (!rating) return;

  const segment = segmentData.find((item) => item.index === rating.segment.index) ?? rating.segment;
  if (!segment) return;

  const start = projectIso(segment.start, projection);
  const end = projectIso(segment.end, projection);
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const screenLength = Math.hypot(dx, dy);
  if (screenLength < 18) return;

  const layoutState = Array.isArray(dimensionLayout)
    ? { labels: dimensionLayout, pipes: [], viewport: dimensionViewport(ctx, 18) }
    : dimensionLayout;
  const labels = layoutState.labels ?? [];
  const pipes = layoutState.pipes ?? [];
  const viewport = layoutState.viewport ?? dimensionViewport(ctx, 18);
  const along = { x: dx / screenLength, y: dy / screenLength };
  const normal = { x: -along.y, y: along.x };
  const target = { x: (start.x + end.x) * 0.5, y: (start.y + end.y) * 0.5 };
  const title = "Weakest pressure";
  const detail = `${pipeSizeDisplayLabel(rating.size)} / ${formatPressureStandard(rating.pressureBar)}`;
  const dark = isDarkAppTheme();

  ctx.save();
  ctx.font = "950 11px Inter, system-ui, sans-serif";
  const titleWidth = ctx.measureText(title).width;
  ctx.font = "900 10px Inter, system-ui, sans-serif";
  const detailWidth = ctx.measureText(detail).width;
  const badgeWidth = Math.max(titleWidth, detailWidth) + 26;
  const badgeHeight = 42;
  const candidates = [];
  for (const side of [-1, 1]) {
    for (const level of [0, 1, 2, 3, 4]) {
      const offset = 38 + level * 24;
      const lead = Math.min(24, screenLength * 0.08);
      const center = {
        x: target.x + normal.x * offset * side + along.x * lead,
        y: target.y + normal.y * offset * side + along.y * lead,
      };
      const rawBounds = {
        left: center.x - badgeWidth * 0.5,
        right: center.x + badgeWidth * 0.5,
        top: center.y - badgeHeight * 0.5,
        bottom: center.y + badgeHeight * 0.5,
      };
      const shift = dimensionLabelShiftForViewport(rawBounds, viewport);
      const bounds = shiftBounds(rawBounds, shift.x, shift.y);
      const overlapPenalty = labels.reduce((sum, existing) => sum + boundsOverlapArea(bounds, existing), 0) * 55;
      const pipePenalty = pipes.reduce((sum, pipe) => (
        pipe.index === segment.index || segmentIntersectsBounds(pipe.start, pipe.end, inflateBounds(bounds, 4))
          ? sum + 900
          : sum
      ), 0);
      candidates.push({
        center: { x: center.x + shift.x, y: center.y + shift.y },
        bounds,
        score: overlapPenalty + pipePenalty + level * 18 + (side < 0 ? 4 : 0),
      });
    }
  }

  const chosen = candidates.sort((a, b) => a.score - b.score)[0];
  if (!chosen) {
    ctx.restore();
    return;
  }

  const markerRadius = options.export ? 5 : 6;
  const lineColor = dark ? "#ffc857" : "#b45309";
  const fillColor = dark ? "rgba(11, 25, 37, 0.96)" : "rgba(255, 251, 235, 0.96)";
  const strokeColor = dark ? "rgba(255, 200, 87, 0.78)" : "rgba(180, 83, 9, 0.42)";
  const titleColor = dark ? "#ffe8a3" : "#7c2d12";
  const detailColor = dark ? "#ecfeff" : "#223236";
  const tailEnd = {
    x: clampNumber(chosen.center.x, chosen.bounds.left + 10, chosen.bounds.right - 10),
    y: clampNumber(chosen.center.y, chosen.bounds.top + 10, chosen.bounds.bottom - 10),
  };

  ctx.shadowColor = dark ? "rgba(255, 200, 87, 0.26)" : "rgba(31, 42, 47, 0.16)";
  ctx.shadowBlur = dark ? 12 : 8;
  ctx.shadowOffsetY = 2;
  ctx.strokeStyle = lineColor;
  ctx.lineWidth = 2;
  ctx.setLineDash([6, 5]);
  drawLine(ctx, target, tailEnd);
  ctx.setLineDash([]);

  ctx.beginPath();
  ctx.fillStyle = lineColor;
  ctx.arc(target.x, target.y, markerRadius, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = dark ? "rgba(6, 18, 28, 0.96)" : "rgba(255, 253, 248, 0.96)";
  ctx.lineWidth = 3;
  ctx.stroke();

  roundRect(ctx, chosen.bounds.left, chosen.bounds.top, badgeWidth, badgeHeight, 8);
  ctx.fillStyle = fillColor;
  ctx.fill();
  ctx.shadowColor = "transparent";
  ctx.strokeStyle = strokeColor;
  ctx.lineWidth = 1.2;
  ctx.stroke();

  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.font = "950 11px Inter, system-ui, sans-serif";
  ctx.fillStyle = titleColor;
  ctx.fillText(title, chosen.bounds.left + 13, chosen.bounds.top + 17);
  ctx.font = "900 10px Inter, system-ui, sans-serif";
  ctx.fillStyle = detailColor;
  ctx.fillText(fitCanvasText(ctx, detail, badgeWidth - 26), chosen.bounds.left + 13, chosen.bounds.top + 32);
  labels.push(inflateBounds(chosen.bounds, 4));
  ctx.restore();
}

function dimensionLabelText(layoutState, displayText, legendText, prefix = "D", target = {}) {
  if (normalizeDimensionStyle(state.dimensionStyle) !== "numbered") return displayText;
  layoutState.numberedItems ??= [];
  const code = `${prefix}${layoutState.numberedItems.length + 1}`;
  layoutState.numberedItems.push({
    code,
    text: legendText,
    target,
  });
  return code;
}

function drawNumberedDimensionLegend(ctx, dimensionLayout) {
  if (normalizeDimensionStyle(state.dimensionStyle) !== "numbered") return;
  const items = dimensionLayout?.numberedItems ?? [];
  if (!items.length) return;

  const viewport = dimensionLayout?.viewport ?? dimensionViewport(ctx, 12);
  const dark = isDarkAppTheme();
  const palette = dimensionLinePalette();
  const availableHeight = Math.max(80, viewport.bottom - viewport.top);
  const maxItems = Math.max(3, Math.min(18, Math.floor((availableHeight - 64) / 16)));
  const visibleItems = items.slice(0, maxItems);
  const overflowCount = items.length - visibleItems.length;

  ctx.save();
  ctx.font = "900 11px Inter, system-ui, sans-serif";
  const maxTextWidth = Math.min(210, Math.max(118, (viewport.right - viewport.left) * 0.36));
  const lineHeight = 16;
  const titleHeight = 36;
  const columns = visibleItems.length > 9 && viewport.right - viewport.left > 560 ? 2 : 1;
  const rows = Math.ceil((visibleItems.length + (overflowCount > 0 ? 1 : 0)) / columns);
  const colWidth = maxTextWidth + 36;
  const gap = columns > 1 ? 12 : 0;
  const padding = 10;
  const cardWidth = Math.min(viewport.right - viewport.left, columns * colWidth + gap + padding * 2);
  const cardHeight = titleHeight + rows * lineHeight + padding * 2;
  const x = viewport.right - cardWidth;
  const cornerReserve = projectCornerTagHeight(12) + 8;
  const y = Math.min(
    viewport.top + cornerReserve,
    Math.max(viewport.top, viewport.bottom - cardHeight),
  );

  ctx.shadowColor = dark ? "rgba(0, 0, 0, 0.42)" : "rgba(31, 42, 47, 0.14)";
  ctx.shadowBlur = dark ? 14 : 10;
  ctx.shadowOffsetY = 4;
  roundRect(ctx, x, y, cardWidth, cardHeight, 8);
  ctx.fillStyle = dark ? "rgba(6, 18, 28, 0.94)" : "rgba(255, 253, 248, 0.94)";
  ctx.fill();
  ctx.shadowColor = "transparent";
  ctx.strokeStyle = palette.border;
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.fillStyle = palette.text;
  ctx.font = "950 11px Inter, system-ui, sans-serif";
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.fillText("Dimension key - editable", x + padding, y + padding + 10);
  ctx.fillStyle = dark ? "rgba(203, 224, 235, 0.78)" : "#4b6468";
  ctx.font = "850 9.5px Inter, system-ui, sans-serif";
  ctx.fillText(fitCanvasText(ctx, "Select mode: click D/O rows to change C/C", cardWidth - padding * 2), x + padding, y + padding + 25);

  ctx.font = "850 10.5px Inter, system-ui, sans-serif";
  const listItems = overflowCount > 0
    ? [...visibleItems, { code: "...", text: `${overflowCount} more in Cut List` }]
    : visibleItems;

  listItems.forEach((item, index) => {
    const column = columns > 1 ? Math.floor(index / rows) : 0;
    const row = columns > 1 ? index % rows : index;
    const itemX = x + padding + column * (colWidth + gap);
    const itemY = y + padding + titleHeight + row * lineHeight + 10;
    const rowBounds = {
      left: itemX - 4,
      right: itemX + colWidth - 6,
      top: itemY - lineHeight + 3,
      bottom: itemY + 4,
    };
    const editableKey = item.target?.type === "segment" || item.target?.type === "offset-set";
    if (editableKey && item.code !== "...") {
      ctx.fillStyle = dark ? "rgba(19, 216, 255, 0.14)" : "rgba(19, 216, 255, 0.08)";
      roundRect(ctx, rowBounds.left, rowBounds.top, rowBounds.right - rowBounds.left, rowBounds.bottom - rowBounds.top, 5);
      ctx.fill();
    }
    if (item.code !== "..." && editableKey && Number.isInteger(item.target?.segmentIndex)) {
      addDimensionHitTarget({
        type: "dimension-key",
        sourceType: item.target.type,
        segmentIndex: item.target.segmentIndex,
        code: item.code,
        bounds: rowBounds,
        lines: [],
      });
    }
    ctx.fillStyle = item.code === "..." ? (dark ? "#7f93a4" : "#657579") : palette.text;
    ctx.fillText(item.code, itemX, itemY);
    ctx.fillStyle = dark ? "#ecfeff" : "#263538";
    const showEditTag = editableKey && item.code !== "..." && colWidth > 138;
    const itemTextWidth = showEditTag ? Math.max(72, maxTextWidth - 34) : maxTextWidth;
    ctx.fillText(fitCanvasText(ctx, item.text, itemTextWidth), itemX + 28, itemY);
    if (showEditTag) {
      ctx.fillStyle = "#0f766e";
      if (dark) ctx.fillStyle = "#13d8ff";
      ctx.font = "900 8.5px Inter, system-ui, sans-serif";
      ctx.fillText("edit", rowBounds.right - 24, itemY);
      ctx.font = "850 10.5px Inter, system-ui, sans-serif";
    }
  });

  ctx.restore();
}

function fitCanvasText(ctx, text, maxWidth) {
  const value = String(text ?? "");
  if (ctx.measureText(value).width <= maxWidth) return value;
  let trimmed = value;
  while (trimmed.length > 4 && ctx.measureText(`${trimmed}...`).width > maxWidth) {
    trimmed = trimmed.slice(0, -1);
  }
  return `${trimmed.trimEnd()}...`;
}

function drawSocketPositionDimensions(ctx, projection, segmentData, dimensionLayout = []) {
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));
  const socketsBySegment = new Map();
  for (const fitting of state.fittings.filter((item) => item.type === "socket")) {
    if (!segmentByIndex.has(fitting.segmentIndex)) continue;
    if (!socketsBySegment.has(fitting.segmentIndex)) socketsBySegment.set(fitting.segmentIndex, []);
    socketsBySegment.get(fitting.segmentIndex).push(fitting);
  }

  let dimensionIndex = 0;
  const sortedGroups = [...socketsBySegment.entries()].sort(([firstIndex], [secondIndex]) => firstIndex - secondIndex);
  for (const [segmentIndex, socketFittings] of sortedGroups) {
    const segment = segmentByIndex.get(segmentIndex);
    if (!segment) continue;
    const orderedSockets = socketFittings
      .map((fitting) => ({
        fitting,
        worldPoint: lerpPoint(segment.start, segment.end, fitting.t),
        distanceFromStart: pointLength(subtractPoints(lerpPoint(segment.start, segment.end, fitting.t), segment.start)),
      }))
      .sort((first, second) => first.fitting.t - second.fitting.t);

    let previousPoint = segment.start;
    let previousDistance = 0;
    for (const [socketIndex, socket] of orderedSockets.entries()) {
      const start = projectIso(previousPoint, projection);
      const socketPoint = projectIso(socket.worldPoint, projection);
      const distanceMm = socketIndex === 0
        ? socket.distanceFromStart
        : Math.max(0, socket.distanceFromStart - previousDistance);
      drawRedSocketPositionDimension(
        ctx,
        start,
        socketPoint,
        segment.index,
        distanceMm,
        dimensionIndex,
        dimensionLayout,
        socket.fitting,
        socketIndex > 0,
      );
      previousPoint = socket.worldPoint;
      previousDistance = socket.distanceFromStart;
      dimensionIndex += 1;
    }
  }
}

function drawRedSocketPositionDimension(ctx, start, socketPoint, segmentIndex, distanceMm, socketIndex, dimensionLayout = [], fitting = null, isCentreToCentre = false) {
  const layoutState = Array.isArray(dimensionLayout)
    ? { labels: dimensionLayout, lines: [], pipes: [] }
    : dimensionLayout;
  const dx = socketPoint.x - start.x;
  const dy = socketPoint.y - start.y;
  const screenLength = Math.hypot(dx, dy);
  if (screenLength < 8) return;

  const along = { x: dx / screenLength, y: dy / screenLength };
  const baseNormal = { x: -along.y, y: along.x };
  const pipeGap = 11;
  const tick = 5;
  const socketLabel = socketSizeChoiceLabel(fittingSocketSizeNb(fitting));
  const fullText = isCentreToCentre
    ? `${socketLabel} SOCK C/C ${formatLength(distanceMm)} mm`
    : `${socketLabel} SOCK ${formatLength(distanceMm)} mm`;
  const text = dimensionLabelText(layoutState, fullText, `Run ${segmentIndex + 1}: ${fullText}`, "S", {
    type: "socket",
    segmentIndex,
  });
  const baseOffset = Math.min(92, Math.max(56, screenLength * 0.08)) + (socketIndex % 3) * 18;
  let labelAngle = Math.atan2(along.y, along.x);
  if (labelAngle > Math.PI / 2 || labelAngle < -Math.PI / 2) {
    labelAngle += Math.PI;
  }

  ctx.save();
  ctx.font = "900 11px Inter, system-ui, sans-serif";
  const metrics = ctx.measureText(text);
  const labelWidth = metrics.width + 18;
  const labelHeight = 21;
  const layout = redDimensionLayout(start, socketPoint, baseNormal, baseOffset, pipeGap, labelWidth, labelHeight, labelAngle, layoutState, segmentIndex);
  const { lineStart, lineEnd, midpoint, normal } = layout;
  const { extensionStart, extensionEnd } = layout;
  const palette = dimensionLinePalette();

  ctx.shadowColor = palette.shadow;
  ctx.shadowBlur = 2;
  ctx.lineCap = "butt";
  ctx.lineJoin = "miter";

  for (const stroke of [
    { color: palette.halo, width: 5 },
    { color: palette.line, width: 2 },
  ]) {
    ctx.strokeStyle = stroke.color;
    ctx.lineWidth = stroke.width;
    drawLine(ctx, lineStart, lineEnd);
    drawLine(ctx, extensionStart, lineStart);
    drawLine(ctx, extensionEnd, lineEnd);
    drawLine(
      ctx,
      { x: lineEnd.x + normal.x * tick + along.x * -tick, y: lineEnd.y + normal.y * tick + along.y * -tick },
      { x: lineEnd.x + normal.x * -tick + along.x * tick, y: lineEnd.y + normal.y * -tick + along.y * tick },
    );
  }

  ctx.shadowColor = "transparent";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.translate(midpoint.x, midpoint.y);
  ctx.rotate(labelAngle);
  roundRect(ctx, -labelWidth * 0.5, -labelHeight * 0.5, labelWidth, labelHeight, 6);
  ctx.fillStyle = palette.fill;
  ctx.fill();
  ctx.strokeStyle = palette.border;
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = palette.text;
  ctx.fillText(text, 0, 0.5);
  layoutState.labels.push(layout.bounds);
  layoutState.lines.push(...layout.lines);
  ctx.restore();
}

function drawLugPositionDimension2d(ctx, projection, lug, dimensionLayout = [], lugIndex = 0) {
  if (!lug?.segment || !lug?.point) return;

  const start = projectIso(lug.segment.start, projection);
  const lugPoint = projectIso(lug.point, projection);
  const distanceMm = Number.isFinite(lug.distanceFromRunStartMm)
    ? lug.distanceFromRunStartMm
    : pointLength(subtractPoints(lug.point, lug.segment.start));
  const text = `LUG ${lug.number ?? lugIndex + 1} ${formatLength(distanceMm)} mm`;

  drawLugDimensionLine(ctx, start, lugPoint, lug.segment.index, text, dimensionLayout, lugIndex);
}

function drawLugDimensionLine(ctx, start, end, segmentIndex, text, dimensionLayout = [], lugIndex = 0) {
  const layoutState = Array.isArray(dimensionLayout)
    ? { labels: dimensionLayout, lines: [], pipes: [] }
    : dimensionLayout;
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const screenLength = Math.hypot(dx, dy);
  if (screenLength < 10) return;

  const along = { x: dx / screenLength, y: dy / screenLength };
  const baseNormal = { x: -along.y, y: along.x };
  const pipeGap = 12;
  const baseOffset = Math.min(96, Math.max(54, screenLength * 0.1)) + (lugIndex % 2) * 20;
  let labelAngle = Math.atan2(along.y, along.x);
  if (labelAngle > Math.PI / 2 || labelAngle < -Math.PI / 2) {
    labelAngle += Math.PI;
  }

  ctx.save();
  ctx.font = "950 11px Inter, system-ui, sans-serif";
  const labelWidth = ctx.measureText(text).width + 18;
  const labelHeight = 22;
  const layout = redDimensionLayout(start, end, baseNormal, baseOffset, pipeGap, labelWidth, labelHeight, labelAngle, layoutState, segmentIndex);
  const { lineStart, lineEnd, midpoint } = layout;
  const { extensionStart, extensionEnd } = layout;
  const lineAngle = Math.atan2(lineEnd.y - lineStart.y, lineEnd.x - lineStart.x);

  ctx.shadowColor = "rgba(31, 42, 47, 0.12)";
  ctx.shadowBlur = 2;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  for (const stroke of [
    { color: "rgba(255, 253, 248, 0.94)", width: 6 },
    { color: "#0f766e", width: 2.2 },
  ]) {
    ctx.strokeStyle = stroke.color;
    ctx.lineWidth = stroke.width;
    drawLine(ctx, lineStart, lineEnd);
    drawLine(ctx, extensionStart, lineStart);
    drawLine(ctx, extensionEnd, lineEnd);
    drawArrowHead(ctx, lineStart, lineAngle, stroke.width);
    drawArrowHead(ctx, lineEnd, lineAngle + Math.PI, stroke.width);
  }

  ctx.shadowColor = "transparent";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.translate(midpoint.x, midpoint.y);
  ctx.rotate(labelAngle);
  roundRect(ctx, -labelWidth * 0.5, -labelHeight * 0.5, labelWidth, labelHeight, 6);
  ctx.fillStyle = "rgba(255, 253, 248, 0.98)";
  ctx.fill();
  ctx.strokeStyle = "rgba(15, 118, 110, 0.34)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = "#0f766e";
  ctx.fillText(text, 0, 0.5);
  layoutState.labels.push(layout.bounds);
  layoutState.lines.push(...layout.lines);
  ctx.restore();
}

function drawSocketDragDimension(ctx, projection) {
  if (!socketDrag) return;

  const fitting = state.fittings.find((item) => item.id === socketDrag.fittingId);
  const segmentData = segments();
  const segment = segmentData.find((item) => item.index === socketDrag.segmentIndex);
  if (!fitting || fitting.type !== "socket" || !segment) return;

  const lengthMm = pointLength(segment.vector);
  if (lengthMm <= 0.001) return;

  const socketPointWorld = lerpPoint(segment.start, segment.end, fitting.t);
  const fromDistance = lengthMm * fitting.t;
  const toDistance = lengthMm - fromDistance;
  const useFrom = fromDistance <= toDistance;
  const referenceWorld = useFrom ? segment.start : segment.end;
  const referenceIndex = useFrom ? segment.from : segment.to;
  const distanceMm = useFrom ? fromDistance : toDistance;
  const referencePoint = projectIso(referenceWorld, projection);
  const socketPoint = projectIso(socketPointWorld, projection);
  const referenceLabel = socketReferenceLabel(referenceIndex, segment, segmentData);
  const text = `SOCKET ${formatLength(distanceMm)} mm FROM ${referenceLabel}`;
  const dimensionLayout = {
    labels: [],
    lines: [],
    viewport: dimensionViewport(ctx, 18),
    pipes: segmentData.map((item) => ({
      index: item.index,
      start: projectIso(item.start, projection),
      end: projectIso(item.end, projection),
    })),
  };

  drawRedArrowDimension(ctx, referencePoint, socketPoint, segment.index, text, dimensionLayout);
}

function socketReferenceLabel(nodeIndex, currentSegment, segmentData) {
  const connections = nodeConnections(segmentData);
  const connected = connections.get(nodeIndex) ?? [];
  if (connected.length <= 1) return "END";
  if (connected.length >= 3) return nodeConnectionType(nodeIndex) === "branch" ? "BRANCH" : "TEE";
  if (connected.length === 2) {
    const first = segmentData.find((segment) => segment.index === connected[0].segmentIndex);
    const second = segmentData.find((segment) => segment.index === connected[1].segmentIndex);
    if (!first || !second) return "JOINT";
    const firstVector = subtractPoints(state.points[connected[0].other], state.points[nodeIndex]);
    const secondVector = subtractPoints(state.points[connected[1].other], state.points[nodeIndex]);
    const bend = Math.abs(180 - bendAngle(firstVector, secondVector));
    if (bend >= 0.5) return "BEND";
    const firstSize = pipeSizeForSegment(first).nb;
    const secondSize = pipeSizeForSegment(second).nb;
    if (firstSize !== secondSize) return "REDUCER";
  }
  return currentSegment ? "JOINT" : "POINT";
}

function drawRedArrowDimension(ctx, start, end, segmentIndex, text, dimensionLayout = []) {
  const layoutState = Array.isArray(dimensionLayout)
    ? { labels: dimensionLayout, lines: [], pipes: [] }
    : dimensionLayout;
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const screenLength = Math.hypot(dx, dy);
  if (screenLength < 10) return;

  const along = { x: dx / screenLength, y: dy / screenLength };
  const baseNormal = { x: -along.y, y: along.x };
  const pipeGap = 13;
  const baseOffset = Math.min(112, Math.max(70, screenLength * 0.12));
  let labelAngle = Math.atan2(along.y, along.x);
  if (labelAngle > Math.PI / 2 || labelAngle < -Math.PI / 2) {
    labelAngle += Math.PI;
  }

  ctx.save();
  ctx.font = "950 12px Inter, system-ui, sans-serif";
  const metrics = ctx.measureText(text);
  const labelWidth = metrics.width + 22;
  const labelHeight = 24;
  const layout = redDimensionLayout(start, end, baseNormal, baseOffset, pipeGap, labelWidth, labelHeight, labelAngle, layoutState, segmentIndex);
  const { lineStart, lineEnd, midpoint } = layout;
  const { extensionStart, extensionEnd } = layout;
  const lineAngle = Math.atan2(lineEnd.y - lineStart.y, lineEnd.x - lineStart.x);

  ctx.shadowColor = "rgba(31, 42, 47, 0.16)";
  ctx.shadowBlur = 3;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  for (const stroke of [
    { color: "rgba(255, 253, 248, 0.94)", width: 6 },
    { color: "#008fb3", width: 2.4 },
  ]) {
    ctx.strokeStyle = stroke.color;
    ctx.lineWidth = stroke.width;
    drawLine(ctx, lineStart, lineEnd);
    drawLine(ctx, extensionStart, lineStart);
    drawLine(ctx, extensionEnd, lineEnd);
    drawArrowHead(ctx, lineStart, lineAngle, stroke.width);
    drawArrowHead(ctx, lineEnd, lineAngle + Math.PI, stroke.width);
  }

  ctx.shadowColor = "transparent";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.translate(midpoint.x, midpoint.y);
  ctx.rotate(labelAngle);
  roundRect(ctx, -labelWidth * 0.5, -labelHeight * 0.5, labelWidth, labelHeight, 6);
  ctx.fillStyle = "rgba(255, 253, 248, 0.98)";
  ctx.fill();
  ctx.strokeStyle = "rgba(0, 143, 179, 0.36)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = "#008fb3";
  ctx.fillText(text, 0, 0.5);
  layoutState.labels.push(layout.bounds);
  layoutState.lines.push(...layout.lines);
  ctx.restore();
}

function drawArrowHead(ctx, point, angle, strokeWidth = 2) {
  const size = strokeWidth > 4 ? 9 : 8;
  ctx.beginPath();
  ctx.moveTo(point.x, point.y);
  ctx.lineTo(point.x + Math.cos(angle + 0.48) * size, point.y + Math.sin(angle + 0.48) * size);
  ctx.moveTo(point.x, point.y);
  ctx.lineTo(point.x + Math.cos(angle - 0.48) * size, point.y + Math.sin(angle - 0.48) * size);
  ctx.stroke();
}

function redDimensionLayout(start, end, baseNormal, baseOffset, pipeGap, labelWidth, labelHeight, labelAngle, dimensionLayout, segmentIndex, options = {}) {
  const midpointBase = {
    x: (start.x + end.x) * 0.5,
    y: (start.y + end.y) * 0.5,
  };
  const labels = Array.isArray(dimensionLayout) ? dimensionLayout : dimensionLayout.labels ?? [];
  const existingLines = Array.isArray(dimensionLayout) ? [] : dimensionLayout.lines ?? [];
  const pipes = Array.isArray(dimensionLayout) ? [] : dimensionLayout.pipes ?? [];
  const viewport = Array.isArray(dimensionLayout) ? null : dimensionLayout.viewport ?? null;
  const manual = options.manual && Number(options.manual.offset) > 0.5
    ? {
        side: Number(options.manual.side) < 0 ? -1 : 1,
        offset: clampNumber(Number(options.manual.offset) || 0, 0, 520),
      }
    : null;
  const sideOptions = manual ? [manual.side] : [1, -1];
  const compactNumbered = !Array.isArray(dimensionLayout) && dimensionLayout.compactNumbered === true;
  const offsetStep = compactNumbered ? 24 : 38;
  const maxLevels = manual ? 3 : compactNumbered ? 7 : 12;
  let best = null;

  for (let level = 0; level < maxLevels; level += 1) {
    const offset = baseOffset + (manual?.offset ?? 0) + level * offsetStep;
    for (const [sideIndex, side] of sideOptions.entries()) {
      const normal = { x: baseNormal.x * side, y: baseNormal.y * side };
      const lineStart = { x: start.x + normal.x * offset, y: start.y + normal.y * offset };
      const lineEnd = { x: end.x + normal.x * offset, y: end.y + normal.y * offset };
      const extensionStart = { x: start.x + normal.x * pipeGap, y: start.y + normal.y * pipeGap };
      const extensionEnd = { x: end.x + normal.x * pipeGap, y: end.y + normal.y * pipeGap };
      const candidateLines = [
        { start: lineStart, end: lineEnd },
        { start: extensionStart, end: lineStart },
        { start: extensionEnd, end: lineEnd },
      ];
      const midpoint = {
        x: midpointBase.x + normal.x * offset,
        y: midpointBase.y + normal.y * offset,
      };
      const rawBounds = rotatedLabelBounds(midpoint, labelWidth, labelHeight, labelAngle, 12);
      const labelShift = dimensionLabelShiftForViewport(rawBounds, viewport);
      const shiftedMidpoint = {
        x: midpoint.x + labelShift.x,
        y: midpoint.y + labelShift.y,
      };
      const bounds = shiftBounds(rawBounds, labelShift.x, labelShift.y);
      const fullBounds = combineBounds(
        bounds,
        dimensionLineBounds(candidateLines, 12),
      );
      const labelShiftPenalty = labelShift.x * labelShift.x + labelShift.y * labelShift.y;
      const viewportPenalty = boundsOverflowPenalty(fullBounds, viewport);
      const overlapArea = labels.reduce((sum, existing) => sum + boundsOverlapArea(bounds, existing), 0);
      const labelPipePenalty = pipes.reduce((sum, pipe) => {
        if (pipe.index === segmentIndex) return sum;
        if (segmentIntersectsBounds(pipe.start, pipe.end, bounds)) return sum + 18000;
        const clearance = Math.hypot(labelWidth, labelHeight) * 0.5 + 18;
        const distance = distancePointToSegment(shiftedMidpoint, pipe.start, pipe.end);
        return distance < clearance ? sum + Math.pow(clearance - distance, 2) : sum;
      }, 0);
      const linePipePenalty = candidateLines.reduce((sum, line) => sum + pipes.reduce((pipeSum, pipe) => {
        if (pipe.index === segmentIndex) return pipeSum;
        if (segmentsIntersect(line.start, line.end, pipe.start, pipe.end)) return pipeSum + 14000;
        const clearance = 14;
        const distance = distanceSegmentToSegment(line.start, line.end, pipe.start, pipe.end);
        return distance < clearance ? pipeSum + Math.pow(clearance - distance, 2) * 12 : pipeSum;
      }, 0), 0);
      const dimensionLinePenalty = candidateLines.reduce((sum, line) => sum + existingLines.reduce((lineSum, existing) => {
        if (segmentsIntersect(line.start, line.end, existing.start, existing.end)) return lineSum + 1600;
        const clearance = 8;
        const distance = distanceSegmentToSegment(line.start, line.end, existing.start, existing.end);
        return distance < clearance ? lineSum + Math.pow(clearance - distance, 2) * 3 : lineSum;
      }, 0), 0);
      const score = viewportPenalty * 220 + overlapArea * 90 + labelPipePenalty * 4 + linePipePenalty + dimensionLinePenalty + labelShiftPenalty * 80 + level * 10 + sideIndex * 2;
      const candidate = {
        lineStart,
        lineEnd,
        extensionStart,
        extensionEnd,
        midpoint: shiftedMidpoint,
        normal,
        bounds,
        lines: candidateLines,
        side,
        offset,
        score,
      };

      if (overlapArea === 0 && labelPipePenalty === 0 && linePipePenalty === 0 && dimensionLinePenalty === 0 && labelShiftPenalty === 0) {
        return candidate;
      }
      if (!best || score < best.score) {
        best = candidate;
      }
    }
  }

  return best;
}

function dimensionLineBounds(lines, padding = 0) {
  const points = lines.flatMap((line) => [line.start, line.end]);
  if (!points.length) return { left: 0, right: 0, top: 0, bottom: 0 };
  return {
    left: Math.min(...points.map((point) => point.x)) - padding,
    right: Math.max(...points.map((point) => point.x)) + padding,
    top: Math.min(...points.map((point) => point.y)) - padding,
    bottom: Math.max(...points.map((point) => point.y)) + padding,
  };
}

function combineBounds(...boundsList) {
  const valid = boundsList.filter(Boolean);
  if (!valid.length) return { left: 0, right: 0, top: 0, bottom: 0 };
  return {
    left: Math.min(...valid.map((bounds) => bounds.left)),
    right: Math.max(...valid.map((bounds) => bounds.right)),
    top: Math.min(...valid.map((bounds) => bounds.top)),
    bottom: Math.max(...valid.map((bounds) => bounds.bottom)),
  };
}

function boundsOverflowPenalty(bounds, viewport) {
  if (!bounds || !viewport) return 0;
  const left = Math.max(0, viewport.left - bounds.left);
  const right = Math.max(0, bounds.right - viewport.right);
  const top = Math.max(0, viewport.top - bounds.top);
  const bottom = Math.max(0, bounds.bottom - viewport.bottom);
  return left * left + right * right + top * top + bottom * bottom;
}

function dimensionLabelShiftForViewport(bounds, viewport) {
  if (!viewport) return { x: 0, y: 0 };

  const labelWidth = bounds.right - bounds.left;
  const labelHeight = bounds.bottom - bounds.top;
  const viewportWidth = Math.max(1, viewport.right - viewport.left);
  const viewportHeight = Math.max(1, viewport.bottom - viewport.top);
  let x = 0;
  let y = 0;

  if (labelWidth > viewportWidth) {
    x = (viewport.left + viewport.right - bounds.left - bounds.right) * 0.5;
  } else if (bounds.left < viewport.left) {
    x = viewport.left - bounds.left;
  } else if (bounds.right > viewport.right) {
    x = viewport.right - bounds.right;
  }

  if (labelHeight > viewportHeight) {
    y = (viewport.top + viewport.bottom - bounds.top - bounds.bottom) * 0.5;
  } else if (bounds.top < viewport.top) {
    y = viewport.top - bounds.top;
  } else if (bounds.bottom > viewport.bottom) {
    y = viewport.bottom - bounds.bottom;
  }

  return { x, y };
}

function shiftBounds(bounds, x, y) {
  if (!x && !y) return bounds;
  return {
    left: bounds.left + x,
    right: bounds.right + x,
    top: bounds.top + y,
    bottom: bounds.bottom + y,
  };
}

function rotatedLabelBounds(center, width, height, angle, padding = 0) {
  const cos = Math.abs(Math.cos(angle));
  const sin = Math.abs(Math.sin(angle));
  const halfWidth = (width * cos + height * sin) * 0.5 + padding;
  const halfHeight = (width * sin + height * cos) * 0.5 + padding;
  return {
    left: center.x - halfWidth,
    right: center.x + halfWidth,
    top: center.y - halfHeight,
    bottom: center.y + halfHeight,
  };
}

function boundsOverlap(first, second) {
  return first.left < second.right && first.right > second.left && first.top < second.bottom && first.bottom > second.top;
}

function boundsOverlapArea(first, second) {
  const width = Math.max(0, Math.min(first.right, second.right) - Math.max(first.left, second.left));
  const height = Math.max(0, Math.min(first.bottom, second.bottom) - Math.max(first.top, second.top));
  return width * height;
}

function segmentIntersectsBounds(start, end, bounds) {
  if (pointInBounds(start, bounds) || pointInBounds(end, bounds)) return true;

  const corners = [
    { x: bounds.left, y: bounds.top },
    { x: bounds.right, y: bounds.top },
    { x: bounds.right, y: bounds.bottom },
    { x: bounds.left, y: bounds.bottom },
  ];

  for (let index = 0; index < corners.length; index += 1) {
    const next = corners[(index + 1) % corners.length];
    if (segmentsIntersect(start, end, corners[index], next)) return true;
  }
  return false;
}

function pointInBounds(point, bounds) {
  return point.x >= bounds.left && point.x <= bounds.right && point.y >= bounds.top && point.y <= bounds.bottom;
}

function inflateBounds(bounds, amount) {
  return {
    left: bounds.left - amount,
    right: bounds.right + amount,
    top: bounds.top - amount,
    bottom: bounds.bottom + amount,
  };
}

function segmentsIntersect(a, b, c, d) {
  const o1 = segmentOrientation(a, b, c);
  const o2 = segmentOrientation(a, b, d);
  const o3 = segmentOrientation(c, d, a);
  const o4 = segmentOrientation(c, d, b);

  if (o1 !== o2 && o3 !== o4) return true;
  if (o1 === 0 && pointOnSegment(a, c, b)) return true;
  if (o2 === 0 && pointOnSegment(a, d, b)) return true;
  if (o3 === 0 && pointOnSegment(c, a, d)) return true;
  if (o4 === 0 && pointOnSegment(c, b, d)) return true;
  return false;
}

function segmentOrientation(a, b, c) {
  const value = (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y);
  if (Math.abs(value) < 0.001) return 0;
  return value > 0 ? 1 : 2;
}

function pointOnSegment(a, point, b) {
  return (
    point.x <= Math.max(a.x, b.x) + 0.001 &&
    point.x >= Math.min(a.x, b.x) - 0.001 &&
    point.y <= Math.max(a.y, b.y) + 0.001 &&
    point.y >= Math.min(a.y, b.y) - 0.001
  );
}

function distancePointToSegment(point, start, end) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const lengthSquared = dx * dx + dy * dy || 1;
  const t = clampNumber(((point.x - start.x) * dx + (point.y - start.y) * dy) / lengthSquared, 0, 1);
  const closest = {
    x: start.x + dx * t,
    y: start.y + dy * t,
  };
  return Math.hypot(point.x - closest.x, point.y - closest.y);
}

function distanceSegmentToSegment(firstStart, firstEnd, secondStart, secondEnd) {
  if (segmentsIntersect(firstStart, firstEnd, secondStart, secondEnd)) return 0;
  return Math.min(
    distancePointToSegment(firstStart, secondStart, secondEnd),
    distancePointToSegment(firstEnd, secondStart, secondEnd),
    distancePointToSegment(secondStart, firstStart, firstEnd),
    distancePointToSegment(secondEnd, firstStart, firstEnd),
  );
}

function drawBendAngles(ctx, projection) {
  const segmentData = segments();
  const connections = nodeConnections(segmentData);

  ctx.save();
  ctx.font = "900 12px Inter, system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";

  for (const [nodeIndex, connected] of connections.entries()) {
    if (connected.length !== 2) continue;

    const first = subtractPoints(state.points[connected[0].other], state.points[nodeIndex]);
    const second = subtractPoints(state.points[connected[1].other], state.points[nodeIndex]);
    const angle = bendAngle(first, second);
    const bend = Math.abs(180 - angle);
    if (bend < 0.5) continue;

    const joint = projectIso(state.points[nodeIndex], projection);
    const firstScreen = projectIso(state.points[connected[0].other], projection);
    const secondScreen = projectIso(state.points[connected[1].other], projection);
    const away = normalizeScreenVector({
      x: (firstScreen.x - joint.x) + (secondScreen.x - joint.x),
      y: (firstScreen.y - joint.y) + (secondScreen.y - joint.y),
    });
    const label = `${formatAngle(bend)} deg`;
    const x = joint.x + away.x * 34;
    const y = joint.y + away.y * 34;

    ctx.lineWidth = 5;
    ctx.strokeStyle = "rgba(255, 253, 248, 0.95)";
    ctx.strokeText(label, x, y);
    ctx.fillStyle = "#7b3f2e";
    ctx.fillText(label, x, y);
  }

  ctx.restore();
}

function bendAngle(previous, next) {
  const a = normalizePoint(previous);
  const b = normalizePoint(next);
  const dot = Math.max(-1, Math.min(1, a.x * b.x + a.y * b.y + a.z * b.z));
  return Math.acos(dot) * 180 / Math.PI;
}

function normalizeScreenVector(vector) {
  const length = Math.hypot(vector.x, vector.y) || 1;
  return { x: vector.x / length, y: vector.y / length };
}

function socketRadialDirectionPoint(direction, angleDegrees = 0) {
  const axis = normalizePoint(direction);
  const reference = Math.abs(axis.z) > 0.82 ? { x: 1, y: 0, z: 0 } : { x: 0, y: 0, z: 1 };
  const u = normalizePoint(crossPoints(reference, axis));
  const v = normalizePoint(crossPoints(axis, u));
  const angle = normalizeSocketAngle(angleDegrees) * Math.PI / 180;
  return normalizePoint(addPoints(scalePoint(v, Math.cos(angle)), scalePoint(u, Math.sin(angle))));
}

function socketScreenDirection(segment, fitting, projection) {
  const base = lerpPoint(segment.start, segment.end, fitting.t);
  const radial = socketRadialDirectionPoint(segment.vector, fittingSocketAngle(fitting));
  const start = projectIso(base, projection);
  const end = projectIso(addPoints(base, radial, 1000), projection);
  const screenVector = { x: end.x - start.x, y: end.y - start.y };
  if (Math.hypot(screenVector.x, screenVector.y) > 0.001) {
    return normalizeScreenVector(screenVector);
  }

  const segmentStart = projectIso(segment.start, projection);
  const segmentEnd = projectIso(segment.end, projection);
  const along = normalizeScreenVector({ x: segmentEnd.x - segmentStart.x, y: segmentEnd.y - segmentStart.y });
  return { x: -along.y, y: along.x };
}

function drawFitting2d(ctx, projection, fitting, segment, pipeWidth) {
  const start = projectIso(segment.start, projection);
  const end = projectIso(segment.end, projection);
  const point = projectIso(fittingDisplayPoint(segment, fitting), projection);
  const angle = Math.atan2(end.y - start.y, end.x - start.x);
  const along = { x: Math.cos(angle), y: Math.sin(angle) };
  const normal = { x: -Math.sin(angle), y: Math.cos(angle) };
  const socketDirection = fitting.type === "socket" ? socketScreenDirection(segment, fitting, projection) : null;
  const selected = state.selectedFitting === fitting.id;
  const fittingWidth = Math.max(14, pipeWidth * 2.8);

  ctx.save();
  ctx.translate(point.x, point.y);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = selected ? "#b42318" : fittingColor(fitting.type);
  ctx.fillStyle = selected ? "#fff1ee" : fittingFill(fitting.type);
  ctx.lineWidth = 3;

  if (fitting.type === "flange") {
    const offsets = fittingFlangeMode(fitting) === "single" ? [0] : [-6, 6];
    for (const offset of offsets) {
      ctx.beginPath();
      ctx.moveTo(along.x * offset + normal.x * fittingWidth * -0.78, along.y * offset + normal.y * fittingWidth * -0.78);
      ctx.lineTo(along.x * offset + normal.x * fittingWidth * 0.78, along.y * offset + normal.y * fittingWidth * 0.78);
      ctx.stroke();
    }
    ctx.fillStyle = selected ? "#b42318" : "#2f3a3d";
    for (const offset of offsets) {
      for (const side of [-0.48, 0.48]) {
        ctx.beginPath();
        ctx.arc(along.x * offset + normal.x * fittingWidth * side, along.y * offset + normal.y * fittingWidth * side, 2.4, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  } else if (fitting.type === "rollGroove") {
    const grooveHalfSpan = Math.max(2.5, Math.min(5, pipeWidth * 0.14));
    ctx.lineCap = "butt";
    ctx.strokeStyle = selected ? "#7f1d1d" : "#4d5754";
    ctx.lineWidth = selected ? 3.5 : 2.8;
    for (const offset of [-grooveHalfSpan, grooveHalfSpan]) {
      ctx.beginPath();
      ctx.moveTo(along.x * offset + normal.x * fittingWidth * -0.6, along.y * offset + normal.y * fittingWidth * -0.6);
      ctx.lineTo(along.x * offset + normal.x * fittingWidth * 0.6, along.y * offset + normal.y * fittingWidth * 0.6);
      ctx.stroke();
    }
    ctx.font = "900 8px Inter, system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.lineWidth = 3;
    ctx.strokeStyle = "rgba(255, 253, 248, 0.95)";
    ctx.fillStyle = selected ? "#b42318" : "#526067";
    const labelX = normal.x * (fittingWidth * 0.95 + 8);
    const labelY = normal.y * (fittingWidth * 0.95 + 8);
    ctx.strokeText("RG", labelX, labelY);
    ctx.fillText("RG", labelX, labelY);
  } else if (fitting.type === "threadedEnd") {
    const threadLength = Math.max(20, pipeWidth * 1.35);
    const endDirection = fitting.t <= 0.5 ? 1 : -1;
    ctx.lineCap = "butt";
    ctx.strokeStyle = selected ? "#b42318" : "#4b5563";
    ctx.lineWidth = selected ? 3 : 2;
    for (let index = 0; index < 7; index += 1) {
      const offset = endDirection * (3 + index * (threadLength / 7));
      const lean = 3.4;
      ctx.beginPath();
      ctx.moveTo(
        along.x * offset + normal.x * (fittingWidth * -0.55 - lean),
        along.y * offset + normal.y * (fittingWidth * -0.55 - lean),
      );
      ctx.lineTo(
        along.x * (offset + endDirection * 4.2) + normal.x * (fittingWidth * 0.55 + lean),
        along.y * (offset + endDirection * 4.2) + normal.y * (fittingWidth * 0.55 + lean),
      );
      ctx.stroke();
    }
    ctx.font = "900 8px Inter, system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.lineWidth = 3;
    ctx.strokeStyle = "rgba(255, 253, 248, 0.95)";
    ctx.fillStyle = selected ? "#b42318" : "#4b5563";
    const labelX = normal.x * (fittingWidth * 0.95 + 9);
    const labelY = normal.y * (fittingWidth * 0.95 + 9);
    ctx.strokeText("THD", labelX, labelY);
    ctx.fillText("THD", labelX, labelY);
  } else if (fitting.type === "valve") {
    ctx.beginPath();
    ctx.moveTo(along.x * -11, along.y * -11);
    ctx.lineTo(normal.x * 13, normal.y * 13);
    ctx.lineTo(along.x * 11, along.y * 11);
    ctx.lineTo(normal.x * -13, normal.y * -13);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(normal.x * -2, normal.y * -2);
    ctx.lineTo(normal.x * -2 + 0, normal.y * -2 - 18);
    ctx.stroke();
  } else if (fitting.type === "weld") {
    for (const offset of [-3, 3]) {
      ctx.beginPath();
      ctx.moveTo(along.x * offset + normal.x * fittingWidth * -0.58, along.y * offset + normal.y * fittingWidth * -0.58);
      ctx.lineTo(along.x * offset + normal.x * fittingWidth * 0.58, along.y * offset + normal.y * fittingWidth * 0.58);
      ctx.stroke();
    }
    const weldRecord = weldRecordForFitting(fitting.id);
    if (weldRecord) {
      const labelX = normal.x * (fittingWidth + 16);
      const labelY = normal.y * (fittingWidth + 16);
      ctx.font = "950 10px Inter, system-ui, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.lineWidth = 4;
      ctx.strokeStyle = "rgba(255, 253, 248, 0.96)";
      ctx.strokeText(weldRecord.number, labelX, labelY);
      ctx.fillStyle = selected ? "#b42318" : "#1d4ed8";
      ctx.fillText(weldRecord.number, labelX, labelY);
    }
  } else if (fitting.type === "socket") {
    const branch = socketDirection ?? normal;
    const branchLength = Math.max(19, fittingWidth * 1.45);
    const socketRadius = Math.max(4.2, fittingWidth * 0.32);
    ctx.lineCap = "butt";
    ctx.lineWidth = selected ? 4 : 3;
    drawLine(
      ctx,
      { x: branch.x * 2, y: branch.y * 2 },
      { x: branch.x * branchLength, y: branch.y * branchLength },
    );
    ctx.beginPath();
    ctx.arc(branch.x * (branchLength + socketRadius * 0.35), branch.y * (branchLength + socketRadius * 0.35), socketRadius, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.font = "900 8px Inter, system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillStyle = selected ? "#b42318" : "#0f766e";
    ctx.lineWidth = 3;
    ctx.strokeStyle = "rgba(255, 253, 248, 0.95)";
    const label = '1/2"';
    const labelX = branch.x * (branchLength + socketRadius * 1.9);
    const labelY = branch.y * (branchLength + socketRadius * 1.9);
    ctx.strokeText(label, labelX, labelY);
    ctx.fillText(label, labelX, labelY);
  } else if (fitting.type === "reducer") {
    drawReducerProfile2d(
      ctx,
      { x: along.x * -12, y: along.y * -12 },
      { x: along.x * 12, y: along.y * 12 },
      fittingWidth * 1.2,
      fittingWidth * 0.64,
      fittingReducerType(fitting),
      { label: reducerTypeCode(fittingReducerType(fitting)), labelColor: selected ? "#b42318" : "#59358f" },
    );
  }

  ctx.restore();
}

function fittingColor(type) {
  if (type === "valve") return "#d99a23";
  if (type === "weld") return "#2563eb";
  if (type === "reducer") return "#7a4dc2";
  if (type === "socket") return "#0f766e";
  if (type === "rollGroove") return "#0f766e";
  if (type === "threadedEnd") return "#4b5563";
  return "#3f484b";
}

function fittingFill(type) {
  if (type === "valve") return "#fff4cf";
  if (type === "weld") return "#eff6ff";
  if (type === "reducer") return "#f1ebff";
  if (type === "socket") return "#dcfce7";
  if (type === "rollGroove") return "#d8f1ed";
  if (type === "threadedEnd") return "#e5e7eb";
  return "#eef2f0";
}

function drawPreviewRun(ctx, projection) {
  if (!state.previewCandidate || state.activeTool !== "draw") {
    return;
  }

  const start = projectIso(activePoint(), projection);
  const end = projectIso(state.previewCandidate.point, projection);

  ctx.save();
  ctx.setLineDash([8, 8]);
  ctx.lineCap = "round";
  ctx.lineWidth = Math.max(6, visualPipeWidth() * 0.82);
  ctx.strokeStyle = "rgba(185, 84, 54, 0.74)";
  drawLine(ctx, start, end);
  ctx.setLineDash([]);
  ctx.fillStyle = "#b95436";
  ctx.beginPath();
  ctx.arc(end.x, end.y, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawLine(ctx, from, to) {
  ctx.beginPath();
  ctx.moveTo(from.x, from.y);
  ctx.lineTo(to.x, to.y);
  ctx.stroke();
}

function formatLength(value) {
  const rounded = Math.round(Number(value) || 0);
  const text = String(rounded);
  return text.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function formatWeldGapMm(value) {
  const gapMm = Math.round((Number(value) || 0) * 10) / 10;
  return gapMm.toFixed(1);
}

function formatMass(value) {
  const rounded = Math.round(value * 10) / 10;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
}

function formatPressureBar(value) {
  const pressure = Number(value);
  if (!Number.isFinite(pressure)) return "N/A";
  const rounded = pressure >= 100 ? Math.round(pressure) : Math.round(pressure * 10) / 10;
  const text = Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
  return `${text.replace(/\B(?=(\d{3})+(?!\d))/g, ",")} bar`;
}

function formatPressureKpa(valueBar) {
  const pressure = Number(valueBar);
  if (!Number.isFinite(pressure)) return "N/A";
  const kpa = Math.round(pressure * 100);
  return `${String(kpa).replace(/\B(?=(\d{3})+(?!\d))/g, ",")} kPa`;
}

function formatPressureStandard(valueBar) {
  const pressure = Number(valueBar);
  if (!Number.isFinite(pressure)) return "N/A";
  return `${formatPressureKpa(pressure)} (${formatPressureBar(pressure)})`;
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function formatPoint(point) {
  return `X ${formatLength(point.x)} mm, Y ${formatLength(point.y)} mm, Z ${formatLength(point.z)} mm`;
}

function formatPointCompact(point) {
  return `X ${formatLength(point.x)} / Y ${formatLength(point.y)} / Z ${formatLength(point.z)}`;
}

function pointLabel(index) {
  let value = Math.max(0, Number(index) || 0);
  let label = "";
  do {
    label = String.fromCharCode(65 + (value % 26)) + label;
    value = Math.floor(value / 26) - 1;
  } while (value >= 0);
  return label;
}

function formatAngle(value) {
  const rounded = Math.round(value * 10) / 10;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
}

function visualPipeWidth(segment = null) {
  const od = (segment ? pipeSizeForSegment(segment) : selectedPipeSize()).od;
  return Math.max(9, Math.min(34, 6 + Math.sqrt(od) * 1.35));
}

function triColorSegmentSizeKey(segment) {
  const size = pipeSizeForSegment(segment);
  const od = Number(size?.od);
  return Number.isFinite(od) ? od : Number(size?.nb) || 0;
}

function updatePreviewSizeColourLegend(segmentData = segments()) {
  if (!previewSizeColourLegend) return;
  const showLegend = normalizePreviewMode(state.previewMode) === "tricolor";
  if (!showLegend) {
    previewSizeColourLegend.hidden = true;
    previewSizeColourLegend.innerHTML = "";
    return;
  }

  const palette = ["#3c9698", "#d19438", "#7864a8"];
  const sizes = new Map();
  for (const segment of segmentData) {
    const key = triColorSegmentSizeKey(segment);
    if (!sizes.has(key)) sizes.set(key, pipeSizeForSegment(segment));
  }
  const ordered = [...sizes.entries()].sort((first, second) => first[0] - second[0]);
  previewSizeColourLegend.innerHTML = ordered
    .map(([, size], index) => `
      <span>
        <i style="--size-colour:${palette[index % palette.length]}"></i>
        ${escapeHtml(pipeSizeDisplayLabel(size))}
      </span>
    `)
    .join("");
  previewSizeColourLegend.hidden = ordered.length === 0;
}

function pipeRadiusMetres(segment = null) {
  const od = (segment ? pipeSizeForSegment(segment) : selectedPipeSize()).od;
  const maxOd = maxPipeOdMm();
  return 0.055 + (od / maxOd) * 0.255;
}

function toModelUnits(point) {
  return {
    x: point.x / 1000,
    y: point.y / 1000,
    z: point.z / 1000,
  };
}

function pointerPosition(event, canvas = drawCanvas) {
  const rect = canvas.getBoundingClientRect();
  return {
    x: event.clientX - rect.left,
    y: event.clientY - rect.top,
  };
}

function isCoarseInput() {
  return Boolean(
    (navigator.maxTouchPoints || 0) > 0 ||
    window.matchMedia?.("(pointer: coarse)")?.matches ||
      window.matchMedia?.("(hover: none)")?.matches,
  );
}

function isTabletLayout() {
  return Boolean(window.matchMedia?.("(max-width: 1100px)")?.matches || isCoarseInput());
}

function isPhoneLayout() {
  return Boolean(window.matchMedia?.("(max-width: 640px)")?.matches);
}

function isTouchLikeEvent(event) {
  return event.pointerType === "touch" || event.pointerType === "pen" || (!event.pointerType && isCoarseInput());
}

function hitLimit(mouseLimit, touchLimit) {
  return isCoarseInput() ? touchLimit : mouseLimit;
}

function unprojectIsoGround(pointer) {
  return unprojectIsoAtZ(pointer, 0, true);
}

function unprojectIsoAtZ(pointer, z = 0, snap = false) {
  const projection = getProjection();
  const rawX = pointer.x - projection.offsetX;
  const rawY = pointer.y - projection.offsetY;
  const u = rawX / (ISO_COS * state.gridScale);
  const v = (rawY + (z / MM_PER_GRID) * state.gridScale) / (ISO_SIN * state.gridScale);
  const point = {
    x: (u + v) * 0.5 * MM_PER_GRID,
    y: (v - u) * 0.5 * MM_PER_GRID,
    z: 0,
  };
  point.z = z;
  if (!snap) {
    point.x = Math.round(point.x);
    point.y = Math.round(point.y);
    return point;
  }
  return {
    x: Math.round(point.x / LENGTH_INCREMENT_MM) * LENGTH_INCREMENT_MM,
    y: Math.round(point.y / LENGTH_INCREMENT_MM) * LENGTH_INCREMENT_MM,
    z,
  };
}

function shiftAngleLabel(axisName, sign) {
  return `${sign > 0 ? "+" : "-"}${axisName.toUpperCase()}`;
}

function shiftAngleSnapAxes() {
  const angle = SHIFT_ANGLE_SNAP_DEGREES;
  const radians = angle * Math.PI / 180;
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  const planes = [
    { key: "xy", primary: "x", secondary: "y", color: "#13a8c8" },
    { key: "xz", primary: "x", secondary: "z", color: "#d66b42" },
    { key: "yz", primary: "y", secondary: "z", color: "#7c8dff" },
  ];
  const axes = [];

  for (const plane of planes) {
    for (const primarySign of [-1, 1]) {
      for (const secondarySign of [-1, 1]) {
        const vector = { x: 0, y: 0, z: 0 };
        vector[plane.primary] = primarySign * cos;
        vector[plane.secondary] = secondarySign * sin;
        axes.push({
          key: `${plane.key}-${primarySign > 0 ? "p" : "n"}${secondarySign > 0 ? "p" : "n"}`,
          label: `${shiftAngleLabel(plane.primary, primarySign)} / ${shiftAngleLabel(plane.secondary, secondarySign)} ${angle} deg`,
          vector,
          color: plane.color,
          shiftAngle: true,
          shiftPlane: plane.key,
          shiftDirection: secondarySign,
          shiftAngleDeg: angle,
        });
      }
    }
  }

  return axes;
}

function shiftAngleEdgeMeta(axis, travelMm) {
  if (!axis?.shiftAngle) return {};
  const angle = Number(axis.shiftAngleDeg) || SHIFT_ANGLE_SNAP_DEGREES;
  const radians = angle * Math.PI / 180;
  const travel = Math.max(1, Math.round(Number(travelMm) || 0));
  return {
    offsetSetMm: Math.max(1, Math.round(travel * Math.sin(radians))),
    offsetTravelMm: travel,
    offsetAngleDeg: angle,
    offsetPlane: axis.shiftPlane,
    offsetDirection: Number(axis.shiftDirection) < 0 ? -1 : 1,
  };
}

function preferredShiftPlaneForPrimaryAxis(primaryAxis) {
  const currentPlane = normalizeAnglePlane(state.anglePlane);
  if (currentPlane.includes(primaryAxis)) return currentPlane;
  if (primaryAxis === "z") return "xz";
  return "xy";
}

function shiftAngleAxisFromBaseAxis(axis) {
  const key = String(axis?.key ?? "");
  const primary = key[0];
  if (!["x", "y", "z"].includes(primary)) return null;

  const sign = key[1] === "n" ? -1 : 1;
  const plane = preferredShiftPlaneForPrimaryAxis(primary);
  const secondary = [...plane].find((axisName) => axisName !== primary) ?? (primary === "z" ? "x" : "z");
  const angle = SHIFT_ANGLE_SNAP_DEGREES;
  const radians = angle * Math.PI / 180;
  const vector = { x: 0, y: 0, z: 0 };
  vector[primary] = sign * Math.cos(radians);
  vector[secondary] = sign * Math.sin(radians);

  return {
    key: `${axis.key}-shift-${plane}`,
    label: `${shiftAngleLabel(primary, sign)} / ${shiftAngleLabel(secondary, sign)} ${angle} deg`,
    vector,
    color: axis.color,
    shiftAngle: true,
    shiftPlane: plane,
    shiftDirection: sign,
    shiftAngleDeg: angle,
  };
}

function addShiftAngleRun(axis) {
  const angledAxis = shiftAngleAxisFromBaseAxis(axis);
  if (!angledAxis) return false;
  const travelMm = offsetTravelLengthMm(state.stepLength, SHIFT_ANGLE_SNAP_DEGREES);
  addRun(angledAxis, travelMm, { edgeMeta: shiftAngleEdgeMeta(angledAxis, travelMm) });
  return true;
}

function shouldUseShiftAngleSnap(event) {
  return state.activeTool === "draw" && Boolean(event?.shiftKey || shiftAngleSnap);
}

function getSnappedCandidate(pointer, options = {}) {
  const useShiftAngle = options.shiftAngle === true;
  const snapAxes = useShiftAngle ? shiftAngleSnapAxes() : AXES;
  const start = activePoint();
  const startScreen = projectIso(start);
  const delta = {
    x: pointer.x - startScreen.x,
    y: pointer.y - startScreen.y,
  };
  const distance = Math.hypot(delta.x, delta.y);

  if (distance < 10) {
    const axis = useShiftAngle ? snapAxes.find((candidateAxis) => candidateAxis.key === "xy-pp") ?? snapAxes[0] : axisByKey.get("xp");
    const length = useShiftAngle ? offsetTravelLengthMm(state.stepLength, SHIFT_ANGLE_SNAP_DEGREES) : state.stepLength;
    return {
      point: addPoints(start, axis.vector, length),
      axis,
      length,
      edgeMeta: shiftAngleEdgeMeta(axis, length),
    };
  }

  let best = null;
  for (const axis of snapAxes) {
    const axisScreen = projectIso(addPoints(start, axis.vector));
    const projected = {
      x: axisScreen.x - startScreen.x,
      y: axisScreen.y - startScreen.y,
    };
    const axisLength = Math.hypot(projected.x, projected.y) || 1;
    const unit = {
      x: projected.x / axisLength,
      y: projected.y / axisLength,
    };
    const score = delta.x * unit.x + delta.y * unit.y;
    if (!best || score > best.score) {
      best = { axis, score };
    }
  }

  if (!best) {
    return null;
  }

  const length = normalizeLength((best.score / state.gridScale) * MM_PER_GRID);
  const point = addPoints(start, best.axis.vector, length);
  return {
    point,
    axis: best.axis,
    length,
    edgeMeta: shiftAngleEdgeMeta(best.axis, length),
  };
}

function setShiftAngleSnap(active) {
  const next = active === true && state.activeTool === "draw";
  if (shiftAngleSnap === next) {
    updateTouchShiftAngleButton();
    return;
  }
  shiftAngleSnap = next;
  updateTouchShiftAngleButton();
  if (state.activeTool !== "draw") return;

  if (state.pointer) {
    const candidate = getSnappedCandidate(state.pointer, { shiftAngle: shiftAngleSnap });
    state.previewCandidate = candidate;
    if (pendingDraw) {
      pendingDraw.candidate = candidate;
    }
  }
  const candidate = state.previewCandidate;
  cursorReadout.textContent = shiftAngleSnap
    ? candidate?.axis?.shiftAngle
      ? `${candidate.axis.label} / ${formatPoint(candidate.point)}`
      : "Shift: 45 deg draw"
    : candidate
    ? formatPoint(candidate.point)
    : formatPoint(activePoint());
  drawIso();
}

function updateTouchShiftAngleButton() {
  if (!touchShiftAngleButton) return;
  const available = state.activeTool === "draw" && !drawingEditLocked();
  touchShiftAngleButton.disabled = !available;
  touchShiftAngleButton.classList.toggle("active", available && shiftAngleSnap);
  touchShiftAngleButton.setAttribute("aria-pressed", String(available && shiftAngleSnap));
  touchShiftAngleButton.title = available
    ? "Press and hold while dragging a 45 degree offset"
    : "Choose Draw to use Hold 45°";
}

function setupTouchShiftAngleButton() {
  if (!touchShiftAngleButton) return;
  const release = (event = null) => {
    if (event && touchShiftAnglePointerId !== null && event.pointerId !== touchShiftAnglePointerId) return;
    touchShiftAnglePointerId = null;
    setShiftAngleSnap(false);
  };

  touchShiftAngleButton.addEventListener("pointerdown", (event) => {
    if (touchShiftAngleButton.disabled || state.activeTool !== "draw") return;
    event.preventDefault();
    touchShiftAnglePointerId = event.pointerId;
    try {
      touchShiftAngleButton.setPointerCapture(event.pointerId);
    } catch {
      // Holding still works when pointer capture is unavailable.
    }
    setShiftAngleSnap(true);
  });
  touchShiftAngleButton.addEventListener("pointerup", release);
  touchShiftAngleButton.addEventListener("pointercancel", release);
  touchShiftAngleButton.addEventListener("lostpointercapture", release);
  touchShiftAngleButton.addEventListener("click", (event) => event.preventDefault());
  touchShiftAngleButton.addEventListener("contextmenu", (event) => event.preventDefault());
  window.addEventListener("blur", () => release());
  updateTouchShiftAngleButton();
}

function findNearestSegment(pointer) {
  let nearest = null;
  for (const segment of segments()) {
    const projection = getProjection();
    const start = projectIso(segment.start, projection);
    const end = projectIso(segment.end, projection);
    const hit = distanceToSegment(pointer, start, end);
    if (!nearest || hit.distance < nearest.distance) {
      nearest = { segment, distance: hit.distance, t: hit.t };
    }
  }

  return nearest && nearest.distance <= hitLimit(18, 34) ? nearest : null;
}

function findNearestPoint(pointer) {
  const projection = getProjection();
  let nearest = null;
  for (const [index, point] of state.points.entries()) {
    const screen = projectIso(point, projection);
    const distance = Math.hypot(pointer.x - screen.x, pointer.y - screen.y);
    if (!nearest || distance < nearest.distance) {
      nearest = { index, point, distance };
    }
  }
  return nearest && nearest.distance <= hitLimit(14, 28) ? nearest : null;
}

function findNearestNote(pointer) {
  const projection = getProjection();
  let nearest = null;
  for (const note of state.notes) {
    const screen = projectIso(noteLabelPoint(note, projection), projection);
    const labelWidth = Math.max(42, Math.min(280, String(note.text ?? "").length * 7.2 + 16));
    const labelHeight = 24;
    const labelLeft = screen.x - labelWidth * 0.5;
    const labelTop = screen.y - labelHeight * 0.5;
    const inLabel =
      pointer.x >= labelLeft - 8 &&
      pointer.x <= labelLeft + labelWidth + 8 &&
      pointer.y >= labelTop - 8 &&
      pointer.y <= labelTop + labelHeight + 8;
    const distance = inLabel
      ? 0
      : Math.hypot(pointer.x - (labelLeft + labelWidth * 0.5), pointer.y - (labelTop + labelHeight * 0.5));
    if (!nearest || distance < nearest.distance) {
      nearest = { note, distance };
    }
  }
  return nearest && nearest.distance <= hitLimit(38, 56) ? nearest : null;
}

function findNearestMeasurement(pointer) {
  const projection = getProjection();
  let nearest = null;
  const measurements = Array.isArray(state.measurements) ? state.measurements : [];

  for (const measurement of measurements) {
    const start = projectIso(measurement.start, projection);
    const end = projectIso(measurement.end, projection);
    const hit = distanceToSegment(pointer, start, end);
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const screenLength = Math.hypot(dx, dy) || 1;
    const normal = { x: -dy / screenLength, y: dx / screenLength };
    const labelCenter = {
      x: (start.x + end.x) * 0.5 + normal.x * 18,
      y: (start.y + end.y) * 0.5 + normal.y * 18,
    };
    const labelWidth = Math.max(54, measurementLabel(measurement).length * 7.4 + 22);
    const labelHeight = 24;
    const labelHit =
      pointer.x >= labelCenter.x - labelWidth * 0.5 - 10 &&
      pointer.x <= labelCenter.x + labelWidth * 0.5 + 10 &&
      pointer.y >= labelCenter.y - labelHeight * 0.5 - 10 &&
      pointer.y <= labelCenter.y + labelHeight * 0.5 + 10;
    const distance = labelHit ? 0 : hit.distance;
    if (!nearest || distance < nearest.distance) {
      nearest = { measurement, distance };
    }
  }

  return nearest && nearest.distance <= hitLimit(16, 30) ? nearest : null;
}

function findNearestFitting(pointer) {
  const projection = getProjection();
  const segmentByIndex = new Map(segments().map((segment) => [segment.index, segment]));
  let nearest = null;

  for (const fitting of state.fittings) {
    const segment = segmentByIndex.get(fitting.segmentIndex);
    if (!segment) continue;

    const point = fittingDisplayPoint(segment, fitting);
    const screen = projectIso(point, projection);
    const distance = Math.hypot(pointer.x - screen.x, pointer.y - screen.y);
    if (!nearest || distance < nearest.distance) {
      nearest = {
        fitting,
        segmentHit: { segment, distance, t: fittingDisplayT(segment, fitting) },
        point,
        distance,
      };
    }
  }

  return nearest && nearest.distance <= hitLimit(26, 40) ? nearest : null;
}

function findNearestDimensionTarget(pointer) {
  if (!state.showDimensions || !isLineDimensionStyle()) return null;
  let nearest = null;

  for (const target of dimensionHitTargets) {
    const labelBounds = inflateBounds(target.bounds, hitLimit(10, 16));
    const labelHit = pointInBounds(pointer, labelBounds);
    const lineDistance = (target.lines ?? []).reduce((best, line) => {
      const hit = distanceToSegment(pointer, line.start, line.end);
      return Math.min(best, hit.distance);
    }, Infinity);
    const distance = labelHit ? 0 : lineDistance;
    const preferTarget = target.type === "dimension-key" && nearest?.type !== "dimension-key";
    if (distance <= hitLimit(12, 22) && (!nearest || distance < nearest.distance || (distance === nearest.distance && preferTarget))) {
      nearest = { ...target, distance };
    }
  }

  return nearest;
}

function findNearestAutoReducer(pointer) {
  const projection = getProjection();
  let nearest = null;

  for (const reducer of autoReducerTransitions(segments())) {
    const segment = reducerPlacementSegment(reducer);
    if (!segment) continue;

    const point = reducerCentrePoint(reducer);
    const screen = projectIso(point, projection);
    const distance = Math.hypot(pointer.x - screen.x, pointer.y - screen.y);
    const lengthSq = Math.max(dotPoints(segment.vector, segment.vector), 1);
    const t = clampNumber(dotPoints(subtractPoints(point, segment.start), segment.vector) / lengthSq, 0, 1);
    if (!nearest || distance < nearest.distance) {
      nearest = {
        reducer,
        point,
        distance,
        segmentHit: { segment, distance, t },
      };
    }
  }

  return nearest && nearest.distance <= hitLimit(30, 46) ? nearest : null;
}

function distanceToSegment(point, start, end) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const lengthSquared = dx * dx + dy * dy || 1;
  const rawT = ((point.x - start.x) * dx + (point.y - start.y) * dy) / lengthSquared;
  const t = Math.max(0, Math.min(1, rawT));
  const closest = {
    x: start.x + dx * t,
    y: start.y + dy * t,
  };
  return {
    distance: Math.hypot(point.x - closest.x, point.y - closest.y),
    t,
  };
}

function closestSegmentParameters3d(firstStart, firstEnd, secondStart, secondEnd) {
  const u = subtractPoints(firstEnd, firstStart);
  const v = subtractPoints(secondEnd, secondStart);
  const w = subtractPoints(firstStart, secondStart);
  const a = dotPoints(u, u);
  const b = dotPoints(u, v);
  const c = dotPoints(v, v);
  const d = dotPoints(u, w);
  const e = dotPoints(v, w);
  const denominator = a * c - b * b;
  let firstT = 0;
  let secondT = 0;

  if (a <= 0.001 && c <= 0.001) {
    return { firstT: 0, secondT: 0, distance: pointLength(subtractPoints(firstStart, secondStart)) };
  }

  if (a <= 0.001) {
    secondT = clampNumber(e / c, 0, 1);
  } else if (c <= 0.001) {
    firstT = clampNumber(-d / a, 0, 1);
  } else if (Math.abs(denominator) > 0.001) {
    firstT = clampNumber((b * e - c * d) / denominator, 0, 1);
    secondT = clampNumber((a * e - b * d) / denominator, 0, 1);
  } else {
    const overlap = collinearOverlapParameters(firstStart, firstEnd, secondStart, secondEnd);
    if (overlap) {
      firstT = overlap.firstT;
      secondT = overlap.secondT;
    }
  }

  const firstPoint = lerpPoint(firstStart, firstEnd, firstT);
  const secondPoint = lerpPoint(secondStart, secondEnd, secondT);
  return {
    firstT,
    secondT,
    distance: pointLength(subtractPoints(firstPoint, secondPoint)),
  };
}

function collinearOverlapParameters(firstStart, firstEnd, secondStart, secondEnd) {
  const firstVector = subtractPoints(firstEnd, firstStart);
  const secondVector = subtractPoints(secondEnd, secondStart);
  const firstLengthSq = dotPoints(firstVector, firstVector);
  const secondLengthSq = dotPoints(secondVector, secondVector);
  if (firstLengthSq <= 0.001 || secondLengthSq <= 0.001) return null;

  const cross = pointLength(crossPoints(firstVector, secondVector));
  const relativeCross = cross / Math.max(1, Math.sqrt(firstLengthSq * secondLengthSq));
  const offLine = pointLength(crossPoints(subtractPoints(secondStart, firstStart), firstVector)) / Math.sqrt(firstLengthSq);
  if (relativeCross > 0.001 || offLine > RUN_CONNECTION_TOLERANCE_MM) return null;

  const tA = dotPoints(subtractPoints(secondStart, firstStart), firstVector) / firstLengthSq;
  const tB = dotPoints(subtractPoints(secondEnd, firstStart), firstVector) / firstLengthSq;
  const overlapStart = Math.max(0, Math.min(tA, tB));
  const overlapEnd = Math.min(1, Math.max(tA, tB));
  if (overlapEnd <= Math.max(overlapStart, 0.02)) return null;

  const firstT = Math.max(overlapStart, 0.02);
  const point = lerpPoint(firstStart, firstEnd, firstT);
  const secondT = clampNumber(dotPoints(subtractPoints(point, secondStart), secondVector) / secondLengthSq, 0, 1);
  return { firstT, secondT };
}

function findRunConnectionForNewSegment(startIndex, endPoint) {
  const start = state.points[startIndex];
  if (!start || almostSamePoint(start, endPoint)) return null;

  let best = null;
  for (const segment of segments()) {
    if (segment.from === startIndex || segment.to === startIndex) continue;

    const closest = closestSegmentParameters3d(start, endPoint, segment.start, segment.end);
    if (closest.distance > RUN_CONNECTION_TOLERANCE_MM) continue;
    if (closest.firstT <= 0.025 || closest.firstT > 1.001) continue;

    let candidate = null;
    if (closest.secondT > 0.025 && closest.secondT < 0.975) {
      candidate = {
        type: "segment",
        firstT: closest.firstT,
        segmentIndex: segment.index,
        segmentT: closest.secondT,
        point: lerpPoint(segment.start, segment.end, closest.secondT),
      };
    } else {
      const pointIndex = closest.secondT <= 0.5 ? segment.from : segment.to;
      if (pointIndex === startIndex) continue;
      candidate = {
        type: "point",
        firstT: closest.firstT,
        pointIndex,
        point: state.points[pointIndex],
      };
    }

    if (!best || candidate.firstT < best.firstT || (Math.abs(candidate.firstT - best.firstT) < 0.001 && candidate.type === "segment")) {
      best = candidate;
    }
  }

  return best;
}

function offsetTravelMultiplier(angleDegrees) {
  const radians = normalizeAngle(angleDegrees) * Math.PI / 180;
  return 1 / Math.max(0.0001, Math.sin(radians));
}

function offsetTravelLengthMm(setMm, angleDegrees) {
  return normalizeLength(Number(setMm) * offsetTravelMultiplier(angleDegrees));
}

function segmentOffsetMeta(segment) {
  if (!segment || !Number.isFinite(segment.offsetSetMm) || !Number.isFinite(segment.offsetTravelMm)) return null;
  return {
    setMm: segment.offsetSetMm,
    travelMm: segment.offsetTravelMm,
    angleDeg: normalizeAngle(segment.offsetAngleDeg),
    plane: normalizeAnglePlane(segment.offsetPlane),
    direction: Number(segment.offsetDirection) < 0 ? -1 : 1,
    multiplier: offsetTravelMultiplier(segment.offsetAngleDeg),
  };
}

function offsetDimensionText(segment, options = {}) {
  const meta = segmentOffsetMeta(segment);
  if (!meta) return null;
  const travel = formatLength(pointLength(segment.vector));
  const set = formatLength(meta.setMm);
  return options.short ? `${travel} mm / SET ${set}` : `C/C ${travel} mm / SET ${set} mm`;
}

function addRun(axis, length, options = {}) {
  const from = activePointIndex();
  const start = state.points[from];
  const next = addPoints(start, axis.vector, length);
  addRunToPoint(from, next, options);
}

function addRunToPoint(from, next, options = {}) {
  if (!ensureDrawingEditable("draw more pipe")) return;
  const start = state.points[from];
  if (!start || almostSamePoint(start, next)) {
    return;
  }
  const runPipeSizeNb = normalizePipeSize(options.pipeSizeNb ?? state.pipeSizeNb);
  const edgeMeta = normalizeOffsetEdgeMeta(options.edgeMeta);

  const connection = findRunConnectionForNewSegment(from, next);
  if (connection) {
    const snapshot = createUndoSnapshot();
    const to = connection.type === "segment"
      ? splitSegmentAt(connection.segmentIndex, connection.segmentT)
      : connection.pointIndex;
    if (to === null || to === from) return;
    if (connection.type === "segment") {
      setNodeConnectionType(to, "tee", { update: false });
    }
    state.edges.push({ from, to, pipeSizeNb: runPipeSizeNb, ...edgeMeta });
    selectSingleSegment(state.edges.length - 1);
    state.selectedFitting = null;
    state.selectedNote = null;
    state.selectedMeasurement = null;
    state.selectedPoint = to;
    state.activePoint = to;
    state.previewCandidate = null;
    recordHistory({ type: "snapshot", snapshot });
    updateAll();
    markFirstUseGuideLearned("draw");
    return;
  }

  const to = state.points.length;
  state.points.push(next);
  state.edges.push({ from, to, pipeSizeNb: runPipeSizeNb, ...edgeMeta });
  selectSingleSegment(state.edges.length - 1);
  state.selectedFitting = null;
  state.selectedNote = null;
  state.selectedMeasurement = null;
  state.selectedPoint = to;
  state.activePoint = to;
  state.previewCandidate = null;
  recordHistory({ type: "edge", pointIndex: to, edgeIndex: state.edges.length - 1 });
  updateAll();
  markFirstUseGuideLearned("draw");
}

function addAngledRun(direction) {
  const angle = normalizeAngle(state.angleDegrees);
  const radians = angle * Math.PI / 180;
  const sign = direction >= 0 ? 1 : -1;
  const setMm = normalizeLength(state.stepLength);
  const travelMm = offsetTravelLengthMm(setMm, angle);
  let vector;

  if (state.anglePlane === "xz") {
    vector = { x: Math.cos(radians), y: 0, z: Math.sin(radians) * sign };
  } else if (state.anglePlane === "yz") {
    vector = { x: 0, y: Math.cos(radians), z: Math.sin(radians) * sign };
  } else {
    vector = { x: Math.cos(radians), y: Math.sin(radians) * sign, z: 0 };
  }

  addRun({ vector }, travelMm, {
    edgeMeta: {
      offsetSetMm: setMm,
      offsetTravelMm: travelMm,
      offsetAngleDeg: angle,
      offsetPlane: state.anglePlane,
      offsetDirection: sign,
    },
  });
}

function selectedSegmentData() {
  const selected = selectedSegmentIndexes();
  if (selected.length !== 1) return null;
  return segments().find((segment) => segment.index === selected[0]) ?? null;
}

function selectedFittingData() {
  if (!state.selectedFitting) return null;
  const fitting = state.fittings.find((item) => item.id === state.selectedFitting);
  if (!fitting) return null;

  const segment = segments().find((item) => item.index === fitting.segmentIndex);
  if (!segment) return null;

  return {
    fitting,
    segment,
    point: fittingDisplayPoint(segment, fitting),
    weightKg: fittingWeightKg(fitting, segment),
    weightSource: fittingWeightSource(fitting, segment),
  };
}

function setSelectedSegmentLength(length, options = {}) {
  if (!ensureDrawingEditable("change pipe lengths")) return;
  const segment = selectedSegmentData();
  if (!segment) return;

  const normalizedLength = normalizeLength(length);
  const snapshot = createUndoSnapshot();
  const anchorIndex =
    state.selectedPoint === segment.to ? segment.to :
    state.selectedPoint === segment.from ? segment.from :
    segment.from;
  const targetIndex = anchorIndex === segment.from ? segment.to : segment.from;
  const anchor = state.points[anchorIndex];
  const target = state.points[targetIndex];
  const direction = normalizePoint(subtractPoints(target, anchor));

  translateSegmentSide(segment, anchorIndex, targetIndex, addPoints(anchor, direction, normalizedLength));
  if (options.edgeMeta) {
    state.edges[segment.index] = {
      ...state.edges[segment.index],
      ...normalizeOffsetEdgeMeta(options.edgeMeta),
    };
  } else if (segmentOffsetMeta(segment)) {
    const meta = segmentOffsetMeta(segment);
    const setMm = Math.round(normalizedLength / meta.multiplier);
    state.edges[segment.index] = {
      ...state.edges[segment.index],
      ...normalizeOffsetEdgeMeta({
        offsetSetMm: setMm,
        offsetTravelMm: normalizedLength,
        offsetAngleDeg: meta.angleDeg,
        offsetPlane: meta.plane,
        offsetDirection: meta.direction,
      }),
    };
  }
  state.activePoint = targetIndex;
  state.selectedPoint = targetIndex;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function editSegmentBendAngle(segment, anchorIndex, bendAngleValue) {
  if (!ensureDrawingEditable("change bend angles")) return false;
  const reference = referenceConnectionForSegment(segment, anchorIndex);
  if (!reference) return false;

  const targetIndex = anchorIndex === segment.from ? segment.to : segment.from;
  const anchor = state.points[anchorIndex];
  const target = state.points[targetIndex];
  const referenceVector = subtractPoints(state.points[reference.other], anchor);
  const segmentVector = subtractPoints(target, anchor);
  const newDirection = segmentDirectionForBend(referenceVector, segmentVector, normalizeBendAngle(bendAngleValue));
  const newTarget = addPoints(anchor, newDirection, pointLength(segmentVector));
  const snapshot = createUndoSnapshot();

  rotateSegmentSide(segment, anchorIndex, targetIndex, newTarget);
  selectSingleSegment(segment.index);
  state.selectedPoint = targetIndex;
  state.activePoint = targetIndex;
  state.selectedFitting = null;
  state.selectedNote = null;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
  return true;
}

function segmentDirectionForBend(referenceVector, segmentVector, bendAngleValue) {
  const includedRadians = (180 - normalizeBendAngle(bendAngleValue)) * Math.PI / 180;
  const referenceDirection = normalizePoint(referenceVector);
  const segmentDirection = normalizePoint(segmentVector);
  const projected = subtractPoints(segmentDirection, scalePoint(referenceDirection, dotPoints(segmentDirection, referenceDirection)));
  const perpendicular = pointLength(projected) > 0.0001
    ? normalizePoint(projected)
    : fallbackPerpendicular(referenceDirection);

  return normalizePoint(addPoints(
    scalePoint(referenceDirection, Math.cos(includedRadians)),
    scalePoint(perpendicular, Math.sin(includedRadians)),
  ));
}

function fallbackPerpendicular(direction) {
  const abs = {
    x: Math.abs(direction.x),
    y: Math.abs(direction.y),
    z: Math.abs(direction.z),
  };
  const reference = abs.z < 0.9 ? { x: 0, y: 0, z: 1 } : { x: 1, y: 0, z: 0 };
  return normalizePoint(crossPoints(reference, direction));
}

function translateSegmentSide(segment, anchorIndex, targetIndex, newTargetPoint) {
  const delta = subtractPoints(newTargetPoint, state.points[targetIndex]);
  const moving = movablePointIndexes(segment, anchorIndex, targetIndex);
  for (const pointIndex of moving) {
    state.points[pointIndex] = addPoints(state.points[pointIndex], delta);
  }
}

function rotateSegmentSide(segment, anchorIndex, targetIndex, newTargetPoint) {
  const anchor = state.points[anchorIndex];
  const oldVector = subtractPoints(state.points[targetIndex], anchor);
  const newVector = subtractPoints(newTargetPoint, anchor);
  const oldDirection = normalizePoint(oldVector);
  const newDirection = normalizePoint(newVector);
  const axisRaw = crossPoints(oldDirection, newDirection);
  const axisLength = pointLength(axisRaw);

  if (axisLength < 0.0001) {
    translateSegmentSide(segment, anchorIndex, targetIndex, newTargetPoint);
    return;
  }

  const axis = scalePoint(axisRaw, 1 / axisLength);
  const angle = Math.atan2(axisLength, Math.max(-1, Math.min(1, dotPoints(oldDirection, newDirection))));
  const moving = movablePointIndexes(segment, anchorIndex, targetIndex);
  for (const pointIndex of moving) {
    const relative = subtractPoints(state.points[pointIndex], anchor);
    state.points[pointIndex] = addPoints(anchor, rotateVectorAroundAxis(relative, axis, angle));
  }
}

function rotateVectorAroundAxis(vector, axis, angle) {
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const parallel = scalePoint(axis, dotPoints(axis, vector) * (1 - cos));
  const crossed = scalePoint(crossPoints(axis, vector), sin);
  return addPoints(addPoints(scalePoint(vector, cos), crossed), parallel);
}

function movablePointIndexes(segment, anchorIndex, targetIndex) {
  const moving = new Set([targetIndex]);
  const stack = [targetIndex];

  while (stack.length) {
    const pointIndex = stack.pop();
    for (const [edgeIndex, edge] of state.edges.entries()) {
      if (edgeIndex === segment.index) continue;
      let next = null;
      if (edge.from === pointIndex) next = edge.to;
      if (edge.to === pointIndex) next = edge.from;
      if (next === null || next === anchorIndex || moving.has(next)) continue;
      moving.add(next);
      stack.push(next);
    }
  }

  return moving;
}

function referenceConnectionForSegment(segment, anchorIndex) {
  for (const [edgeIndex, edge] of state.edges.entries()) {
    if (edgeIndex === segment.index) continue;
    if (edge.from === anchorIndex) return { edgeIndex, other: edge.to };
    if (edge.to === anchorIndex) return { edgeIndex, other: edge.from };
  }
  return null;
}

function bendEditAnchorForHit(hit) {
  if (!hit) return null;
  const candidates = [
    { index: hit.segment.from, distance: hit.t },
    { index: hit.segment.to, distance: 1 - hit.t },
  ].filter((candidate) => referenceConnectionForSegment(hit.segment, candidate.index));

  if (!candidates.length) return null;
  candidates.sort((a, b) => a.distance - b.distance);
  return candidates[0].index;
}

function bendAngleForSegmentAt(segment, anchorIndex) {
  const reference = referenceConnectionForSegment(segment, anchorIndex);
  if (!reference) return null;
  const targetIndex = anchorIndex === segment.from ? segment.to : segment.from;
  const first = subtractPoints(state.points[reference.other], state.points[anchorIndex]);
  const second = subtractPoints(state.points[targetIndex], state.points[anchorIndex]);
  return Math.abs(180 - bendAngle(first, second));
}

function takeoffData(segmentData = segments()) {
  const connections = nodeConnections(segmentData);
  const segmentTakeoffs = new Map(segmentData.map((segment) => [segment.index, 0]));
  const elbows = [];
  const reducers = [];
  const tees = [];
  const branches = [];

  for (const [nodeIndex, connected] of connections.entries()) {
    if (connected.length >= 3) {
      if (nodeConnectionType(nodeIndex) === "branch") {
        const branch = branchTakeoffForNode(nodeIndex, connected, segmentData);
        if (branch) {
          for (const connection of branch.connections) {
            segmentTakeoffs.set(connection.segmentIndex, (segmentTakeoffs.get(connection.segmentIndex) ?? 0) + connection.takeoffMm);
          }
          branches.push(branch);
        }
        // A fabricated branch is a continuous main pipe with a welded outlet.
        // It never receives tee take-offs, a tee fitting, or automatic reducers.
        continue;
      }

      const tee = teeTakeoffForNode(nodeIndex, connected, segmentData);
      if (tee) {
        for (const connection of tee.connections) {
          segmentTakeoffs.set(connection.segmentIndex, (segmentTakeoffs.get(connection.segmentIndex) ?? 0) + connection.takeoffMm);
        }
        tees.push(tee);
      }
      for (const reducer of autoReducersForTeeNode(nodeIndex, connected, segmentData)) {
        applyReducerTakeoff(segmentTakeoffs, reducer);
        reducers.push(reducer);
      }
      continue;
    }

    if (connected.length !== 2) continue;

    const firstSegment = segmentData.find((segment) => segment.index === connected[0].segmentIndex);
    const secondSegment = segmentData.find((segment) => segment.index === connected[1].segmentIndex);
    if (!firstSegment || !secondSegment) continue;

    const firstVector = subtractPoints(state.points[connected[0].other], state.points[nodeIndex]);
    const secondVector = subtractPoints(state.points[connected[1].other], state.points[nodeIndex]);
    const bend = Math.abs(180 - bendAngle(firstVector, secondVector));
    const reducer = autoReducerForConnection(nodeIndex, connected[0], connected[1], firstSegment, secondSegment, { bend });
    if (reducer) {
      applyReducerTakeoff(segmentTakeoffs, reducer);
      reducers.push(reducer);
    }

    if (bend < 0.5) {
      continue;
    }

    const firstTakeoff = bendTakeoffMm(firstSegment, bend);
    const secondTakeoff = bendTakeoffMm(secondSegment, bend);
    segmentTakeoffs.set(firstSegment.index, (segmentTakeoffs.get(firstSegment.index) ?? 0) + firstTakeoff);
    segmentTakeoffs.set(secondSegment.index, (segmentTakeoffs.get(secondSegment.index) ?? 0) + secondTakeoff);

    const bendSize = largerPipeSize(firstSegment, secondSegment);
    elbows.push({
      nodeIndex,
      bend,
      nb: bendSize.nb,
      takeoffMm: Math.max(firstTakeoff, secondTakeoff),
      firstSegmentIndex: firstSegment.index,
      secondSegmentIndex: secondSegment.index,
      firstTakeoffMm: firstTakeoff,
      secondTakeoffMm: secondTakeoff,
      weightKg: elbowWeightKg(bendSize, bend),
    });
  }

  return { segmentTakeoffs, elbows, reducers, tees, branches };
}

function weldedSegmentEndCounts(segmentData = segments(), data = takeoffData(segmentData)) {
  const segmentIndexes = new Set(segmentData.map((segment) => segment.index));
  const weldedEnds = new Set();
  const add = (segmentIndex, nodeIndex) => {
    if (!segmentIndexes.has(segmentIndex) || !Number.isInteger(Number(nodeIndex))) return;
    weldedEnds.add(`${segmentIndex}:${Number(nodeIndex)}`);
  };

  for (const elbow of data.elbows ?? []) {
    add(elbow.firstSegmentIndex, elbow.nodeIndex);
    add(elbow.secondSegmentIndex, elbow.nodeIndex);
  }
  for (const tee of data.tees ?? []) {
    for (const connection of tee.connections ?? []) add(connection.segmentIndex, tee.nodeIndex);
  }
  // A fabricated branch keeps the main pipe continuous. Only each outlet pipe
  // meets the welded branch, so the straight-through main receives no gap here.
  for (const branch of data.branches ?? []) {
    for (const connection of branch.connections ?? []) add(connection.segmentIndex, branch.nodeIndex);
  }
  for (const reducer of data.reducers ?? []) {
    add(reducer.firstSegmentIndex, reducer.nodeIndex);
    add(reducer.secondSegmentIndex, reducer.nodeIndex);
  }
  // End flanges are welded fitting connections even though the spool terminates
  // there. Roll-grooved, threaded and genuinely plain/open pipe ends are not.
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));
  for (const fitting of state.fittings ?? []) {
    const segment = segmentByIndex.get(Number(fitting.segmentIndex));
    if (!segment) continue;
    if (fitting?.type === "flange") {
      const t = normalizeFittingPosition("flange", fitting.t);
      if (t === 0) add(segment.index, segment.from);
      if (t === 1) add(segment.index, segment.to);
      continue;
    }
    if (fitting?.type === "weld" && fitting.bigSpoolFieldJoint === true) {
      if (fitting.fieldJointEnd === "start") add(segment.index, segment.from);
      if (fitting.fieldJointEnd === "end") add(segment.index, segment.to);
    }
  }

  const counts = new Map(segmentData.map((segment) => [segment.index, 0]));
  for (const key of weldedEnds) {
    const segmentIndex = Number(key.split(":")[0]);
    counts.set(segmentIndex, (counts.get(segmentIndex) ?? 0) + 1);
  }
  return counts;
}

function autoReducerTransitions(segmentData = segments()) {
  const connections = nodeConnections(segmentData);
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));
  const reducers = [];

  for (const [nodeIndex, connected] of connections.entries()) {
    if (nodeConnectionType(nodeIndex) === "branch") continue;

    if (connected.length >= 3) {
      reducers.push(...autoReducersForTeeNode(nodeIndex, connected, segmentData));
      continue;
    }

    if (connected.length !== 2) continue;
    const firstSegment = segmentByIndex.get(connected[0].segmentIndex);
    const secondSegment = segmentByIndex.get(connected[1].segmentIndex);
    if (!firstSegment || !secondSegment) continue;

    const firstVector = subtractPoints(state.points[connected[0].other], state.points[nodeIndex]);
    const secondVector = subtractPoints(state.points[connected[1].other], state.points[nodeIndex]);
    const bend = Math.abs(180 - bendAngle(firstVector, secondVector));

    const reducer = autoReducerForConnection(nodeIndex, connected[0], connected[1], firstSegment, secondSegment, { bend });
    if (reducer) reducers.push(reducer);
  }

  return reducers;
}

function autoReducersForTeeNode(nodeIndex, connected, segmentData = segments()) {
  if (nodeConnectionType(nodeIndex) === "branch") return [];

  const entries = nodeConnectionEntries(nodeIndex, connected, segmentData);
  if (entries.length < 3) return [];

  const reducers = [];
  const addTeeReducer = (first, second) => {
    const reducer = teeReducerFromEntries(nodeIndex, first, second);
    if (!reducer) return;
    const duplicate = reducers.some((item) => item.smallSegment.index === reducer.smallSegment.index);
    if (!duplicate) reducers.push(reducer);
  };

  // Model a mixed-size connection as an equal tee at the largest connected
  // size, then reduce every smaller leg. This remains correct when the largest
  // pipe is the outlet rather than one of the straight-through legs.
  const largestEntry = [...entries].sort((a, b) =>
    b.size.od - a.size.od ||
    b.size.nb - a.size.nb ||
    a.segment.index - b.segment.index
  )[0];
  for (const entry of entries) {
    if (entry.segment.index === largestEntry.segment.index) continue;
    addTeeReducer(largestEntry, entry);
  }

  return reducers;
}

function teeReducerFromEntries(nodeIndex, first, second) {
  const reducer = autoReducerForConnection(nodeIndex, first, second, first.segment, second.segment, { bend: 0 });
  if (!reducer) return null;

  const takeoffMm = Math.min(reducer.lengthMm, pointLength(reducer.smallSegment.vector) * 0.45);
  return {
    ...reducer,
    kind: "tee",
    firstTakeoffMm: reducer.firstSegmentIndex === reducer.smallSegment.index ? takeoffMm : 0,
    secondTakeoffMm: reducer.secondSegmentIndex === reducer.smallSegment.index ? takeoffMm : 0,
    source: reducer.source.includes("Atlas") ? reducer.source : "estimated tee reducer",
  };
}

function applyReducerTakeoff(segmentTakeoffs, reducer) {
  if (!reducer) return;
  if (Number.isInteger(reducer.firstSegmentIndex)) {
    segmentTakeoffs.set(reducer.firstSegmentIndex, (segmentTakeoffs.get(reducer.firstSegmentIndex) ?? 0) + (reducer.firstTakeoffMm ?? 0));
  }
  if (Number.isInteger(reducer.secondSegmentIndex)) {
    segmentTakeoffs.set(reducer.secondSegmentIndex, (segmentTakeoffs.get(reducer.secondSegmentIndex) ?? 0) + (reducer.secondTakeoffMm ?? 0));
  }
}

function teeTakeoffForNode(nodeIndex, connected, segmentData = segments()) {
  const rawEntries = nodeConnectionEntries(nodeIndex, connected, segmentData);
  if (rawEntries.length < 3) return null;

  const largestSize = rawEntries
    .map((entry) => entry.size)
    .sort((a, b) => b.od - a.od)[0];
  const smallestSize = rawEntries
    .map((entry) => entry.size)
    .sort((a, b) => a.od - b.od)[0];
  const entries = rawEntries.map((entry) => ({
    ...entry,
    // A smaller connected run is modelled as an equal tee plus a reducer.
    // The tee centre-to-end deduction therefore remains the line-size tee takeoff on every leg.
    takeoffMm: Math.min(teeTakeoffMm(largestSize), entry.lengthMm * 0.45),
  }));
  const reducing = entries.some((entry) => entry.size.nb !== largestSize.nb);
  const atlasWeightKg = atlasButtweldWeight(largestSize, "tee");
  const weightKg = atlasWeightKg ?? estimatedTeeWeightKg(largestSize);

  return {
    type: "tee",
    nodeIndex,
    nb: largestSize.nb,
    branchNb: smallestSize.nb,
    reducing,
    weightKg,
    source: atlasWeightKg === null
      ? "estimated"
      : isTubePipeSize(largestSize)
      ? "Atlas tube tee table"
      : "Atlas table",
    connections: entries.map((entry) => ({
      segmentIndex: entry.segment.index,
      nb: entry.size.nb,
      takeoffMm: entry.takeoffMm,
    })),
  };
}

function branchTakeoffForNode(nodeIndex, connected, segmentData = segments()) {
  const info = branchNodeInfo(nodeIndex, connected, segmentData);
  if (!info || info.entries.length < 3) return null;

  const branchEntries = info.branchEntries.length ? info.branchEntries : info.entries.slice(2);
  if (!branchEntries.length) return null;

  const connections = branchEntries.map((entry) => ({
    segmentIndex: entry.segment.index,
    nb: entry.size.nb,
    takeoffMm: Math.min(branchTakeoffMm(info.mainSize, entry.size), entry.lengthMm * 0.45),
  }));
  const branchSize = branchEntries
    .map((entry) => entry.size)
    .sort((a, b) => a.od - b.od)[0] ?? info.mainSize;
  const weightKg = branchEntries.reduce((sum, entry) => sum + estimatedBranchWeldWeightKg(info.mainSize, entry.size), 0);

  return {
    type: "branch",
    nodeIndex,
    nb: info.mainSize.nb,
    branchNb: branchSize.nb,
    reducing: branchEntries.some((entry) => entry.size.nb !== info.mainSize.nb),
    weightKg,
    source: "branch weld estimate",
    connections,
  };
}

function nodeConnectionEntries(nodeIndex, connected, segmentData = segments()) {
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));
  return connected
    .map((connection) => {
      const segment = segmentByIndex.get(connection.segmentIndex);
      if (!segment) return null;
      const vector = subtractPoints(state.points[connection.other], state.points[nodeIndex]);
      const lengthMm = pointLength(vector);
      if (lengthMm <= 0.001) return null;
      return {
        ...connection,
        segment,
        size: pipeSizeForSegment(segment),
        vector: normalizePoint(vector),
        lengthMm,
      };
    })
    .filter(Boolean);
}

function branchNodeInfo(nodeIndex, connected, segmentData = segments()) {
  const entries = nodeConnectionEntries(nodeIndex, connected, segmentData);
  if (entries.length < 3) return null;

  // A welded branch is defined by geometry: the most straight-through pair is
  // the continuous main, even when the outlet is temporarily the largest size.
  const mainPair = mostOppositeEntryPair(entries);
  const mainSegments = new Set(mainPair ? mainPair.map((entry) => entry.segment.index) : []);
  const branchEntries = entries.filter((entry) => !mainSegments.has(entry.segment.index));
  const mainSize = (mainPair ?? [])
    .map((entry) => entry.size)
    .sort((a, b) => b.od - a.od)[0] ?? pipeSizeByNb(state.pipeSizeNb);

  return {
    entries,
    mainPair,
    mainSegments,
    mainSize,
    branchEntries,
  };
}

function branchMainLinkedSegmentIndexes(indexes, segmentData = segments()) {
  const linked = new Set(normalizeSelectedSegments(indexes, state.edges.length));
  if (!linked.size || !segmentData.length) return [...linked];
  const connections = nodeConnections(segmentData);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [nodeIndex, connected] of connections.entries()) {
      if (connected.length < 3 || nodeConnectionType(nodeIndex) !== "branch") continue;
      const mainPair = branchNodeInfo(nodeIndex, connected, segmentData)?.mainPair ?? [];
      const mainIndexes = mainPair
        .map((entry) => entry?.segment?.index)
        .filter((index) => Number.isInteger(index));
      if (mainIndexes.length !== 2 || !mainIndexes.some((index) => linked.has(index))) continue;
      for (const index of mainIndexes) {
        if (linked.has(index)) continue;
        linked.add(index);
        changed = true;
      }
    }
  }
  return [...linked].sort((a, b) => a - b);
}

function mostOppositeEntryPair(entries) {
  if (entries.length < 2) return null;

  let best = null;
  let bestDot = Infinity;
  for (let i = 0; i < entries.length; i += 1) {
    for (let j = i + 1; j < entries.length; j += 1) {
      const dot = dotPoints(entries[i].vector, entries[j].vector);
      if (dot < bestDot) {
        bestDot = dot;
        best = [entries[i], entries[j]];
      }
    }
  }
  return best;
}

function teeTakeoffMm(size) {
  if (isTubePipeSize(size) && Number.isFinite(size.tubeTeeTakeoffMm)) return size.tubeTeeTakeoffMm;
  return TEE_TAKEOFF_MM[size.nb] ?? Math.max(size.od * 0.85, size.lrRadius * 0.68);
}

function branchTakeoffMm(mainSize, branchSize) {
  return Math.max(mainSize.od * 0.5, branchSize.od * 0.35, 25);
}

function estimatedTeeWeightKg(size) {
  const scale = Math.max(0.12, Math.pow(size.od / 60.3, 2));
  return Math.max(0.2, scale * 0.9);
}

function estimatedBranchWeldWeightKg(mainSize, branchSize) {
  const scale = Math.max(0.08, Math.pow(branchSize.od / 60.3, 2));
  const mainScale = Math.max(0.9, mainSize.od / Math.max(branchSize.od, 1));
  return Math.max(0.06, scale * 0.16 * Math.min(mainScale, 1.8));
}

function autoReducerForConnection(nodeIndex, firstConnection, secondConnection, firstSegment, secondSegment, options = {}) {
  const firstSize = pipeSizeForSegment(firstSegment);
  const secondSize = pipeSizeForSegment(secondSegment);
  if (firstSize.nb === secondSize.nb) return null;

  const lengthMm = reducerLengthMm(firstSize, secondSize);
  const isBendReducer = Number(options.bend) >= 0.5;
  const firstIsLarge = firstSize.od >= secondSize.od;
  const largeSegment = firstIsLarge ? firstSegment : secondSegment;
  const smallSegment = firstIsLarge ? secondSegment : firstSegment;
  const largeSize = firstIsLarge ? firstSize : secondSize;
  const smallSize = firstIsLarge ? secondSize : firstSize;
  const largeOtherIndex = firstIsLarge ? firstConnection.other : secondConnection.other;
  const smallOtherIndex = firstIsLarge ? secondConnection.other : firstConnection.other;
  const reducerType = reducerTypeForNode(nodeIndex);
  const eccentricOffsetMm = reducerEccentricOffsetMm(largeSize, smallSize);
  const placementSide = isBendReducer ? reducerSideForNode(nodeIndex) : "small";
  const placementSegment = placementSide === "large" ? largeSegment : smallSegment;
  const inlineFirstTakeoffMm = Math.min(lengthMm * 0.5, pointLength(firstSegment.vector) * 0.45);
  const inlineSecondTakeoffMm = Math.min(lengthMm * 0.5, pointLength(secondSegment.vector) * 0.45);
  const bendReducerTakeoffMm = Math.min(lengthMm, pointLength(placementSegment.vector) * 0.45);
  const firstTakeoffMm = isBendReducer
    ? (firstSegment.index === placementSegment.index ? bendReducerTakeoffMm : 0)
    : inlineFirstTakeoffMm;
  const secondTakeoffMm = isBendReducer
    ? (secondSegment.index === placementSegment.index ? bendReducerTakeoffMm : 0)
    : inlineSecondTakeoffMm;
  const firstBendTakeoffMm = isBendReducer ? bendTakeoffMm(firstSegment, options.bend) : 0;
  const secondBendTakeoffMm = isBendReducer ? bendTakeoffMm(secondSegment, options.bend) : 0;
  const atlasWeightKg = atlasReducerWeightForSizes(largeSize, smallSize, reducerType);
  const reducerWeightKg = atlasWeightKg ?? (lengthMm / 1000) * ((pipeMassPerMetreForSize(firstSize) + pipeMassPerMetreForSize(secondSize)) * 0.5) * 1.12;
  const reducerWeightSource = atlasWeightKg === null
    ? "estimated"
    : isTubePipeSize(largeSize)
    ? "Atlas tube reducer table"
    : normalizePipeSpec(state.pipeSpec) === "stainless10"
    ? "Atlas Sch 10S size-pair table"
    : "Atlas large-end table";

  return {
    nodeIndex,
    firstSegmentIndex: firstSegment.index,
    secondSegmentIndex: secondSegment.index,
    firstTakeoffMm,
    secondTakeoffMm,
    lengthMm,
    reducerType,
    eccentricOffsetMm: reducerType === "eccentric" ? eccentricOffsetMm : 0,
    weightKg: reducerWeightKg,
    source: reducerWeightSource,
    kind: isBendReducer ? "bend" : "inline",
    placementSide,
    bend: Number(options.bend) || 0,
    largeBendTakeoffMm: firstIsLarge ? firstBendTakeoffMm : secondBendTakeoffMm,
    smallBendTakeoffMm: firstIsLarge ? secondBendTakeoffMm : firstBendTakeoffMm,
    largeNb: largeSize.nb,
    smallNb: smallSize.nb,
    largeSegment,
    smallSegment,
    largeOtherIndex,
    smallOtherIndex,
  };
}

function atlasStainless10ReducerWeightForSizes(largeSize, smallSize, reducerType = "concentric") {
  if (!largeSize || !smallSize) return null;
  const key = `${Number(largeSize.nb)}:${Number(smallSize.nb)}`;
  const eccentricWeight = ATLAS_STAINLESS10_ECCENTRIC_REDUCER_WEIGHT_OVERRIDES[key];
  if (normalizeReducerType(reducerType) === "eccentric" && Number.isFinite(eccentricWeight)) return eccentricWeight;
  const weight = ATLAS_STAINLESS10_REDUCER_WEIGHTS[key];
  return Number.isFinite(weight) ? weight : null;
}

function atlasReducerWeightForSizes(largeSize, smallSize, reducerType = "concentric") {
  if (!largeSize || !smallSize) return null;
  if (normalizePipeSpec(state.pipeSpec) === "stainless10" && !isTubePipeSize(largeSize)) {
    return atlasStainless10ReducerWeightForSizes(largeSize, smallSize, reducerType);
  }
  return atlasButtweldWeight(largeSize, "reducer");
}

function reducerEccentricOffsetMm(firstSize, secondSize) {
  if (!firstSize || !secondSize) return 0;
  return Math.max(0, Math.abs(Number(firstSize.od) - Number(secondSize.od)) * 0.5);
}

function reducerLengthMm(firstSize, secondSize) {
  const largeOd = Math.max(firstSize.od, secondSize.od);
  const largeSize = firstSize.od >= secondSize.od ? firstSize : secondSize;
  if (isTubePipeSize(largeSize) && Number.isFinite(largeSize.tubeReducerLengthMm)) return largeSize.tubeReducerLengthMm;
  const tableLength = REDUCER_LENGTH_MM[largeSize.nb];
  if (Number.isFinite(tableLength)) return tableLength;
  return clampNumber(largeOd * 0.9, 38, 450);
}

function bendTakeoffMm(segment, bendDegrees) {
  const size = pipeSizeForSegment(segment);
  const bend = normalizeBendAngle(bendDegrees);
  if (!isTubePipeSize(size)) {
    if (Math.abs(bend - 45) < 0.5 && Number.isFinite(ELBOW_45_TAKEOFF_MM[size.nb])) {
      return ELBOW_45_TAKEOFF_MM[size.nb];
    }
    if (Math.abs(bend - 90) < 0.5 && Number.isFinite(size.lrRadius)) {
      return size.lrRadius;
    }
  }
  // Non-standard pipe angles and sanitary tube bends do not have an explicit
  // centre-to-end table in the supplied Atlas manual, so retain the geometric
  // centre-line estimate rather than presenting it as an Atlas dimension.
  return size.lrRadius * Math.tan((bend * Math.PI / 180) / 2);
}

function largerPipeSize(firstSegment, secondSegment) {
  const first = pipeSizeForSegment(firstSegment);
  const second = pipeSizeForSegment(secondSegment);
  return first.od >= second.od ? first : second;
}

function elbowWeightKg(size, bendDegrees) {
  const bend = normalizeBendAngle(bendDegrees);
  const elbow90 = atlasButtweldWeight(size, "elbow90");
  const elbow45 = atlasButtweldWeight(size, "elbow45");
  if (Math.abs(bend - 90) < 0.5 && elbow90 !== null) {
    return elbow90;
  }
  if (Math.abs(bend - 45) < 0.5 && elbow45 !== null) {
    return elbow45;
  }
  if (elbow90 !== null) {
    return elbow90 * (bend / 90);
  }
  const bendRadians = bend * Math.PI / 180;
  return pipeMassPerMetreForSize(size) * (size.lrRadius / 1000) * bendRadians;
}

function segmentQuantity(segment, takeoffs = null, weldEndCounts = null) {
  if (!(takeoffs instanceof Map) || !(weldEndCounts instanceof Map)) {
    const segmentData = segments();
    const data = takeoffData(segmentData);
    if (!(takeoffs instanceof Map)) takeoffs = data.segmentTakeoffs;
    if (!(weldEndCounts instanceof Map)) weldEndCounts = weldedSegmentEndCounts(segmentData, data);
  }
  const centrelineMm = pointLength(segment.vector);
  const bendTakeoffMmTotal = takeoffs.get(segment.index) ?? 0;
  const weldEndCount = Math.max(0, Math.floor(Number(weldEndCounts.get(segment.index)) || 0));
  const weldGapPerEndMm = projectWeldGapMm();
  const weldGapMm = weldEndCount * weldGapPerEndMm;
  const cutLengthMm = Math.max(0, centrelineMm - bendTakeoffMmTotal - weldGapMm);
  const pipeWeightKg = (cutLengthMm / 1000) * pipeMassPerMetre(segment);
  return {
    centrelineMm,
    bendTakeoffMm: bendTakeoffMmTotal,
    weldEndCount,
    weldGapPerEndMm,
    weldGapMm,
    cutLengthMm,
    pipeWeightKg,
  };
}

function fittingWeightOverride(fitting) {
  if (fitting?.type === "rollGroove" || fitting?.type === "threadedEnd") return null;
  const weightKg = Number(fitting?.weightKg);
  return Number.isFinite(weightKg) && weightKg >= 0 ? weightKg : null;
}

function fittingWeightSource(fitting, segment = null) {
  if (fitting?.type === "rollGroove" || fitting?.type === "threadedEnd") return "zero weight";
  if (fittingWeightOverride(fitting) !== null) return "manual";
  if (atlasFittingWeightKg(fitting, segment) === null) return "estimated";
  if (fitting?.type === "flange" && fittingFlangeStandard(fitting) !== "ansi150") {
    return "estimated from base table";
  }
  return "Atlas table";
}

function fittingWeightKg(fitting, segment) {
  if (fitting?.type === "rollGroove" || fitting?.type === "threadedEnd") return 0;
  return fittingWeightOverride(fitting) ?? atlasFittingWeightKg(fitting, segment) ?? estimatedFittingWeightKg(fitting, segment);
}

function atlasSpecKey() {
  return normalizePipeSpec(state.pipeSpec);
}

function atlasButtweldWeight(size, key) {
  const table = ATLAS_BUTTWELD_WEIGHTS[atlasSpecKey()] ?? {};
  const weight = table[size.nb]?.[key];
  return Number.isFinite(weight) ? weight : null;
}

function atlasFittingWeightKg(fitting, segment) {
  if (!fitting || !segment) return null;
  const size = pipeSizeForSegment(segment);

  if (fitting.type === "flange") {
    const single = ATLAS_FLANGE_WEIGHTS[size.nb];
    if (!Number.isFinite(single)) return null;
    const adjusted = single * (flangeStandardInfo(fittingFlangeStandard(fitting)).weightFactor || 1);
    return fittingFlangeMode(fitting) === "single" ? adjusted : adjusted * 2;
  }

  if (fitting.type === "reducer") {
    // Stainless Sch 10S reducer weights depend on both end sizes. A manually placed
    // marker has no nominated outlet size, so do not present a large-end value as exact.
    if (normalizePipeSpec(state.pipeSpec) === "stainless10" && !isTubePipeSize(size)) return null;
    return atlasButtweldWeight(size, "reducer");
  }

  if (fitting.type === "tee") {
    return atlasButtweldWeight(size, "tee");
  }

  return null;
}

function estimatedFittingWeightKg(fitting, segment) {
  const size = pipeSizeForSegment(segment);
  const scale = Math.max(0.12, Math.pow(size.od / 60.3, 2));

  if (fitting.type === "flange") {
    const single = Math.max(0.4, scale * 2.2) * (flangeStandardInfo(fittingFlangeStandard(fitting)).weightFactor || 1);
    return fittingFlangeMode(fitting) === "single" ? single : single * 2.12;
  }
  if (fitting.type === "valve") return Math.max(0.6, scale * 5.6);
  if (fitting.type === "weld") return Math.max(0.05, scale * 0.12);
  if (fitting.type === "reducer") return Math.max(0.25, scale * 1.35);
  if (fitting.type === "socket") {
    const socketSize = pipeSizeByNb(fittingSocketSizeNb(fitting), "carbon40");
    return Math.max(0.06, pipeMassPerMetreForSize(socketSize) * 0.05 + 0.03);
  }
  if (fitting.type === "rollGroove") return 0;
  if (fitting.type === "threadedEnd") return 0;
  return 0;
}

function fittingQuantities(segmentData = segments()) {
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));
  return state.fittings
    .map((fitting) => {
      const segment = segmentByIndex.get(fitting.segmentIndex);
      if (!segment) return null;
      return {
        fitting,
        segment,
        point: fittingDisplayPoint(segment, fitting),
        weightKg: fittingWeightKg(fitting, segment),
        weightSource: fittingWeightSource(fitting, segment),
      };
    })
    .filter(Boolean);
}

function quantitySummary(segmentData = segments()) {
  const data = takeoffData(segmentData);
  const weldEndCounts = weldedSegmentEndCounts(segmentData, data);
  const segmentsWithQuantity = segmentData.map((segment) => ({
    segment,
    quantity: segmentQuantity(segment, data.segmentTakeoffs, weldEndCounts),
  }));
  const cutSegmentsWithQuantity = branchMergedCutSegments(segmentData, data.segmentTakeoffs, weldEndCounts);
  const centrelineMm = segmentsWithQuantity.reduce((sum, item) => sum + item.quantity.centrelineMm, 0);
  const cutLengthMm = segmentsWithQuantity.reduce((sum, item) => sum + item.quantity.cutLengthMm, 0);
  const bendTakeoffMm = segmentsWithQuantity.reduce((sum, item) => sum + item.quantity.bendTakeoffMm, 0);
  const weldEndCount = segmentsWithQuantity.reduce((sum, item) => sum + item.quantity.weldEndCount, 0);
  const weldGapMm = segmentsWithQuantity.reduce((sum, item) => sum + item.quantity.weldGapMm, 0);
  const pipeWeightKg = segmentsWithQuantity.reduce((sum, item) => sum + item.quantity.pipeWeightKg, 0);
  const bendWeightKg = data.elbows.reduce((sum, elbow) => sum + elbow.weightKg, 0);
  const reducerWeightKg = data.reducers.reduce((sum, reducer) => sum + reducer.weightKg, 0);
  const teeWeightKg = data.tees.reduce((sum, tee) => sum + tee.weightKg, 0);
  const branchWeightKg = data.branches.reduce((sum, branch) => sum + branch.weightKg, 0);
  const fittings = fittingQuantities(segmentData);
  const fittingWeightKg = fittings.reduce((sum, fitting) => sum + fitting.weightKg, 0);

  return {
    segments: segmentsWithQuantity,
    cutSegments: cutSegmentsWithQuantity,
    elbows: data.elbows,
    reducers: data.reducers,
    tees: data.tees,
    branches: data.branches,
    fittings,
    centrelineMm,
    cutLengthMm,
    bendTakeoffMm,
    weldEndCount,
    weldGapPerEndMm: projectWeldGapMm(),
    weldGapMm,
    pipeWeightKg,
    bendWeightKg,
    reducerWeightKg,
    teeWeightKg,
    branchWeightKg,
    fittingWeightKg,
    totalWeightKg: pipeWeightKg + bendWeightKg + reducerWeightKg + teeWeightKg + branchWeightKg + fittingWeightKg,
  };
}

function branchMergedCutSegments(
  segmentData = segments(),
  segmentTakeoffs = takeoffData(segmentData).segmentTakeoffs,
  weldEndCounts = weldedSegmentEndCounts(segmentData),
) {
  const rawRows = segmentData.map((segment) => ({
    segment,
    quantity: segmentQuantity(segment, segmentTakeoffs, weldEndCounts),
  }));
  const rowByIndex = new Map(rawRows.map((row) => [row.segment.index, row]));
  const connections = nodeConnections(segmentData);
  const consumed = new Set();
  const mergedByFirstIndex = new Map();

  for (const [nodeIndex, connected] of connections.entries()) {
    if (connected.length < 3 || nodeConnectionType(nodeIndex) !== "branch") continue;
    const info = branchNodeInfo(nodeIndex, connected, segmentData);
    const mainPair = info?.mainPair ?? [];
    if (mainPair.length !== 2) continue;
    const [first, second] = mainPair;
    if (!first?.segment || !second?.segment) continue;
    if (pipeSizeForSegment(first.segment).nb !== pipeSizeForSegment(second.segment).nb) continue;
    if (consumed.has(first.segment.index) || consumed.has(second.segment.index)) continue;

    const firstRow = rowByIndex.get(first.segment.index);
    const secondRow = rowByIndex.get(second.segment.index);
    if (!firstRow || !secondRow) continue;
    const firstIndex = Math.min(first.segment.index, second.segment.index);
    const startPoint = state.points[first.other];
    const endPoint = state.points[second.other];
    const mergedSegment = {
      index: firstIndex,
      from: first.other,
      to: second.other,
      pipeSizeNb: info.mainSize.nb,
      start: startPoint,
      end: endPoint,
      vector: subtractPoints(endPoint, startPoint),
      cutLabel: `${pointLabel(first.other)}-${pointLabel(second.other)} via branch ${pointLabel(nodeIndex)}`,
      mergedIndexes: [first.segment.index, second.segment.index],
    };
    mergedByFirstIndex.set(firstIndex, {
      segment: mergedSegment,
      quantity: {
        centrelineMm: firstRow.quantity.centrelineMm + secondRow.quantity.centrelineMm,
        bendTakeoffMm: firstRow.quantity.bendTakeoffMm + secondRow.quantity.bendTakeoffMm,
        weldEndCount: firstRow.quantity.weldEndCount + secondRow.quantity.weldEndCount,
        weldGapPerEndMm: projectWeldGapMm(),
        weldGapMm: firstRow.quantity.weldGapMm + secondRow.quantity.weldGapMm,
        cutLengthMm: firstRow.quantity.cutLengthMm + secondRow.quantity.cutLengthMm,
        pipeWeightKg: firstRow.quantity.pipeWeightKg + secondRow.quantity.pipeWeightKg,
      },
    });
    consumed.add(first.segment.index);
    consumed.add(second.segment.index);
  }

  const rows = [];
  for (const row of rawRows) {
    const merged = mergedByFirstIndex.get(row.segment.index);
    if (merged) {
      rows.push(merged);
      continue;
    }
    if (!consumed.has(row.segment.index)) rows.push(row);
  }
  return rows;
}

function cutRunLabel(segment) {
  return segment?.cutLabel ?? `${pointLabel(segment.from)}-${pointLabel(segment.to)}`;
}

function dimensionCodeForSegmentIndex(segmentIndex) {
  const index = Number(segmentIndex);
  return Number.isInteger(index) && index >= 0 ? `D${index + 1}` : "";
}

function cutRunDimensionIndexes(segment) {
  const indexes = Array.isArray(segment?.mergedIndexes) && segment.mergedIndexes.length
    ? segment.mergedIndexes
    : [segment?.index];
  return indexes.filter((index) => Number.isInteger(Number(index)) && Number(index) >= 0);
}

function cutRunDimensionLabel(segment) {
  const codes = cutRunDimensionIndexes(segment)
    .map(dimensionCodeForSegmentIndex)
    .filter(Boolean);
  return codes.length ? codes.join("+") : cutRunLabel(segment);
}

function cutRunDisplayTitle(segment) {
  const direction = runLabelForVector(segment?.vector);
  return `${cutRunDimensionLabel(segment)}${direction ? ` ${direction}` : ""} cut`;
}

function cutRunPointDetail(segment) {
  const pointLabelText = cutRunLabel(segment);
  return pointLabelText === cutRunDimensionLabel(segment) ? "" : pointLabelText;
}

function takeoffCountRows(quantities = quantitySummary()) {
  const rows = new Map();
  const spec = pipeSpec();
  const add = (key, label, quantity = 1, weightKg = 0, detail = "", order = 50) => {
    const existing = rows.get(key) ?? {
      key,
      label,
      quantity: 0,
      weightKg: 0,
      detail,
      order,
      lengthMm: 0,
      runCount: 0,
      singleFlanges: 0,
      doubleFlangeSets: 0,
    };
    existing.quantity += quantity;
    existing.weightKg += Number(weightKg) || 0;
    rows.set(key, existing);
    return existing;
  };

  for (const { segment, quantity } of quantities.cutSegments ?? quantities.segments) {
    const size = pipeSizeForSegment(segment);
    const row = add(
      `pipe:${size.nb}:${spec.schedule}`,
      `${isTubePipeSize(size) ? "Tube" : "Pipe"} ${pipeSizeDisplayLabel(size)} ${spec.schedule}`,
      0,
      quantity.pipeWeightKg,
      `${spec.material} ${isTubePipeSize(size) ? "tube" : "pipe"}`,
      0,
    );
    row.lengthMm += quantity.cutLengthMm;
    row.runCount += 1;
  }

  for (const elbow of quantities.elbows) {
    const angle = formatAngle(elbow.bend);
    add(
      `elbow:${elbow.nb}:${angle}`,
      `${isTubePipeSpec(state.pipeSpec) ? "Tube bend" : "LR elbow"} ${pipeSizeDisplayLabelByNb(elbow.nb)} ${angle} deg`,
      1,
      elbow.weightKg,
      isTubePipeSpec(state.pipeSpec) ? "tube bend" : "buttweld bend",
      10,
    );
  }

  for (const tee of quantities.tees) {
    add(
      `tee:${tee.nb}:equal`,
      `Tee ${pipeSizeDisplayLabelByNb(tee.nb)}`,
      1,
      tee.weightKg,
      tee.reducing
        ? `${tee.source} / equal tee; ${pipeSizeDisplayLabelByNb(tee.branchNb)} outlet uses the separately listed reducer`
        : tee.source,
      20,
    );
  }

  for (const branch of quantities.branches) {
    add(
      `branch:${branch.nb}:${branch.branchNb}`,
      `Branch weld ${pipeSizeDisplayLabelByNb(branch.nb)} x ${pipeSizeDisplayLabelByNb(branch.branchNb)}`,
      1,
      branch.weightKg,
      branch.source,
      25,
    );
  }

  for (const reducer of quantities.reducers) {
    add(
      `reducer:auto:${normalizeReducerType(reducer.reducerType)}:${reducer.largeNb}:${reducer.smallNb}`,
      `${reducerTypeLabel(reducer.reducerType)} reducer ${pipeSizeDisplayLabelByNb(reducer.largeNb)} x ${pipeSizeDisplayLabelByNb(reducer.smallNb)}`,
      1,
      reducer.weightKg,
      `${reducerDimensionDetail(reducer)} / ${reducer.source ?? "auto size change"}`,
      30,
    );
  }

  for (const item of quantities.fittings) {
    const size = pipeSizeForSegment(item.segment);
    const type = item.fitting?.type;
    if (type === "flange") {
      const mode = fittingFlangeMode(item.fitting);
      const standard = fittingFlangeStandard(item.fitting);
      const standardLabel = flangeStandardLabel(standard);
      const row = add(
        `flange:${standard}:${size.nb}`,
        `${standardLabel} flange ${pipeSizeDisplayLabel(size)}`,
        mode === "double" ? 2 : 1,
        item.weightKg,
        `${mode === "double" ? "double set" : "single"} / physical flange plates`,
        40,
      );
      if (mode === "double") row.doubleFlangeSets += 1;
      else row.singleFlanges += 1;
      continue;
    }

    if (type === "reducer") {
      const reducerType = fittingReducerType(item.fitting);
      add(
        `reducer:manual:${reducerType}:${size.nb}`,
        `Manual ${reducerTypeLabel(reducerType).toLowerCase()} reducer on ${pipeSizeDisplayLabel(size)}`,
        1,
        item.weightKg,
        "confirm outlet size",
        31,
      );
      continue;
    }

    if (type === "socket") {
      const socketNb = fittingSocketSizeNb(item.fitting);
      add(
        `socket:${socketNb}:host:${size.nb}`,
        `Socket ${pipeSizeDisplayLabelByNb(socketNb, "carbon40")} on ${pipeSizeDisplayLabel(size)}`,
        1,
        item.weightKg,
        `${formatAngle(fittingSocketAngle(item.fitting))} deg rotation`,
        70,
      );
      continue;
    }

    if (type === "rollGroove") {
      add(
        `rollGroove:${size.nb}`,
        `Roll groove ${pipeSizeDisplayLabel(size)}`,
        1,
        0,
        "0 kg allowance",
        60,
      );
      continue;
    }

    if (type === "threadedEnd") {
      add(
        `threadedEnd:${size.nb}`,
        `Threaded pipe end ${pipeSizeDisplayLabel(size)}`,
        1,
        0,
        "0 kg end preparation",
        61,
      );
      continue;
    }

    if (type === "valve") {
      add(`valve:${size.nb}`, `Valve ${pipeSizeDisplayLabel(size)}`, 1, item.weightKg, item.weightSource, 50);
      continue;
    }

    if (type === "weld") {
      add(`weld:${size.nb}`, `Weld mark ${pipeSizeDisplayLabel(size)}`, 1, item.weightKg, item.weightSource, 55);
    }
  }

  return [...rows.values()]
    .map((row) => {
      let countText = row.lengthMm > 0
        ? `${formatLength(row.lengthMm)} mm`
        : `x${row.quantity}`;
      let detail = row.detail;
      if (row.runCount) {
        detail = `${detail}; ${row.runCount} cut run${row.runCount === 1 ? "" : "s"}`;
      }
      if (row.singleFlanges || row.doubleFlangeSets) {
        detail = `${row.singleFlanges} single / ${row.doubleFlangeSets} double set${row.doubleFlangeSets === 1 ? "" : "s"}`;
      }
      return {
        ...row,
        countText,
        detail,
      };
    })
    .sort((a, b) => a.order - b.order || a.label.localeCompare(b.label));
}

function inferredMaterialChecklistItems(source = state) {
  const target = drawingStateTarget(source) ?? source;
  if (!target || typeof target !== "object") return [];
  try {
    return withTemporaryState(target, () => takeoffCountRows()
      .filter((row) => !/^(branch|rollGroove|threadedEnd|weld):/.test(String(row.key)))
      .map((row, index) => ({
        id: `gear-${String(row.key).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 80) || index}`,
        key: String(row.key),
        label: String(row.label),
        quantity: String(row.countText || (row.quantity ? `x${row.quantity}` : "")),
        detail: String(row.detail || ""),
        status: "pending",
        note: "",
        custom: false,
      })));
  } catch (error) {
    console.warn("Could not build the gear checklist from the spool take-off.", error);
    return [];
  }
}

function materialChecklistForState(source = state) {
  const target = drawingStateTarget(source) ?? source;
  const production = normalizeProductionInfo(target?.productionInfo);
  const saved = normalizeMaterialChecklist(production.materialChecklist);
  const byKey = new Map(saved.items.filter((item) => !item.custom).map((item) => [item.key, item]));
  const inferred = inferredMaterialChecklistItems(target).map((item) => ({
    ...item,
    ...(byKey.get(item.key) ?? {}),
    id: item.id,
    key: item.key,
    label: item.label,
    quantity: item.quantity,
    detail: item.detail,
    custom: false,
  }));
  return normalizeMaterialChecklist({
    ...saved,
    items: [...inferred, ...saved.items.filter((item) => item.custom)],
  });
}

function materialChecklistStats(checklist) {
  const normalized = normalizeMaterialChecklist(checklist);
  const resolved = normalized.items.filter((item) => item.status === "inshop" || item.status === "na").length;
  const missing = normalized.items.filter((item) => item.status === "order").length;
  const pending = normalized.items.filter((item) => item.status === "pending").length;
  const ready = normalized.items.length > 0 && pending === 0 && missing === 0 && Boolean(normalized.checkedAt);
  const overridden = Boolean(normalized.overrideAt && normalized.overrideReason);
  return { total: normalized.items.length, resolved, missing, pending, ready, overridden };
}

function materialChecklistCanStart(checklist) {
  const stats = materialChecklistStats(checklist);
  return stats.ready || stats.overridden;
}

function materialChecklistSummary(checklist) {
  const normalized = normalizeMaterialChecklist(checklist);
  const stats = materialChecklistStats(normalized);
  if (stats.ready) return `Ready / checked by ${normalized.checkedBy || "team"}`;
  if (stats.overridden) return `Override / ${normalized.overrideReason}`;
  if (stats.missing) return `${stats.missing} need ordering`;
  if (!stats.total) return "No gear list yet";
  return `${stats.resolved}/${stats.total} confirmed`;
}

function materialChecklistStatusLabel(value) {
  const status = normalizeMaterialCheckStatus(value);
  if (status === "inshop") return "In shop";
  if (status === "order") return "Needs ordering";
  if (status === "na") return "Not required";
  return "Not checked";
}

function centreOfGravityData(quantities = quantitySummary()) {
  const components = [];
  const addComponent = (weightKg, point, type) => {
    if (!Number.isFinite(weightKg) || weightKg <= 0 || !point) return;
    components.push({
      weightKg,
      point: clonePoint(point),
      type,
    });
  };

  for (const { segment, quantity } of quantities.cutSegments ?? quantities.segments) {
    addComponent(quantity.pipeWeightKg, lerpPoint(segment.start, segment.end, 0.5), "pipe");
  }

  for (const elbow of quantities.elbows) {
    addComponent(elbow.weightKg, state.points[elbow.nodeIndex], "elbow");
  }

  for (const reducer of quantities.reducers) {
    addComponent(reducer.weightKg, reducerCentrePoint(reducer), "reducer");
  }

  for (const tee of quantities.tees) {
    addComponent(tee.weightKg, state.points[tee.nodeIndex], "tee");
  }

  for (const branch of quantities.branches) {
    addComponent(branch.weightKg, state.points[branch.nodeIndex], "branch");
  }

  for (const fitting of quantities.fittings) {
    addComponent(fitting.weightKg, fitting.point, fitting.fitting.type);
  }

  const totalWeightKg = components.reduce((sum, component) => sum + component.weightKg, 0);
  if (totalWeightKg <= 0) return null;

  const weighted = components.reduce((sum, component) => ({
    x: sum.x + component.point.x * component.weightKg,
    y: sum.y + component.point.y * component.weightKg,
    z: sum.z + component.point.z * component.weightKg,
  }), { x: 0, y: 0, z: 0 });

  return {
    point: {
      x: weighted.x / totalWeightKg,
      y: weighted.y / totalWeightKg,
      z: weighted.z / totalWeightKg,
    },
    totalWeightKg,
    components,
  };
}

function reducerCentrePoint(reducer) {
  const joint = state.points[reducer.nodeIndex];
  const placementOther = state.points[reducerPlacementOtherIndex(reducer)];
  if (!joint || !placementOther) return joint;
  if (reducer.kind !== "bend" && !reducerStartsAtJoint(reducer)) return joint;

  const direction = normalizePoint(subtractPoints(placementOther, joint));
  const segmentLength = pointLength(subtractPoints(placementOther, joint));
  const offset = reducer.kind === "bend" ? reducerLegOffsetMm(reducer) : 0;
  const distance = Math.min(offset + (reducer.lengthMm ?? 0) * 0.5, segmentLength * 0.95);
  return addPoints(joint, direction, distance);
}

function reducerStartsAtJoint(reducer) {
  return reducer?.kind === "tee";
}

function reducerModelLengthMetres(reducer) {
  return Math.max(0.08, (Number(reducer?.lengthMm) || 0) / 1000);
}

function reducerRenderLengthMetres(reducer) {
  const nominalLength = reducerModelLengthMetres(reducer);
  const segmentLengths = [reducer?.largeSegment, reducer?.smallSegment]
    .map((segment) => pointLength(segment?.vector ?? { x: 0, y: 0, z: 0 }) / 1000)
    .filter((length) => Number.isFinite(length) && length > 0);
  const placementLength = reducer?.kind === "inline"
    ? Math.min(...segmentLengths)
    : pointLength(reducerPlacementSegment(reducer)?.vector ?? { x: 0, y: 0, z: 0 }) / 1000;
  if (!Number.isFinite(placementLength) || placementLength <= 0) return nominalLength;

  const maxShare = reducer?.kind === "tee" ? 0.48 : reducer?.kind === "inline" ? 0.44 : 0.58;
  const minimumVisibleLength = 0.035;
  const maxLength = Math.max(minimumVisibleLength, placementLength * maxShare);
  return clampNumber(nominalLength, minimumVisibleLength, maxLength);
}

function teeReducerStartOffsetMetres(reducer, style = null) {
  if (!reducerStartsAtJoint(reducer)) return 0;
  const coreRadius = Math.max(
    pipeRadiusMetres(reducer.largeSegment),
    pipeRadiusMetres(reducer.smallSegment),
  );
  return teeNodeLegLengthMetres(coreRadius, style);
}

function reducerSideForNode(nodeIndex) {
  const value = state.reducerSideOverrides?.[nodeIndex];
  return value === "large" ? "large" : "small";
}

function reducerTypeForNode(nodeIndex) {
  return normalizeReducerType(state.reducerTypeOverrides?.[nodeIndex] ?? state.reducerType);
}

function fittingReducerType(fitting) {
  return normalizeReducerType(fitting?.reducerType ?? state.reducerType);
}

function reducerDimensionDetail(reducer) {
  const length = `${formatLength(reducer?.lengthMm ?? 0)} mm H`;
  if (normalizeReducerType(reducer?.reducerType) !== "eccentric") return length;
  return `${length}; ${formatLength(reducer?.eccentricOffsetMm ?? 0)} mm centreline offset e`;
}

function reducerDimensionCompact(reducer) {
  const length = `H ${formatLength(reducer?.lengthMm ?? 0)} mm`;
  if (normalizeReducerType(reducer?.reducerType) !== "eccentric") return length;
  return `${length} · e ${formatLength(reducer?.eccentricOffsetMm ?? 0)} mm`;
}

function reducerPlacementSide(reducer) {
  return reducer?.kind === "bend" && reducer.placementSide === "large" ? "large" : "small";
}

function reducerPlacementSegment(reducer) {
  return reducerPlacementSide(reducer) === "large" ? reducer.largeSegment : reducer.smallSegment;
}

function reducerPlacementOtherIndex(reducer) {
  return reducerPlacementSide(reducer) === "large" ? reducer.largeOtherIndex : reducer.smallOtherIndex;
}

function reducerPlacementBendTakeoffMm(reducer) {
  return reducerPlacementSide(reducer) === "large"
    ? Number(reducer.largeBendTakeoffMm) || 0
    : Number(reducer.smallBendTakeoffMm) || 0;
}

function reducerLegOffsetMm(reducer) {
  if (reducer?.kind !== "bend") return 0;
  const placementSegment = reducerPlacementSegment(reducer);
  const smallLength = pointLength(placementSegment?.vector ?? { x: 0, y: 0, z: 0 });
  const bendTakeoff = reducerPlacementBendTakeoffMm(reducer);
  const reducerLength = Number(reducer.lengthMm) || 0;
  return clampNumber(bendTakeoff, 0, Math.max(0, smallLength - reducerLength));
}

function reducerScreenOffsetPixels(reducer, joint, placementOther, reducerLengthPx) {
  const screenLength = Math.hypot(placementOther.x - joint.x, placementOther.y - joint.y);
  const placementLength = pointLength(reducerPlacementSegment(reducer)?.vector ?? { x: 0, y: 0, z: 0 });
  if (screenLength <= reducerLengthPx + 4 || placementLength <= 0) return 2;

  const raw = (reducerLegOffsetMm(reducer) / placementLength) * screenLength;
  const visibleOffset = Math.max(raw, 18);
  return clampNumber(visibleOffset, 2, Math.max(2, screenLength - reducerLengthPx - 2));
}

function computeAutoReducerRenderTrims(reducers, style = null) {
  const trims = new Map();
  const addTrim = (segment, nodeIndex, amount) => {
    if (!segment || !Number.isInteger(nodeIndex) || !Number.isFinite(amount) || amount <= 0) return;
    const key = `${segment.index}:${nodeIndex}`;
    trims.set(key, Math.max(trims.get(key) ?? 0, amount));
  };

  for (const reducer of reducers) {
    const modelLength = reducerRenderLengthMetres(reducer);
    if (reducer.kind === "bend") {
      addTrim(reducerPlacementSegment(reducer), reducer.nodeIndex, modelLength);
    } else if (reducerStartsAtJoint(reducer)) {
      addTrim(reducer.smallSegment, reducer.nodeIndex, teeReducerStartOffsetMetres(reducer, style) + modelLength);
    } else {
      addTrim(reducer.largeSegment, reducer.nodeIndex, modelLength * 0.5);
      addTrim(reducer.smallSegment, reducer.nodeIndex, modelLength * 0.5);
    }
  }

  return trims;
}

function centreOfGravityReferenceData(quantities = quantitySummary(), liftPoint = centreOfGravityData(quantities)) {
  if (!liftPoint) return null;

  const references = [];
  const segmentByIndex = new Map(quantities.segments.map(({ segment }) => [segment.index, segment]));
  for (const [index, elbow] of quantities.elbows.entries()) {
    const point = state.points[elbow.nodeIndex];
    if (point) {
      references.push({
        label: `Bend ${index + 1}`,
        type: "bend",
        point,
        nodeIndex: elbow.nodeIndex,
        firstSegment: segmentByIndex.get(elbow.firstSegmentIndex),
        secondSegment: segmentByIndex.get(elbow.secondSegmentIndex),
      });
    }
  }

  const connections = nodeConnections(quantities.segments.map(({ segment }) => segment));
  let teeIndex = 0;
  let branchIndex = 0;
  for (const [nodeIndex, connected] of connections.entries()) {
    if (connected.length < 3) continue;
    const point = state.points[nodeIndex];
    if (!point) continue;
    const connectionType = nodeConnectionType(nodeIndex);
    if (connectionType === "branch") branchIndex += 1;
    else teeIndex += 1;
    references.push({
      label: connectionType === "branch" ? `Branch ${branchIndex}` : `Tee ${teeIndex}`,
      type: connectionType,
      point,
    });
  }

  if (!references.length) return null;

  const reference = references
    .map((reference) => ({
      ...reference,
      distanceMm: pointLength(subtractPoints(liftPoint.point, reference.point)),
    }))
    .sort((a, b) => a.distanceMm - b.distanceMm)[0];

  if (reference.type === "bend") {
    reference.offsetsMm = bendReferenceOffsets(reference, liftPoint.point);
  }
  return reference;
}

function bendReferenceOffsets(reference, liftPoint) {
  if (!reference.firstSegment || !reference.secondSegment || !state.points[reference.nodeIndex]) return null;

  const bendPoint = state.points[reference.nodeIndex];
  const firstOther = reference.firstSegment.from === reference.nodeIndex ? reference.firstSegment.to : reference.firstSegment.from;
  const secondOther = reference.secondSegment.from === reference.nodeIndex ? reference.secondSegment.to : reference.secondSegment.from;
  const firstDirection = normalizePoint(subtractPoints(state.points[firstOther], bendPoint));
  const secondDirection = normalizePoint(subtractPoints(state.points[secondOther], bendPoint));
  const relative = subtractPoints(liftPoint, bendPoint);
  const cross = pointLength(crossPoints(firstDirection, secondDirection));
  if (cross < 0.001) return null;

  const dot = dotPoints(firstDirection, secondDirection);
  const firstProjection = dotPoints(relative, firstDirection);
  const secondProjection = dotPoints(relative, secondDirection);
  const denominator = 1 - dot * dot;
  if (Math.abs(denominator) < 0.001) return null;

  return [
    Math.abs((firstProjection - dot * secondProjection) / denominator),
    Math.abs((secondProjection - dot * firstProjection) / denominator),
  ];
}

function centreOfGravityReferenceText(quantities = quantitySummary(), liftPoint = centreOfGravityData(quantities)) {
  const reference = centreOfGravityReferenceData(quantities, liftPoint);
  if (!reference) {
    return liftPoint ? formatPointCompact(liftPoint.point) : "No lift point";
  }
  if (reference.type === "bend" && reference.offsetsMm) {
    const [firstOffset, secondOffset] = reference.offsetsMm;
    if (Math.abs(firstOffset - secondOffset) < 5) {
      return `COG ${formatLength(firstOffset)} mm along each leg from ${reference.label}`;
    }
    return `COG ${formatLength(firstOffset)} / ${formatLength(secondOffset)} mm along legs from ${reference.label}`;
  }
  return `COG ${formatLength(reference.distanceMm)} mm from ${reference.label}`;
}

function centreOfGravityReferenceLines(quantities = quantitySummary(), liftPoint = centreOfGravityData(quantities)) {
  const reference = centreOfGravityReferenceData(quantities, liftPoint);
  if (!reference) return ["COG"];

  if (reference.type === "bend" && reference.offsetsMm) {
    const [firstOffset, secondOffset] = reference.offsetsMm;
    if (Math.abs(firstOffset - secondOffset) < 5) {
      return [`COG ${formatLength(firstOffset)} mm`, `each leg from ${reference.label}`];
    }
    return [`COG ${formatLength(firstOffset)} / ${formatLength(secondOffset)} mm`, `from ${reference.label} legs`];
  }

  return [`COG ${formatLength(reference.distanceMm)} mm`, `from ${reference.label}`];
}

function suggestedLugPlan(quantities = quantitySummary(), liftPoint = centreOfGravityData(quantities)) {
  if (!liftPoint || !quantities.segments.length) return null;

  const slingAngleDegrees = normalizeLiftingSlingAngle(state.liftingSlingAngleDegrees);
  const slingLoadFactor = slingAngleLoadFactor(slingAngleDegrees);
  const segmentEntries = quantities.segments
    .filter(({ segment, quantity }) => quantity.pipeWeightKg > 0 && pointLength(segment.vector) > 200);
  if (!segmentEntries.length) return null;

  const span = spoolSpanMm(segmentEntries.map(({ segment }) => segment));
  const candidates = [];
  for (const { segment } of segmentEntries) {
    const length = pointLength(segment.vector);
    const clearance = clampNumber(300 / length, 0.08, 0.28);
    const steps = 20;
    for (let index = 0; index <= steps; index += 1) {
      const t = clearance + ((1 - clearance * 2) * index) / steps;
      const point = lerpPoint(segment.start, segment.end, t);
      candidates.push({ segment, t, point });
    }
  }

  if (candidates.length < 2) return null;

  const spreadRatio = slingAngleSpreadRatio(slingAngleDegrees);
  const targetMin = Math.min(900, Math.max(350, span * 0.18));
  const targetMax = Math.min(7000, Math.max(targetMin, span * 0.86));
  const targetSeparation = clampNumber(span * spreadRatio, targetMin, targetMax);
  const minSeparation = Math.min(Math.max(350, targetSeparation * 0.48), Math.max(350, span * 0.72));
  const separationWeight = slingAngleSeparationWeight(slingAngleDegrees);
  let best = null;

  for (let firstIndex = 0; firstIndex < candidates.length; firstIndex += 1) {
    for (let secondIndex = firstIndex + 1; secondIndex < candidates.length; secondIndex += 1) {
      const first = candidates[firstIndex];
      const second = candidates[secondIndex];
      const separationMm = pointLength(subtractPoints(first.point, second.point));
      if (separationMm < minSeparation) continue;

      const midpoint = midpointPoint(first.point, second.point);
      const midpointErrorMm = pointLength(subtractPoints(midpoint, liftPoint.point));
      const loadSplit = liftingPointLoadSplit(first.point, second.point, liftPoint.point, liftPoint.totalWeightKg);
      const firstFromCog = subtractPoints(first.point, liftPoint.point);
      const secondFromCog = subtractPoints(second.point, liftPoint.point);
      const sameSidePenalty = dotPoints(firstFromCog, secondFromCog) > 0 ? span * 0.4 : 0;
      const separationPenalty = Math.abs(separationMm - targetSeparation) * separationWeight;
      const halfTargetSeparation = targetSeparation * 0.5;
      const angleDistancePenalty = (
        Math.abs(pointLength(firstFromCog) - halfTargetSeparation) +
        Math.abs(pointLength(secondFromCog) - halfTargetSeparation)
      ) * 0.55;
      const outsidePenalty = loadSplit.withinSpan ? 0 : span * 2;
      const imbalancePenalty = liftPoint.totalWeightKg > 0
        ? (Math.abs(loadSplit.firstLoadKg - loadSplit.secondLoadKg) / liftPoint.totalWeightKg) * span * 0.18
        : 0;
      const score = midpointErrorMm * 1.15 + loadSplit.offLineErrorMm * 2.2 + sameSidePenalty + separationPenalty + angleDistancePenalty + imbalancePenalty + outsidePenalty;

      if (!best || score < best.score) {
        best = {
          score,
          midpoint,
          midpointErrorMm,
          separationMm,
          loadSplit,
          points: [first, second],
        };
      }
    }
  }

  if (!best) return null;

  best.points = best.points
    .map((point, index) => ({
      ...point,
      number: index + 1,
      distanceFromRunStartMm: pointLength(subtractPoints(point.point, point.segment.start)),
    }))
    .sort((a, b) => a.segment.index - b.segment.index || a.t - b.t)
    .map((point, index) => ({ ...point, number: index + 1 }));

  const loadSplit = liftingPointLoadSplit(best.points[0].point, best.points[1].point, liftPoint.point, liftPoint.totalWeightKg);
  best.loadSplit = loadSplit;
  best.midpoint = midpointPoint(best.points[0].point, best.points[1].point);
  best.midpointErrorMm = pointLength(subtractPoints(best.midpoint, liftPoint.point));
  best.separationMm = pointLength(subtractPoints(best.points[0].point, best.points[1].point));
  best.points[0].loadKg = loadSplit.firstLoadKg;
  best.points[1].loadKg = loadSplit.secondLoadKg;
  best.points[0].slingTensionKg = loadSplit.firstLoadKg * slingLoadFactor;
  best.points[1].slingTensionKg = loadSplit.secondLoadKg * slingLoadFactor;
  best.points[0].slingAngleDegrees = slingAngleDegrees;
  best.points[1].slingAngleDegrees = slingAngleDegrees;
  best.slingAngleDegrees = slingAngleDegrees;
  best.slingLoadFactor = slingLoadFactor;
  best.targetSeparationMm = targetSeparation;
  best.minSeparationMm = minSeparation;

  return best;
}

function slingAngleSpreadRatio(angleDegrees = state.liftingSlingAngleDegrees) {
  const angle = normalizeLiftingSlingAngle(angleDegrees);
  const flatness = clampNumber((90 - angle) / 60, 0, 1);
  return clampNumber(0.2 + flatness * 0.56, 0.2, 0.76);
}

function slingAngleSeparationWeight(angleDegrees = state.liftingSlingAngleDegrees) {
  const angle = normalizeLiftingSlingAngle(angleDegrees);
  const flatness = clampNumber((90 - angle) / 60, 0, 1);
  return clampNumber(1.15 + flatness * 1.35, 1.15, 2.5);
}

function slingAngleLoadFactor(angleDegrees = state.liftingSlingAngleDegrees) {
  const angle = normalizeLiftingSlingAngle(angleDegrees);
  const sine = Math.sin((angle * Math.PI) / 180);
  return 1 / Math.max(0.001, sine);
}

function liftingPointLoadSplit(firstPoint, secondPoint, cogPoint, totalWeightKg) {
  const span = subtractPoints(secondPoint, firstPoint);
  const spanLengthSq = Math.max(dotPoints(span, span), 1);
  const rawT = dotPoints(subtractPoints(cogPoint, firstPoint), span) / spanLengthSq;
  const t = clampNumber(rawT, 0, 1);
  const projected = addPoints(firstPoint, span, t);
  const offLineErrorMm = pointLength(subtractPoints(cogPoint, projected));
  const safeWeight = Math.max(0, Number(totalWeightKg) || 0);

  return {
    t: rawT,
    withinSpan: rawT >= 0 && rawT <= 1,
    projected,
    offLineErrorMm,
    firstLoadKg: safeWeight * (1 - t),
    secondLoadKg: safeWeight * t,
  };
}

function midpointPoint(first, second) {
  return {
    x: (first.x + second.x) * 0.5,
    y: (first.y + second.y) * 0.5,
    z: (first.z + second.z) * 0.5,
  };
}

function spoolSpanMm(segmentData) {
  const points = segmentData.flatMap((segment) => [segment.start, segment.end]);
  let span = 0;
  for (let i = 0; i < points.length; i += 1) {
    for (let j = i + 1; j < points.length; j += 1) {
      span = Math.max(span, pointLength(subtractPoints(points[i], points[j])));
    }
  }
  return Math.max(span, 1000);
}

function lugPointText(lug) {
  const angle = normalizeLiftingSlingAngle(lug.slingAngleDegrees ?? state.liftingSlingAngleDegrees);
  const slingTension = lug.slingTensionKg ?? ((lug.loadKg ?? 0) * slingAngleLoadFactor(angle));
  return `Lug ${lug.number}: run ${lug.segment.index + 1}, ${formatLength(lug.distanceFromRunStartMm)} mm from run start, est. vertical share ${formatMass(lug.loadKg ?? 0)} kg / sling tension ${formatMass(slingTension)} kg @ ${angle} deg`;
}

function liftingPointPlanSummary(lugPlan) {
  if (!lugPlan) return "No calculated lifting points yet.";
  const offLine = lugPlan.loadSplit?.offLineErrorMm ?? 0;
  const angle = normalizeLiftingSlingAngle(lugPlan.slingAngleDegrees ?? state.liftingSlingAngleDegrees);
  const factor = lugPlan.slingLoadFactor ?? slingAngleLoadFactor(angle);
  const target = Number.isFinite(lugPlan.targetSeparationMm) ? `target ${formatLength(lugPlan.targetSeparationMm)} mm; ` : "";
  return `Spacing ${formatLength(lugPlan.separationMm)} mm; ${target}COG ${formatLength(offLine)} mm off lug line; midpoint ${formatLength(lugPlan.midpointErrorMm)} mm from COG; sling angle ${angle} deg from horizontal, load factor x${factor.toFixed(2)}.`;
}

function splitSegmentAt(segmentIndex, t) {
  if (!ensureDrawingEditable("split a pipe run")) return null;
  const edge = state.edges[segmentIndex];
  if (!edge || t <= 0.02 || t >= 0.98) return null;
  const originalLengthMm = pointLength(subtractPoints(state.points[edge.to], state.points[edge.from]));

  const splitPoint = lerpPoint(state.points[edge.from], state.points[edge.to], t);
  const splitIndex = state.points.length;
  state.points.push(splitPoint);
  state.edges.splice(
    segmentIndex,
    1,
    { from: edge.from, to: splitIndex, pipeSizeNb: normalizePipeSize(edge.pipeSizeNb ?? state.pipeSizeNb) },
    { from: splitIndex, to: edge.to, pipeSizeNb: normalizePipeSize(edge.pipeSizeNb ?? state.pipeSizeNb) },
  );
  reindexDimensionOffsetsAfterSegmentSplit(segmentIndex);
  reindexBigSpoolCutsAfterSegmentSplit(segmentIndex, originalLengthMm * t);

  const normalizedSplitFittingT = (fitting, localT) => {
    if (isEndpointFittingType(fitting.type)) {
      return localT <= 0.5 ? 0 : 1;
    }
    return Math.max(0.04, Math.min(0.96, localT));
  };

  state.fittings = state.fittings.map((fitting) => {
    if (fitting.segmentIndex < segmentIndex) return fitting;
    if (fitting.segmentIndex > segmentIndex) {
      return { ...fitting, segmentIndex: fitting.segmentIndex + 1 };
    }
    const fittingT = normalizeFittingPosition(fitting.type, fitting.t);
    if (fittingT <= t) {
      return { ...fitting, t: normalizedSplitFittingT(fitting, fittingT / t) };
    }
    return {
      ...fitting,
      segmentIndex: segmentIndex + 1,
      t: normalizedSplitFittingT(fitting, (fittingT - t) / (1 - t)),
    };
  });

  state.selectedPoint = splitIndex;
  state.activePoint = splitIndex;
  clearSelectedSegments();
  state.selectedFitting = null;
  state.selectedMeasurement = null;
  return splitIndex;
}

function placeFitting(type, segmentIndex, t, options = {}) {
  if (!ensureDrawingEditable("add fittings")) return;
  const normalizedT = normalizeFittingPosition(type, t);
  const fitting = {
    id: nextFittingId,
    type,
    segmentIndex,
    t: isEndpointFittingType(type) ? (normalizedT <= 0.5 ? 0 : 1) : normalizedT,
  };
  if (type === "flange") {
    fitting.flangeMode = normalizeFlangeMode(options.flangeMode ?? state.flangeMode);
    fitting.flangeStandard = normalizeFlangeStandard(options.flangeStandard ?? state.flangeStandard);
  } else if (type === "socket") {
    fitting.socketSizeNb = normalizePipeSize(options.socketSizeNb ?? SOCKET_SIZE_NB);
    fitting.socketAngle = normalizeSocketAngle(options.socketAngle);
  } else if (type === "reducer") {
    fitting.reducerType = normalizeReducerType(options.reducerType ?? state.reducerType);
  }

  state.fittings.push(fitting);
  state.selectedFitting = nextFittingId;
  selectSingleSegment(segmentIndex);
  state.selectedNote = null;
  state.selectedMeasurement = null;
  nextFittingId += 1;
  recordHistory({ type: "fitting" });
  updateAll();
  revealInspectorForSelection();
}

function placeSocketFittings(segmentIndex, positions, options = {}) {
  if (!ensureDrawingEditable("add sockets")) return;
  const fittingIds = [];
  const socketSizeNb = normalizePipeSize(options.socketSizeNb ?? SOCKET_SIZE_NB);
  const socketAngle = normalizeSocketAngle(options.socketAngle);
  for (const t of positions) {
    const fitting = {
      id: nextFittingId,
      type: "socket",
      segmentIndex,
      t: normalizeFittingPosition("socket", t),
      socketSizeNb,
      socketAngle,
    };
    state.fittings.push(fitting);
    fittingIds.push(fitting.id);
    nextFittingId += 1;
  }

  if (!fittingIds.length) return;
  state.selectedFitting = fittingIds[fittingIds.length - 1];
  selectSingleSegment(segmentIndex);
  state.selectedNote = null;
  state.selectedMeasurement = null;
  recordHistory({ type: "fittings", fittingIds });
  updateAll();
  revealInspectorForSelection();
}

function placeNote(point, textOverride = null) {
  if (!ensureDrawingEditable("add notes")) return;
  const noteOptions = textOverride && typeof textOverride === "object" ? textOverride : { text: textOverride };
  const text = String(noteOptions.text ?? noteTextInput.value).trim() || "NOTE";
  const colour = normalizeNoteColour(noteOptions.colour ?? noteOptions.color ?? noteColorInput?.value);
  noteTextInput.value = text.slice(0, 80);
  if (noteColorInput) noteColorInput.value = colour;
  const note = {
    id: nextNoteId,
    text: text.slice(0, 80),
    point,
    labelPoint: defaultNoteLabelPoint(point),
    colour,
  };
  state.notes.push(note);
  state.selectedNote = nextNoteId;
  state.selectedFitting = null;
  state.selectedMeasurement = null;
  clearSelectedSegments();
  nextNoteId += 1;
  recordHistory({ type: "note", noteId: note.id });
  updateAll();
  revealInspectorForSelection();
}

function measurementLengthMm(measurement) {
  return pointLength(subtractPoints(measurement.end, measurement.start));
}

function measurementLabel(measurement) {
  const label = String(measurement?.label ?? "").trim();
  return label || `${formatLength(measurementLengthMm(measurement))} mm`;
}

function measurePointFromPointer(pointer) {
  const pointHit = findNearestPoint(pointer);
  if (pointHit) return { point: clonePoint(pointHit.point), label: `Point ${pointHit.index + 1}` };

  const segmentHit = findNearestSegment(pointer);
  if (segmentHit) {
    return {
      point: lerpPoint(segmentHit.segment.start, segmentHit.segment.end, segmentHit.t),
      label: `Run ${segmentHit.segment.index + 1}`,
    };
  }

  return { point: unprojectIsoGround(pointer), label: "Iso paper" };
}

function beginOrFinishMeasurement(pointer) {
  if (!ensureDrawingEditable("add measurements")) return;
  const picked = measurePointFromPointer(pointer);
  if (!measurementDraft) {
    measurementDraft = { start: picked.point, startLabel: picked.label };
    state.selectedMeasurement = null;
    state.selectedFitting = null;
    state.selectedNote = null;
    state.selectedPoint = null;
    clearSelectedSegments();
    cursorReadout.textContent = `Measure from ${picked.label}`;
    drawIso();
    return;
  }

  const start = measurementDraft.start;
  const end = picked.point;
  measurementDraft = null;
  if (pointLength(subtractPoints(end, start)) < 1) {
    cursorReadout.textContent = "Pick a second point further away";
    drawIso();
    return;
  }

  const snapshot = createUndoSnapshot();
  const measurement = {
    id: nextMeasurementId,
    start,
    end,
    label: "",
  };
  state.measurements.push(measurement);
  state.selectedMeasurement = measurement.id;
  state.selectedFitting = null;
  state.selectedNote = null;
  state.selectedPoint = null;
  clearSelectedSegments();
  nextMeasurementId += 1;
  recordHistory({ type: "snapshot", snapshot });
  cursorReadout.textContent = `Measured ${measurementLabel(measurement)}`;
  updateAll();
  revealInspectorForSelection();
}

function createUndoSnapshot() {
  return {
    payload: cloneStatePayload(),
    nextFittingId,
    nextNoteId,
    nextMeasurementId,
  };
}

function cloneStatePayload() {
  return JSON.parse(JSON.stringify(statePayload()));
}

function cloneHistoryEntries(entries) {
  try {
    return JSON.parse(JSON.stringify(Array.isArray(entries) ? entries : []));
  } catch {
    return [];
  }
}

function createHistorySnapshot() {
  return {
    payload: cloneStatePayload(),
    history: cloneHistoryEntries(state.history),
    nextFittingId,
    nextNoteId,
    nextMeasurementId,
  };
}

function redoStack() {
  return Array.isArray(state.redoHistory) ? state.redoHistory : [];
}

function clearRedoHistory() {
  state.redoHistory = [];
}

function recordHistory(entry) {
  state.history = [...(Array.isArray(state.history) ? state.history : []), entry].slice(-HISTORY_LIMIT);
  clearRedoHistory();
}

function restoreHistorySnapshot(snapshot) {
  const restored = stateFromPayload(snapshot?.payload);
  if (!restored) return false;
  state = restored;
  state.history = cloneHistoryEntries(snapshot.history).slice(-HISTORY_LIMIT);
  state.redoHistory = [];
  nextFittingId = Number(snapshot?.nextFittingId) || nextFittingId;
  nextNoteId = Number(snapshot?.nextNoteId) || nextNoteId;
  nextMeasurementId = Number(snapshot?.nextMeasurementId) || nextMeasurementId;
  return true;
}

function undo() {
  if (cloudPermissionReadOnly) {
    ensureDrawingEditable("undo changes");
    return;
  }
  const redoSnapshot = createHistorySnapshot();
  const last = state.history.pop();
  if (!last) return;
  const nextRedoHistory = [...redoStack(), redoSnapshot].slice(-HISTORY_LIMIT);
  let changed = false;

  if (last.type === "snapshot") {
    const remainingHistory = state.history;
    const restored = stateFromPayload(last.snapshot?.payload);
    if (restored) {
      state = restored;
      state.history = remainingHistory;
      state.redoHistory = nextRedoHistory;
      nextFittingId = Number(last.snapshot?.nextFittingId) || nextFittingId;
      nextNoteId = Number(last.snapshot?.nextNoteId) || nextNoteId;
      nextMeasurementId = Number(last.snapshot?.nextMeasurementId) || nextMeasurementId;
      changed = true;
    }
  } else if (last.type === "edge" && state.points.length > 1) {
    state.edges.splice(last.edgeIndex, 1);
    state.points.splice(last.pointIndex, 1);
    reindexNodeTypesAfterPointRemoval(last.pointIndex);
    reindexReducerSideOverridesAfterPointRemoval(last.pointIndex);
    reindexReducerTypeOverridesAfterPointRemoval(last.pointIndex);
    reindexDimensionOffsetsAfterSegmentRemoval(last.edgeIndex);
    reindexBigSpoolCutsAfterSegmentRemoval(last.edgeIndex);
    state.edges = state.edges.map((edge) => ({
      ...edge,
      from: edge.from > last.pointIndex ? edge.from - 1 : edge.from,
      to: edge.to > last.pointIndex ? edge.to - 1 : edge.to,
    }));
    state.fittings = state.fittings.filter((fitting) => fitting.segmentIndex !== last.edgeIndex);
    state.fittings = state.fittings.map((fitting) => ({
      ...fitting,
      segmentIndex: fitting.segmentIndex > last.edgeIndex ? fitting.segmentIndex - 1 : fitting.segmentIndex,
    }));
    clearSelectedSegments();
    state.selectedPoint = Math.max(0, last.pointIndex - 1);
    state.activePoint = state.selectedPoint;
    changed = true;
  } else if (last.type === "fitting") {
    state.fittings.pop();
    state.selectedFitting = null;
    changed = true;
  } else if (last.type === "fittings") {
    const fittingIds = new Set(last.fittingIds ?? []);
    state.fittings = state.fittings.filter((fitting) => !fittingIds.has(fitting.id));
    state.selectedFitting = null;
    changed = true;
  } else if (last.type === "note") {
    state.notes = state.notes.filter((note) => note.id !== last.noteId);
    state.selectedNote = null;
    changed = true;
  } else if (last.type === "measurement") {
    state.measurements = (state.measurements ?? []).filter((measurement) => measurement.id !== last.measurementId);
    state.selectedMeasurement = null;
    changed = true;
  }

  if (!changed) {
    state.history.push(last);
    return;
  }

  state.redoHistory = nextRedoHistory;
  updateAll();
}

function redo() {
  if (cloudPermissionReadOnly) {
    ensureDrawingEditable("redo changes");
    return;
  }
  const stack = redoStack();
  const snapshot = stack.pop();
  if (!snapshot) return;
  const remainingRedoHistory = stack.slice(-HISTORY_LIMIT);
  if (!restoreHistorySnapshot(snapshot)) return;
  state.redoHistory = remainingRedoHistory;
  updateAll();
}

function updateHistoryButtons() {
  if (undoButton) undoButton.disabled = cloudPermissionReadOnly || !(Array.isArray(state.history) && state.history.length);
  if (redoButton) redoButton.disabled = cloudPermissionReadOnly || !redoStack().length;
}

function updateRoleRestrictedDrawingTools() {
  const canEdit = currentDrawingProjectPermission().canEdit;
  for (const button of sideToolButtons) {
    const tool = sideToolIdForButton(button);
    if (!tool) continue;
    if (!button.dataset.editableTitle) button.dataset.editableTitle = button.title || sideToolLabel(tool);
    const roleRestricted = !canEdit && tool !== "select";
    button.disabled = roleRestricted;
    button.title = roleRestricted ? currentPermissionRestrictionText("edit") : button.dataset.editableTitle;
    button.setAttribute("aria-disabled", String(roleRestricted));
  }
  if (!canEdit && state.activeTool !== "select") state.activeTool = "select";
}

function deleteSelection() {
  if (!ensureDrawingEditable("delete items")) return;
  if (state.selectedNote) {
    const snapshot = createUndoSnapshot();
    state.notes = state.notes.filter((note) => note.id !== state.selectedNote);
    state.selectedNote = null;
    recordHistory({ type: "snapshot", snapshot });
    updateAll();
    return;
  }

  if (state.selectedMeasurement) {
    const snapshot = createUndoSnapshot();
    state.measurements = (state.measurements ?? []).filter((measurement) => measurement.id !== state.selectedMeasurement);
    state.selectedMeasurement = null;
    recordHistory({ type: "snapshot", snapshot });
    updateAll();
    return;
  }

  if (state.selectedFitting) {
    const snapshot = createUndoSnapshot();
    state.fittings = state.fittings.filter((fitting) => fitting.id !== state.selectedFitting);
    state.selectedFitting = null;
    recordHistory({ type: "snapshot", snapshot });
    updateAll();
    return;
  }

  const selectedSegments = selectedSegmentIndexes().sort((a, b) => b - a);
  if (selectedSegments.length) {
    deleteSegmentsByIndex(selectedSegments);
  }
}

function deleteSegmentsByIndex(indexes) {
  if (!ensureDrawingEditable("delete pipe runs")) return false;
  const selectedSegments = normalizeSelectedSegments(indexes, state.edges.length).sort((a, b) => b - a);
  if (!selectedSegments.length) return false;

  const snapshot = createUndoSnapshot();
  for (const removedEdgeIndex of selectedSegments) {
    state.edges.splice(removedEdgeIndex, 1);
    reindexDimensionOffsetsAfterSegmentRemoval(removedEdgeIndex);
    reindexBigSpoolCutsAfterSegmentRemoval(removedEdgeIndex);
    state.fittings = state.fittings.filter((fitting) => fitting.segmentIndex !== removedEdgeIndex);
    state.fittings = state.fittings.map((fitting) => ({
      ...fitting,
      segmentIndex: fitting.segmentIndex > removedEdgeIndex ? fitting.segmentIndex - 1 : fitting.segmentIndex,
    }));
  }
  clearSelectedSegments();
  state.selectedFitting = null;
  state.selectedMeasurement = null;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
  return true;
}

function setTool(tool) {
  if (tool && !isSideToolAvailable(tool)) {
    tool = defaultToolForMode(appMode);
  }
  if (tool && !isSideToolAvailable(tool)) {
    tool = "draw";
  }
  if (tool !== "boxSelect") {
    cancelBoxSelect({ redraw: false });
  }
  if (tool !== "measure") {
    measurementDraft = null;
  }
  cancelDimensionDrag({ redraw: false });
  state.activeTool = tool;
  if (tool !== "draw") {
    shiftAngleSnap = false;
    touchShiftAnglePointerId = null;
  }
  updateTouchShiftAngleButton();
  state.previewCandidate = null;
  document.querySelectorAll("[data-tool]").forEach((button) => {
    button.classList.toggle("active", button.dataset.tool === tool);
  });
  updateFittingsToolButton(tool);
  if (tool === "select") {
    cursorReadout.textContent = "Select - hold Shift to pick multiple runs";
    markFirstUseGuideLearned("select");
  } else if (tool === "measure") {
    cursorReadout.textContent = "Measure - pick first point";
  }
  drawIso();
  checkTutorialPractice();
}

function updateFittingsToolButton(tool = state.activeTool) {
  if (!fittingsToolButton) return;
  const active = FITTINGS_FLYOUT_TOOLS.has(tool);
  fittingsToolButton.classList.toggle("active", active);
  fittingsToolButton.dataset.activeFitting = active ? tool : "";
  if (fittingsToolLabel) fittingsToolLabel.textContent = active ? sideToolLabel(tool) : "Fittings";
  const iconUse = fittingsToolButton.querySelector("use");
  iconUse?.setAttribute("href", active ? FITTINGS_FLYOUT_ICONS[tool] ?? "#icon-flange" : "#icon-flange");
  fittingsToolButton.title = active ? `${sideToolLabel(tool)} selected. Open fitting tools.` : "Open fitting tools";
}

function fittingsToolMenuOpen() {
  return Boolean(fittingsToolMenu && !fittingsToolMenu.hidden);
}

function setFittingsToolMenuOpen(open) {
  if (!fittingsToolButton || !fittingsToolMenu) return;
  const next = Boolean(open && !fittingsToolButton.hidden);
  fittingsToolMenu.hidden = !next;
  fittingsToolButton.setAttribute("aria-expanded", String(next));
  document.body.classList.toggle("fittings-tool-menu-open", next);
  if (next) {
    positionFittingsToolMenu();
    markFirstUseGuideLearned("fittings");
  }
}

function positionFittingsToolMenu() {
  if (!fittingsToolButton || !fittingsToolMenu || fittingsToolMenu.hidden) return;
  fittingsToolMenu.style.left = "";
  fittingsToolMenu.style.right = "";
  fittingsToolMenu.style.top = "";
  fittingsToolMenu.style.bottom = "";
  if (isTabletLayout()) {
    fittingsToolMenu.style.left = "10px";
    fittingsToolMenu.style.right = "10px";
    fittingsToolMenu.style.bottom = isPhoneLayout()
      ? "calc(164px + env(safe-area-inset-bottom))"
      : "calc(142px + env(safe-area-inset-bottom))";
    return;
  }
  const triggerRect = fittingsToolButton.getBoundingClientRect();
  const menuWidth = 300;
  const menuHeight = Math.min(fittingsToolMenu.scrollHeight || 520, window.innerHeight - 20);
  fittingsToolMenu.style.left = `${Math.min(window.innerWidth - menuWidth - 10, triggerRect.right + 8)}px`;
  fittingsToolMenu.style.top = `${Math.max(10, Math.min(triggerRect.top, window.innerHeight - menuHeight - 10))}px`;
}

function setupFittingsToolMenu() {
  if (fittingsToolMenu && fittingsToolMenu.parentElement !== document.body) {
    document.body.append(fittingsToolMenu);
  }
  fittingsToolButton?.addEventListener("click", (event) => {
    event.stopPropagation();
    setFittingsToolMenuOpen(!fittingsToolMenuOpen());
  });
  fittingsToolCloseButton?.addEventListener("click", () => setFittingsToolMenuOpen(false));
  fittingsToolMenu?.addEventListener("click", (event) => {
    if (event.target.closest("[data-tool], [data-side-tool]")) {
      setFittingsToolMenuOpen(false);
    }
  });
  document.addEventListener("pointerdown", (event) => {
    if (!fittingsToolMenuOpen()) return;
    if (fittingsToolMenu?.contains(event.target) || fittingsToolButton?.contains(event.target)) return;
    setFittingsToolMenuOpen(false);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && fittingsToolMenuOpen()) {
      setFittingsToolMenuOpen(false);
    }
  });
  window.addEventListener("resize", () => {
    if (fittingsToolMenuOpen()) positionFittingsToolMenu();
  });
  updateFittingsToolButton();
}

function updateSegmentList() {
  const segmentData = segments();
  const quantities = quantitySummary(segmentData);
  const cutRows = quantities.cutSegments ?? quantities.segments;
  segmentList.innerHTML = "";

  if (cutRows.length === 0) {
    const empty = document.createElement("div");
    empty.className = "segment-row";
    empty.innerHTML = '<span class="segment-index">0</span><span class="segment-main"><strong>Start point</strong><small>Origin ready</small></span><span class="segment-fit">0</span>';
    segmentList.append(empty);
    return;
  }

  for (const { segment, quantity } of cutRows) {
    const segmentIndexes = Array.isArray(segment.mergedIndexes) ? segment.mergedIndexes : [segment.index];
    const row = document.createElement("button");
    row.type = "button";
    row.className = "segment-row";
    row.classList.toggle("active", segmentIndexes.some((index) => isSegmentSelected(index)));
    row.dataset.segmentIndex = String(segment.index);

    const fittingCount = state.fittings.filter((fitting) => segmentIndexes.includes(fitting.segmentIndex)).length;
    const indexLabel = cutRunDimensionLabel(segment);
    const pointDetail = cutRunPointDetail(segment);
    row.innerHTML = `
      <span class="segment-index">${escapeHtml(indexLabel)}</span>
      <span class="segment-main">
        <strong>${escapeHtml(cutRunDisplayTitle(segment))}</strong>
        <small>Cut ${formatLength(quantity.cutLengthMm)} mm / CL ${formatLength(quantity.centrelineMm)} mm / ${formatMass(quantity.pipeWeightKg)} kg</small>
        <small>${pointDetail ? `${escapeHtml(pointDetail)} / ` : ""}${escapeHtml(pipeSizeSpecLabel(pipeSizeForSegment(segment)))} / fitting deductions ${formatLength(quantity.bendTakeoffMm)} mm / Weld gap ${formatWeldGapMm(quantity.weldGapMm)} mm (${quantity.weldEndCount} welded end${quantity.weldEndCount === 1 ? "" : "s"})</small>
      </span>
      <span class="segment-fit">${fittingCount}</span>
    `;
    row.addEventListener("click", (event) => {
      if (segmentIndexes.length > 1) {
        setSelectedSegments(event.shiftKey || event.ctrlKey || event.metaKey
          ? [...new Set([...selectedSegmentIndexes(), ...segmentIndexes])]
          : segmentIndexes);
      } else {
        chooseSegmentFromPointer(event, segment.index);
      }
      state.selectedFitting = null;
      state.selectedNote = null;
      state.selectedPoint = segment.to;
      state.activePoint = segment.to;
      state.activeTool = "select";
      setTool("select");
      updateAll({ save: false });
    });
    segmentList.append(row);
  }
}

function updateStats() {
  const quantities = quantitySummary();
  spoolStats.textContent = `${quantities.segments.length} runs / ${formatMass(quantities.totalWeightKg)} kg`;
}

function updateWeightsSummary() {
  if (!weightsSummary) return;
  const quantities = quantitySummary();
  const liftPoint = centreOfGravityData(quantities);
  const pressureLimit = weakestPressureEstimate(segments());

  if (!quantities.segments.length) {
    weightsSummary.innerHTML = '<div class="takeoff-empty">No pipe weight yet</div>';
    return;
  }

  weightsSummary.innerHTML = `
    <div class="weight-card-grid">
      <div class="weight-card"><span>Pipe</span><strong>${formatMass(quantities.pipeWeightKg)} kg</strong></div>
      <div class="weight-card"><span>Elbows</span><strong>${formatMass(quantities.bendWeightKg)} kg</strong></div>
      <div class="weight-card"><span>Tees</span><strong>${formatMass(quantities.teeWeightKg)} kg</strong></div>
      <div class="weight-card"><span>Branches</span><strong>${formatMass(quantities.branchWeightKg)} kg</strong></div>
      <div class="weight-card"><span>Reducers</span><strong>${formatMass(quantities.reducerWeightKg)} kg</strong></div>
      <div class="weight-card"><span>Fittings</span><strong>${formatMass(quantities.fittingWeightKg)} kg</strong></div>
      <div class="weight-card total"><span>Total estimated</span><strong>${formatMass(quantities.totalWeightKg)} kg</strong></div>
      <div class="weight-card"><span>COG</span><strong>${liftPoint ? formatPointCompact(liftPoint.point) : "N/A"}</strong></div>
      <div class="weight-card"><span>Weakest pressure</span><strong>${pressureLimit ? `${formatPressureStandard(pressureLimit.pressureBar)} / ${pipeSizeDisplayLabel(pressureLimit.size)}` : "N/A"}</strong></div>
    </div>
    <p class="weight-note">${pipeSpec().label}. Pipe kg/m and standard fitting table weights are used where available. Roll grooves add 0 kg. Branch welds, valves, sockets, adjusted flange standards and custom weld allowances remain estimates unless set manually. Weakest pressure is an estimated pipe-wall check only.</p>
  `;
}

function updateTakeoffSummary() {
  const quantities = quantitySummary();
  if (!takeoffSummary) return;

  if (!quantities.segments.length) {
    takeoffSummary.innerHTML = '<div class="takeoff-empty">No pipe runs yet</div>';
    return;
  }

  const bendNotes = quantities.elbows.length
    ? quantities.elbows.map((elbow, index) => {
        const sameTakeoff = Math.abs(elbow.firstTakeoffMm - elbow.secondTakeoffMm) < 0.5;
        const takeoffText = sameTakeoff
          ? `${formatLength(elbow.takeoffMm)} mm each side`
          : `run ${elbow.firstSegmentIndex + 1}: ${formatLength(elbow.firstTakeoffMm)} mm, run ${elbow.secondSegmentIndex + 1}: ${formatLength(elbow.secondTakeoffMm)} mm`;
        return `<li>Bend ${index + 1}: ${pipeSizeDisplayLabelByNb(elbow.nb)} / ${formatAngle(elbow.bend)} deg - take off ${takeoffText}</li>`;
      }).join("")
    : "<li>No bend take-off yet.</li>";
  const reducerNotes = quantities.reducers.length
    ? quantities.reducers.map((reducer, index) => {
        return `<li>Reducer ${index + 1}: <strong>${escapeHtml(reducerTypeLabel(reducer.reducerType))}</strong> ${pipeSizeDisplayLabelByNb(reducer.largeNb)} to ${pipeSizeDisplayLabelByNb(reducer.smallNb)} - ${escapeHtml(reducerDimensionDetail(reducer))}; take off ${formatLength(reducer.firstTakeoffMm + reducer.secondTakeoffMm)} mm total / ${formatMass(reducer.weightKg)} kg ${escapeHtml(reducer.source ?? "estimated")}</li>`;
      }).join("")
    : "<li>No automatic reducers yet.</li>";
  const teeNotes = quantities.tees.length
    ? quantities.tees.map((tee, index) => {
        const legs = tee.connections.map((connection) => `run ${connection.segmentIndex + 1}: ${formatLength(connection.takeoffMm)} mm`).join(", ");
        const outlet = tee.reducing
          ? ` / separate reducer to ${pipeSizeDisplayLabelByNb(tee.branchNb)} listed below`
          : "";
        return `<li>Tee ${index + 1}: equal ${pipeSizeDisplayLabelByNb(tee.nb)}${outlet} - take off ${legs} / ${formatMass(tee.weightKg)} kg ${tee.source}</li>`;
      }).join("")
    : "<li>No tee take-off yet.</li>";
  const branchNotes = quantities.branches.length
    ? quantities.branches.map((branch, index) => {
        const legs = branch.connections.map((connection) => `run ${connection.segmentIndex + 1}: ${formatLength(connection.takeoffMm)} mm`).join(", ");
        return `<li>Branch ${index + 1}: main ${pipeSizeDisplayLabelByNb(branch.nb)} to branch ${pipeSizeDisplayLabelByNb(branch.branchNb)} - take off ${legs} / ${formatMass(branch.weightKg)} kg ${branch.source}</li>`;
      }).join("")
    : "<li>No branch weld take-off yet.</li>";
  const fittingNotes = quantities.fittings.length
    ? quantities.fittings.map((item) => {
        const label = fittingActionLabel(item.fitting.type);
        return `<li>${label} on run ${item.segment.index + 1} at ${formatLength(pointLength(subtractPoints(item.point, item.segment.start)))} mm - ${formatMass(item.weightKg)} kg ${item.weightSource}</li>`;
      }).join("")
    : "<li>No fittings with weight yet.</li>";
  const liftPoint = centreOfGravityData(quantities);
  const pressureLimit = weakestPressureEstimate(segments());
  const liftPointText = centreOfGravityReferenceText(quantities, liftPoint);
  const lugPlan = suggestedLugPlan(quantities, liftPoint);
  const lugNotes = lugPlan
    ? lugPlan.points.map((lug) => `<li>${lugPointText(lug)}</li>`).join("")
    : "<li>No calculated lifting points yet.</li>";
  const liftRows = state.showLiftingPoints
    ? `<span>COG</span><strong>${liftPointText}</strong>
      <span>Lift point spread</span><strong>${lugPlan ? `${formatLength(lugPlan.separationMm)} mm` : "N/A"}</strong>`
    : "";
  const liftSection = state.showLiftingPoints
    ? `<div class="bend-notes">
      <strong>Calculated lifting points</strong>
      <ul>${lugNotes}</ul>
      ${lugPlan ? `<p>${liftingPointPlanSummary(lugPlan)} Verify lug design, welds and sling angles.</p>` : ""}
    </div>`
    : "";
  const liftDisclaimer = state.showLiftingPoints
    ? " Branch weld weights, automatic reducer weights, COG and lifting points are estimates. Verify all lifting points, sling angles and attachments before lifting."
    : " Branch weld weights, automatic reducer weights and COG are estimates.";
  const takeoffCounts = takeoffCountRows(quantities)
    .map((row) => `
      <span>${row.label}</span>
      <strong>${row.countText}${row.weightKg ? ` / ${formatMass(row.weightKg)} kg` : ""}</strong>
      <small>${row.detail}</small>
    `)
    .join("");

  takeoffSummary.innerHTML = `
    <div class="takeoff-grid">
      <span>Centreline</span><strong>${formatLength(quantities.centrelineMm)} mm</strong>
      <span>Fitting deductions</span><strong>${formatLength(quantities.bendTakeoffMm)} mm</strong>
      <span>Weld gap</span><strong>${formatWeldGapMm(quantities.weldGapMm)} mm (${formatWeldGapMm(quantities.weldGapPerEndMm)} mm x ${quantities.weldEndCount} welded ends)</strong>
      <span>Cut pipe</span><strong>${formatLength(quantities.cutLengthMm)} mm</strong>
      <span>Pipe weight</span><strong>${formatMass(quantities.pipeWeightKg)} kg</strong>
      <span>Elbows</span><strong>${quantities.elbows.length} / ${formatMass(quantities.bendWeightKg)} kg</strong>
      <span>Tees</span><strong>${quantities.tees.length} / ${formatMass(quantities.teeWeightKg)} kg</strong>
      <span>Branches</span><strong>${quantities.branches.length} / ${formatMass(quantities.branchWeightKg)} kg</strong>
      <span>Reducers</span><strong>${quantities.reducers.length} / ${formatMass(quantities.reducerWeightKg)} kg</strong>
      <span>Fittings</span><strong>${quantities.fittings.length} / ${formatMass(quantities.fittingWeightKg)} kg</strong>
      <span>Total est.</span><strong>${formatMass(quantities.totalWeightKg)} kg</strong>
      ${pressureLimit ? `<span>Weakest pressure</span><strong>${escapeHtml(formatPressureStandard(pressureLimit.pressureBar))} / ${escapeHtml(pipeSizeDisplayLabel(pressureLimit.size))}</strong>` : ""}
      ${liftRows}
    </div>
    <div class="bend-notes takeoff-counts">
      <strong>Take-off list by size</strong>
      <div class="takeoff-count-grid">${takeoffCounts}</div>
    </div>
    <div class="bend-notes">
      <strong>Bend notes</strong>
      <ul>${bendNotes}</ul>
    </div>
    <div class="bend-notes">
      <strong>Tee notes</strong>
      <ul>${teeNotes}</ul>
    </div>
    <div class="bend-notes">
      <strong>Branch notes</strong>
      <ul>${branchNotes}</ul>
    </div>
    <div class="bend-notes">
      <strong>Reducer notes</strong>
      <ul>${reducerNotes}</ul>
    </div>
    <div class="bend-notes">
      <strong>Fitting weights</strong>
      <ul>${fittingNotes}</ul>
    </div>
    ${liftSection}
    <p>${pipeSpec().label}, LR elbows.${liftDisclaimer} Pipe kg/m and standard fitting table weights are used where available. Roll grooves add 0 kg. Valves, sockets, adjusted flange standards and weld allowances remain estimated unless set manually. Weakest pressure is a pipe-wall estimate only and excludes fittings, flanges, gaskets, corrosion allowance, temperature and code checks.</p>
  `;
}

function healthIssue(severity, title, detail = "", target = null, options = {}) {
  const key = String(options.key ?? "").trim();
  const acknowledgement = key
    ? normalizeHealthAcknowledgements(state.healthAcknowledgements)[key] ?? null
    : null;
  return {
    severity,
    title,
    detail,
    target,
    key,
    guidance: String(options.guidance ?? "").trim(),
    canAcknowledge: options.canAcknowledge === true,
    acknowledgement,
    acknowledged: Boolean(acknowledgement),
  };
}

function endpointHasFinish(segment, pointIndex) {
  const endpointT = segment.from === pointIndex ? 0 : 1;
  return state.fittings.some((fitting) =>
    fitting.segmentIndex === segment.index &&
    (
      ((fitting.type === "flange" || fitting.type === "rollGroove" || fitting.type === "threadedEnd")
        && Math.abs(endpointSnappedFittingT(segment, fitting) - endpointT) < 0.001)
      || (fitting.type === "weld"
        && fitting.bigSpoolFieldJoint === true
        && fitting.fieldJointEnd === (endpointT === 0 ? "start" : "end"))
    ),
  );
}

function missingReducerIssues(segmentData, quantities) {
  const issues = [];
  const connections = nodeConnections(segmentData);
  const reducerNodes = new Set(quantities.reducers.map((reducer) => reducer.nodeIndex));
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));

  for (const [nodeIndex, connected] of connections.entries()) {
    const entries = connected
      .map((connection) => {
        const segment = segmentByIndex.get(connection.segmentIndex);
        return segment ? { segment, size: pipeSizeForSegment(segment) } : null;
      })
      .filter(Boolean);
    if (entries.length < 2) continue;

    const sizes = new Set(entries.map((entry) => entry.size.nb));
    if (sizes.size <= 1) continue;
    if (nodeConnectionType(nodeIndex) === "branch") continue;
    if (reducerNodes.has(nodeIndex)) continue;

    const label = entries.length >= 3 ? "tee" : "bend/run";
    const segmentIndexes = entries.map((entry) => entry.segment.index).sort((a, b) => a - b);
    const connectedSizes = [...sizes].sort((a, b) => a - b);
    issues.push(healthIssue(
      "error",
      `Missing reducer at ${label} ${pointLabel(nodeIndex)}`,
      `Connected sizes: ${connectedSizes.map((nb) => pipeSizeDisplayLabelByNb(nb)).join(", ")}.`,
      {
        type: "reducer-node",
        pointIndex: nodeIndex,
        segmentIndexes,
        connectionCount: entries.length,
      },
      {
        key: `missing-reducer:${nodeIndex}:${segmentIndexes.join("-")}:${connectedSizes.join("-")}`,
        canAcknowledge: true,
        guidance: entries.length >= 3
          ? "Choose Set as tee when this is a separate tee fitting; every smaller connected leg receives its own reducer. Choose Set as branch only when an outlet pipe is welded directly into a continuous main and no tee or reducer is required."
          : "Show the joint and confirm both run sizes. Keep the automatic reducer for a real size transition, or acknowledge this exception only when the transition is intentionally handled outside this spool.",
      },
    ));
  }

  return issues;
}

function drawingHealthItems() {
  const segmentData = segments();
  const quantities = quantitySummary(segmentData);
  const project = normalizeProjectInfo(state.projectInfo);
  const items = [];

  if (!project.jobNumber) items.push(healthIssue("error", "Job number missing", "Add a job number before issuing the drawing.", { type: "project", field: "jobNumber" }));
  if (!project.spoolNumber) items.push(healthIssue("error", "Spool number missing", "Add a spool number so the shop can identify this spool.", { type: "project", field: "spoolNumber" }));
  if (!project.revision) {
    items.push(healthIssue(
      "error",
      "Revision missing",
      "Set the drawing revision before issuing it.",
      { type: "project", field: "revision" },
      { guidance: "Use Set Rev A for the first issue, or Edit revision if your company uses another revision format." },
    ));
  }
  if (!segmentData.length) {
    items.push(healthIssue("error", "No pipe runs drawn", "Draw at least one pipe run before issuing or exporting.", { type: "tool", tool: "draw" }));
  }
  const invalidLengthRuns = segmentData.filter((segment) => pointLength(segment.vector) <= 0.001);
  if (invalidLengthRuns.length) {
    items.push(healthIssue(
      "error",
      "Invalid pipe run length",
      `${invalidLengthRuns.length} run${invalidLengthRuns.length === 1 ? "" : "s"} have no usable centreline length.`,
      { type: "segments", segmentIndexes: invalidLengthRuns.map((segment) => segment.index) },
    ));
  }
  const unusuallyShortRuns = segmentData.filter((segment) => {
    const length = pointLength(segment.vector);
    return length > 0.001 && length < MIN_LENGTH_MM;
  });
  if (unusuallyShortRuns.length) {
    items.push(healthIssue(
      "warning",
      "Confirm very short pipe runs",
      `${unusuallyShortRuns.length} run${unusuallyShortRuns.length === 1 ? "" : "s"} are shorter than ${MIN_LENGTH_MM} mm.`,
      { type: "segments", segmentIndexes: unusuallyShortRuns.map((segment) => segment.index) },
    ));
  }
  const pressureLimit = weakestPressureEstimate(segmentData);
  if (pressureLimit) {
    items.push(healthIssue(
      "info",
      "Weakest pressure point",
      `${pressureEstimateDetail(pressureLimit)} Verify fittings, flanges, temperature and design code before using this as a rating.`,
      {
        type: "pressure",
        segmentIndexes: pressureLimit.matchingSegmentIndexes,
      },
    ));
  }

  const connections = nodeConnections(segmentData);
  const openEnds = [];
  const openEndPointIndexes = [];
  for (const [pointIndex, connected] of connections.entries()) {
    if (connected.length !== 1) continue;
    const segment = segmentData.find((item) => item.index === connected[0].segmentIndex);
    if (segment && !endpointHasFinish(segment, pointIndex)) {
      openEnds.push(`${pointLabel(pointIndex)} on run ${segment.index + 1}`);
      openEndPointIndexes.push(pointIndex);
    }
  }
  if (openEnds.length) {
    items.push(healthIssue(
      "warning",
      "Open pipe ends",
      openEnds.slice(0, 8).join(", "),
      {
        type: "open-ends",
        pointIndexes: openEndPointIndexes,
        pointOnly: true,
      },
    ));
  }

  items.push(...missingReducerIssues(segmentData, quantities));

  const untypedBranchNodes = [...connections.entries()]
    .filter(([, connected]) => connected.length >= 3)
    .filter(([nodeIndex]) => !state.nodeTypes?.[nodeIndex])
    .map(([nodeIndex, connected]) => ({
      nodeIndex,
      segmentIndexes: connected.map((connection) => connection.segmentIndex),
    }));
  for (const item of untypedBranchNodes) {
    const segmentIndexes = [...new Set(item.segmentIndexes)].sort((a, b) => a - b);
    items.push(healthIssue(
      "warning",
      `Confirm tee or branch at ${pointLabel(item.nodeIndex)}`,
      "This connection is currently calculated as a tee until its fabrication type is confirmed.",
      {
        type: "tee-branch-review",
        pointIndex: item.nodeIndex,
        pointIndexes: [item.nodeIndex],
        segmentIndexes,
      },
      {
        key: `tee-branch-review:${item.nodeIndex}:${segmentIndexes.join("-")}`,
        canAcknowledge: true,
        guidance: "Choose Set as tee for a separate tee fitting with tee take-off and weight. Choose Set as branch when the outlet pipe is welded into the side of the main pipe with no tee or reducer.",
      },
    ));
  }

  const estimatedRows = takeoffCountRows(quantities).filter((row) => String(row.detail ?? "").toLowerCase().includes("estimated"));
  if (estimatedRows.length) {
    items.push(healthIssue("info", "Estimated weights present", `${estimatedRows.length} order-list row${estimatedRows.length === 1 ? "" : "s"} use estimated weights.`));
  }

  if (!state.showDimensions) {
    items.push(healthIssue("warning", "Dimensions hidden", "Turn dimensions on before exporting the fab sheet.", { type: "dimensions" }));
  }
  if (state.dimensionStyle === "redline" && segmentData.length > 8) {
    items.push(healthIssue(
      "info",
      "Red dimensions may need dragging",
      "Use Select to drag crowded red dimension labels away from the pipe.",
      {
        type: "segments",
        segmentIndexes: segmentData.slice(0, 12).map((segment) => segment.index),
      },
    ));
  }
  if (state.locked) {
    items.push(healthIssue("ok", "Drawing locked", "Edits are blocked until Lock edits is turned off or a new revision is created."));
  }
  if (!items.some((item) => item.severity === "error" || item.severity === "warning")) {
    items.unshift(healthIssue("ok", "Drawing checks clear", "Geometry and drawing checks passed. Workflow approval is shown separately below."));
  }

  return items;
}

function healthCounts(items = drawingHealthItems()) {
  return items.reduce((counts, item) => {
    if (item.acknowledged) {
      counts.acknowledged = (counts.acknowledged ?? 0) + 1;
      return counts;
    }
    counts[item.severity] = (counts[item.severity] ?? 0) + 1;
    return counts;
  }, {});
}

function healthSummaryText(items = drawingHealthItems()) {
  const counts = healthCounts(items);
  if (counts.error) return `${counts.error} issue${counts.error === 1 ? "" : "s"} need fixing`;
  if (counts.warning) return `${counts.warning} warning${counts.warning === 1 ? "" : "s"} to review`;
  if (counts.acknowledged) return `Drawing checks clear / ${counts.acknowledged} acknowledged`;
  return "Drawing checks clear";
}

function healthIssueClickable(item) {
  return Boolean(item?.target);
}

function projectFieldLabel(field) {
  if (field === "jobNumber") return "job number";
  if (field === "spoolNumber") return "spool number";
  if (field === "revision") return "revision";
  if (field === "drawnBy") return "drawn by";
  if (field === "client") return "client / area";
  if (field === "fittingProfile") return "fitting data profile";
  if (field === "fittingProfileReference") return "supplier / workshop reference";
  if (field === "weldGapMm") return "weld gap";
  return "project details";
}

function healthIssueTargetHint(item) {
  if (!healthIssueClickable(item)) return "";
  if (item.target.type === "project") return `Edit ${projectFieldLabel(item.target.field)}`;
  if (item.target.type === "dimensions") return "Turn dimensions on";
  if (item.target.type === "tool") return "Open Draw tool";
  return "Show on drawing";
}

function healthIssueActionHtml(item, index) {
  const actions = [];
  if (item.target?.type === "project" && item.target.field === "revision") {
    actions.push(["set-revision-a", "Set Rev A", "primary"]);
  }
  if (healthIssueClickable(item)) {
    actions.push(["locate", healthIssueTargetHint(item), ""]);
  }
  if (item.target?.type === "tee-branch-review" || (item.target?.type === "reducer-node" && item.target.connectionCount >= 3)) {
    actions.push(["set-tee", "Set as tee", "primary"]);
    actions.push(["set-branch", "Set as branch", ""]);
  }
  if (item.canAcknowledge && item.key) {
    actions.push(item.acknowledged
      ? ["reopen", "Reopen check", ""]
      : ["acknowledge", "Acknowledge & allow issue", "acknowledge"]);
  }
  if (!actions.length) return "";
  return `
    <div class="health-item-actions">
      ${actions.map(([action, label, className]) => `
        <button type="button" class="${escapeHtml(className)}" data-health-action="${escapeHtml(action)}" data-health-index="${index}">${escapeHtml(label)}</button>
      `).join("")}
    </div>
  `;
}

function healthAcknowledgementHtml(item) {
  if (!item.acknowledgement) return "";
  const who = item.acknowledgement.by || "Reviewer";
  const when = item.acknowledgement.at ? new Date(item.acknowledgement.at).toLocaleString() : "date not recorded";
  return `
    <div class="health-acknowledgement">
      <strong>Acknowledged by ${escapeHtml(who)} / ${escapeHtml(when)}</strong>
      <span>${escapeHtml(item.acknowledgement.reason)}</span>
    </div>
  `;
}

function updateHealthSummary() {
  if (!healthSummary) return;
  const items = drawingHealthItems();
  const level = items.some((item) => item.severity === "error" && !item.acknowledged)
    ? "error"
    : items.some((item) => item.severity === "warning" && !item.acknowledged)
    ? "warning"
    : "ok";
  healthSummary.innerHTML = `
    <div class="health-head ${level}">
      <strong>${escapeHtml(healthSummaryText(items))}</strong>
      <span>${escapeHtml(projectStatusLabel())}${state.locked ? " / Locked" : ""}</span>
    </div>
    <div class="health-list">
      ${items.map((item, index) => `
        <div class="health-item ${escapeHtml(item.severity)}${item.acknowledged ? " acknowledged" : ""}" data-health-index="${index}">
          <strong>${escapeHtml(item.title)}</strong>
          ${item.detail ? `<span>${escapeHtml(item.detail)}</span>` : ""}
          ${item.guidance ? `<p class="health-guidance"><b>How to fix:</b> ${escapeHtml(item.guidance)}</p>` : ""}
          ${healthAcknowledgementHtml(item)}
          ${healthIssueActionHtml(item, index)}
        </div>
      `).join("")}
    </div>
  `;
}

function setupHealthIssueClicks() {
  healthSummary?.addEventListener("click", (event) => {
    if (!(event.target instanceof Element)) return;
    const actionButton = event.target.closest("[data-health-action][data-health-index]");
    if (!actionButton || !healthSummary.contains(actionButton)) return;
    const index = Number(actionButton.dataset.healthIndex);
    const item = drawingHealthItems()[index];
    if (!item) return;
    handleHealthIssueAction(item, actionButton.dataset.healthAction).catch((error) => {
      console.warn("Could not handle health issue.", error);
      showAppNotice(error?.message || "Could not update that check.");
    });
  });
}

async function handleHealthIssueAction(item, action) {
  if (action === "set-revision-a") {
    if (cloudPermissionReadOnly) {
      showAppNotice(cloudReadOnlyMessage("set the drawing revision"));
      return;
    }
    state.projectInfo = normalizeProjectInfo({ ...state.projectInfo, revision: "A" });
    state.projectInfoPrompted = true;
    updateAll();
    showHealthPanel();
    showAppNotice("Revision A set. The drawing can now continue through the pre-issue check.");
    return;
  }
  if (action === "locate") {
    await focusHealthIssue(item);
    return;
  }
  if (action === "set-tee" || action === "set-branch") {
    if (!ensureDrawingEditable("change this tee/branch connection")) return;
    const pointIndex = Number(item.target?.pointIndex ?? item.target?.pointIndexes?.[0]);
    if (!Number.isInteger(pointIndex)) return;
    const snapshot = createUndoSnapshot();
    state.selectedPoint = pointIndex;
    state.activePoint = pointIndex;
    setNodeConnectionType(pointIndex, action === "set-branch" ? "branch" : "tee", { update: false });
    if (item.key) {
      state.healthAcknowledgements = normalizeHealthAcknowledgements(state.healthAcknowledgements);
      delete state.healthAcknowledgements[item.key];
    }
    recordHistory({ type: "snapshot", snapshot });
    updateAll();
    showHealthPanel();
    showAppNotice(action === "set-branch"
      ? "Connection set as a welded branch. Tee and reducer take-off will not be used there."
      : "Connection set as a tee. The app will add a separate reducer to every smaller connected leg.");
    return;
  }
  if (action === "acknowledge") {
    await acknowledgeHealthIssue(item);
    return;
  }
  if (action === "reopen") {
    reopenHealthIssue(item);
  }
}

async function acknowledgeHealthIssue(item) {
  if (!item?.canAcknowledge || !item.key) return;
  if (!currentDrawingProjectPermission().canIssue) {
    showAppNotice(currentPermissionRestrictionText("issue"));
    return;
  }
  const response = await openFieldInputDialog({
    title: "Acknowledge drawing exception",
    label: "Reason this can proceed",
    value: "",
    placeholder: "Engineering confirmed branch weld; reducer supplied elsewhere...",
    help: "The exception, your name and the time are saved with the spool and added to activity history.",
    submitLabel: "Acknowledge exception",
    multiline: true,
  });
  if (response === null) return;
  const reason = String(response).trim().slice(0, 500);
  if (!reason) {
    showAppNotice("Enter a reason before acknowledging this drawing exception.");
    return;
  }
  const now = new Date().toISOString();
  const by = checkerName() || "Reviewer";
  state.healthAcknowledgements = normalizeHealthAcknowledgements(state.healthAcknowledgements);
  state.healthAcknowledgements[item.key] = { title: item.title, reason, by, at: now };
  state.productionActivity = addProductionActivity(
    state.productionActivity,
    "review",
    `Acknowledged drawing check "${item.title}": ${reason}`,
    now,
  );
  persistState();
  updateHealthSummary();
  updateWorkflowSummary();
  showAppNotice("Exception acknowledged. It no longer blocks approval or issue, and the reason is recorded.");
}

function reopenHealthIssue(item) {
  if (!item?.key) return;
  if (!currentDrawingProjectPermission().canIssue) {
    showAppNotice(currentPermissionRestrictionText("issue"));
    return;
  }
  state.healthAcknowledgements = normalizeHealthAcknowledgements(state.healthAcknowledgements);
  if (!state.healthAcknowledgements[item.key]) return;
  delete state.healthAcknowledgements[item.key];
  const now = new Date().toISOString();
  state.productionActivity = addProductionActivity(
    state.productionActivity,
    "review",
    `Reopened drawing check "${item.title}".`,
    now,
  );
  persistState();
  updateHealthSummary();
  updateWorkflowSummary();
  showAppNotice("Drawing check reopened and will block issue again until fixed or acknowledged.");
}

async function focusHealthIssue(item) {
  const target = item?.target;
  if (!target) return;

  if (target.type === "project") {
    await editProjectDetailsFromHealth(target.field);
    return;
  }

  if (target.type === "dimensions") {
    applyAppMode("draw", { keepTool: true, activateTab: false });
    state.showDimensions = true;
    state.dimensionStyle = normalizeDimensionStyle(state.dimensionStyle);
    healthHighlight = null;
    updateControls();
    updateAll();
    dimensionToggle?.focus();
    if (isTabletLayout()) showMobilePanel("drawing");
    return;
  }

  if (target.type === "tool") {
    applyAppMode("draw", { keepTool: true, activateTab: false });
    setTool(target.tool || "draw");
    drawCanvas?.focus?.();
    return;
  }

  if (appMode !== "review") {
    applyAppMode("review", { keepTool: true, activateTab: false });
  }
  activateInspectorTab("checks");
  startHealthIssueHighlight(target, item.title);
  drawIso();
  if (isTabletLayout()) {
    showMobilePanel("inspector");
  } else {
    setInspectorDrawerOpen(true);
  }
}

function startHealthIssueHighlight(target, label) {
  const now = performance.now();
  healthHighlight = {
    target,
    label,
    startedAt: now,
    expiresAt: now + 4200,
  };
  if (healthHighlightAnimationFrame) {
    cancelAnimationFrame(healthHighlightAnimationFrame);
  }
  animateHealthIssueHighlight();
}

function animateHealthIssueHighlight() {
  if (!healthHighlight) {
    healthHighlightAnimationFrame = 0;
    return;
  }
  const now = performance.now();
  drawIso();
  // The redraw can clear a highlight whose target was removed during an edit.
  if (!healthHighlight) {
    healthHighlightAnimationFrame = 0;
    return;
  }
  if (now > healthHighlight.expiresAt) {
    healthHighlight = null;
    healthHighlightAnimationFrame = 0;
    drawIso();
    return;
  }
  healthHighlightAnimationFrame = requestAnimationFrame(animateHealthIssueHighlight);
}

function updateBomSummary() {
  if (!bomSummary) return;
  const rows = takeoffCountRows(quantitySummary());
  if (!rows.length) {
    bomSummary.innerHTML = '<div class="takeoff-empty">No items to order yet.</div>';
    return;
  }

  bomSummary.innerHTML = `
    <div class="bom-table">
      <div class="bom-row bom-head">
        <strong>Item</strong>
        <span>Qty / length</span>
        <span>Weight</span>
      </div>
      ${rows.map((row) => `
        <div class="bom-row">
          <strong>${escapeHtml(row.label)}<small>${escapeHtml(row.detail)}</small></strong>
          <span>${escapeHtml(row.countText)}</span>
          <span>${row.weightKg ? `${escapeHtml(formatMass(row.weightKg))} kg` : "-"}</span>
        </div>
      `).join("")}
    </div>
    <p>This is the ordering view: pipe by size and length, plus fittings by size.</p>
  `;
}

function currentWorkflowRows() {
  const checked = state.checkedAt ? `${new Date(state.checkedAt).toLocaleString()} by ${state.checkedBy || "unknown"}` : "Not checked";
  const issued = state.issuedAt ? `${new Date(state.issuedAt).toLocaleString()} by ${state.issuedBy || "unknown"}` : "Not issued";
  return [
    ["Stage", projectStatusLabel()],
    ["Lock", state.locked ? "Locked" : "Editable"],
    ["Checked", checked],
    ["Issued", issued],
    ["Health", healthSummaryText()],
  ];
}

function readyIssueFinding(severity, category, title, detail, action = null, source = null) {
  return {
    severity: severity === "blocker" ? "blocker" : "warning",
    category: String(category ?? "Drawing").trim() || "Drawing",
    title: String(title ?? "").trim(),
    detail: String(detail ?? "").trim(),
    action,
    source,
  };
}

function weldReadyIssueFindings(welds = synchronizeWeldRegister(state)) {
  const blockers = [];
  const warnings = [];
  for (const weld of welds) {
    const action = { type: "weld", fittingId: weld.fittingId };
    if (!weld.wps) {
      blockers.push(readyIssueFinding(
        "blocker",
        "Weld register",
        `${weld.number} is missing a WPS`,
        "Enter the approved welding procedure before issuing the fabrication drawing.",
        { ...action, field: "wps" },
      ));
    }
    if (weld.status === "repair") {
      blockers.push(readyIssueFinding(
        "blocker",
        "Weld register",
        `${weld.number} has an unresolved repair`,
        weld.repairHistory || "Record the repair, retest and accepted result before issue.",
        { ...action, field: "status" },
      ));
    }
    const inspectionIncomplete = !weld.inspectionType || !weld.inspectedBy;
    if (weld.status === "accepted" && inspectionIncomplete) {
      blockers.push(readyIssueFinding(
        "blocker",
        "Weld register",
        `${weld.number} acceptance record is incomplete`,
        "Accepted welds require both the inspection/NDT method and inspector name or ID.",
        { ...action, field: weld.inspectionType ? "inspectedBy" : "inspectionType" },
      ));
    } else if (["visual", "ndt"].includes(weld.status) && inspectionIncomplete) {
      warnings.push(readyIssueFinding(
        "warning",
        "Weld register",
        `${weld.number} inspection details are incomplete`,
        "Record the inspection/NDT method and inspector name or ID.",
        { ...action, field: weld.inspectionType ? "inspectedBy" : "inspectionType" },
      ));
    } else if (weld.status === "welded") {
      warnings.push(readyIssueFinding(
        "warning",
        "Weld register",
        `${weld.number} inspection is still pending`,
        "The weld is marked complete but has not progressed to visual, NDT or accepted.",
        { ...action, field: "status" },
      ));
    }
  }
  return { blockers, warnings };
}

function fittingCalculationSourceSummary(segmentData = segments()) {
  const profile = fittingDataProfileInfo(state);
  const connections = nodeConnections(segmentData);
  const takeoffs = takeoffData(segmentData);
  const hasTube = segmentData.some((segment) => isTubePipeSize(pipeSizeForSegment(segment)));
  const hasBranch = [...connections.entries()].some(([nodeIndex, connected]) =>
    connected.length >= 3 && nodeConnectionType(nodeIndex) === "branch"
  );
  const hasNonStandardElbow = takeoffs.elbows.some((elbow) =>
    Math.abs(Number(elbow.bend) - 45) >= 0.5 && Math.abs(Number(elbow.bend) - 90) >= 0.5
  );
  const hasUntabled45 = takeoffs.elbows.some((elbow) =>
    Math.abs(Number(elbow.bend) - 45) < 0.5 && !Number.isFinite(ELBOW_45_TAKEOFF_MM[elbow.nb])
  );
  const reasons = [];
  const mismatches = [];

  if (hasTube) reasons.push("supplier tube fitting dimensions");
  if (hasBranch) reasons.push("fabricated branch take-off");
  if (hasNonStandardElbow) reasons.push("non-standard elbow angle");
  if (hasUntabled45) reasons.push("45 degree size outside the Atlas B table");
  if (hasTube && profile.key !== "as1528Supplier") {
    mismatches.push("select the AS 1528.3 sanitary tube profile");
  }
  if (!hasTube && profile.key === "as1528Supplier") {
    mismatches.push("the AS 1528.3 profile is selected for a pipe drawing");
  }
  if (hasBranch && profile.key !== "workshopBranch") {
    mismatches.push("select the fabricated branch workshop profile");
  }
  if (!hasBranch && profile.key === "workshopBranch") {
    mismatches.push("the workshop branch profile is selected but no branch is present");
  }

  const verified = profile.key === "atlasAsmeB169" && reasons.length === 0 && mismatches.length === 0;
  const referenceText = profile.reference ? ` / ${profile.reference}` : "";
  return {
    profile,
    hasTube,
    hasBranch,
    hasNonStandardElbow,
    hasUntabled45,
    reasons,
    mismatches,
    verified,
    profileText: `${profile.label}${referenceText}`,
    shortProfileText: `${profile.shortLabel}${profile.reference ? ` / ${profile.reference}` : ""}`,
    statusLabel: verified ? "Verified dimensions" : `Estimate review: ${[...reasons, ...mismatches].join("; ") || profile.sourceStatus}`,
  };
}

function preIssueChecklist() {
  const project = normalizeProjectInfo(state.projectInfo);
  const health = drawingHealthItems();
  const segmentData = segments();
  const fittingSource = fittingCalculationSourceSummary(segmentData);
  const production = normalizeProductionInfo(state.productionInfo);
  const welds = synchronizeWeldRegister(state);
  const projectFields = [
    ["jobNumber", "job number"],
    ["spoolNumber", "spool number"],
    ["revision", "revision"],
  ];
  const projectMissing = projectFields.filter(([field]) => !project[field]).map(([, label]) => label);
  const projectBlockers = projectFields
    .filter(([field]) => !project[field])
    .map(([field, label]) => readyIssueFinding(
      "blocker",
      "Project",
      `${label[0].toUpperCase()}${label.slice(1)} missing`,
      `Add the ${label} before issuing the fabrication drawing.`,
      { type: "project", field },
    ));
  const projectWarnings = [
    !project.drawnBy
      ? readyIssueFinding("warning", "Project", "Drawn by is not recorded", "Add the drawing author for traceability.", { type: "project", field: "drawnBy" })
      : null,
    !project.client
      ? readyIssueFinding("warning", "Project", "Client / area is not recorded", "Add the client, plant or work area when it is known.", { type: "project", field: "client" })
      : null,
  ].filter(Boolean);
  const healthErrors = health.filter((item) => item.severity === "error" && !item.acknowledged && item.target?.type !== "project");
  const healthWarnings = health.filter((item) => item.severity === "warning" && !item.acknowledged);
  const healthBlockers = healthErrors.map((item) => readyIssueFinding(
    "blocker",
    "Drawing",
    item.title,
    item.detail,
    { type: "health" },
    item,
  ));
  const drawingWarnings = healthWarnings.map((item) => readyIssueFinding(
    "warning",
    "Drawing",
    item.title,
    item.detail,
    { type: "health" },
    item,
  ));
  const dimensionSourceWarnings = [
    fittingSource.mismatches.length
      ? readyIssueFinding(
          "warning",
          "Dimensions",
          "Fitting data profile does not match this drawing",
          `${fittingSource.profile.label}: ${fittingSource.mismatches.join("; ")}.`,
          { type: "project", field: "fittingProfile" },
        )
      : null,
    fittingSource.hasTube
      ? readyIssueFinding(
          "warning",
          "Dimensions",
          "Sanitary tube fitting dimensions need supplier confirmation",
          `The supplied Atlas manual verifies AS 1528.3 tube fitting weights but does not publish bend centre-to-end, tee centre-to-end or reducer face-to-face dimensions. Confirm the selected supplier dimensions before issue${fittingSource.profile.reference ? ` (${fittingSource.profile.reference})` : " and record the supplier reference"}.`,
          { type: "project", field: "fittingProfileReference" },
        )
      : null,
    fittingSource.hasBranch
      ? readyIssueFinding(
          "warning",
          "Dimensions",
          "Fabricated branch take-off uses a workshop estimate",
          `Atlas/ASME B16.9 dimensions cover manufactured tees, not welded-on branches. Confirm the branch saddle and cut allowance against the workshop procedure before issue${fittingSource.profile.reference ? ` (${fittingSource.profile.reference})` : " and record the workshop reference"}.`,
          { type: "project", field: "fittingProfileReference" },
        )
      : null,
    fittingSource.hasNonStandardElbow || fittingSource.hasUntabled45
      ? readyIssueFinding(
          "warning",
          "Dimensions",
          "One or more elbow deductions use geometry",
          "Only published 45 degree B and 90 degree A pipe dimensions are Atlas-verified. Confirm non-standard angles or untabled sizes before issue.",
        )
      : null,
  ].filter(Boolean);
  const weldFindings = weldReadyIssueFindings(welds);
  const productionBlockers = production.hold
    ? [readyIssueFinding(
        "blocker",
        "Production",
        "Spool is on hold",
        production.holdReason || "Remove the hold or record how it has been resolved.",
        { type: "production" },
      )]
    : [];
  const dueState = productionDueState(production);
  const productionWarnings = [
    !production.assignee
      ? readyIssueFinding("warning", "Production", "No worker is assigned", "Assign the spool so the workshop knows who owns the next action.", { type: "production" })
      : null,
    !production.dueDate
      ? readyIssueFinding("warning", "Production", "No due date is set", "Set the required workshop or issue date.", { type: "production" })
      : dueState.key === "overdue"
      ? readyIssueFinding("warning", "Production", "The due date is overdue", "Review the due date before issuing this revision.", { type: "production" })
      : null,
  ].filter(Boolean);
  const approvalBlockers = state.checkedAt
    ? []
    : [readyIssueFinding(
        "blocker",
        "Approval",
        "Drawing has not been approved",
        projectStatusAtLeast(state.projectStatus, "readycheck")
          ? "Record the checker before issuing."
          : "Move the spool to Ready to check, then record the checker.",
        { type: "approval" },
      )];
  const blockers = [
    ...projectBlockers,
    ...healthBlockers,
    ...weldFindings.blockers,
    ...productionBlockers,
    ...approvalBlockers,
  ];
  const warnings = [
    ...projectWarnings,
    ...drawingWarnings,
    ...dimensionSourceWarnings,
    ...weldFindings.warnings,
  ];
  const regressionResults = runRegressionAutoChecks();
  const sizeLabels = [...new Set(segmentData.map((segment) => pipeSizeDisplayLabel(pipeSizeForSegment(segment))))];
  return {
    projectMissing,
    health,
    errors: healthErrors,
    healthWarnings,
    dimensionSourceWarnings,
    acknowledged: health.filter((item) => item.acknowledged),
    projectBlockers,
    projectWarnings,
    welds,
    weldBlockers: weldFindings.blockers,
    weldWarnings: weldFindings.warnings,
    productionBlockers,
    productionWarnings,
    approvalBlockers,
    blockers,
    warnings,
    findings: [...blockers, ...warnings],
    materialText: `${pipeSpec().shortLabel} / ${sizeLabels.length ? sizeLabels.join(", ") : pipeSizeDisplayLabelByNb(state.pipeSizeNb)}`,
    fittingProfileText: fittingSource.profileText,
    fittingSourceStatus: fittingSource.statusLabel,
    fittingSourceVerified: fittingSource.verified,
    weldGapText: `${formatWeldGapMm(projectWeldGapMm())} mm per welded pipe end; open ends 0.0 mm`,
    regressionResults,
    regressionFailures: regressionResults.filter((result) => result.passed !== true),
  };
}

function preIssueChecklistStatus(checks = preIssueChecklist()) {
  if (checks.blockers.length) return "blocked";
  if (checks.warnings.length) return "review";
  return "ready";
}

function preIssueChecklistRowHtml(label, value, status) {
  return `
    <li class="preissue-${escapeHtml(status)}">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
    </li>
  `;
}

function preIssueFindingActionLabel(finding) {
  if (finding.action?.type === "project") return `Edit ${projectFieldLabel(finding.action.field)}`;
  if (finding.action?.type === "health") return healthIssueTargetHint(finding.source) || "Review drawing";
  if (finding.action?.type === "weld") return `Open ${finding.title.split(" ")[0]}`;
  if (finding.action?.type === "production") return "Open Jobs";
  if (finding.action?.type === "approval") return "Approve drawing";
  return "";
}

function preIssueFindingHtml(finding, index) {
  const actionLabel = preIssueFindingActionLabel(finding);
  const buttonLabel = finding.severity === "blocker"
    ? `Fix: ${actionLabel || "Review checks"}`
    : actionLabel;
  return `
    <li class="ready-issue-finding ${escapeHtml(finding.severity)}">
      <div>
        <small>${escapeHtml(finding.category)}</small>
        <strong>${escapeHtml(finding.title)}</strong>
        ${finding.detail ? `<span>${escapeHtml(finding.detail)}</span>` : ""}
      </div>
      ${buttonLabel ? `<button type="button" class="${finding.severity === "blocker" ? "primary-fix" : ""}" data-preissue-finding="${index}">${escapeHtml(buttonLabel)}</button>` : ""}
    </li>
  `;
}

function latestIssueAudit(source = state) {
  if (!source?.issuedAt || !projectStatusAtLeast(source.projectStatus, "issued")) return null;
  const audits = normalizeIssueAudits(source.issueAudits);
  const revisionUid = currentRevisionUid(source);
  const revision = normalizeProjectInfo(source.projectInfo).revision;
  return audits.find((audit) => audit.revisionUid && audit.revisionUid === revisionUid)
    ?? audits.find((audit) => !audit.revisionUid && audit.revision === revision)
    ?? null;
}

function issueAuditSummaryHtml(audit = latestIssueAudit()) {
  if (!audit) return "";
  const when = audit.createdAt ? new Date(audit.createdAt).toLocaleString() : "time not recorded";
  const result = audit.result === "overridden" ? "Warnings overridden" : "Passed";
  return `
    <div class="ready-issue-audit ${escapeHtml(audit.result)}">
      <strong>Last issue audit: ${escapeHtml(result)}</strong>
      <span>Rev ${escapeHtml(audit.revision || "-")} / ${escapeHtml(audit.issuedBy || "unknown")} / ${escapeHtml(when)}</span>
      ${audit.overrideReason ? `<small>${escapeHtml(audit.overrideReason)}</small>` : ""}
    </div>
  `;
}

function preIssueChecklistCardHtml() {
  const checks = preIssueChecklist();
  const status = preIssueChecklistStatus(checks);
  const projectText = checks.projectMissing.length
    ? `Missing ${checks.projectMissing.join(", ")}`
    : checks.projectWarnings.length
    ? `${checks.projectWarnings.length} detail warning${checks.projectWarnings.length === 1 ? "" : "s"}`
    : "Job, spool, revision and authorship set";
  const healthText = checks.errors.length
    ? `${checks.errors.length} issue${checks.errors.length === 1 ? "" : "s"} to fix`
    : checks.healthWarnings.length
    ? `${checks.healthWarnings.length} warning${checks.healthWarnings.length === 1 ? "" : "s"} to review`
    : "No drawing issues";
  const weldText = checks.weldBlockers.length
    ? `${checks.weldBlockers.length} critical weld item${checks.weldBlockers.length === 1 ? "" : "s"}`
    : checks.weldWarnings.length
    ? `${checks.weldWarnings.length} weld warning${checks.weldWarnings.length === 1 ? "" : "s"}`
    : checks.welds.length
    ? `${checks.welds.length} weld record${checks.welds.length === 1 ? "" : "s"} ready`
    : "No weld markers";
  const checkedText = state.checkedAt
    ? `Checked by ${state.checkedBy || "unknown"}`
    : "Not checked yet";
  const issuedText = state.issuedAt
    ? `Issued by ${state.issuedBy || "unknown"}`
    : status === "ready"
    ? "GREEN / Ready"
    : status === "review"
    ? "AMBER / Review"
    : "RED / Blocked";

  return `
    <div class="workflow-card preissue-card preissue-${escapeHtml(status)}">
      <div class="preissue-heading">
        <strong>Ready to Issue</strong>
        <span>${escapeHtml(issuedText)}</span>
      </div>
      <ul class="workflow-list preissue-list">
        ${preIssueChecklistRowHtml("Project", projectText, checks.projectBlockers.length ? "blocked" : checks.projectWarnings.length ? "review" : "ready")}
        ${preIssueChecklistRowHtml("Material / sizes", checks.materialText, "ready")}
        ${preIssueChecklistRowHtml("Fitting data", `${checks.fittingProfileText} / ${checks.fittingSourceStatus}`, checks.fittingSourceVerified ? "ready" : "review")}
        ${preIssueChecklistRowHtml("Weld gap", checks.weldGapText, "ready")}
        ${preIssueChecklistRowHtml("Drawing checks", healthText, checks.errors.length ? "blocked" : checks.healthWarnings.length ? "review" : "ready")}
        ${preIssueChecklistRowHtml("Weld register", weldText, checks.weldBlockers.length ? "blocked" : checks.weldWarnings.length ? "review" : "ready")}
        ${checks.productionBlockers.length ? preIssueChecklistRowHtml("Production", "On hold", "blocked") : ""}
        ${checks.acknowledged.length ? preIssueChecklistRowHtml("Acknowledged", `${checks.acknowledged.length} recorded exception${checks.acknowledged.length === 1 ? "" : "s"}`, "review") : ""}
        ${preIssueChecklistRowHtml("Approval", checkedText, state.checkedAt ? "ready" : "blocked")}
      </ul>
      ${checks.findings.length ? `
        <details class="ready-issue-findings"${status === "blocked" ? " open" : ""}>
          <summary>${checks.blockers.length ? `${checks.blockers.length} blocker${checks.blockers.length === 1 ? "" : "s"}` : "No blockers"} / ${checks.warnings.length} warning${checks.warnings.length === 1 ? "" : "s"}</summary>
          <ul>${checks.findings.map(preIssueFindingHtml).join("")}</ul>
        </details>
      ` : `<div class="ready-issue-clear"><strong>All issue checks are clear.</strong><span>The fabrication PDF can be issued without an override.</span></div>`}
      <p class="preissue-help">Red items block issue. Amber items require a recorded override reason. Assignment, due date and gear checks stay in Jobs and do not hold up drawing approval.</p>
      <div class="preissue-actions">
        <button type="button" data-workflow-action="open-health">Review drawing checks</button>
      </div>
      ${issueAuditSummaryHtml()}
    </div>
  `;
}

function productionAssigneeChoices() {
  const choices = new Set();
  const project = normalizeProjectInfo(state.projectInfo);
  const production = normalizeProductionInfo(state.productionInfo);
  if (production.assignee) choices.add(production.assignee);
  if (cloudUser?.email) choices.add(cloudUser.email);
  if (project.drawnBy) choices.add(project.drawnBy);
  for (const member of companyMembers) {
    if (member.status === "approved" && member.email) {
      choices.add(member.email);
    }
  }
  return [...choices].slice(0, 24);
}

function productionWorkflowCardHtml() {
  const production = normalizeProductionInfo(state.productionInfo);
  const materialChecklist = materialChecklistForState(state);
  return `
    <div class="workflow-card production-workflow-card production-workflow-summary">
      <div class="production-activity-head">
        <strong>Production</strong>
        <span>Managed from Jobs</span>
      </div>
      <ul class="workflow-list">
        <li><span>Assigned</span><strong>${escapeHtml(production.assignee || "Unassigned")}</strong></li>
        <li><span>Due</span><strong>${escapeHtml([production.dueDate, production.dueTime].filter(Boolean).join(" ") || "Not set")}</strong></li>
        <li><span>Priority</span><strong>${escapeHtml(productionPriorityLabel(production.priority))}</strong></li>
        <li><span>Hold</span><strong>${escapeHtml(production.hold ? production.holdReason || "On hold" : "No")}</strong></li>
        <li><span>Gear check</span><strong>${escapeHtml(production.assignee ? materialChecklistSummary(materialChecklist) : "Assign spool first")}</strong></li>
      </ul>
      <button type="button" data-workflow-action="open-jobs">Open Jobs</button>
    </div>
  `;
}

function productionActivityEntryHtml(entry) {
  return `
    <li>
      <span>${escapeHtml(entry.actor || "Team")} / ${escapeHtml(formatProductionActivityTime(entry.createdAt))}</span>
      <strong>${escapeHtml(entry.text)}</strong>
    </li>
  `;
}

function productionActivityCardHtml() {
  const activity = normalizeProductionActivity(state.productionActivity).reverse();
  const recent = activity.slice(0, 8);
  const older = activity.slice(8);
  return `
    <div class="workflow-card production-activity-card">
      <div class="production-activity-head">
        <strong>Activity history</strong>
        <span>${activity.length} retained event${activity.length === 1 ? "" : "s"}</span>
      </div>
      ${recent.length ? `<ul class="production-activity-list">${recent.map(productionActivityEntryHtml).join("")}</ul>` : "<span>No production activity recorded yet.</span>"}
      ${older.length ? `
        <details class="production-activity-older">
          <summary>View ${older.length} older event${older.length === 1 ? "" : "s"}</summary>
          <ul class="production-activity-list">${older.map(productionActivityEntryHtml).join("")}</ul>
        </details>
      ` : ""}
    </div>
  `;
}

async function handlePreIssueFinding(index) {
  const finding = preIssueChecklist().findings[Number(index)];
  if (!finding) return;
  if (!finding.action) {
    showHealthPanel();
    return;
  }
  if (finding.action.type === "project") {
    await editProjectDetailsFromHealth(finding.action.field);
    return;
  }
  if (finding.action.type === "health" && finding.source) {
    await focusHealthIssue(finding.source);
    return;
  }
  if (finding.action.type === "production") {
    const project = normalizeProjectInfo(state.projectInfo);
    projectLibrarySearch = project.spoolNumber || project.jobNumber || "";
    setTeamDashboardView("board");
    await openBrowserProject({ keepSearch: true });
    window.requestAnimationFrame(() => {
      const card = [...(projectLibraryList?.querySelectorAll("[data-production-project-id]") ?? [])]
        .find((item) => item.dataset.productionProjectId === state.projectId);
      card?.scrollIntoView?.({ behavior: "smooth", block: "center" });
      card?.classList.add("ready-issue-focus");
      card?.querySelector("[data-production-field='holdReason'], [data-production-field='hold']")?.focus?.();
      window.setTimeout(() => card?.classList.remove("ready-issue-focus"), 2800);
    });
    return;
  }
  if (finding.action.type === "approval") {
    if (!projectStatusAtLeast(state.projectStatus, "readycheck")) {
      const proceed = await confirmAppAction("Move this spool to Ready to check and open the approval form?", {
        title: "Prepare drawing approval",
        confirmLabel: "Move and approve",
      });
      if (!proceed) return;
      applyProjectStatusChange("readycheck");
      updateControls();
      updateAll();
    }
    await markDrawingChecked();
    return;
  }
  if (finding.action.type === "weld") {
    showHealthPanel();
    updateWorkflowSummary();
    window.requestAnimationFrame(() => {
      const row = workflowSummary?.querySelector(`[data-weld-row="${Number(finding.action.fittingId)}"]`);
      row?.scrollIntoView?.({ behavior: "smooth", block: "center" });
      row?.querySelector(`[data-weld-field="${CSS.escape(String(finding.action.field || "wps"))}"]`)?.focus?.();
      row?.classList.add("ready-issue-focus");
      window.setTimeout(() => row?.classList.remove("ready-issue-focus"), 2800);
    });
  }
}

function updateWorkflowSummary() {
  if (!workflowSummary) return;
  synchronizeWeldRegister(state);
  const permission = currentDrawingProjectPermission();
  const history = normalizeRevisionHistory(state.revisionHistory);
  const currentAudit = latestIssueAudit();
  const reviewReady = projectStatusAtLeast(state.projectStatus, "readycheck");
  const reviewDisabledAttr = !permission.canIssue
    ? ` disabled title="${escapeHtml(currentPermissionRestrictionText("issue"))}"`
    : !reviewReady
    ? ' disabled title="Move the spool to Ready to check before review"'
    : "";
  const issueDisabledAttr = permission.canIssue
    ? ""
    : ` disabled title="${escapeHtml(currentPermissionRestrictionText("issue"))}"`;
  const issueChecks = preIssueChecklist();
  const issueBlockerCount = issueChecks.blockers.length;
  const issueActionLabel = issueBlockerCount
    ? `Fix ${issueBlockerCount} blocker${issueBlockerCount === 1 ? "" : "s"} before issue`
    : !state.checkedAt
      ? "Approve before issue"
      : "Issue drawing";
  const editDisabledAttr = permission.canEdit
    ? ""
    : ` disabled title="${escapeHtml(currentPermissionRestrictionText("edit"))}"`;
  workflowSummary.innerHTML = `
    <div class="workflow-card workflow-status-card">
      <strong>Drawing workflow</strong>
      <ul class="workflow-list">
        ${currentWorkflowRows().map(([label, value]) => `<li><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></li>`).join("")}
      </ul>
    </div>
    ${preIssueChecklistCardHtml()}
    <div class="workflow-actions">
      <button type="button" data-workflow-action="mark-checked"${reviewDisabledAttr}>Approve drawing</button>
      <button type="button" data-workflow-action="return-changes"${reviewDisabledAttr}>Return for changes</button>
      <button type="button" class="workflow-primary-action" data-workflow-action="issue-drawing"${issueDisabledAttr}>${escapeHtml(issueActionLabel)}</button>
      <button type="button" data-workflow-action="new-revision"${editDisabledAttr}>New revision</button>
      <button type="button" data-workflow-action="share-readonly">Read-only export</button>
    </div>
    ${weldRegisterCardHtml()}
    <details class="workflow-more-details">
      <summary><strong>Workshop handoff & history</strong><span>Production allocation and previous revisions</span></summary>
      ${productionWorkflowCardHtml()}
    <div class="revision-card">
      <strong>Revision history</strong>
      <div class="revision-current">
        <strong>Current Rev ${escapeHtml(normalizeProjectInfo(state.projectInfo).revision || "-")}</strong>
        <span>${escapeHtml(state.checkedAt ? `Checked by ${state.checkedBy || "unknown"}` : "Not checked")}</span>
        <span>${escapeHtml(state.issuedAt ? `Issued by ${state.issuedBy || "unknown"}` : "Not issued")}</span>
        ${currentAudit ? `<small class="revision-audit ${escapeHtml(currentAudit.result)}">Issue audit: ${escapeHtml(currentAudit.result === "overridden" ? "Warnings overridden" : "Passed")}</small>` : ""}
      </div>
      ${history.length ? `<ul class="revision-list">${history.map((entry) => `
        <li>
          <div>
            <strong>Rev ${escapeHtml(entry.revision || "-")} / ${escapeHtml(projectStatusLabel(entry.status))}</strong>
            <span>${escapeHtml(entry.createdAt ? new Date(entry.createdAt).toLocaleString() : "not dated")}</span>
            <small>${escapeHtml(entry.checkedAt ? `Checked by ${entry.checkedBy || "unknown"}` : "Not checked")} / ${escapeHtml(entry.issuedAt ? `Issued by ${entry.issuedBy || "unknown"}` : "Not issued")}</small>
            ${entry.issueAudit ? `<small class="revision-audit ${escapeHtml(entry.issueAudit.result)}">Ready to Issue: ${escapeHtml(entry.issueAudit.result === "overridden" ? `Overridden - ${entry.issueAudit.overrideReason || "reason recorded"}` : "Passed")}</small>` : ""}
          </div>
          <button type="button" data-restore-revision="${escapeHtml(entry.id)}">Restore</button>
        </li>
      `).join("")}</ul>` : "<span>No saved revisions yet.</span>"}
    </div>
    </details>
  `;

  workflowSummary.querySelectorAll("[data-workflow-action]").forEach((button) => {
    button.addEventListener("click", () => {
      handleWorkflowAction(button.dataset.workflowAction).catch((error) => {
        console.warn("Drawing workflow action failed.", error);
        showAppNotice(error?.message || "Could not update drawing workflow.");
      });
    });
  });
  workflowSummary.querySelectorAll("[data-preissue-finding]").forEach((button) => {
    button.addEventListener("click", () => {
      handlePreIssueFinding(button.dataset.preissueFinding).catch((error) => {
        console.warn("Ready to Issue action failed.", error);
        showAppNotice(error?.message || "Could not open that issue.");
      });
    });
  });
  workflowSummary.querySelectorAll("[data-restore-revision]").forEach((button) => {
    button.addEventListener("click", () => restoreRevision(button.dataset.restoreRevision));
  });
  workflowSummary.querySelectorAll("[data-production-field]").forEach((field) => {
    field.addEventListener("change", () => {
      handleProductionFieldChange(field).catch((error) => {
        console.warn("Production allocation update failed.", error);
        showAppNotice(error?.message || "Could not update production allocation.");
      });
    });
  });
  workflowSummary.querySelectorAll("[data-weld-field]").forEach((field) => {
    field.addEventListener("change", () => handleWeldRegisterFieldChange(field));
  });
  workflowSummary.querySelectorAll("[data-weld-action]").forEach((button) => {
    button.addEventListener("click", () => handleWeldRegisterAction(button));
  });
  workflowSummary.querySelectorAll("[data-weld-assignment-mode]").forEach((select) => {
    select.addEventListener("change", () => {
      if (select.value === "mixed") {
        workflowSummary.querySelector("[data-weld-field='welderId']")?.focus?.();
        showAppNotice("Mixed welders selected. Enter the welder ID against each numbered weld.");
      } else {
        workflowSummary.querySelector("[data-weld-all-input]")?.focus?.();
      }
    });
  });
}

function weldStatusLabel(value) {
  const status = normalizeWeldStatus(value);
  if (status === "visual") return "Visual passed";
  if (status === "ndt") return "NDT passed";
  if (status === "accepted") return "Accepted";
  if (status === "repair") return "Repair required";
  if (status === "welded") return "Welded";
  return "Pending";
}

function weldRegisterCardHtml() {
  const welds = synchronizeWeldRegister(state);
  const permission = currentDrawingProjectPermission();
  const disabledAttr = permission.canManageProduction
    ? ""
    : ` disabled title="${escapeHtml(currentPermissionRestrictionText("production"))}"`;
  const spoolUid = ensureSpoolUid(state);
  const revisionUid = currentRevisionUid(state);
  const namedWelders = [...new Set(welds.map((weld) => weld.welderId.trim()).filter(Boolean))];
  const welderMode = namedWelders.length > 1 ? "mixed" : "all";
  const welderSummary = namedWelders.length > 1
    ? `Mixed welders / ${namedWelders.length} IDs`
    : namedWelders.length === 1
    ? `All welds by ${namedWelders[0]}`
    : "Welder not assigned";
  return `
    <div class="workflow-card weld-register-card">
      <div class="weld-register-head">
        <div><strong>Weld register</strong><span>${welds.length} numbered weld${welds.length === 1 ? "" : "s"} / ${escapeHtml(welderSummary)}</span></div>
        <div class="traceability-ids"><code>${escapeHtml(spoolUid)}</code><code>${escapeHtml(revisionUid)}</code></div>
      </div>
      ${welds.length ? `
        <div class="weld-register-bulk">
          <label>
            <span>Welder setup</span>
            <select data-weld-assignment-mode${disabledAttr}>
              <option value="all"${welderMode === "all" ? " selected" : ""}>One welder for all welds</option>
              <option value="mixed"${welderMode === "mixed" ? " selected" : ""}>Mixed welders</option>
            </select>
          </label>
          <label class="weld-register-all-welder">
            <span>All welds done by</span>
            <input data-weld-all-input value="${escapeHtml(welderMode === "all" ? namedWelders[0] || "" : "")}" maxlength="40" placeholder="Welder name / ID"${disabledAttr} />
          </label>
          <button type="button" data-weld-action="apply-all-welder"${disabledAttr}>Apply to every weld</button>
          <small>Choose Mixed welders to enter a different Welder ID on each numbered row below.</small>
        </div>
      ` : ""}
      ${welds.length ? `<div class="weld-register-list">${welds.map((weld) => `
        <section class="weld-register-row" data-weld-row="${weld.fittingId}">
          <div class="weld-register-number"><strong>${escapeHtml(weld.number)}</strong><span>Marker ${weld.fittingId}</span></div>
          <label><span>Welder ID</span><input data-weld-id="${weld.fittingId}" data-weld-field="welderId" value="${escapeHtml(weld.welderId)}" maxlength="40" placeholder="Welder"${disabledAttr} /></label>
          <label><span>WPS</span><input data-weld-id="${weld.fittingId}" data-weld-field="wps" value="${escapeHtml(weld.wps)}" maxlength="48" placeholder="WPS reference"${disabledAttr} /></label>
          <label><span>Status</span><select data-weld-id="${weld.fittingId}" data-weld-field="status"${disabledAttr}>${["pending","welded","visual","ndt","accepted","repair"].map((status) => `<option value="${status}"${weld.status === status ? " selected" : ""}>${weldStatusLabel(status)}</option>`).join("")}</select></label>
          <label><span>Inspection / NDT</span><input data-weld-id="${weld.fittingId}" data-weld-field="inspectionType" value="${escapeHtml(weld.inspectionType)}" maxlength="40" placeholder="VT, PT, RT, UT..."${disabledAttr} /></label>
          <label><span>Inspector</span><input data-weld-id="${weld.fittingId}" data-weld-field="inspectedBy" value="${escapeHtml(weld.inspectedBy)}" maxlength="64" placeholder="Name / ID"${disabledAttr} /></label>
          <label class="weld-register-wide"><span>Repair history / notes</span><input data-weld-id="${weld.fittingId}" data-weld-field="repairHistory" value="${escapeHtml(weld.repairHistory)}" maxlength="400" placeholder="Repair, retest and acceptance history"${disabledAttr} /></label>
        </section>
      `).join("")}</div>` : `<p class="weld-register-empty">Place Weld markers on the drawing. SpoolMate will number them W01, W02 and build the register automatically.</p>`}
    </div>
  `;
}

function persistProductionState() {
  persistState();
  window.clearTimeout(cloudAutosaveTimer);
  if (!cloudUser || !currentProjectHasCloudRecord()) return Promise.resolve(false);
  return saveCloudProject({ silent: true, productionOnly: true }).catch((error) => {
    console.warn("Production cloud save failed.", error);
    return false;
  });
}

function handleWeldRegisterFieldChange(field) {
  if (!currentDrawingProjectPermission().canManageProduction) {
    showAppNotice(currentPermissionRestrictionText("production"));
    updateWorkflowSummary();
    return;
  }
  const fittingId = Number(field?.dataset?.weldId);
  const key = String(field?.dataset?.weldField ?? "");
  const weld = weldRecordForFitting(fittingId);
  if (!weld || !["welderId", "wps", "status", "inspectionType", "inspectedBy", "repairHistory", "notes"].includes(key)) return;
  weld[key] = key === "status" ? normalizeWeldStatus(field.value) : String(field.value ?? "").trim();
  if (key === "status" && weld.status !== "pending" && !weld.completedAt) weld.completedAt = new Date().toISOString();
  state.productionActivity = addProductionActivity(state.productionActivity, "weld", `${weld.number} ${key} updated${key === "status" ? ` to ${weldStatusLabel(weld.status)}` : ""}.`, new Date().toISOString());
  persistProductionState();
  updateAll({ save: false });
}

function handleWeldRegisterAction(actionElement) {
  if (!currentDrawingProjectPermission().canManageProduction) {
    showAppNotice(currentPermissionRestrictionText("production"));
    updateWorkflowSummary();
    return;
  }
  const action = actionElement?.dataset?.weldAction;
  if (action !== "apply-all-welder") return;
  const input = actionElement.closest(".weld-register-bulk")?.querySelector("[data-weld-all-input]");
  const welderId = String(input?.value ?? "").trim().slice(0, 40);
  if (!welderId) {
    showAppNotice("Enter the welder name or ID before applying it to every weld.");
    input?.focus?.();
    return;
  }
  const welds = synchronizeWeldRegister(state);
  for (const weld of welds) weld.welderId = welderId;
  state.productionActivity = addProductionActivity(state.productionActivity, "weld", `All ${welds.length} welds assigned to ${welderId}.`, new Date().toISOString());
  persistProductionState();
  updateAll({ save: false });
  showAppNotice(`All ${welds.length} welds are assigned to ${welderId}.`);
}

async function handleWorkflowAction(action) {
  const permission = currentDrawingProjectPermission();
  if (["mark-checked", "return-changes", "issue-drawing"].includes(action) && !permission.canIssue) {
    showAppNotice(currentPermissionRestrictionText("issue"));
    return;
  }
  if (action === "new-revision" && !permission.canEdit) {
    showAppNotice(currentPermissionRestrictionText("edit"));
    return;
  }
  if (action === "mark-checked") await markDrawingChecked();
  if (action === "return-changes") await returnDrawingForChanges();
  if (action === "issue-drawing") await issueDrawing();
  if (action === "new-revision") createNextRevision();
  if (action === "share-readonly") shareReadOnlyProject();
  if (action === "open-jobs") await openBrowserProject();
  if (action === "open-health") showHealthPanel();
  if (action === "open-test-kit") openRegressionDialog();
}

async function handleProductionFieldChange(field) {
  const key = field?.dataset?.productionField;
  if (!key) return;
  if (!currentDrawingProjectPermission().canManageProduction) {
    showAppNotice(currentPermissionRestrictionText("production"));
    updateWorkflowSummary();
    return;
  }
  const previous = normalizeProductionInfo(state.productionInfo);
  const value = field.type === "checkbox" ? field.checked : field.value;
  if (key === "holdReason" && previous.hold && !String(value ?? "").trim()) {
    field.value = previous.holdReason;
    showAppNotice("A spool on hold must keep a hold reason. Remove the hold first if it is no longer blocked.");
    return;
  }
  let requiredHoldReason = "";
  if (key === "hold" && value === true) {
    const response = await openFieldInputDialog({
      title: "Place spool on hold",
      label: "Hold reason",
      value: previous.holdReason,
      placeholder: "Missing flange, client hold, material unavailable...",
      help: "A hold reason is required so the team knows what must be resolved.",
      submitLabel: "Place on hold",
    });
    requiredHoldReason = String(response ?? "").trim().slice(0, 140);
    if (!requiredHoldReason) {
      field.checked = false;
      showAppNotice("Hold was not applied. Enter a reason before placing a spool on hold.");
      return;
    }
  }
  const now = new Date().toISOString();
  state.productionInfo = normalizeProductionInfo({
    ...previous,
    [key]: value,
    ...(requiredHoldReason ? { holdReason: requiredHoldReason } : {}),
    lastUpdatedBy: checkerName(),
    lastUpdatedAt: now,
  });
  if (state.productionInfo.assignee) {
    state.productionInfo.materialChecklist = materialChecklistForState(state);
  }
  const next = normalizeProductionInfo(state.productionInfo);
  if (key === "assignee" && previous.assignee !== next.assignee) {
    state.productionActivity = addProductionActivity(state.productionActivity, "assignee", `Assigned changed from ${previous.assignee || "Unassigned"} to ${next.assignee || "Unassigned"}.`, now);
  }
  if ((key === "dueDate" || key === "dueTime") && (previous.dueDate !== next.dueDate || previous.dueTime !== next.dueTime)) {
    state.productionActivity = addProductionActivity(state.productionActivity, "due", `Due changed from ${formatProductionDue(previous) || "No due date"} to ${formatProductionDue(next) || "No due date"}.`, now);
  }
  if (key === "priority" && previous.priority !== next.priority) {
    state.productionActivity = addProductionActivity(state.productionActivity, "priority", `Priority changed from ${productionPriorityLabel(previous.priority)} to ${productionPriorityLabel(next.priority)}.`, now);
  }
  if (key === "hold" && previous.hold !== next.hold) {
    state.productionActivity = addProductionActivity(state.productionActivity, "hold", next.hold
      ? `Put on hold${next.holdReason ? `: ${next.holdReason}` : "."}`
      : "Hold removed.", now);
  }
  if (key === "holdReason" && previous.holdReason !== next.holdReason) {
    state.productionActivity = addProductionActivity(state.productionActivity, "hold", `Hold reason changed from ${previous.holdReason || "none"} to ${next.holdReason || "none"}.`, now);
  }
  updateProjectReadout();
  await persistProductionState();
  updateWorkflowSummary();
}

function checkerName() {
  return cloudUser?.email || normalizeProjectInfo(state.projectInfo).drawnBy || "";
}

async function recordReviewConversationMessage(body) {
  if (!cloudUser || !hasActiveCloudLicense() || !state.projectId || !currentProjectHasCloudRecord()) return false;
  try {
    await insertProjectCommentRecord(body);
    await loadProjectComments({ silent: true });
    return true;
  } catch (error) {
    console.warn("Could not add review message to spool conversation.", error);
    showAppNotice("Review was recorded, but its spool conversation message could not be added.");
    return false;
  }
}

async function markDrawingChecked() {
  if (!currentDrawingProjectPermission().canIssue) {
    showAppNotice(currentPermissionRestrictionText("issue"));
    return;
  }
  if (!projectStatusAtLeast(state.projectStatus, "readycheck")) {
    showAppNotice("Move the spool to Ready to check before approving it.");
    return;
  }
  const issues = drawingHealthItems().filter((item) => item.severity === "error" && !item.acknowledged);
  if (issues.length) {
    const proceed = await confirmAppAction(`${issues.length} health issue${issues.length === 1 ? "" : "s"} still need fixing. Mark checked anyway?`, {
      title: "Health issues remain",
      confirmLabel: "Mark checked",
      tone: "warning",
    });
    if (!proceed) {
      showHealthPanel();
      return;
    }
  }

  const name = await openFieldInputDialog({
    title: "Mark drawing checked",
    label: "Checked by",
    value: checkerName(),
    help: "This name will be recorded on the drawing history.",
    submitLabel: "Mark checked",
  });
  if (name === null) return;
  const reviewNote = await openFieldInputDialog({
    title: "Approve drawing",
    label: "Checker comment (optional)",
    value: "",
    placeholder: "Checked against dimensions, fittings and project requirements...",
    help: "This comment is added to the spool conversation. Leave it blank when no extra note is needed.",
    submitLabel: "Approve drawing",
    multiline: true,
  });
  if (reviewNote === null) return;
  const checkedBy = String(name).trim().slice(0, 64) || checkerName() || "unknown";
  const approvalComment = String(reviewNote).trim().slice(0, 900);
  const previousStatus = normalizeProjectStatus(state.projectStatus);
  const now = new Date().toISOString();
  state.checkedBy = checkedBy;
  state.checkedAt = now;
  state.projectStatus = "checked";
  state.issuedBy = "";
  state.issuedAt = "";
  updateProductionStatusMeta("checked", now);
  if (previousStatus !== "checked") {
    state.productionActivity = addProductionActivity(state.productionActivity, "status", `Moved from ${projectStatusLabel(previousStatus)} to ${projectStatusLabel("checked")}.`, now);
  }
  state.productionActivity = addProductionActivity(
    state.productionActivity,
    "review",
    `Approved by ${checkedBy}${approvalComment ? `: ${approvalComment}` : "."}`,
    now,
  );
  state.locked = true;
  updateControls();
  updateAll();
  await recordReviewConversationMessage(`APPROVED by ${checkedBy}${approvalComment ? `: ${approvalComment}` : "."}`);
  showAppNotice("Drawing approved and locked for issue.");
  showHealthPanel();
}

async function returnDrawingForChanges() {
  if (!currentDrawingProjectPermission().canIssue) {
    showAppNotice(currentPermissionRestrictionText("issue"));
    return false;
  }
  if (!projectStatusAtLeast(state.projectStatus, "readycheck")) {
    showAppNotice("Only spools in Ready to check or a later stage can be returned for changes.");
    return false;
  }
  const reason = await openFieldInputDialog({
    title: "Return drawing for changes",
    label: "Required checker comment",
    value: "",
    placeholder: "Explain exactly what needs changing...",
    help: "The drawing will return to Draft and this comment will be kept in the spool conversation and activity history.",
    submitLabel: "Return for changes",
    multiline: true,
  });
  if (reason === null) return false;
  const comment = String(reason).trim().slice(0, 900);
  if (!comment) {
    showAppNotice("Enter a checker comment before returning the drawing.");
    return false;
  }

  const reviewer = checkerName() || "Checker";
  const previousStatus = normalizeProjectStatus(state.projectStatus);
  const wasIssued = Boolean(state.issuedAt) || projectStatusAtLeast(previousStatus, "issued");
  addRevisionSnapshot(`Returned for changes: ${comment.slice(0, 90)}`);
  if (wasIssued) {
    const project = normalizeProjectInfo(state.projectInfo);
    state.projectInfo = normalizeProjectInfo({ ...project, revision: nextRevisionValue(project.revision) });
  }
  const now = new Date().toISOString();
  state.projectStatus = "draft";
  state.checkedBy = "";
  state.checkedAt = "";
  state.issuedBy = "";
  state.issuedAt = "";
  state.locked = false;
  updateProductionStatusMeta("draft", now);
  state.productionActivity = addProductionActivity(
    state.productionActivity,
    "review",
    `Returned for changes by ${reviewer}: ${comment}`,
    now,
  );
  if (wasIssued) {
    state.productionActivity = addProductionActivity(
      state.productionActivity,
      "revision",
      `Opened revision ${normalizeProjectInfo(state.projectInfo).revision || "-"} after checker return.`,
      now,
    );
  }
  updateControls();
  updateAll();
  await recordReviewConversationMessage(`RETURNED FOR CHANGES by ${reviewer}: ${comment}`);
  showAppNotice(wasIssued
    ? `Issued revision preserved. Rev ${normalizeProjectInfo(state.projectInfo).revision || "-"} is ready for changes.`
    : "Drawing returned to Draft with the checker comment recorded.");
  showHealthPanel();
  return true;
}

function updateProductionStatusMeta(nextStatus, now = new Date().toISOString()) {
  const currentProduction = normalizeProductionInfo(state.productionInfo);
  state.productionInfo = normalizeProductionInfo({
    ...currentProduction,
    completedAt: nextStatus === "complete" ? currentProduction.completedAt || now : "",
    removeAfter: nextStatus === "complete" ? currentProduction.removeAfter || isoDaysFromNow(7) : "",
    lastUpdatedBy: checkerName(),
    lastUpdatedAt: now,
  });
}

function recordStatusMove(previousStatus, nextStatus, now = new Date().toISOString()) {
  if (normalizeProjectStatus(previousStatus) !== normalizeProjectStatus(nextStatus)) {
    state.productionActivity = addProductionActivity(
      state.productionActivity,
      "status",
      `Moved from ${projectStatusLabel(previousStatus)} to ${projectStatusLabel(nextStatus)}.`,
      now,
    );
  }
}

function clearIssueStampIfUnissuedStatus(nextStatus) {
  if (projectStatusAtLeast(nextStatus, "issued")) return;
  state.issuedBy = "";
  state.issuedAt = "";
}

function applyProjectStatusChange(nextStatus, options = {}) {
  const normalizedStatus = normalizeProjectStatus(nextStatus);
  const previousStatus = normalizeProjectStatus(state.projectStatus);
  const now = options.now || new Date().toISOString();
  state.projectStatus = normalizedStatus;
  updateProductionStatusMeta(normalizedStatus, now);
  recordStatusMove(previousStatus, normalizedStatus, now);
  if (projectStatusAtLeast(normalizedStatus, "checked") && !state.checkedAt) {
    state.checkedAt = now;
    state.checkedBy = checkerName();
  }
  clearIssueStampIfUnissuedStatus(normalizedStatus);
  if (normalizedStatus !== "draft" && state.locked !== true) {
    state.locked = true;
  }
}

function preIssueBlockingMessage(checks) {
  if (!checks.blockers.length) return "";
  const titles = checks.blockers.slice(0, 3).map((finding) => finding.title);
  const remaining = Math.max(0, checks.blockers.length - titles.length);
  return `${checks.blockers.length} blocker${checks.blockers.length === 1 ? "" : "s"}: ${titles.join("; ")}${remaining ? `; and ${remaining} more` : ""}`;
}

async function promptForMissingIssueRevision() {
  const project = normalizeProjectInfo(state.projectInfo);
  if (project.revision) return true;
  const revision = await openFieldInputDialog({
    title: "Set drawing revision",
    label: "Revision",
    value: "A",
    placeholder: "A",
    help: "Initial drawings normally start at A. Change this if your company uses another revision format.",
    submitLabel: "Set revision and continue",
  });
  if (revision === null) return false;
  const value = String(revision).trim().slice(0, 16);
  if (!value) {
    showAppNotice("Enter a revision before issuing the drawing.");
    return false;
  }
  state.projectInfo = normalizeProjectInfo({ ...project, revision: value });
  state.projectInfoPrompted = true;
  updateAll();
  return true;
}

async function promptForIssueWarningOverride(checks) {
  const warnings = [...checks.warnings];
  if (!warnings.length) return "";
  const warningList = warnings.slice(0, 5).map((finding) => finding.title).join("; ");
  const response = await openFieldInputDialog({
    title: "Record issue warning override",
    label: "Required reason for issuing with warnings",
    value: "",
    placeholder: "Reviewed open ends against client mark-up; workshop assignment will follow...",
    help: `${warnings.length} warning${warnings.length === 1 ? "" : "s"}: ${warningList}${warnings.length > 5 ? "; and more" : ""}. The reason, issuer and time are saved with this revision.`,
    submitLabel: "Record reason and continue",
    multiline: true,
  });
  if (response === null) return null;
  const reason = String(response).trim().slice(0, 700);
  if (!reason) {
    showAppNotice("Enter a reason before issuing a drawing with warnings.");
    return null;
  }
  return reason;
}

function issueAuditFindingSnapshot(finding) {
  return normalizeIssueAuditFinding({
    severity: finding.severity,
    category: finding.category,
    title: finding.title,
    detail: finding.detail,
  });
}

function recordReadyIssueAudit(checks, options = {}) {
  const now = String(options.now ?? new Date().toISOString());
  const overrideReason = String(options.overrideReason ?? "").trim().slice(0, 700);
  const acknowledgedFindings = checks.acknowledged.map((item) => readyIssueFinding(
    "warning",
    "Acknowledged drawing exception",
    item.title,
    item.acknowledgement?.reason || item.detail,
  ));
  const audit = normalizeIssueAudit({
    id: `audit-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    revision: normalizeProjectInfo(state.projectInfo).revision || "-",
    revisionUid: currentRevisionUid(state),
    createdAt: now,
    result: overrideReason ? "overridden" : "ready",
    issuedBy: options.issuedBy,
    checkedBy: state.checkedBy,
    checkedAt: state.checkedAt,
    overrideReason,
    findings: [...checks.warnings, ...acknowledgedFindings]
      .map(issueAuditFindingSnapshot)
      .filter(Boolean),
  });
  state.issueAudits = normalizeIssueAudits([
    audit,
    ...normalizeIssueAudits(state.issueAudits).filter((entry) => entry.revisionUid !== audit.revisionUid),
  ]);
  return audit;
}

async function issueDrawing(options = {}) {
  if (!currentDrawingProjectPermission().canIssue) {
    showAppNotice(currentPermissionRestrictionText("issue"));
    updateControls();
    return false;
  }

  let checks = preIssueChecklist();
  if (checks.projectMissing.includes("revision")) {
    const revisionSet = await promptForMissingIssueRevision();
    if (!revisionSet) {
      showHealthPanel();
      updateWorkflowSummary();
      return false;
    }
    checks = preIssueChecklist();
  }
  const blocking = preIssueBlockingMessage(checks);
  if (blocking) {
    const nextStep = "Open Ready to Issue and use the action beside each red item.";
    showAppNotice(`Pre-issue check blocked: ${blocking}. ${nextStep}`);
    showHealthPanel();
    updateWorkflowSummary();
    return false;
  }

  if (!state.checkedAt) {
    showAppNotice("Approve the drawing before issuing it so the checker is recorded.");
    showHealthPanel();
    updateWorkflowSummary();
    return false;
  }

  const overrideReason = await promptForIssueWarningOverride(checks);
  if (overrideReason === null) {
    showHealthPanel();
    updateControls();
    return false;
  }

  const name = await openFieldInputDialog({
    title: "Issue drawing",
    label: "Issued by",
    value: checkerName() || state.checkedBy || "",
    help: "This name is recorded on the fab sheet, workflow card and activity history.",
    submitLabel: "Issue drawing",
  });
  if (name === null) {
    updateControls();
    return false;
  }

  const issuedBy = String(name).trim().slice(0, 64) || checkerName() || "unknown";
  const now = new Date().toISOString();
  state.issuedBy = issuedBy;
  state.issuedAt = now;
  if (!state.checkedAt) {
    state.checkedBy = issuedBy;
    state.checkedAt = now;
  }
  applyProjectStatusChange("issued", { now });
  state.issuedBy = issuedBy;
  state.issuedAt = now;
  state.locked = true;
  const issuedRevision = normalizeProjectInfo(state.projectInfo).revision || "-";
  state.productionActivity = addProductionActivity(
    state.productionActivity,
    "revision",
    `Revision ${issuedRevision} issued by ${issuedBy}${overrideReason ? ` with warning override: ${overrideReason}` : "."}`,
    now,
  );
  const issueAudit = recordReadyIssueAudit(checks, { now, issuedBy, overrideReason });
  addRevisionSnapshot("Issued after Ready to Issue gate", { issueAudit });
  if (options.targetStatus && normalizeProjectStatus(options.targetStatus) !== "issued") {
    applyProjectStatusChange(options.targetStatus, { now: new Date().toISOString() });
  }
  updateControls();
  updateAll();
  showAppNotice(overrideReason
    ? "Drawing issued with the warning override recorded against this revision."
    : "Ready to Issue passed. The drawing and fabrication PDF are now approved for issue.");
  return true;
}

function revisionRankText(value) {
  return String(value ?? "").trim().toUpperCase();
}

function nextRevisionValue(value) {
  const current = revisionRankText(value);
  if (!current) return "A";
  if (/^\d+$/.test(current)) return String(Number(current) + 1);
  if (/^[A-Z]+$/.test(current)) {
    const chars = current.split("");
    let index = chars.length - 1;
    while (index >= 0) {
      if (chars[index] !== "Z") {
        chars[index] = String.fromCharCode(chars[index].charCodeAt(0) + 1);
        return chars.join("");
      }
      chars[index] = "A";
      index -= 1;
    }
    return `A${chars.join("")}`;
  }
  return `${current}-1`;
}

function addRevisionSnapshot(note = "Saved revision", options = {}) {
  const project = normalizeProjectInfo(state.projectInfo);
  const snapshot = {
    id: `rev-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    revision: project.revision || "-",
    createdAt: new Date().toISOString(),
    status: normalizeProjectStatus(state.projectStatus),
    note,
    checkedBy: String(state.checkedBy ?? "").trim(),
    checkedAt: String(state.checkedAt ?? "").trim(),
    issuedBy: String(state.issuedBy ?? "").trim(),
    issuedAt: String(state.issuedAt ?? "").trim(),
    issueAudit: normalizeIssueAudit(options.issueAudit ?? latestIssueAudit()),
    state: statePayload({ includeRevisionHistory: false }),
  };
  const history = normalizeRevisionHistory(state.revisionHistory).filter((entry) => !(
    snapshot.issuedAt &&
    entry.revision === snapshot.revision &&
    entry.issuedAt === snapshot.issuedAt
  ));
  history.unshift(snapshot);
  state.revisionHistory = history.slice(0, 12);
}

function createNextRevision() {
  if (!currentDrawingProjectPermission().canEdit) {
    showAppNotice(currentPermissionRestrictionText("edit"));
    return;
  }
  const project = normalizeProjectInfo(state.projectInfo);
  const previousRevision = project.revision || "-";
  const nextRevision = nextRevisionValue(project.revision);
  addRevisionSnapshot("Before new revision");
  state.projectInfo = normalizeProjectInfo({
    ...project,
    revision: nextRevision,
  });
  state.projectStatus = "draft";
  state.checkedBy = "";
  state.checkedAt = "";
  state.issuedBy = "";
  state.issuedAt = "";
  state.locked = false;
  state.productionActivity = addProductionActivity(
    state.productionActivity,
    "revision",
    `Created revision ${nextRevision} from revision ${previousRevision}.`,
  );
  updateControls();
  updateAll();
  showHealthPanel();
}

async function restoreRevision(revisionId) {
  if (!currentDrawingProjectPermission().canEdit) {
    showAppNotice(currentPermissionRestrictionText("edit"));
    return;
  }
  const entry = normalizeRevisionHistory(state.revisionHistory).find((item) => item.id === revisionId);
  if (!entry?.state) return;
  const proceed = await confirmAppAction(`Restore revision ${entry.revision || "-"}? The current drawing will be replaced.`, {
    title: "Restore revision",
    confirmLabel: "Restore",
    tone: "warning",
  });
  if (!proceed) return;

  addRevisionSnapshot("Before restore");
  const history = normalizeRevisionHistory(state.revisionHistory);
  const restored = stateFromPayload(entry.state);
  if (!restored) {
    showAppNotice("That revision could not be restored.");
    return;
  }
  state = restored;
  state.revisionHistory = history;
  state.projectStatus = "draft";
  state.checkedBy = "";
  state.checkedAt = "";
  state.issuedBy = "";
  state.issuedAt = "";
  state.locked = false;
  state.productionActivity = addProductionActivity(
    state.productionActivity,
    "revision",
    `Restored revision ${entry.revision || "-"} into an editable Draft.`,
  );
  three.userMovedCamera = false;
  setNextIdsFromState(state);
  updateControls();
  updateAll();
  showHealthPanel();
}

function saveCurrentSettingsAsDefaults() {
  persistUserDrawingDefaults();
  showAppNotice("Current material, pipe size, dimensions, lifting, preview and drawing settings saved as your defaults.");
}

function projectBackupKey(source = state) {
  return normalizeProjectId(source?.projectId) || [
    normalizeProjectInfo(source?.projectInfo).jobNumber,
    normalizeProjectInfo(source?.projectInfo).spoolNumber,
  ].filter(Boolean).join("::").toLowerCase() || "current";
}

function loadProjectBackups() {
  try {
    const backups = JSON.parse(localStorage.getItem(PROJECT_BACKUPS_KEY));
    return Array.isArray(backups) ? backups : [];
  } catch {
    return [];
  }
}

function loadLastSessionRecovery() {
  try {
    const recovery = JSON.parse(localStorage.getItem(LAST_SESSION_RECOVERY_KEY));
    if (!recovery?.state || !Array.isArray(recovery.state.points) || recovery.state.points.length < 2) return null;
    return recovery;
  } catch {
    return null;
  }
}

async function restoreLastSession() {
  const recovery = loadLastSessionRecovery();
  if (!recovery?.state) {
    showAppNotice("No previous session is available to restore.");
    updateHomeDashboard();
    return;
  }
  const when = recovery.createdAt ? new Date(recovery.createdAt).toLocaleString() : "the previous session";
  const proceed = await confirmAppAction(
    `Restore the drawing captured at ${when}? Your current drawing will be backed up first. The recovered drawing opens as a local copy and will not overwrite a cloud spool automatically.`,
    {
      title: "Restore last session",
      confirmLabel: "Restore local copy",
      cancelLabel: "Keep current",
      tone: "warning",
    },
  );
  if (!proceed) return;

  createProjectBackup("before last-session restore");
  const restored = stateFromPayload(recovery.state);
  if (!restored) {
    showAppNotice("The previous session could not be restored.");
    return;
  }
  restored.projectId = null;
  state = restored;
  currentCloudProjectOwnerId = null;
  currentCloudProjectCompanyId = null;
  cloudPermissionReadOnly = false;
  resetCloudSaveTracking();
  three.userMovedCamera = false;
  setNextIdsFromState(state);
  closeHomeDashboard();
  updateControls();
  updateAll();
  showAppNotice("Last session restored as a local recovery copy. Use Save when you are ready to keep it.");
}

function storeProjectBackups(backups) {
  try {
    localStorage.setItem(PROJECT_BACKUPS_KEY, JSON.stringify(backups.slice(0, 36)));
  } catch (error) {
    console.warn("Could not save project backup.", error);
  }
}

function createProjectBackup(reason = "autosave") {
  if (!hasDrawingContent()) return;
  const key = projectBackupKey();
  const backups = loadProjectBackups().filter((backup) => backup?.state);
  backups.unshift({
    id: `backup-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    key,
    projectId: normalizeProjectId(state.projectId),
    name: projectDisplayName(),
    projectInfo: normalizeProjectInfo(state.projectInfo),
    createdAt: new Date().toISOString(),
    reason,
    state: statePayload({ includeRevisionHistory: false }),
  });
  const seen = new Map();
  for (const backup of backups) {
    const backupKey = backup.key || projectBackupKey(backup.state);
    const list = seen.get(backupKey) ?? [];
    if (list.length < 8) list.push(backup);
    seen.set(backupKey, list);
  }
  storeProjectBackups([...seen.values()].flat().sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))));
}

function maybeCreateProjectBackup() {
  if (!hasDrawingContent()) return;
  const backups = loadProjectBackups();
  const key = projectBackupKey();
  const latest = backups.find((backup) => backup.key === key);
  const lastTime = latest?.createdAt ? new Date(latest.createdAt).getTime() : 0;
  if (Date.now() - lastTime < 4 * 60 * 1000) return;
  createProjectBackup("autosave backup");
}

function relevantProjectBackups() {
  const key = projectBackupKey();
  return loadProjectBackups()
    .filter((backup) => backup.key === key || (state.projectId && backup.projectId === state.projectId))
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)))
    .slice(0, 5);
}

function updateBackupSummary() {
  if (!backupSummary) return;
  const backups = relevantProjectBackups();
  backupSummary.innerHTML = backups.length
    ? `<div class="backup-card">
        <strong>Local backups</strong>
        <ul class="backup-list">
        ${backups.map((backup) => `
          <li>
            <div>
              <strong>${escapeHtml(backup.reason || "backup")}</strong>
              <span>${escapeHtml(backup.createdAt ? new Date(backup.createdAt).toLocaleString() : "not dated")}</span>
            </div>
            <button type="button" data-restore-backup="${escapeHtml(backup.id)}">Restore</button>
          </li>
        `).join("")}
        </ul>
      </div>`
    : '<div class="takeoff-empty">No backup snapshots for this drawing yet.</div>';

  backupSummary.querySelectorAll("[data-restore-backup]").forEach((button) => {
    button.addEventListener("click", () => restoreProjectBackup(button.dataset.restoreBackup));
  });
}

async function restoreProjectBackup(backupId) {
  const backup = loadProjectBackups().find((item) => item.id === backupId);
  if (!backup?.state) return;
  const proceed = await confirmAppAction("Restore this backup? The current drawing will be replaced.", {
    title: "Restore backup",
    confirmLabel: "Restore",
    tone: "warning",
  });
  if (!proceed) return;
  createProjectBackup("before backup restore");
  const restored = stateFromPayload(backup.state);
  if (!restored) {
    showAppNotice("That backup could not be restored.");
    return;
  }
  state = restored;
  three.userMovedCamera = false;
  setNextIdsFromState(state);
  updateControls();
  updateAll();
  showHealthPanel();
}

function populatePipeSizeOptions() {
  const current = pipeSizeNbForSpec(pipeSizeSelect.value || state.pipeSizeNb, state.pipeSpec);
  pipeSizeSelect.innerHTML = "";
  for (const size of pipeSizesForSpec(state.pipeSpec)) {
    const option = document.createElement("option");
    option.value = String(size.nb);
    option.textContent = pipeSizeOptionText(size);
    pipeSizeSelect.append(option);
  }
  pipeSizeSelect.value = String(current);
}

function updatePipeSizeReadout() {
  const selected = selectedSegmentsData();
  const size = selectedPipeSize();
  const wall = pipeWallForSize(size);
  const mass = pipeMassPerMetreForSize(size);
  if (selected.length > 1) {
    const sizes = new Set(selected.map((segment) => pipeSizeForSegment(segment).nb));
    const prefix = sizes.size === 1 ? `Selected ${selected.length} sections` : `Selected ${selected.length} sections / mixed`;
    pipeSizeReadout.textContent = `${prefix}: ${pipeSpecShortLabel()} - choose a ${pipeSizeReadoutNoun()} to update all selected sections`;
    return;
  }

  const prefix = selected.length === 1 ? "Selected section" : "Default";
  pipeSizeReadout.textContent = `${prefix}: ${pipeSizeDisplayLabel(size)} ${pipeSpecShortLabel()} - OD ${size.od.toFixed(1)} mm / wall ${wall.toFixed(2)} mm / ${formatMass(mass)} kg/m`;
}

function updatePipeSizeControls() {
  populatePipeSizeOptions();
  const selected = selectedSegmentsData();
  pipeSizeSelect.value = String(selected.length ? pipeSizeForSegment(selected[0]).nb : pipeSizeNbForSpec(state.pipeSizeNb, state.pipeSpec));
  updatePipeSizeReadout();
}

function setPipeSizeForSegments(indexes, pipeSizeNb) {
  pipeSizeNb = pipeSizeNbForSpec(pipeSizeNb, state.pipeSpec);
  const previousDefault = state.pipeSizeNb;
  const requestedSelected = normalizeSelectedSegments(indexes, state.edges.length);
  if (!requestedSelected.length) {
    state.pipeSizeNb = pipeSizeNb;
    updateAll();
    return;
  }
  if (!ensureDrawingEditable("change pipe sizes")) return;
  const selected = branchMainLinkedSegmentIndexes(requestedSelected);
  const linkedMainCount = Math.max(0, selected.length - requestedSelected.length);

  const previousSizes = selected.map((segmentIndex) => normalizePipeSize(state.edges[segmentIndex]?.pipeSizeNb ?? previousDefault));
  const changed = previousSizes.some((sizeNb) => sizeNb !== pipeSizeNb);
  const snapshot = changed ? createUndoSnapshot() : null;
  state.pipeSizeNb = pipeSizeNb;
  for (const segmentIndex of selected) {
    if (state.edges[segmentIndex]) {
      state.edges[segmentIndex].pipeSizeNb = pipeSizeNb;
    }
  }
  setSelectedSegments(selected);
  if (snapshot) {
    recordHistory({ type: "snapshot", snapshot });
    const uniquePreviousSizes = [...new Set(previousSizes)];
    const previousLabel = uniquePreviousSizes.length === 1
      ? pipeSizeDisplayLabelByNb(uniquePreviousSizes[0])
      : "mixed sizes";
    const nextLabel = pipeSizeDisplayLabelByNb(pipeSizeNb);
    const runText = selected.length === 1
      ? `Run ${selected[0] + 1}`
      : linkedMainCount
      ? `${selected.length} continuous branch-main runs`
      : `${selected.length} selected runs`;
    state.productionActivity = addProductionActivity(
      state.productionActivity,
      "pipe-size",
      `Changed ${runText} from ${previousLabel} to ${nextLabel}.`,
    );
  }
  updateAll();
  if (changed && linkedMainCount) {
    showAppNotice(`Updated ${selected.length} continuous main-pipe sections through the branch. The branch outlet size was left unchanged.`);
  }
}

function updateSelectionControls() {
  const selectedSegment = selectedSegmentData();
  selectedRunLengthInput.disabled = !selectedSegment;
  selectedRunLengthInput.value = selectedSegment ? String(Math.round(pointLength(selectedSegment.vector))) : "";
}

function updateProjectInputs() {
  const project = normalizeProjectInfo(state.projectInfo);
  for (const input of projectInputs) {
    const field = input.dataset.projectField;
    input.value = project[field] ?? "";
  }
  updateProjectReadout();
}

function updateProjectReadout() {
  if (!projectReadout) return;
  const title = projectDisplayName();
  const status = projectStatusLabel();
  const locked = cloudPermissionReadOnly ? " / View only" : state.locked ? " / Locked" : "";
  projectReadout.textContent = isQuickPdfMode()
    ? `Quick PDF${state.projectId ? " · Saved copy" : " · Temporary"}`
    : hasProjectInfo() ? title : "No project set";
  projectReadout.title = state.projectId
    ? `${title} - ${status}${locked} - saved in this browser`
    : hasProjectInfo()
    ? `${title} - ${status}${locked} - not saved in project list yet`
    : "No project details entered";
}

function updateWorkflowControls() {
  const permission = currentDrawingProjectPermission();
  if (projectStatusSelect) projectStatusSelect.value = normalizeProjectStatus(state.projectStatus);
  if (projectStatusSelect) {
    const canChangeAnyStatus = permission.canEdit || permission.canIssue || permission.canManageProduction;
    projectStatusSelect.disabled = !canChangeAnyStatus;
    projectStatusSelect.title = canChangeAnyStatus ? "" : currentPermissionRestrictionText("production");
    for (const option of projectStatusSelect.options) {
      const status = normalizeProjectStatus(option.value);
      option.disabled = status === "checked" || status === "issued"
        ? !permission.canIssue
        : status === "draft" || status === "readycheck"
        ? !(permission.canEdit || permission.canIssue)
        : !permission.canManageProduction;
    }
  }
  if (projectAssigneeReadout) {
    const assignee = normalizeProductionInfo(state.productionInfo).assignee.trim();
    projectAssigneeReadout.textContent = assignee ? `Assigned: ${assignee}` : "Unassigned";
    projectAssigneeReadout.classList.toggle("assigned", Boolean(assignee));
  }
  if (projectLockToggle) {
    const issuedLocked = Boolean(state.issuedAt) || projectStatusAtLeast(state.projectStatus, "issued");
    if (issuedLocked) state.locked = true;
    projectLockToggle.checked = state.locked === true || !permission.canEdit || issuedLocked;
    projectLockToggle.disabled = !permission.canEdit || issuedLocked;
    projectLockToggle.title = !permission.canEdit
      ? currentPermissionRestrictionText("edit")
      : issuedLocked
      ? "Issued drawings stay locked. Use Return for changes or New revision."
      : "";
  }
}

function activateInspectorTab(name) {
  const tabs = [...document.querySelectorAll("[data-inspector-tab]")];
  const panels = [...document.querySelectorAll("[data-inspector-panel]")];
  const requestedTab = tabs.find((tab) => tab.dataset.inspectorTab === name && !tab.hidden);
  const fallbackTab = tabs.find((tab) => tab.dataset.inspectorTab === APP_MODE_DEFAULT_TAB[appMode] && !tab.hidden)
    ?? tabs.find((tab) => !tab.hidden);
  const activeName = (requestedTab ?? fallbackTab)?.dataset.inspectorTab ?? "properties";
  for (const tab of tabs) {
    const active = !tab.hidden && tab.dataset.inspectorTab === activeName;
    tab.classList.toggle("active", active);
    tab.setAttribute("aria-selected", String(active));
  }
  for (const panel of panels) {
    panel.classList.toggle("active", panel.dataset.inspectorPanel === activeName);
  }
  refreshPreviewAfterLayoutChange();
  checkTutorialPractice();
}

function refreshPreviewAfterLayoutChange() {
  schedulePreviewStabilize();
}

function syncPreviewCanvasVisibility() {
  if (!threeCanvas || !fallbackCanvas) return;
  if (three.ready) {
    threeCanvas.hidden = false;
    fallbackCanvas.hidden = true;
  } else {
    threeCanvas.hidden = true;
    fallbackCanvas.hidden = false;
  }
}

function forcePreviewRender() {
  syncPreviewCanvasVisibility();
  if (three.ready) {
    resizeThree();
    update3dPreview();
    resizeThree();
    if (three.renderer && three.scene && three.camera) {
      three.renderer.render(three.scene, three.camera);
    }
    update3dLabelPositions();
    return;
  }

  clear3dPipeLabels();
  renderFallbackPreview();
}

function schedulePreviewStabilize() {
  window.requestAnimationFrame(() => {
    forcePreviewRender();
    window.requestAnimationFrame(forcePreviewRender);
  });
  window.setTimeout(forcePreviewRender, 90);
  window.setTimeout(forcePreviewRender, 260);
}

function showHealthPanel() {
  if (appMode !== "review") {
    applyAppMode("review", { keepTool: true });
  }
  activateInspectorTab("checks");
  showMobilePanel("inspector");
}

function drawingEditLocked() {
  return state.locked === true || cloudPermissionReadOnly;
}

function ensureDrawingEditable(action = "edit this drawing") {
  if (!drawingEditLocked()) return true;
  if (cloudPermissionReadOnly) {
    showAppNotice(cloudReadOnlyMessage(action));
  } else {
    showAppNotice(`This drawing is locked as ${projectStatusLabel()}. Unlock edits or create a new revision before you ${action}.`);
  }
  showHealthPanel();
  return false;
}

function updatePropertiesPanel() {
  if (!propertiesPanel) return;

  const fitting = selectedFittingData();
  if (fitting) {
    const distance = pointLength(subtractPoints(fitting.point, fitting.segment.start));
    const fittingActions = fitting.fitting.type === "rollGroove"
      ? [["delete-fitting", "Delete", "danger"]]
      : [
          ["set-fitting-weight", "Set weight"],
          ...(fitting.fitting.type === "flange" ? [["change-flange-standard", "Flange type"]] : []),
          ...(fitting.fitting.type === "socket" ? [["change-socket-size", "Socket size"]] : []),
          ...(fitting.fitting.type === "reducer" ? [["change-reducer-type", "Reducer type"]] : []),
          ...(fitting.weightSource === "manual" ? [["clear-fitting-weight", "Clear manual"]] : []),
          ["delete-fitting", "Delete", "danger"],
        ];
    const fittingProperties = [
      ["Run", fitting.segment.index + 1],
      ["Position", `${formatLength(distance)} mm`],
      ["Size", pipeSizeSpecLabel(pipeSizeForSegment(fitting.segment))],
      ["Mode", fittingModeText(fitting)],
      ["Weight", `${formatMass(fitting.weightKg)} kg ${fitting.weightSource}`],
    ];
    if (fitting.fitting.type === "flange") {
      const flangeSize = pipeSizeForSegment(fitting.segment);
      const drilling = flangeDrillingDimensions(
        fittingFlangeStandard(fitting.fitting),
        flangeSize,
        pipeRadiusMetres(fitting.segment),
      );
      fittingProperties.splice(4, 0,
        ["Plate", `OD ${formatFlangeTableMm(drilling.odMm)} x ${formatFlangeTableMm(drilling.thicknessMm)} mm`],
        ["Drilling", `${drilling.boltCount} x ${formatFlangeTableMm(drilling.holeMm)} mm holes / PCD ${formatFlangeTableMm(drilling.pcdMm)} mm`],
      );
      if (!drilling.exactSize) {
        fittingProperties.splice(6, 0, ["Table row", `NB ${drilling.sourceNb} for NB ${drilling.requestedNb}`]);
      }
    }
    renderProperties(
      `${fittingActionLabel(fitting.fitting.type)} fitting`,
      fittingProperties,
      fittingActions,
    );
    return;
  }

  if (state.selectedNote) {
    const note = state.notes.find((item) => item.id === state.selectedNote);
    if (note) {
      renderProperties(
        "Text note",
        [
          ["Text", note.text],
          ["Colour", noteColourStyle(note.colour).label],
          ["Arrow X", `${formatLength(note.point.x)} mm`],
          ["Arrow Y", `${formatLength(note.point.y)} mm`],
          ["Arrow Z", `${formatLength(note.point.z)} mm`],
        ],
        [
          ["edit-note", "Edit note"],
          ["delete-note", "Delete", "danger"],
        ],
      );
      return;
    }
  }

  if (state.selectedMeasurement) {
    const measurement = (state.measurements ?? []).find((item) => item.id === state.selectedMeasurement);
    if (measurement) {
      renderProperties(
        "Measurement",
        [
          ["Length", `${formatLength(measurementLengthMm(measurement))} mm`],
          ["From", formatPointCompact(measurement.start)],
          ["To", formatPointCompact(measurement.end)],
          ["Label", measurement.label || "Auto length"],
        ],
        [
          ["edit-measurement-label", "Edit label"],
          ["delete-measurement", "Delete", "danger"],
        ],
      );
      return;
    }
  }

  const selected = selectedSegmentIndexes();
  if (selected.length) {
    const selectedSegments = segments().filter((segment) => selected.includes(segment.index));
    const allQuantities = quantitySummary();
    const quantityBySegment = new Map(allQuantities.segments.map((item) => [item.segment.index, item.quantity]));
    const selectedQuantities = selectedSegments.map((segment) => ({
      segment,
      quantity: quantityBySegment.get(segment.index) ?? segmentQuantity(segment),
    }));
    const selectedTotals = selectedQuantities.reduce((totals, item) => ({
      centrelineMm: totals.centrelineMm + item.quantity.centrelineMm,
      cutLengthMm: totals.cutLengthMm + item.quantity.cutLengthMm,
      weldEndCount: totals.weldEndCount + item.quantity.weldEndCount,
      weldGapMm: totals.weldGapMm + item.quantity.weldGapMm,
      pipeWeightKg: totals.pipeWeightKg + item.quantity.pipeWeightKg,
    }), { centrelineMm: 0, cutLengthMm: 0, weldEndCount: 0, weldGapMm: 0, pipeWeightKg: 0 });
    if (selectedSegments.length === 1) {
      const segment = selectedSegments[0];
      const quantity = selectedQuantities[0].quantity;
      const size = pipeSizeForSegment(segment);
      const offsetMeta = segmentOffsetMeta(segment);
      renderProperties(
        `Run ${segment.index + 1}`,
        [
          ["Size", pipeSizeSpecLabel(size)],
          ["C/C", `${formatLength(quantity.centrelineMm)} mm`],
          ...(offsetMeta ? [
            ["Offset set", `${formatLength(offsetMeta.setMm)} mm`],
            ["Travel factor", offsetMeta.multiplier.toFixed(3)],
            ["Offset angle", `${formatAngle(offsetMeta.angleDeg)} deg`],
          ] : []),
          ["Cut", `${formatLength(quantity.cutLengthMm)} mm`],
          ["Fitting deduct", `${formatLength(quantity.bendTakeoffMm)} mm`],
          ["Weld gap", `${formatWeldGapMm(quantity.weldGapMm)} mm (${formatWeldGapMm(quantity.weldGapPerEndMm)} mm x ${quantity.weldEndCount} welded end${quantity.weldEndCount === 1 ? "" : "s"})`],
          ["Weight", `${formatMass(quantity.pipeWeightKg)} kg`],
        ],
        [
          ["edit-run-length", "Edit length"],
          ["delete-run", "Delete", "danger"],
        ],
      );
      return;
    }

    renderProperties(
      `${selectedSegments.length} runs selected`,
      [
        ["Centreline", `${formatLength(selectedTotals.centrelineMm)} mm`],
        ["Cut pipe", `${formatLength(selectedTotals.cutLengthMm)} mm`],
        ["Weld gap", `${formatWeldGapMm(selectedTotals.weldGapMm)} mm (${formatWeldGapMm(projectWeldGapMm())} mm x ${selectedTotals.weldEndCount} welded end${selectedTotals.weldEndCount === 1 ? "" : "s"})`],
        ["Pipe weight", `${formatMass(selectedTotals.pipeWeightKg)} kg`],
        ["Sizes", new Set(selectedSegments.map((segment) => pipeSizeForSegment(segment).nb)).size === 1 ? pipeSizeDisplayLabel(pipeSizeForSegment(selectedSegments[0])) : "Mixed"],
      ],
      [
        ["delete-run", "Delete selected", "danger"],
      ],
    );
    return;
  }

  if (state.selectedPoint !== null && state.points[state.selectedPoint]) {
    const point = state.points[state.selectedPoint];
    const connected = segments().filter((segment) => segment.from === state.selectedPoint || segment.to === state.selectedPoint);
    const connectionType = connected.length >= 3 ? nodeConnectionType(state.selectedPoint) : null;
    renderProperties(
      `Point ${pointLabel(state.selectedPoint)}`,
      [
        ["X", `${formatLength(point.x)} mm`],
        ["Y", `${formatLength(point.y)} mm`],
        ["Z", `${formatLength(point.z)} mm`],
        ["Runs", connected.length],
        ...(connectionType ? [["Connection", connectionType === "branch" ? "Branch weld" : "Buttweld tee"]] : []),
      ],
      connectionType
        ? [[connectionType === "branch" ? "mark-point-tee" : "mark-point-branch", connectionType === "branch" ? "Mark as tee" : "Mark as branch"]]
        : [],
    );
    return;
  }

  const quantities = quantitySummary();
  const liftPoint = centreOfGravityData(quantities);
  const pressureLimit = weakestPressureEstimate(segments());
  renderProperties(
    "Spool summary",
    [
      ["Runs", quantities.segments.length],
      ["Material", pipeSpecShortLabel()],
      ["Total weight", `${formatMass(quantities.totalWeightKg)} kg`],
      ["Weakest pressure", pressureLimit ? `${formatPressureStandard(pressureLimit.pressureBar)} / ${pipeSizeDisplayLabel(pressureLimit.size)}` : "N/A"],
      ["COG", liftPoint ? formatPointCompact(liftPoint.point) : "N/A"],
    ],
    [],
  );
}

function renderProperties(title, rows, actions) {
  propertiesPanel.innerHTML = `
    <div class="property-grid">
      <span>Selection</span><strong>${escapeHtml(title)}</strong>
      ${rows.map(([label, value]) => `<span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong>`).join("")}
    </div>
    ${actions.length ? `<div class="property-actions">${actions.map(([action, label, tone]) => `<button type="button" data-property-action="${action}" class="${tone === "danger" ? "danger" : ""}">${escapeHtml(label)}</button>`).join("")}</div>` : ""}
  `;

  propertiesPanel.querySelectorAll("[data-property-action]").forEach((button) => {
    button.addEventListener("click", () => handlePropertyAction(button.dataset.propertyAction));
  });
}

function handlePropertyAction(action) {
  if (action === "set-fitting-weight") setSelectedFittingWeight();
  if (action === "clear-fitting-weight") clearSelectedFittingWeight();
  if (action === "change-flange-standard") promptSelectedFlangeStandard();
  if (action === "change-socket-size") promptSelectedSocketSize();
  if (action === "change-reducer-type") toggleSelectedReducerType();
  if (action === "delete-fitting") deleteSelectedFitting();
  if (action === "edit-note") editSelectedNote();
  if (action === "delete-note") deleteSelectedNote();
  if (action === "edit-measurement-label") editSelectedMeasurementLabel();
  if (action === "delete-measurement") deleteSelectedMeasurement();
  if (action === "edit-run-length") editSelectedRunLength();
  if (action === "delete-run") deleteSegmentsByIndex(selectedSegmentIndexes());
  if (action === "mark-point-branch") setSelectedPointConnectionType("branch");
  if (action === "mark-point-tee") setSelectedPointConnectionType("tee");
}

async function setSelectedFittingWeight() {
  const data = selectedFittingData();
  if (!data) return;
  if (data.fitting.type === "rollGroove") return;

  const text = await openFieldInputDialog({
    title: "Set fitting weight",
    label: "Fitting weight",
    value: formatMass(data.weightKg),
    unit: "kg",
    type: "number",
    inputMode: "decimal",
    min: "0",
    help: "Use this when you want to override the estimated fitting weight.",
    submitLabel: "Save weight",
  });
  if (text === null) return;

  const weightKg = Number(text);
  if (!Number.isFinite(weightKg) || weightKg < 0) {
    showAppNotice("Enter a valid fitting weight in kg.");
    return;
  }

  const nextWeight = Math.round(weightKg * 10) / 10;
  if (fittingWeightOverride(data.fitting) === nextWeight) return;
  const snapshot = createUndoSnapshot();
  data.fitting.weightKg = nextWeight;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function clearSelectedFittingWeight() {
  const data = selectedFittingData();
  if (!data) return;
  if (fittingWeightOverride(data.fitting) === null) return;
  const snapshot = createUndoSnapshot();
  delete data.fitting.weightKg;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function promptSelectedFlangeStandard() {
  const data = selectedFittingData();
  if (!data || data.fitting.type !== "flange") return;
  openSelectedFlangeStandardMenu(data.fitting.id);
}

function promptSelectedSocketSize() {
  const data = selectedFittingData();
  if (!data || data.fitting.type !== "socket") return;
  openSelectedSocketSizeMenu(data.fitting.id);
}

function toggleSelectedReducerType() {
  const data = selectedFittingData();
  if (!data || data.fitting.type !== "reducer" || !ensureDrawingEditable("change reducer type")) return;
  const snapshot = createUndoSnapshot();
  data.fitting.reducerType = fittingReducerType(data.fitting) === "eccentric" ? "concentric" : "eccentric";
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function deleteSelectedFitting() {
  if (!state.selectedFitting) return;
  const snapshot = createUndoSnapshot();
  state.fittings = state.fittings.filter((fitting) => fitting.id !== state.selectedFitting);
  state.selectedFitting = null;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function editSelectedNote() {
  const note = state.notes.find((item) => item.id === state.selectedNote);
  if (note) editContextNote(note);
}

function deleteSelectedNote() {
  if (!state.selectedNote) return;
  const snapshot = createUndoSnapshot();
  state.notes = state.notes.filter((note) => note.id !== state.selectedNote);
  state.selectedNote = null;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

async function editSelectedMeasurementLabel() {
  const measurement = (state.measurements ?? []).find((item) => item.id === state.selectedMeasurement);
  if (!measurement) return;

  const text = await openFieldInputDialog({
    title: "Edit measurement label",
    label: "Label",
    value: measurement.label || "",
    placeholder: measurementLabel(measurement),
    help: "Leave blank to use the measured length automatically.",
    submitLabel: "Save label",
  });
  if (text === null) return;
  const nextLabel = String(text).trim().slice(0, 64);
  if (nextLabel === measurement.label) return;
  const snapshot = createUndoSnapshot();
  measurement.label = nextLabel;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function deleteSelectedMeasurement() {
  if (!state.selectedMeasurement) return;
  const snapshot = createUndoSnapshot();
  state.measurements = (state.measurements ?? []).filter((measurement) => measurement.id !== state.selectedMeasurement);
  state.selectedMeasurement = null;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function editSelectedRunLength() {
  const segment = selectedSegmentData();
  if (!segment) return;
  editSegmentLengthFromDimensionSource(segment, {
    sourceType: "segment",
    anchorPointIndex:
      state.selectedPoint === segment.to || state.selectedPoint === segment.from
        ? state.selectedPoint
        : segment.from,
  });
}

function setSelectedPointConnectionType(type) {
  if (state.selectedPoint === null || !state.points[state.selectedPoint]) return;
  const connected = segments().filter((segment) => segment.from === state.selectedPoint || segment.to === state.selectedPoint);
  if (connected.length < 3) return;
  if (nodeConnectionType(state.selectedPoint) === type) return;
  const snapshot = createUndoSnapshot();
  setNodeConnectionType(state.selectedPoint, type, { update: false });
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function sideToolIdForButton(button) {
  return button?.dataset?.tool || button?.dataset?.sideTool || "";
}

function sideToolLabel(id) {
  return SIDE_TOOL_DETAILS[id]?.[0] ?? id;
}

function sideToolDetail(id) {
  return SIDE_TOOL_DETAILS[id]?.[1] ?? "Side rail tool";
}

function readSideToolVisibility() {
  let saved = {};
  try {
    saved = JSON.parse(localStorage.getItem(SIDE_TOOL_VISIBILITY_KEY)) ?? {};
  } catch {
    saved = {};
  }

  const visibility = {};
  for (const button of sideToolButtons) {
    const id = sideToolIdForButton(button);
    if (!id) continue;
    visibility[id] = ALWAYS_VISIBLE_SIDE_TOOLS.has(id) ? true : saved[id] !== false;
  }
  return visibility;
}

function writeSideToolVisibility(visibility) {
  const normalized = {};
  for (const button of sideToolButtons) {
    const id = sideToolIdForButton(button);
    if (!id) continue;
    normalized[id] = ALWAYS_VISIBLE_SIDE_TOOLS.has(id) ? true : visibility[id] !== false;
  }
  try {
    localStorage.setItem(SIDE_TOOL_VISIBILITY_KEY, JSON.stringify(normalized));
  } catch (error) {
    console.warn("Could not save side tool settings.", error);
  }
}

function isSideToolVisible(id, visibility = readSideToolVisibility()) {
  return ALWAYS_VISIBLE_SIDE_TOOLS.has(id) || visibility[id] !== false;
}

function sideToolButtonForId(id) {
  return sideToolButtons.find((button) => sideToolIdForButton(button) === id) ?? null;
}

function isSideToolAllowedInMode(id, mode = appMode) {
  const button = sideToolButtonForId(id);
  const modes = button?.dataset.modeTools;
  if (!modes) return true;
  return modes.split(/\s+/).filter(Boolean).includes(normalizeAppMode(mode));
}

function isSideToolAvailable(id, visibility = readSideToolVisibility(), mode = appMode) {
  return isSideToolVisible(id, visibility) && isSideToolAllowedInMode(id, mode);
}

function elementAllowsAppMode(element, dataKey, mode = appMode) {
  const modes = element?.dataset?.[dataKey];
  if (!modes) return true;
  return modes.split(/\s+/).filter(Boolean).includes(normalizeAppMode(mode));
}

function updateAppModeVisibility(mode = appMode) {
  const normalized = normalizeAppMode(mode);
  for (const group of appModeSettingGroups) {
    group.hidden = !elementAllowsAppMode(group, "modeSettings", normalized);
  }
  for (const tab of document.querySelectorAll("[data-inspector-tab]")) {
    tab.hidden = !elementAllowsAppMode(tab, "modeTabs", normalized);
  }
  for (const trigger of document.querySelectorAll("[data-mode-trigger]")) {
    trigger.hidden = !elementAllowsAppMode(trigger, "modeTrigger", normalized);
  }
  if (fittingsToolButton?.closest("[data-mode-trigger]")?.hidden) {
    setFittingsToolMenuOpen(false);
  }
  if (inspectorModeHint) {
    inspectorModeHint.textContent = APP_MODE_INSPECTOR_HINT[normalized] ?? APP_MODE_INSPECTOR_HINT.draw;
  }
  if (workspaceTitle) {
    workspaceTitle.textContent = APP_MODE_WORKSPACE_TITLE[normalized] ?? APP_MODE_WORKSPACE_TITLE.draw;
    if (isQuickPdfMode()) workspaceTitle.textContent = normalized === "export" ? "Quick PDF" : "Quick drawing";
  }
}

function applyWorkflowKindUi() {
  const quick = isQuickPdfMode();
  document.body.dataset.workflowKind = quick ? "quick" : "managed";
  if (quickPdfBar) quickPdfBar.hidden = !quick;

  const reviewButton = appModeButtons.find((button) => button.dataset.appMode === "review");
  const exportButton = appModeButtons.find((button) => button.dataset.appMode === "export");
  if (reviewButton) reviewButton.hidden = quick;
  if (exportButton) exportButton.textContent = quick ? "PDF" : "Export";

  const saveLabel = saveBrowserProjectButton?.querySelector("span");
  if (saveLabel) saveLabel.textContent = quick ? "Save copy" : "Save";
  if (saveBrowserProjectButton) {
    saveBrowserProjectButton.title = quick
      ? "Optionally save this quick drawing for later"
      : "Save project in this browser";
    saveBrowserProjectButton.setAttribute("aria-label", saveBrowserProjectButton.title);
  }
}

function defaultToolForMode(mode = appMode) {
  return APP_MODE_DEFAULT_TOOL[normalizeAppMode(mode)] ?? "draw";
}

function applySideToolVisibility(options = {}) {
  const visibility = readSideToolVisibility();
  for (const button of sideToolButtons) {
    const id = sideToolIdForButton(button);
    if (!id) continue;
    button.hidden = !isSideToolAvailable(id, visibility, appMode);
  }

  if (options.keepActive !== true && state.activeTool && !isSideToolAvailable(state.activeTool, visibility, appMode)) {
    setTool(defaultToolForMode(appMode));
  }
}

function renderToolSettingsOptions() {
  if (!toolSettingsList) return;
  const visibility = readSideToolVisibility();
  toolSettingsList.innerHTML = "";

  for (const button of sideToolButtons) {
    const id = sideToolIdForButton(button);
    if (!id) continue;
    const locked = ALWAYS_VISIBLE_SIDE_TOOLS.has(id);
    const row = document.createElement("label");
    row.className = "tool-setting-row";
    if (locked) row.classList.add("locked");
    row.innerHTML = `
      <input type="checkbox" data-tool-setting-id="${escapeHtml(id)}" ${isSideToolVisible(id, visibility) ? "checked" : ""} ${locked ? "disabled" : ""} />
      <span class="tool-setting-copy">
        <strong>${escapeHtml(sideToolLabel(id))}</strong>
        <small>${escapeHtml(locked ? "Built-in workflow tool" : sideToolDetail(id))}</small>
      </span>
    `;
    toolSettingsList.append(row);
  }
}

function openToolSettingsDialog() {
  captureTemporaryWorkspaceNavigation();
  closePrimaryWorkspaceDialogs("tools");
  renderToolSettingsOptions();
  if (toolSettingsDialog) toolSettingsDialog.hidden = false;
}

function closeToolSettingsDialog() {
  if (toolSettingsDialog) toolSettingsDialog.hidden = true;
  scheduleTemporaryWorkspaceRestore();
}

function resetSideToolVisibility() {
  const visibility = {};
  for (const button of sideToolButtons) {
    const id = sideToolIdForButton(button);
    if (id) visibility[id] = true;
  }
  writeSideToolVisibility(visibility);
  applySideToolVisibility();
  renderToolSettingsOptions();
}

function setupToolSettingsDialog() {
  toolSettingsButton?.addEventListener("click", openToolSettingsDialog);
  toolSettingsDoneButton?.addEventListener("click", closeToolSettingsDialog);
  toolSettingsResetButton?.addEventListener("click", resetSideToolVisibility);
  toolSettingsDialog?.addEventListener("pointerdown", (event) => {
    if (event.target === toolSettingsDialog) {
      closeToolSettingsDialog();
    }
  });
  toolSettingsList?.addEventListener("change", (event) => {
    const input = event.target;
    if (!(input instanceof HTMLInputElement)) return;
    const id = input.dataset.toolSettingId;
    if (!id || ALWAYS_VISIBLE_SIDE_TOOLS.has(id)) return;
    const visibility = readSideToolVisibility();
    visibility[id] = input.checked;
    writeSideToolVisibility(visibility);
    applySideToolVisibility();
  });
  applySideToolVisibility({ keepActive: true });
}

function applyAppMode(mode, options = {}) {
  let normalized = normalizeAppMode(mode);
  if (isQuickPdfMode() && normalized === "review") normalized = "draw";
  appMode = normalized;
  document.body.dataset.appMode = normalized;
  applyWorkflowKindUi();

  for (const button of appModeButtons) {
    const active = button.dataset.appMode === normalized;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  }

  if (options.persist !== false) {
    storeAppMode(normalized);
  }

  updateAppModeVisibility(normalized);
  applySideToolVisibility({ keepActive: true });
  const activeAvailable = state.activeTool && isSideToolAvailable(state.activeTool);
  if (options.keepTool === true && activeAvailable) {
    drawIso();
  } else {
    setTool(defaultToolForMode(normalized));
  }

  if (options.activateTab !== false) {
    activateInspectorTab(APP_MODE_DEFAULT_TAB[normalized] ?? "properties");
  }

  if (normalized === "review" || normalized === "export") {
    showMobilePanel("inspector");
  } else {
    showMobilePanel("drawing");
  }

  closeDrawingContextMenu();
  if (normalized === "review") markFirstUseGuideLearned("review");
}

function setupAppModes() {
  for (const button of appModeButtons) {
    button.addEventListener("click", () => applyAppMode(button.dataset.appMode));
  }
  applyAppMode(appMode, { persist: false, activateTab: false, keepTool: true });
}

function browserFullscreenElement() {
  return document.fullscreenElement || document.webkitFullscreenElement || document.msFullscreenElement || null;
}

async function requestNativeFullscreen(element) {
  const request =
    element?.requestFullscreen ||
    element?.webkitRequestFullscreen ||
    element?.msRequestFullscreen;
  if (!request) return false;
  const result = request.call(element);
  if (result?.then) await result;
  return true;
}

async function exitNativeFullscreen() {
  const exit =
    document.exitFullscreen ||
    document.webkitExitFullscreen ||
    document.msExitFullscreen;
  if (!exit || !browserFullscreenElement()) return false;
  const result = exit.call(document);
  if (result?.then) await result;
  return true;
}

function panelFullscreenActive(panel) {
  return Boolean(panel && (panel.classList.contains("panel-fullscreen") || browserFullscreenElement() === panel));
}

function schedulePanelFullscreenResize() {
  requestAnimationFrame(() => {
    drawIso();
    updatePreviewFloatingState();
    forcePreviewRender();
  });
}

function setFullscreenButtonState(button, active) {
  if (!button) return;
  button.setAttribute("aria-pressed", String(active));
  button.title = active ? "Exit full screen" : "View full screen";
  button.setAttribute("aria-label", button.title);
  const label = button.querySelector("span");
  if (label) label.textContent = active ? "Exit" : "Full";
}

function setFocusModeButtonState() {
  if (!drawingFullscreenButton) return;
  drawingFullscreenButton.setAttribute("aria-pressed", String(focusModeActive));
  drawingFullscreenButton.title = focusModeActive ? "Exit Focus mode" : "Enter Focus mode";
  drawingFullscreenButton.setAttribute("aria-label", drawingFullscreenButton.title);
  const label = drawingFullscreenButton.querySelector("span");
  if (label) label.textContent = focusModeActive ? "Exit" : "Focus";
}

function currentWorkspaceSurface() {
  if (isTabletLayout()) {
    const mobilePanel = document.body.dataset.mobilePanel;
    if (mobilePanel === "preview" && previewPanelHidden) return "drawing";
    return mobilePanel === "inspector" || mobilePanel === "preview" ? mobilePanel : "drawing";
  }
  if (!previewPanelHidden) return "preview";
  if (document.body.classList.contains("inspector-drawer-open")) return "inspector";
  return "drawing";
}

function captureWorkspaceSurfaceState() {
  return {
    surface: currentWorkspaceSurface(),
    previewHidden: previewPanelHidden,
    previewMinimized: previewPanelMinimized,
    previewFloatManual,
    previewFloatBounds: previewFloatBounds ? { ...previewFloatBounds } : null,
  };
}

function restoreWorkspaceSurfaceState(restore) {
  if (!restore) return;
  previewPanelHidden = restore.previewHidden;
  previewPanelMinimized = restore.previewHidden ? false : restore.previewMinimized;
  previewFloatManual = restore.previewFloatManual;
  previewFloatBounds = restore.previewFloatBounds ? { ...restore.previewFloatBounds } : null;

  if (isTabletLayout()) {
    const mobileSurface = restore.surface === "preview" && restore.previewHidden ? "drawing" : restore.surface;
    showMobilePanel(mobileSurface);
    return;
  }

  if (restore.surface === "preview" && !restore.previewHidden) {
    setInspectorDrawerOpen(false);
    previewPanelMinimized = false;
    updatePreviewFloatingState();
  } else if (restore.surface === "inspector") {
    previewPanelHidden = true;
    previewPanelMinimized = false;
    updatePreviewFloatingState();
    setInspectorDrawerOpen(true);
  } else {
    previewPanelHidden = true;
    previewPanelMinimized = false;
    updatePreviewFloatingState();
    setInspectorDrawerOpen(false);
  }
}

function activeInspectorTabName() {
  return document.querySelector('[data-inspector-tab].active:not([hidden])')?.dataset.inspectorTab || "properties";
}

function currentSpoolNavigationIdentity() {
  return {
    projectId: normalizeProjectId(state.projectId),
    spoolUid: normalizeTraceabilityId(state.spoolUid),
  };
}

function captureTemporaryWorkspaceNavigation() {
  if (temporaryWorkspaceNavigationState) return temporaryWorkspaceNavigationState;
  temporaryWorkspaceNavigationState = {
    ...currentSpoolNavigationIdentity(),
    appMode,
    activeTool: state.activeTool,
    gridScale: state.gridScale,
    drawingViewOffset: { ...drawingViewOffset },
    selectedSegments: selectedSegmentIndexes(),
    selectedFitting: state.selectedFitting,
    selectedNote: state.selectedNote,
    selectedMeasurement: state.selectedMeasurement,
    selectedPoint: state.selectedPoint,
    activePoint: state.activePoint,
    inspectorTab: activeInspectorTabName(),
    surfaceState: captureWorkspaceSurfaceState(),
    focusMode: focusModeActive,
  };
  return temporaryWorkspaceNavigationState;
}

function discardTemporaryWorkspaceNavigation() {
  temporaryWorkspaceNavigationState = null;
}

function primaryWorkspaceDialogOpen() {
  return [
    homeDashboardDialog,
    projectLibraryDialog,
    tutorialDialog,
    videoTutorialDialog,
    authDialog,
    helpDialog,
    toolSettingsDialog,
  ].some((dialog) => dialog && !dialog.hidden);
}

function restoreTemporaryWorkspaceNavigation() {
  const restore = temporaryWorkspaceNavigationState;
  if (!restore || primaryWorkspaceDialogOpen()) return false;
  temporaryWorkspaceNavigationState = null;
  const identity = currentSpoolNavigationIdentity();
  if (restore.projectId !== identity.projectId || restore.spoolUid !== identity.spoolUid) {
    renderWorkspaceLocationStrips();
    return false;
  }

  state.gridScale = clampNumber(Number(restore.gridScale) || state.gridScale, 10, 72);
  drawingViewOffset = {
    x: Number(restore.drawingViewOffset?.x) || 0,
    y: Number(restore.drawingViewOffset?.y) || 0,
  };
  setSelectedSegments(restore.selectedSegments);
  state.selectedFitting = Number.isInteger(restore.selectedFitting) &&
    state.fittings.some((fitting) => fitting.id === restore.selectedFitting)
    ? restore.selectedFitting
    : null;
  state.selectedNote = Number.isInteger(restore.selectedNote) &&
    state.notes.some((note) => note.id === restore.selectedNote)
    ? restore.selectedNote
    : null;
  state.selectedMeasurement = Number.isInteger(restore.selectedMeasurement) &&
    normalizeMeasurements(state.measurements).some((measurement) => measurement.id === restore.selectedMeasurement)
    ? restore.selectedMeasurement
    : null;
  state.selectedPoint = Number.isInteger(restore.selectedPoint) && state.points[restore.selectedPoint]
    ? restore.selectedPoint
    : null;
  state.activePoint = Number.isInteger(restore.activePoint) && state.points[restore.activePoint]
    ? restore.activePoint
    : Math.max(0, state.points.length - 1);

  applyAppMode(restore.appMode, { persist: false, activateTab: false, keepTool: true });
  setTool(restore.activeTool);
  activateInspectorTab(restore.inspectorTab);
  updateAll({ save: false });
  restoreWorkspaceSurfaceState(restore.surfaceState);
  if (restore.focusMode && !focusModeActive) setFocusMode(true);
  renderWorkspaceLocationStrips();
  return true;
}

function normalizeMobileWorkspaceSurface() {
  if (isTabletLayout() && previewPanelHidden && document.body.dataset.mobilePanel === "preview") {
    showMobilePanel("drawing");
  }
}

function scheduleTemporaryWorkspaceRestore() {
  queueMicrotask(() => {
    restoreTemporaryWorkspaceNavigation();
    window.requestAnimationFrame(normalizeMobileWorkspaceSurface);
    window.setTimeout(normalizeMobileWorkspaceSurface, 250);
  });
}

function createSpoolWorkspaceTabId() {
  return `spool-tab-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function cloneSpoolWorkspaceValue(value) {
  if (typeof structuredClone === "function") {
    try {
      return structuredClone(value);
    } catch {
      // JSON fallback keeps the workspace available in older WebViews.
    }
  }
  return JSON.parse(JSON.stringify(value));
}

function spoolWorkspaceStateSnapshot(source = state) {
  const snapshot = cloneSpoolWorkspaceValue(source);
  snapshot.pointer = null;
  snapshot.previewCandidate = null;
  snapshot.hoveredSegment = null;
  snapshot.history = Array.isArray(snapshot.history) ? snapshot.history.slice(-40) : [];
  snapshot.redoHistory = Array.isArray(snapshot.redoHistory) ? snapshot.redoHistory.slice(-40) : [];
  return snapshot;
}

function spoolWorkspaceSourceForCurrentState() {
  if (currentProjectHasCloudRecord()) return "cloud";
  return state.projectId ? "browser" : "draft";
}

function spoolWorkspaceLabelFromState(source = state) {
  const info = normalizeProjectInfo(source?.projectInfo, source?.pipeSpec);
  const job = info.jobNumber || "No job";
  const spool = info.spoolNumber || "Untitled";
  return `${job} · ${spool}`;
}

function spoolWorkspaceTabDetail(tab) {
  const source = tab?.state ?? state;
  const info = normalizeProjectInfo(source?.projectInfo, source?.pipeSpec);
  const revision = info.revision || "A";
  const status = projectStatusLabel(source?.projectStatus);
  return `Rev ${revision} · ${status}`;
}

function spoolWorkspaceTabCompactLabel(tab) {
  const source = tab?.state ?? state;
  const info = normalizeProjectInfo(source?.projectInfo, source?.pipeSpec);
  return info.spoolNumber || "Untitled spool";
}

function captureSpoolWorkspaceUiState() {
  return {
    appMode,
    activeTool: state.activeTool,
    drawingViewOffset: { ...drawingViewOffset },
    inspectorTab: activeInspectorTabName(),
    surfaceState: captureWorkspaceSurfaceState(),
    focusMode: focusModeActive,
  };
}

function captureSpoolWorkspaceCloudState() {
  return {
    ownerId: normalizeUuid(currentCloudProjectOwnerId),
    companyId: normalizeUuid(currentCloudProjectCompanyId),
    readOnly: cloudPermissionReadOnly === true,
    dirty: cloudSaveDirty === true,
    conflict: cloudSaveConflict === true,
    error: String(cloudSaveError ?? ""),
    lastSavedAt: String(cloudLastSavedAt ?? ""),
    remoteUpdatedAt: String(cloudLastRemoteUpdatedAt ?? ""),
    trackedProjectId: normalizeProjectId(cloudSaveTrackedProjectId),
  };
}

function activeSpoolWorkspaceTab() {
  return spoolWorkspaceTabs.find((tab) => tab.id === activeSpoolWorkspaceTabId) ?? null;
}

function captureCurrentSpoolWorkspaceTab(options = {}) {
  if (spoolWorkspaceSwitching) return null;
  const tab = activeSpoolWorkspaceTab();
  if (!tab) return null;
  tab.state = spoolWorkspaceStateSnapshot();
  tab.projectId = normalizeProjectId(state.projectId);
  tab.spoolUid = normalizeTraceabilityId(state.spoolUid);
  tab.source = spoolWorkspaceSourceForCurrentState();
  tab.label = spoolWorkspaceLabelFromState();
  tab.ui = captureSpoolWorkspaceUiState();
  tab.cloud = captureSpoolWorkspaceCloudState();
  tab.updatedAt = new Date().toISOString();
  if (options.persist !== false) scheduleSpoolWorkspaceSessionPersist();
  renderSpoolWorkspaceTabs();
  if (spoolWorkspaceWindowed) renderSpoolWindowGrid();
  return tab;
}

function spoolWorkspaceSessionPayload() {
  return {
    version: 1,
    activeId: activeSpoolWorkspaceTabId,
    windowed: spoolWorkspaceWindowed,
    tabs: spoolWorkspaceTabs.slice(0, 8).map((tab) => ({
      id: tab.id,
      projectId: tab.projectId,
      spoolUid: tab.spoolUid,
      source: tab.source,
      label: tab.label,
      updatedAt: tab.updatedAt,
      state: tab.state,
      ui: tab.ui,
      cloud: tab.cloud,
    })),
  };
}

function persistSpoolWorkspaceSession() {
  window.clearTimeout(spoolWorkspaceSessionPersistTimer);
  spoolWorkspaceSessionPersistTimer = null;
  try {
    sessionStorage.setItem(SPOOL_WORKSPACE_SESSION_KEY, JSON.stringify(spoolWorkspaceSessionPayload()));
  } catch (error) {
    console.warn("Open spool tabs could not be stored for this session.", error);
  }
}

function scheduleSpoolWorkspaceSessionPersist() {
  window.clearTimeout(spoolWorkspaceSessionPersistTimer);
  spoolWorkspaceSessionPersistTimer = window.setTimeout(persistSpoolWorkspaceSession, 180);
}

function readSpoolWorkspaceSession() {
  try {
    const saved = JSON.parse(sessionStorage.getItem(SPOOL_WORKSPACE_SESSION_KEY));
    if (!saved || !Array.isArray(saved.tabs)) return null;
    const candidates = saved.tabs.slice(0, 8).map((tab) => {
      const restored = stateFromPayload(tab?.state);
      if (!tab?.id || !restored) return null;
      return {
        id: String(tab.id),
        projectId: normalizeProjectId(tab.projectId ?? restored.projectId),
        spoolUid: normalizeTraceabilityId(tab.spoolUid ?? restored.spoolUid),
        source: ["cloud", "browser", "draft"].includes(tab.source) ? tab.source : "browser",
        label: String(tab.label ?? spoolWorkspaceLabelFromState(restored)),
        updatedAt: String(tab.updatedAt ?? ""),
        state: spoolWorkspaceStateSnapshot(tab.state),
        ui: tab.ui && typeof tab.ui === "object" ? tab.ui : {},
        cloud: tab.cloud && typeof tab.cloud === "object" ? tab.cloud : {},
      };
    }).filter(Boolean);
    const tabs = [];
    candidates.forEach((candidate) => {
      const identity = candidate.projectId
        ? `${candidate.source}:${candidate.projectId}`
        : candidate.spoolUid
          ? `draft:${candidate.spoolUid}`
          : "";
      const duplicateIndex = identity
        ? tabs.findIndex((tab) => (tab.projectId ? `${tab.source}:${tab.projectId}` : tab.spoolUid ? `draft:${tab.spoolUid}` : "") === identity)
        : -1;
      if (duplicateIndex < 0) tabs.push(candidate);
      else if (candidate.id === saved.activeId) tabs[duplicateIndex] = candidate;
    });
    if (!tabs.length) return null;
    return {
      tabs,
      activeId: tabs.some((tab) => tab.id === saved.activeId) ? saved.activeId : tabs[0].id,
      windowed: saved.windowed === true,
    };
  } catch {
    return null;
  }
}

function addCurrentStateAsSpoolWorkspaceTab(options = {}) {
  const tab = {
    id: options.id || createSpoolWorkspaceTabId(),
    projectId: normalizeProjectId(state.projectId),
    spoolUid: normalizeTraceabilityId(state.spoolUid),
    source: options.source || spoolWorkspaceSourceForCurrentState(),
    label: spoolWorkspaceLabelFromState(),
    updatedAt: new Date().toISOString(),
    state: spoolWorkspaceStateSnapshot(),
    ui: captureSpoolWorkspaceUiState(),
    cloud: captureSpoolWorkspaceCloudState(),
  };
  spoolWorkspaceTabs.push(tab);
  activeSpoolWorkspaceTabId = tab.id;
  scheduleSpoolWorkspaceSessionPersist();
  renderSpoolWorkspaceTabs();
  return tab;
}

function restoreSpoolWorkspaceDrawingState(snapshot) {
  const restored = stateFromPayload(snapshot);
  if (!restored) return null;
  restored.activeTool = DRAW_STOP_TOOLS.has(snapshot.activeTool) || ["select", "note", "measure", "box-select"].includes(snapshot.activeTool)
    ? snapshot.activeTool
    : "select";
  restored.selectedFitting = Number.isInteger(snapshot.selectedFitting) ? snapshot.selectedFitting : null;
  restored.selectedNote = Number.isInteger(snapshot.selectedNote) ? snapshot.selectedNote : null;
  restored.selectedSegment = Number.isInteger(snapshot.selectedSegment) ? snapshot.selectedSegment : null;
  restored.hoveredSegment = null;
  restored.pointer = null;
  restored.previewCandidate = null;
  restored.history = Array.isArray(snapshot.history) ? cloneSpoolWorkspaceValue(snapshot.history).slice(-40) : [];
  restored.redoHistory = Array.isArray(snapshot.redoHistory) ? cloneSpoolWorkspaceValue(snapshot.redoHistory).slice(-40) : [];
  return restored;
}

function restoreSpoolWorkspaceCloudState(tab) {
  const cloud = tab.cloud ?? {};
  currentCloudProjectOwnerId = normalizeUuid(cloud.ownerId);
  currentCloudProjectCompanyId = normalizeUuid(cloud.companyId);
  cloudPermissionReadOnly = cloud.readOnly === true;
  cloudSaveDirty = cloud.dirty === true;
  cloudSaveConflict = cloud.conflict === true;
  cloudSaveError = String(cloud.error ?? "");
  cloudLastSavedAt = String(cloud.lastSavedAt ?? "");
  cloudLastRemoteUpdatedAt = String(cloud.remoteUpdatedAt ?? "");
  cloudSaveTrackedProjectId = normalizeProjectId(cloud.trackedProjectId ?? state.projectId);
}

async function flushActiveSpoolWorkspaceTab() {
  const tab = captureCurrentSpoolWorkspaceTab({ persist: false });
  if (!tab) return true;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(statePayload()));
    autoSaveCurrentBrowserProject();
  } catch (error) {
    console.warn("The active spool could not be copied to browser recovery before switching tabs.", error);
  }
  window.clearTimeout(cloudAutosaveTimer);
  if (cloudSaveDirty && currentProjectHasCloudRecord() && !cloudPermissionReadOnly) {
    let attempts = 0;
    while (cloudAutosaveBusy && attempts < 30) {
      await new Promise((resolve) => window.setTimeout(resolve, 100));
      attempts += 1;
    }
    if (!cloudAutosaveBusy) {
      try {
        await saveCloudProject({ silent: true, autosave: true });
      } catch (error) {
        console.warn("Cloud save was queued while changing spool tabs.", error);
      }
    } else {
      queueCurrentCloudSave("tab-switch");
    }
  }
  captureCurrentSpoolWorkspaceTab({ persist: false });
  persistSpoolWorkspaceSession();
  return true;
}

async function restoreSpoolWorkspaceTab(tab) {
  const restored = restoreSpoolWorkspaceDrawingState(tab.state);
  if (!restored) return false;
  spoolWorkspaceSwitching = true;
  try {
    closeDrawingContextMenu();
    setFocusMode(false);
    state = restored;
    restoreSpoolWorkspaceCloudState(tab);
    if (cloudUser) {
      if (tab.cloud?.companyId) await activateCompanyFromId(tab.cloud.companyId);
      else if (activeWorkspaceIsBusiness()) activatePersonalWorkspace();
    }
    projectComments = [];
    projectCommentsProjectId = null;
    three.userMovedCamera = false;
    setNextIdsFromState(state);
    drawingViewOffset = {
      x: Number(tab.ui?.drawingViewOffset?.x) || 0,
      y: Number(tab.ui?.drawingViewOffset?.y) || 0,
    };
    applyAppMode(tab.ui?.appMode || "draw", { persist: false, activateTab: false, keepTool: true });
    updateControls();
    withCloudDirtySuppressed(() => updateAll({ save: false }));
    activateInspectorTab(tab.ui?.inspectorTab || "properties");
    restoreWorkspaceSurfaceState(tab.ui?.surfaceState);
    if (tab.ui?.focusMode) setFocusMode(true);
    updateCloudStatus();
    if (currentProjectHasCloudRecord()) {
      loadProjectComments({ silent: true }).catch((error) => console.warn("Spool comments could not be refreshed after changing tabs.", error));
    }
    return true;
  } finally {
    spoolWorkspaceSwitching = false;
  }
}

async function activateSpoolWorkspaceTab(tabId, options = {}) {
  const target = spoolWorkspaceTabs.find((tab) => tab.id === tabId);
  if (!target || spoolWorkspaceSwitching) return false;
  if (target.id === activeSpoolWorkspaceTabId) {
    if (options.exitWindows !== false) setSpoolWorkspaceWindowed(false);
    return true;
  }
  const previousId = activeSpoolWorkspaceTabId;
  await flushActiveSpoolWorkspaceTab();
  activeSpoolWorkspaceTabId = target.id;
  const restored = await restoreSpoolWorkspaceTab(target);
  if (!restored) {
    activeSpoolWorkspaceTabId = previousId;
    showAppNotice("That open spool tab could not be restored.", { tone: "warning" });
    return false;
  }
  if (options.exitWindows !== false) setSpoolWorkspaceWindowed(false);
  scheduleSpoolWorkspaceSessionPersist();
  renderSpoolWorkspaceTabs();
  return true;
}

async function openProjectInWorkspaceTab(projectId, source = projectLibrarySource) {
  const normalizedId = normalizeProjectId(projectId);
  if (!normalizedId) return false;
  const existing = spoolWorkspaceTabs.find((tab) => tab.projectId === normalizedId && tab.source === source);
  if (existing) {
    closeProjectLibrary();
    return activateSpoolWorkspaceTab(existing.id);
  }
  if (spoolWorkspaceTabs.length >= 8) {
    showAppNotice("Close one open spool tab before opening another. The workspace supports up to 8 tabs.", { tone: "warning" });
    return false;
  }
  const previousId = activeSpoolWorkspaceTabId;
  await flushActiveSpoolWorkspaceTab();
  spoolWorkspaceSwitching = true;
  try {
    if (source === "cloud") await openSavedCloudProject(normalizedId, { skipConfirm: true });
    else await openSavedBrowserProject(normalizedId, { skipConfirm: true });
  } finally {
    spoolWorkspaceSwitching = false;
  }
  if (normalizeProjectId(state.projectId) !== normalizedId) {
    await activateSpoolWorkspaceTab(previousId);
    return false;
  }
  addCurrentStateAsSpoolWorkspaceTab({ source });
  closeProjectLibrary();
  setSpoolWorkspaceWindowed(false);
  showAppNotice(`Opened ${projectDisplayName()} in a new spool tab.`, { tone: "success" });
  return true;
}

async function createNewSpoolWorkspaceTab() {
  if (spoolWorkspaceTabs.length >= 8) {
    showAppNotice("Close one open spool tab before starting another.", { tone: "warning" });
    return false;
  }
  const previousId = activeSpoolWorkspaceTabId;
  const defaults = nextProjectInfoForNewSpool(state.projectInfo);
  await flushActiveSpoolWorkspaceTab();
  persistUserDrawingDefaults();
  spoolWorkspaceSwitching = true;
  try {
    state = blankState();
    currentCloudProjectOwnerId = null;
    currentCloudProjectCompanyId = null;
    cloudPermissionReadOnly = false;
    resetCloudSaveTracking();
    projectComments = [];
    projectCommentsProjectId = null;
    nextFittingId = 1;
    nextNoteId = 1;
    nextMeasurementId = 1;
    drawingViewOffset = { x: 0, y: 0 };
    three.userMovedCamera = false;
    applyAppMode("draw", { persist: false, activateTab: false, keepTool: false });
    setTool("draw");
    setPreviewHidden(true);
    showMobilePanel("drawing");
    updateControls();
    updateAll({ save: false });
  } finally {
    spoolWorkspaceSwitching = false;
  }
  const newTab = addCurrentStateAsSpoolWorkspaceTab({ source: "draft" });
  setSpoolWorkspaceWindowed(false);
  const confirmed = await promptForProjectDetails({ force: true, defaults });
  if (!confirmed) {
    const newTabIndex = spoolWorkspaceTabs.findIndex((tab) => tab.id === newTab.id);
    if (newTabIndex >= 0) spoolWorkspaceTabs.splice(newTabIndex, 1);
    activeSpoolWorkspaceTabId = previousId;
    const previous = spoolWorkspaceTabs.find((tab) => tab.id === previousId) ?? spoolWorkspaceTabs[0];
    if (previous) await restoreSpoolWorkspaceTab(previous);
    persistSpoolWorkspaceSession();
    renderSpoolWorkspaceTabs();
    return false;
  }
  applyAppMode("draw");
  setTool("draw");
  setPreviewHidden(true);
  showMobilePanel("drawing");
  activateFirstUseGuide({ force: true, reset: true, compact: true, stepId: "draw" });
  captureCurrentSpoolWorkspaceTab();
  return true;
}

async function closeSpoolWorkspaceTab(tabId) {
  const tabIndex = spoolWorkspaceTabs.findIndex((tab) => tab.id === tabId);
  if (tabIndex < 0 || spoolWorkspaceTabs.length <= 1) return false;
  const tab = spoolWorkspaceTabs[tabIndex];
  const unsavedDraft = !tab.projectId && (tab.state?.edges?.length || tab.state?.fittings?.length || tab.state?.notes?.length);
  if (unsavedDraft) {
    const proceed = await confirmAppAction(`Close ${tab.label || "this spool"}? It has not been saved as a project.`, {
      title: "Close unsaved spool tab",
      confirmLabel: "Close tab",
      tone: "warning",
    });
    if (!proceed) return false;
  }
  if (tab.id === activeSpoolWorkspaceTabId) {
    await flushActiveSpoolWorkspaceTab();
    const next = spoolWorkspaceTabs[tabIndex - 1] ?? spoolWorkspaceTabs[tabIndex + 1];
    spoolWorkspaceTabs.splice(tabIndex, 1);
    activeSpoolWorkspaceTabId = next.id;
    await restoreSpoolWorkspaceTab(next);
  } else {
    spoolWorkspaceTabs.splice(tabIndex, 1);
  }
  persistSpoolWorkspaceSession();
  renderSpoolWorkspaceTabs();
  if (spoolWorkspaceWindowed) renderSpoolWindowGrid();
  return true;
}

function renderSpoolWorkspaceTabs() {
  if (!spoolWorkspaceTabsElement) return;
  const singleSpool = spoolWorkspaceTabs.length <= 1;
  spoolWorkspaceShell?.classList.toggle("single-spool", singleSpool);
  document.body.classList.toggle("single-spool-workspace", singleSpool);
  spoolWorkspaceTabsElement.innerHTML = spoolWorkspaceTabs.map((tab) => {
    const active = tab.id === activeSpoolWorkspaceTabId;
    const dirty = tab.cloud?.dirty === true || (!tab.projectId && (tab.state?.edges?.length ?? 0) > 0);
    return `
      <div class="spool-workspace-tab-wrap ${active ? "active" : ""}">
        <button type="button" class="spool-workspace-tab" role="tab" aria-selected="${active ? "true" : "false"}" data-spool-workspace-tab="${escapeHtml(tab.id)}" title="${escapeHtml(tab.label)}">
          <span class="spool-workspace-tab-state ${dirty ? "dirty" : "saved"}" aria-hidden="true"></span>
          <span class="spool-workspace-tab-copy">
            <strong>
              <span class="spool-workspace-tab-label-full">${escapeHtml(tab.label || "Untitled spool")}</span>
              <span class="spool-workspace-tab-label-compact">${escapeHtml(spoolWorkspaceTabCompactLabel(tab))}</span>
            </strong>
            <small>${escapeHtml(spoolWorkspaceTabDetail(tab))}</small>
          </span>
        </button>
        <button type="button" class="spool-workspace-tab-close" data-close-spool-workspace-tab="${escapeHtml(tab.id)}" aria-label="Close ${escapeHtml(tab.label || "spool")} tab" ${spoolWorkspaceTabs.length <= 1 ? "disabled" : ""}>×</button>
      </div>
    `;
  }).join("");
  if (spoolWorkspaceWindowButton) {
    spoolWorkspaceWindowButton.disabled = spoolWorkspaceTabs.length < 2;
    spoolWorkspaceWindowButton.setAttribute("aria-pressed", String(spoolWorkspaceWindowed));
    spoolWorkspaceWindowButton.textContent = spoolWorkspaceWindowed ? "Active spool" : `Windows${spoolWorkspaceTabs.length > 1 ? ` (${spoolWorkspaceTabs.length})` : ""}`;
  }
}

function drawSpoolWorkspacePreview(canvas, source, colourIndex = 0) {
  if (!(canvas instanceof HTMLCanvasElement)) return;
  const rect = canvas.getBoundingClientRect();
  const ratio = Math.min(2, window.devicePixelRatio || 1);
  const width = Math.max(240, Math.round(rect.width || 420));
  const height = Math.max(150, Math.round(rect.height || 220));
  canvas.width = Math.round(width * ratio);
  canvas.height = Math.round(height * ratio);
  const ctx = canvas.getContext("2d");
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  ctx.clearRect(0, 0, width, height);
  const dark = document.documentElement.dataset.theme === "dark";
  ctx.fillStyle = dark ? "#111b20" : "#fffdf8";
  ctx.fillRect(0, 0, width, height);
  const points = Array.isArray(source?.points) && source.points.length ? source.points : [{ x: 0, y: 0, z: 0 }];
  const projected = points.map((point) => ({
    x: (Number(point.x) - Number(point.y)) * 0.866,
    y: (Number(point.x) + Number(point.y)) * 0.5 - Number(point.z),
  }));
  const minX = Math.min(...projected.map((point) => point.x));
  const maxX = Math.max(...projected.map((point) => point.x));
  const minY = Math.min(...projected.map((point) => point.y));
  const maxY = Math.max(...projected.map((point) => point.y));
  const scale = Math.min((width - 54) / Math.max(1, maxX - minX), (height - 48) / Math.max(1, maxY - minY));
  const toScreen = (index) => ({
    x: 27 + (projected[index].x - minX) * scale,
    y: 24 + (projected[index].y - minY) * scale,
  });
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  const colours = ["#087f9f", "#7c3aed", "#d97706", "#0f766e", "#be123c", "#2563eb"];
  (Array.isArray(source?.edges) ? source.edges : []).forEach((edge, index) => {
    if (!projected[edge.from] || !projected[edge.to]) return;
    const start = toScreen(edge.from);
    const end = toScreen(edge.to);
    ctx.strokeStyle = colours[(colourIndex + index) % colours.length];
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(start.x, start.y);
    ctx.lineTo(end.x, end.y);
    ctx.stroke();
  });
  ctx.fillStyle = dark ? "#dce7e8" : "#1f2a2f";
  projected.forEach((_, index) => {
    const point = toScreen(index);
    ctx.beginPath();
    ctx.arc(point.x, point.y, 3.5, 0, Math.PI * 2);
    ctx.fill();
  });
  if (!(source?.edges?.length)) {
    ctx.fillStyle = dark ? "#8ca1a8" : "#68777d";
    ctx.font = "700 13px Inter, system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("New spool — no runs yet", width / 2, height / 2);
  }
}

function renderSpoolWindowGrid() {
  if (!spoolWindowGrid) return;
  spoolWindowGrid.innerHTML = spoolWorkspaceTabs.map((tab, index) => {
    const active = tab.id === activeSpoolWorkspaceTabId;
    const source = tab.state ?? state;
    const runs = Array.isArray(source.edges) ? source.edges.length : 0;
    return `
      <article class="spool-window-card ${active ? "active" : ""}" data-spool-window-card="${escapeHtml(tab.id)}">
        <div class="spool-window-card-head">
          <div>
            <span>${active ? "Active editor" : "Open spool"}</span>
            <strong>${escapeHtml(tab.label || "Untitled spool")}</strong>
            <small>${escapeHtml(spoolWorkspaceTabDetail(tab))} · ${runs} run${runs === 1 ? "" : "s"}</small>
          </div>
          <button type="button" data-edit-spool-window="${escapeHtml(tab.id)}">Edit</button>
        </div>
        <canvas aria-label="Preview of ${escapeHtml(tab.label || "open spool")}" data-spool-window-canvas="${escapeHtml(tab.id)}"></canvas>
      </article>
    `;
  }).join("");
  spoolWorkspaceTabs.forEach((tab, index) => {
    const canvas = spoolWindowGrid.querySelector(`[data-spool-window-canvas="${CSS.escape(tab.id)}"]`);
    drawSpoolWorkspacePreview(canvas, tab.state, index);
  });
}

function setSpoolWorkspaceWindowed(active) {
  spoolWorkspaceWindowed = active === true && spoolWorkspaceTabs.length > 1;
  document.body.classList.toggle("spool-windowed-mode", spoolWorkspaceWindowed);
  if (spoolWindowGridShell) spoolWindowGridShell.hidden = !spoolWorkspaceWindowed;
  if (spoolWorkspaceWindowed) {
    captureCurrentSpoolWorkspaceTab({ persist: false });
    renderSpoolWindowGrid();
  }
  renderSpoolWorkspaceTabs();
  scheduleSpoolWorkspaceSessionPersist();
}

async function initializeSpoolWorkspaceTabs() {
  const saved = readSpoolWorkspaceSession();
  if (saved) {
    spoolWorkspaceTabs = saved.tabs;
    activeSpoolWorkspaceTabId = saved.activeId;
    const active = activeSpoolWorkspaceTab();
    if (active) await restoreSpoolWorkspaceTab(active);
  } else {
    addCurrentStateAsSpoolWorkspaceTab();
  }
  spoolWorkspaceWindowed = saved?.windowed === true && spoolWorkspaceTabs.length > 1;
  renderSpoolWorkspaceTabs();
  setSpoolWorkspaceWindowed(spoolWorkspaceWindowed);
}

function setupSpoolWorkspaceTabs() {
  initializeSpoolWorkspaceTabs().catch((error) => console.warn("The open spool workspace could not be restored.", error));
  spoolWorkspaceTabsElement?.addEventListener("click", (event) => {
    const closeButton = event.target instanceof Element ? event.target.closest("[data-close-spool-workspace-tab]") : null;
    if (closeButton) {
      closeSpoolWorkspaceTab(closeButton.dataset.closeSpoolWorkspaceTab).catch((error) => console.warn("Spool tab could not be closed.", error));
      return;
    }
    const tabButton = event.target instanceof Element ? event.target.closest("[data-spool-workspace-tab]") : null;
    if (tabButton) {
      activateSpoolWorkspaceTab(tabButton.dataset.spoolWorkspaceTab).catch((error) => console.warn("Spool tab could not be opened.", error));
    }
  });
  spoolWorkspaceOpenButton?.addEventListener("click", () => {
    setSpoolWorkspaceWindowed(false);
    openBrowserProject();
  });
  spoolWorkspaceNewButton?.addEventListener("click", () => {
    createNewSpoolWorkspaceTab().catch((error) => console.warn("A new spool tab could not be started.", error));
  });
  spoolWorkspaceWindowButton?.addEventListener("click", () => setSpoolWorkspaceWindowed(!spoolWorkspaceWindowed));
  spoolWindowGridCloseButton?.addEventListener("click", () => setSpoolWorkspaceWindowed(false));
  spoolWindowGrid?.addEventListener("click", (event) => {
    const button = event.target instanceof Element ? event.target.closest("[data-edit-spool-window]") : null;
    if (!button) return;
    activateSpoolWorkspaceTab(button.dataset.editSpoolWindow).catch((error) => console.warn("Spool window could not be activated.", error));
  });
  window.addEventListener("pagehide", () => {
    captureCurrentSpoolWorkspaceTab({ persist: false });
    persistSpoolWorkspaceSession();
  });
}

function workspaceLocationValues() {
  const project = normalizeProjectInfo(state.projectInfo);
  return {
    workspace: cloudUser ? activeWorkspaceLabel() : "This device",
    job: project.jobNumber || "No job",
    spool: project.spoolNumber || "Untitled",
    revision: project.revision || "-",
    status: projectStatusLabel(state.projectStatus),
  };
}

function updateWorkspaceDocumentTitle() {
  const project = normalizeProjectInfo(state.projectInfo);
  const identity = [project.jobNumber, project.spoolNumber].filter(Boolean).join(" / ");
  document.title = identity ? `${identity} - SpoolMate` : "SpoolMate";
}

function renderWorkspaceLocationStrips() {
  const values = workspaceLocationValues();
  updateWorkspaceDocumentTitle();
  for (const strip of document.querySelectorAll("[data-workspace-location]")) {
    strip.classList.toggle("compact", strip.classList.contains("workspace-location-main"));
    const configuredContext = strip.dataset.locationContext || "Drawing";
    const surface = currentWorkspaceSurface();
    const context = configuredContext === "Drawing"
      ? surface === "preview"
        ? "3D"
        : surface === "inspector"
        ? "Details"
        : APP_MODE_WORKSPACE_TITLE[normalizeAppMode(appMode)] || "Drawing"
      : configuredContext;
    strip.replaceChildren();

    const contextBadge = document.createElement("span");
    contextBadge.className = "workspace-location-context";
    contextBadge.textContent = context;
    strip.append(contextBadge);

    for (const [key, label] of [
      ["workspace", "Workspace"],
      ["job", "Job"],
      ["spool", "Spool"],
      ["revision", "Revision"],
      ["status", "Status"],
    ]) {
      const crumb = document.createElement("span");
      crumb.className = `workspace-location-crumb ${key}`;
      const caption = document.createElement("small");
      caption.textContent = label;
      const value = document.createElement("b");
      value.textContent = values[key];
      value.title = values[key];
      crumb.append(caption, value);
      strip.append(crumb);
    }

    if (configuredContext !== "Drawing") {
      const back = document.createElement("button");
      back.type = "button";
      back.className = "workspace-location-return";
      back.dataset.workspaceReturn = "drawing";
      back.textContent = "Back to drawing";
      strip.append(back);
    }
  }
}

document.addEventListener("click", (event) => {
  const back = event.target instanceof Element ? event.target.closest("[data-workspace-return]") : null;
  if (!back) return;
  event.preventDefault();
  if (authDialog && !authDialog.hidden) {
    startupProjectPromptPending = false;
    closeAuthDialog();
  }
  else closePrimaryWorkspaceDialogs();
  scheduleTemporaryWorkspaceRestore();
});

function setFocusMode(active) {
  const next = active === true;
  if (next === focusModeActive) return;
  if (next) {
    focusModeRestoreState = captureWorkspaceSurfaceState();
  }
  focusModeActive = next;
  document.body.classList.toggle("focus-mode", focusModeActive);
  if (focusModeActive) {
    setInspectorDrawerOpen(false);
    setPreviewHidden(true);
    setFittingsToolMenuOpen(false);
    closeActionMenu();
    closeDrawingContextMenu();
    if (isTabletLayout()) showMobilePanel("drawing");
  } else if (focusModeRestoreState) {
    const restore = focusModeRestoreState;
    focusModeRestoreState = null;
    restoreWorkspaceSurfaceState(restore);
  }
  setFocusModeButtonState();
  syncDrawingContextMenuHost();
  requestAnimationFrame(() => {
    drawIso();
    resizeThree();
  });
}

function toggleFocusMode() {
  setFocusMode(!focusModeActive);
}

function updatePanelFullscreenState() {
  const native = browserFullscreenElement();
  for (const panel of [drawingPanel, previewPanel]) {
    if (!panel) continue;
    const active = panel === appFullscreenPanel || panel === native;
    panel.classList.toggle("panel-fullscreen", active);
  }
  const drawingFullscreen = panelFullscreenActive(drawingPanel);
  const previewFullscreen = panelFullscreenActive(previewPanel);
  document.body.classList.toggle("has-panel-fullscreen", Boolean(appFullscreenPanel || native));
  document.body.classList.toggle("drawing-panel-fullscreen", drawingFullscreen);
  document.body.classList.toggle("preview-panel-fullscreen", previewFullscreen);
  updatePreviewFloatingState();
  setFocusModeButtonState();
  setFullscreenButtonState(previewFullscreenButton, previewFullscreen);
  syncDrawingContextMenuHost();
  if (!drawingContextMenu.hidden) clampDrawingContextMenuToViewport();
  schedulePanelFullscreenResize();
}

async function closePanelFullscreen() {
  appFullscreenPanel = null;
  if (browserFullscreenElement()) {
    try {
      await exitNativeFullscreen();
    } catch (error) {
      console.warn("Could not exit browser fullscreen.", error);
    }
  }
  updatePanelFullscreenState();
}

async function togglePanelFullscreen(panel) {
  if (!panel) return;
  if (panelFullscreenActive(panel)) {
    await closePanelFullscreen();
    return;
  }

  await closePanelFullscreen();
  appFullscreenPanel = panel;
  updatePanelFullscreenState();
}

function setupPanelFullscreen() {
  drawingFullscreenButton?.addEventListener("click", toggleFocusMode);
  previewFullscreenButton?.addEventListener("click", () => togglePanelFullscreen(previewPanel));
  document.addEventListener("fullscreenchange", () => {
    if (!browserFullscreenElement()) appFullscreenPanel = null;
    updatePanelFullscreenState();
  });
  document.addEventListener("webkitfullscreenchange", () => {
    if (!browserFullscreenElement()) appFullscreenPanel = null;
    updatePanelFullscreenState();
  });
}

function previewFloatingActive() {
  return Boolean(
    previewPanel &&
      !previewPanelHidden &&
      !isTabletLayout() &&
      (previewFloatManual || document.body.classList.contains("drawing-panel-fullscreen")) &&
      !panelFullscreenActive(previewPanel),
  );
}

function setPreviewFloatButtonState() {
  if (!previewFloatButton) return;
  const active = previewFloatingActive();
  previewFloatButton.setAttribute("aria-pressed", String(active));
  previewFloatButton.title = active ? "Dock 3D preview" : "Float 3D preview over drawing";
  previewFloatButton.setAttribute("aria-label", previewFloatButton.title);
  const label = previewFloatButton.querySelector("span");
  if (label) label.textContent = active ? "Dock" : "Float";
}

function setPreviewMinimizeButtonState() {
  if (!previewMinimizeButton) return;
  previewMinimizeButton.hidden = !previewFloatingActive();
  previewMinimizeButton.setAttribute("aria-pressed", String(previewPanelMinimized));
  previewMinimizeButton.title = previewPanelMinimized ? "Restore 3D preview" : "Minimize 3D preview";
  previewMinimizeButton.setAttribute("aria-label", previewMinimizeButton.title);
  const label = previewMinimizeButton.querySelector("span:last-child");
  if (label) label.textContent = previewPanelMinimized ? "Restore" : "Min";
}

function updatePreviewVisibilityControls() {
  if (previewPanel) previewPanel.hidden = previewPanelHidden;
  if (previewShowButton) previewShowButton.hidden = !previewPanelHidden;
  document.body.classList.toggle("preview-panel-hidden", previewPanelHidden);
  document.body.classList.toggle("preview-panel-minimized", previewPanelMinimized && !previewPanelHidden);
  setPreviewMinimizeButtonState();
}

function updatePreviewFloatingState() {
  const active = previewFloatingActive();
  document.body.classList.toggle("preview-panel-floating", active);
  updatePreviewVisibilityControls();
  if (previewPanelHidden && isTabletLayout() && document.body.dataset.mobilePanel === "preview") {
    showMobilePanel("drawing");
  }
  setPreviewFloatButtonState();
  applyPreviewFloatBounds();
  refreshPreviewAfterLayoutChange();
}

function togglePreviewFloating() {
  if (!previewPanel || panelFullscreenActive(previewPanel)) return;
  previewPanelHidden = false;
  previewFloatManual = !previewFloatManual;
  storePreviewFloatPreference(previewFloatManual);
  if (!previewFloatManual) {
    previewPanelMinimized = false;
  }
  if (previewFloatManual) {
    showMobilePanel("drawing");
  }
  updatePreviewFloatingState();
}

function togglePreviewMinimized() {
  if (!previewPanel || previewPanelHidden || panelFullscreenActive(previewPanel)) return;
  if (isTabletLayout()) return;
  if (!previewFloatingActive()) return;
  previewPanelMinimized = !previewPanelMinimized;
  updatePreviewFloatingState();
}

function setPreviewHidden(hidden) {
  previewPanelHidden = hidden === true;
  if (previewPanelHidden) {
    previewPanelMinimized = false;
  } else {
    previewPanelMinimized = false;
  }
  if (!previewPanelHidden && !isTabletLayout()) {
    setInspectorDrawerOpen(false);
  }
  updatePreviewFloatingState();
  // A hidden mobile preview must also release its sheet and scrim. Keeping
  // data-mobile-panel="preview" after hiding the panel leaves the drawing
  // greyed out with no visible Close button on iPhone and Android.
  if (previewPanelHidden && isTabletLayout() && document.body.dataset.mobilePanel === "preview") {
    showMobilePanel("drawing");
  }
}

function openPreviewPreservingWorkspace() {
  if (previewPanelHidden || currentWorkspaceSurface() !== "preview") {
    previewReturnSurfaceState = captureWorkspaceSurfaceState();
  }
  if (isTabletLayout()) {
    showMobilePanel("preview");
  } else {
    setPreviewHidden(false);
  }
  renderWorkspaceLocationStrips();
}

function closePreviewToPreviousWorkspace() {
  const restore = previewReturnSurfaceState;
  previewReturnSurfaceState = null;
  if (isTabletLayout()) {
    showMobilePanel("drawing");
  } else {
    setPreviewHidden(true);
  }
  if (restore) restoreWorkspaceSurfaceState(restore);
  renderWorkspaceLocationStrips();
}

function defaultPreviewFloatBounds() {
  const coarse = isTabletLayout();
  const sideReserve = coarse ? 0 : 86;
  const bottomReserve = coarse ? 84 : 0;
  const margin = coarse ? 10 : 18;
  const availableWidth = Math.max(260, window.innerWidth - sideReserve - margin * 2);
  const availableHeight = Math.max(200, window.innerHeight - bottomReserve - margin * 2);
  const width = Math.min(coarse ? 390 : 420, availableWidth);
  const height = Math.min(coarse ? 290 : 310, availableHeight);
  return {
    left: window.innerWidth - width - margin,
    top: window.innerHeight - bottomReserve - height - margin,
    width,
    height,
  };
}

function clampPreviewFloatBounds(bounds) {
  const coarse = isTabletLayout();
  const sideReserve = previewFloatingActive() && !coarse ? 86 : 0;
  const bottomReserve = previewFloatingActive() && coarse ? 84 : 0;
  const margin = coarse ? 10 : 8;
  const availableWidth = Math.max(220, window.innerWidth - sideReserve - margin * 2);
  const availableHeight = Math.max(180, window.innerHeight - bottomReserve - margin * 2);
  const minWidth = Math.min(coarse ? 280 : 300, availableWidth);
  const minHeight = Math.min(coarse ? 190 : 220, availableHeight);
  const width = clampNumber(Number(bounds?.width) || 420, minWidth, availableWidth);
  const height = clampNumber(Number(bounds?.height) || 300, minHeight, availableHeight);
  const minLeft = sideReserve + margin;
  const maxLeft = Math.max(minLeft, window.innerWidth - width - margin);
  const minTop = margin;
  const maxTop = Math.max(minTop, window.innerHeight - bottomReserve - height - margin);
  return {
    left: clampNumber(Number(bounds?.left) || maxLeft, minLeft, maxLeft),
    top: clampNumber(Number(bounds?.top) || maxTop, minTop, maxTop),
    width,
    height,
  };
}

function clearPreviewFloatStyles() {
  if (!previewPanel) return;
  previewPanel.style.left = "";
  previewPanel.style.top = "";
  previewPanel.style.right = "";
  previewPanel.style.bottom = "";
  previewPanel.style.width = "";
  previewPanel.style.height = "";
}

function applyPreviewFloatBounds() {
  if (!previewPanel) return;
  if (!previewFloatingActive()) {
    clearPreviewFloatStyles();
    return;
  }

  previewFloatBounds = clampPreviewFloatBounds(previewFloatBounds ?? defaultPreviewFloatBounds());
  previewPanel.style.left = `${previewFloatBounds.left}px`;
  previewPanel.style.top = `${previewFloatBounds.top}px`;
  previewPanel.style.right = "auto";
  previewPanel.style.bottom = "auto";
  previewPanel.style.width = `${previewFloatBounds.width}px`;
  previewPanel.style.height = previewPanelMinimized ? "auto" : `${previewFloatBounds.height}px`;
}

function previewFloatHandleAllowed(event) {
  if (!previewFloatingActive()) return false;
  if (event.pointerType === "mouse" && event.button !== 0) return false;
  return true;
}

function isPreviewFloatControlTarget(target) {
  return target instanceof Element && Boolean(target.closest(
    "button, input, select, label, textarea, a, .preview-stage, .preview-float-resize",
  ));
}

function beginPreviewFloatMove(event) {
  if (!previewFloatHandleAllowed(event) || isPreviewFloatControlTarget(event.target)) return;
  const rect = previewPanel.getBoundingClientRect();
  previewFloatDrag = {
    mode: "move",
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    left: rect.left,
    top: rect.top,
    width: rect.width,
    height: rect.height,
  };
  previewPanel.classList.add("preview-floating-dragging");
  previewPanel.setPointerCapture?.(event.pointerId);
  event.preventDefault();
}

function beginPreviewFloatResize(event) {
  if (!previewFloatHandleAllowed(event)) return;
  const rect = previewPanel.getBoundingClientRect();
  previewFloatDrag = {
    mode: "resize",
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    left: rect.left,
    top: rect.top,
    width: rect.width,
    height: rect.height,
  };
  previewPanel.classList.add("preview-floating-resizing");
  previewPanel.setPointerCapture?.(event.pointerId);
  event.preventDefault();
}

function updatePreviewFloatDrag(event) {
  if (!previewFloatDrag || previewFloatDrag.pointerId !== event.pointerId) return;
  const dx = event.clientX - previewFloatDrag.startX;
  const dy = event.clientY - previewFloatDrag.startY;
  const nextBounds = previewFloatDrag.mode === "resize"
    ? {
        left: previewFloatDrag.left,
        top: previewFloatDrag.top,
        width: previewFloatDrag.width + dx,
        height: previewFloatDrag.height + dy,
      }
    : {
        left: previewFloatDrag.left + dx,
        top: previewFloatDrag.top + dy,
        width: previewFloatDrag.width,
        height: previewFloatDrag.height,
      };

  previewFloatBounds = clampPreviewFloatBounds(nextBounds);
  applyPreviewFloatBounds();
  resizeThree();
  renderFallbackPreview();
  event.preventDefault();
}

function finishPreviewFloatDrag(event) {
  if (!previewFloatDrag || previewFloatDrag.pointerId !== event.pointerId) return;
  previewPanel.releasePointerCapture?.(event.pointerId);
  previewPanel.classList.remove("preview-floating-dragging", "preview-floating-resizing");
  previewFloatDrag = null;
  storePreviewFloatBoundsPreference(previewFloatBounds);
  schedulePreviewStabilize();
  event.preventDefault();
}

function setupFloatingPreviewPanel() {
  const previewBar = previewPanel?.querySelector(".panel-bar");
  previewFloatButton?.addEventListener("click", togglePreviewFloating);
  previewMinimizeButton?.addEventListener("click", togglePreviewMinimized);
  previewHideButton?.addEventListener("click", closePreviewToPreviousWorkspace);
  previewShowButton?.addEventListener("click", openPreviewPreservingWorkspace);
  previewBar?.addEventListener("pointerdown", beginPreviewFloatMove);
  previewFloatResize?.addEventListener("pointerdown", beginPreviewFloatResize);
  window.addEventListener("pointermove", updatePreviewFloatDrag);
  window.addEventListener("pointerup", finishPreviewFloatDrag);
  window.addEventListener("pointercancel", finishPreviewFloatDrag);
  updatePreviewFloatingState();
}

function isGestureSurfaceTarget(target) {
  return target instanceof Element && Boolean(target.closest(
    "#drawCanvas, #threeCanvas, #fallbackCanvas, .canvas-frame, .preview-stage, .tool-rail, .drawing-panel, .preview-panel",
  ));
}

function setupTouchSelectionGuards() {
  for (const eventName of ["selectstart", "dragstart"]) {
    document.addEventListener(eventName, (event) => {
      if (isGestureSurfaceTarget(event.target) && !isEditingField(event.target)) {
        event.preventDefault();
      }
    }, { passive: false });
  }

  for (const surface of [drawCanvas, threeCanvas, fallbackCanvas, previewStage]) {
    surface?.addEventListener("gesturestart", (event) => event.preventDefault(), { passive: false });
    surface?.addEventListener("gesturechange", (event) => event.preventDefault(), { passive: false });
  }
}

function updateTouchComfortClass() {
  const previousLayout = lastWorkspaceLayoutKind;
  const previousSurface = previousLayout ? workspaceSurfaceForLayout(previousLayout) : currentWorkspaceSurface();
  const touchMode = isTabletLayout();
  const phoneMode = isPhoneLayout();
  const tabletMode = touchMode && !phoneMode;
  document.body.classList.toggle("touch-comfort", touchMode);
  document.body.classList.toggle("field-layout", touchMode);
  document.body.classList.toggle("tablet-layout", tabletMode);
  document.body.classList.toggle("phone-layout", phoneMode);
  document.body.classList.toggle("mobile-touch-layout", touchMode);
  if (phoneMode) {
    try {
      if (localStorage.getItem(PHONE_PREVIEW_DEFAULT_KEY) !== "applied") {
        previewPanelHidden = true;
        previewPanelMinimized = false;
        localStorage.setItem(PHONE_PREVIEW_DEFAULT_KEY, "applied");
        window.requestAnimationFrame(() => setPreviewHidden(true));
      }
    } catch {
      previewPanelHidden = true;
      previewPanelMinimized = false;
      window.requestAnimationFrame(() => setPreviewHidden(true));
    }
  }
  const nextLayout = workspaceLayoutKind();
  reconcileWorkspaceLayout(previousLayout, nextLayout, previousSurface);
  lastWorkspaceLayoutKind = nextLayout;
}

function setupTouchComfort() {
  updateTouchComfortClass();
  const mediaQueries = [
    window.matchMedia?.("(max-width: 1100px)"),
    window.matchMedia?.("(pointer: coarse)"),
    window.matchMedia?.("(hover: none)"),
  ].filter(Boolean);
  for (const mediaQuery of mediaQueries) {
    mediaQuery.addEventListener?.("change", updateTouchComfortClass);
  }
  window.addEventListener("resize", updateTouchComfortClass);
}

function normalizeAppTheme(value) {
  return value === "dark" ? "dark" : "light";
}

function loadAppMode() {
  try {
    return normalizeAppMode(localStorage.getItem(APP_MODE_KEY));
  } catch {
    return "draw";
  }
}

function storeAppMode(mode) {
  try {
    localStorage.setItem(APP_MODE_KEY, normalizeAppMode(mode));
  } catch (error) {
    console.warn("Could not save workflow mode.", error);
  }
}

function loadPreviewFloatPreference() {
  try {
    const saved = localStorage.getItem(PREVIEW_FLOAT_KEY);
    if (saved === "false") return false;
    if (saved === "true") return true;
  } catch {
    // Default below keeps first use cleaner if local storage is not available.
  }
  // Touch layouts ignore floating while active, but retaining this value means
  // a convertible device can return to its previous desktop Float/Dock choice.
  return true;
}

function loadPreviewFloatBoundsPreference() {
  try {
    const saved = JSON.parse(localStorage.getItem(PREVIEW_FLOAT_BOUNDS_KEY) || "null");
    if (!saved || typeof saved !== "object") return null;
    const values = [saved.left, saved.top, saved.width, saved.height].map(Number);
    if (values.some((value) => !Number.isFinite(value))) return null;
    return { left: values[0], top: values[1], width: values[2], height: values[3] };
  } catch {
    return null;
  }
}

function storePreviewFloatBoundsPreference(bounds) {
  if (!bounds) return;
  try {
    localStorage.setItem(PREVIEW_FLOAT_BOUNDS_KEY, JSON.stringify({
      left: Math.round(bounds.left),
      top: Math.round(bounds.top),
      width: Math.round(bounds.width),
      height: Math.round(bounds.height),
    }));
  } catch (error) {
    console.warn("Could not save the 3D preview position.", error);
  }
}

function storePreviewFloatPreference(active) {
  try {
    localStorage.setItem(PREVIEW_FLOAT_KEY, active ? "true" : "false");
  } catch (error) {
    console.warn("Could not save 3D preview float preference.", error);
  }
}

function loadAppTheme() {
  try {
    const saved = localStorage.getItem(APP_THEME_KEY);
    return saved === "dark" ? "dark" : "light";
  } catch {
    return "light";
  }
}

function isDarkAppTheme() {
  return document.documentElement.dataset.theme === "dark";
}

function setAppTheme(theme, options = {}) {
  const nextTheme = normalizeAppTheme(theme);
  document.documentElement.dataset.theme = nextTheme;
  document.body?.setAttribute("data-theme", nextTheme);
  if (themeColorMeta) {
    themeColorMeta.content = nextTheme === "dark" ? "#071018" : "#f6f8f7";
  }
  for (const button of themeChoiceButtons) {
    const active = button.dataset.themeChoice === nextTheme;
    button.classList.toggle("active", active);
    button.setAttribute("aria-selected", String(active));
  }
  if (options.persist !== false) {
    try {
      localStorage.setItem(APP_THEME_KEY, nextTheme);
    } catch {
      // Theme still applies for this page even if storage is blocked.
    }
  }
  if (options.redraw !== false) {
    drawIso();
    update3dPreview();
    renderFallbackPreview();
  }
}

function setupAppTheme() {
  setAppTheme(loadAppTheme(), { persist: false, redraw: false });
  for (const button of themeChoiceButtons) {
    button.addEventListener("click", () => {
      setAppTheme(button.dataset.themeChoice);
    });
  }
}

let actionCommandMatches = [];
let actionCommandActiveIndex = -1;

function openCommandDrawingTool(tool, mode = "edit") {
  if (!currentDrawingProjectPermission().canEdit) {
    showAppNotice(currentPermissionRestrictionText("edit"));
    return;
  }
  applyAppMode(mode, { keepTool: true });
  setTool(tool);
  setFittingsToolMenuOpen(false);
  showMobilePanel("drawing");
}

function openCommandInspector(mode, tab, focusSelector = "") {
  applyAppMode(mode, { keepTool: true });
  activateInspectorTab(tab);
  showMobilePanel("inspector");
  if (focusSelector) {
    window.requestAnimationFrame(() => {
      const target = document.querySelector(focusSelector);
      target?.scrollIntoView?.({ behavior: "smooth", block: "center" });
      target?.focus?.({ preventScroll: true });
    });
  }
}

function openCommandExport(targetSelector, tab = "bom") {
  openCommandInspector("export", tab);
  window.requestAnimationFrame(() => document.querySelector(targetSelector)?.focus?.({ preventScroll: true }));
}

