function setupProjectDialog() {
  if (!projectDialogForm || !projectDialogCancelButton) return;
  ensureProjectLibraryDashboardShell();

  projectDialogForm.addEventListener("submit", (event) => {
    event.preventDefault();
    closeProjectDetailsDialog(projectDetailsFromDialog());
  });

  projectDialogCancelButton.addEventListener("click", () => {
    closeProjectDetailsDialog(null);
  });

  projectDialog?.addEventListener("pointerdown", (event) => {
    if (event.target === projectDialog) {
      closeProjectDetailsDialog(null);
    }
  });

  newDrawingCancelButton?.addEventListener("click", () => closeNewDrawingDialog("cancel"));
  newDrawingDiscardButton?.addEventListener("click", () => closeNewDrawingDialog("discard"));
  newDrawingSaveButton?.addEventListener("click", () => closeNewDrawingDialog("save"));
  newDrawingDialog?.addEventListener("pointerdown", (event) => {
    if (event.target === newDrawingDialog) {
      closeNewDrawingDialog("cancel");
    }
  });

  projectDialogJobPickerButton?.addEventListener("click", () => {
    if (!projectJobQuickPick || projectDialogJobPickerButton.disabled) return;
    if (projectJobQuickPick.hidden) {
      openProjectJobPicker();
    } else {
      closeProjectJobPicker();
    }
  });

  projectDialogInputs.jobNumber?.addEventListener("contextmenu", (event) => {
    if (!recentProjectChoices().length) return;
    event.preventDefault();
    openProjectJobPicker();
  });

  projectDialogInputs.jobNumber?.addEventListener("input", () => {
    if (projectJobQuickPick && !projectJobQuickPick.hidden) renderProjectJobPicker();
  });

  projectJobQuickPick?.addEventListener("click", (event) => {
    const choiceButton = event.target.closest("[data-project-job-number]");
    if (!choiceButton) return;
    applyProjectJobChoice(choiceButton);
  });

  document.addEventListener("pointerdown", (event) => {
    if (!projectJobQuickPick || projectJobQuickPick.hidden) return;
    const target = event.target;
    if (
      projectJobQuickPick.contains(target) ||
      projectDialogJobPickerButton?.contains(target) ||
      projectDialogInputs.jobNumber?.contains(target)
    ) {
      return;
    }
    closeProjectJobPicker();
  });

  projectLibraryCloseButton?.addEventListener("click", closeProjectLibrary);
  projectLibrarySearchInput?.addEventListener("input", () => {
    projectLibrarySearch = projectLibrarySearchInput.value;
    projectLibraryOpenFolderKey = "";
    projectLibraryJobPage = 1;
    renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
  });
  projectLibrarySourceButton?.addEventListener("click", () => {
    const nextSource = projectLibrarySource === "cloud" ? "browser" : "cloud";
    openBrowserProject({ keepSearch: true, source: nextSource }).catch((error) => {
      console.warn("Project source switch failed.", error);
      showAppNotice(error?.message || "Could not switch the project source.");
    });
  });
  projectLibraryNewButton?.addEventListener("click", () => {
    closeProjectLibrary();
    startNewDrawing();
  });
  projectLibrarySaveButton?.addEventListener("click", () => {
    saveBrowserProject({ silent: true })
      .then((saved) => {
        if (saved) return openBrowserProject({ keepSearch: true, source: hasActiveCloudLicense() ? undefined : "browser" });
        return null;
      })
      .catch((error) => {
        console.warn("Save project failed.", error);
        showAppNotice(error?.message || "Save project failed.");
      });
  });
  projectLibraryDialog?.addEventListener("pointerdown", (event) => {
    if (event.target === projectLibraryDialog) {
      closeProjectLibrary();
    }
  });
  projectLibraryDialog?.addEventListener("click", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    const libraryAction = target?.closest("[data-project-library-action]");
    if (libraryAction) {
      event.preventDefault();
      event.stopPropagation();
      handleProjectLibraryAction(libraryAction);
      return;
    }
    if (target?.closest("[data-production-action], [data-open-project-id]")) {
      handleProjectLibraryActivation(event);
      return;
    }
    if (!target?.closest("#projectLibraryGuideButton")) return;
    event.preventDefault();
    event.stopPropagation();
    showProjectLibraryGuide();
  });
  projectLibraryDialog?.addEventListener("keydown", (event) => {
    const target = event.target instanceof HTMLElement ? event.target : null;
    if (!target?.matches("[data-team-message-input]")) return;
    if (event.key !== "Enter" || event.shiftKey) return;
    event.preventDefault();
    const body = String(target.value ?? "").trim();
    if (!body) return;
    addTeamMessage(body)
      .then(() => {
        target.value = "";
      })
      .catch((error) => {
        console.warn("Team message add failed.", error);
        showAppNotice(error?.message || "Could not add team message.");
      });
  });
  projectLibraryList?.addEventListener("click", (event) => {
    handleProjectLibraryActivation(event);
  });
  projectLibraryList?.addEventListener("change", (event) => {
    handleProjectLibraryFieldChange(event).catch((error) => {
      console.warn("Production field update failed.", error);
      showAppNotice(error?.message || "Could not update production field.");
    });
  });
  projectLibraryList?.addEventListener("dragstart", handleProjectLibraryDragStart);
  projectLibraryList?.addEventListener("dragover", handleProjectLibraryDragOver);
  projectLibraryList?.addEventListener("dragleave", handleProjectLibraryDragLeave);
  projectLibraryList?.addEventListener("drop", handleProjectLibraryDrop);
  projectLibraryList?.addEventListener("dragend", handleProjectLibraryDragEnd);
}

function handleProjectLibraryActivation(event) {
  const target = event.target instanceof Element ? event.target : null;
  if (!target) return;

  const libraryAction = target.closest("[data-project-library-action]");
  if (libraryAction) {
    event.preventDefault();
    event.stopPropagation();
    handleProjectLibraryAction(libraryAction);
    return;
  }

  const productionAction = target.closest("[data-production-action]");
  if (productionAction) {
    event.preventDefault();
    event.stopPropagation();
    const actionKey = [
      "production",
      productionAction.dataset.productionAction,
      productionAction.dataset.projectId,
      productionAction.dataset.messageId,
    ].filter(Boolean).join(":");
    if (shouldSkipProjectLibraryActivation(actionKey)) return;
    handleProjectLibraryProductionAction(productionAction).catch((error) => {
      console.warn("Production action failed.", error);
      showAppNotice(error?.message || "Could not update production board.");
    });
    return;
  }

  const folderBack = target.closest("[data-project-folder-back]");
  if (folderBack) {
    event.preventDefault();
    event.stopPropagation();
    if (shouldSkipProjectLibraryActivation("folder-back")) return;
    closeProjectLibraryFolder();
    return;
  }

  const folderOpen = target.closest("[data-project-folder-open]");
  if (folderOpen) {
    const folderKey = folderOpen.dataset.projectFolderOpen ?? "";
    const focus = folderOpen.dataset.jobFocus ?? "";
    event.preventDefault();
    event.stopPropagation();
    if (shouldSkipProjectLibraryActivation(`folder:${folderKey}`)) return;
    openProjectLibraryFolder(folderKey, focus);
    return;
  }

  const deleteButton = target.closest("[data-delete-project-id]");
  if (deleteButton) {
    event.preventDefault();
    event.stopPropagation();
    if (shouldSkipProjectLibraryActivation(`delete:${deleteButton.dataset.deleteProjectId ?? ""}`)) return;
    if (deleteButton.dataset.projectSource === "cloud") {
      deleteSavedCloudProject(deleteButton.dataset.deleteProjectId).catch((error) => {
        console.warn("Could not delete cloud project.", error);
        updateCloudStatus("Cloud delete failed", "warning");
      });
    } else {
      deleteSavedBrowserProject(deleteButton.dataset.deleteProjectId);
    }
    return;
  }

  const newWindowTarget = target.closest("[data-open-project-window]");
  if (newWindowTarget) {
    event.preventDefault();
    event.stopPropagation();
    if (shouldSkipProjectLibraryActivation(`window:${newWindowTarget.dataset.openProjectWindow ?? ""}`)) return;
    openProjectInWorkspaceTab(
      newWindowTarget.dataset.openProjectWindow,
      newWindowTarget.dataset.projectSource,
    ).catch((error) => {
      console.warn("Could not open spool tab.", error);
      showAppNotice("That spool could not be opened in a tab.", { tone: "warning" });
    });
    return;
  }

  const openTarget = target.closest("[data-open-project-id]");
  if (!openTarget) return;
  event.preventDefault();
  event.stopPropagation();
  if (event.ctrlKey || event.metaKey || event.shiftKey) {
    openProjectInWorkspaceTab(openTarget.dataset.openProjectId, openTarget.dataset.projectSource).catch((error) => {
      console.warn("Could not open spool tab.", error);
    });
    return;
  }
  if (shouldSkipProjectLibraryActivation(`open:${openTarget.dataset.openProjectId ?? ""}`)) return;
  if (openTarget.dataset.projectSource === "cloud") {
    openSavedCloudProject(openTarget.dataset.openProjectId).catch((error) => {
      console.warn("Could not open cloud project.", error);
      updateCloudStatus("Cloud open failed", "warning");
    });
  } else {
    openSavedBrowserProject(openTarget.dataset.openProjectId);
  }
}

function handleProjectLibraryAction(actionElement) {
  const action = actionElement?.dataset?.projectLibraryAction;
  if (!action) return;
  const actionKey = [
    "library-action",
    action,
    actionElement.dataset.dashboardView,
    actionElement.dataset.jobFilter,
    actionElement.dataset.jobKey,
    actionElement.dataset.jobPage,
    actionElement.dataset.reportPeriod,
  ].filter(Boolean).join(":");
  if (shouldSkipProjectLibraryActivation(actionKey, 1500)) return;
  if (action === "dashboard-view") {
    setTeamDashboardView(actionElement.dataset.dashboardView);
    return;
  }
  if (action === "job-filter") {
    setProjectLibraryJobFilter(actionElement.dataset.jobFilter);
    return;
  }
  if (action === "pin-job") {
    toggleProjectLibraryJobPin(actionElement.dataset.jobKey);
    return;
  }
  if (action === "job-page") {
    const page = Number.parseInt(actionElement.dataset.jobPage, 10);
    if (Number.isFinite(page) && page > 0) {
      projectLibraryJobPage = page;
      renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
    }
    return;
  }
  if (action === "toggle-dashboard-more") {
    projectLibraryMoreVisible = !projectLibraryMoreVisible;
    renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
    return;
  }
  if (action === "scan-qr") {
    openQrScanner().catch((error) => {
      console.warn("QR scanner could not open.", error);
      showAppNotice(error?.message || "The QR scanner could not be opened.");
    });
    return;
  }
  if (action === "show-guide") {
    showProjectLibraryGuide();
    return;
  }
  if (action === "hide-guide") {
    hideProjectLibraryGuide();
    return;
  }
  if (action === "show-comms") {
    showProjectLibraryComms();
    return;
  }
  if (action === "hide-comms") {
    hideProjectLibraryComms();
    return;
  }
  if (action === "refresh-team-messages") {
    loadTeamMessages().catch((error) => {
      console.warn("Team messages refresh failed.", error);
      showAppNotice(error?.message || "Could not refresh team messages.");
    });
    return;
  }
  if (action === "add-team-message") {
    const input = projectLibraryCommsSlot?.querySelector("[data-team-message-input]");
    const body = String(input?.value ?? "").trim();
    if (!body) return;
    addTeamMessage(body)
      .then(() => {
        if (input) input.value = "";
      })
      .catch((error) => {
        console.warn("Team message add failed.", error);
        showAppNotice(error?.message || "Could not add team message.");
      });
    return;
  }
  if (action === "complete-team-message") {
    completeTeamMessage(actionElement.dataset.teamMessageId).catch((error) => {
      console.warn("Team message complete failed.", error);
      showAppNotice(error?.message || "Could not mark team message done.");
    });
    return;
  }
  if (action === "show-report") {
    if (actionElement.dataset.reportPeriod) {
      projectLibraryReportPeriod = actionElement.dataset.reportPeriod === "weekly" ? "weekly" : "daily";
    }
    showProjectLibraryReport();
    return;
  }
  if (action === "hide-report") {
    hideProjectLibraryReport();
    return;
  }
  if (action === "report-period") {
    const period = actionElement.dataset.reportPeriod === "weekly" ? "weekly" : "daily";
    setProjectLibraryReportPeriod(period);
    return;
  }
  if (action === "copy-report") {
    copyProjectLibraryReport();
    return;
  }
  if (action === "board-filter") {
    setProjectLibraryBoardFilter(actionElement.dataset.boardFilter);
  }
}

async function handleProjectLibraryFieldChange(event) {
  const target = event.target instanceof HTMLInputElement || event.target instanceof HTMLSelectElement ? event.target : null;
  if (!target) return;
  if (target.dataset.materialCheckField) {
    await handleMaterialChecklistFieldChange(target);
    return;
  }
  if (!target.dataset.productionField) return;
  const projectId = target.dataset.projectId;
  if (!projectId) return;

  const field = target.dataset.productionField;
  const value = target.type === "checkbox" ? target.checked : target.value;
  const project = projectLibraryProjects.find((item) => item.id === projectId);
  const currentProduction = savedProjectProductionInfo(project);
  if (field === "status") {
    const currentStatus = normalizeProjectStatus(savedProjectState(project)?.projectStatus);
    const nextStatus = normalizeProjectStatus(value);
    if (nextStatus === "checked" && currentStatus !== "checked") {
      target.value = currentStatus;
      showAppNotice("Open the spool and use Approve drawing so the checker and comment are recorded.");
      return;
    }
    if (projectStatusAtLeast(currentStatus, "checked") && projectStatusIndex(nextStatus) < projectStatusIndex("checked")) {
      target.value = currentStatus;
      showAppNotice("Open the spool and use Return for changes so a checker comment and revision record are kept.");
      return;
    }
  }
  if (field === "holdReason" && currentProduction.hold && !String(value ?? "").trim()) {
    target.value = currentProduction.holdReason;
    showAppNotice("A spool on hold must keep a hold reason. Remove the hold first if it is no longer blocked.");
    return;
  }
  const updates = {};
  if (field === "status") {
    updates.status = value;
  } else {
    updates.productionInfo = { [field]: value };
  }
  if (field === "hold" && value === true) {
    const response = await openFieldInputDialog({
      title: "Place spool on hold",
      label: "Hold reason",
      value: currentProduction.holdReason,
      placeholder: "Missing flange, client hold, material unavailable...",
      help: "A hold reason is required so everyone can see what is blocking the spool.",
      submitLabel: "Place on hold",
    });
    const reason = String(response ?? "").trim().slice(0, 140);
    if (!reason) {
      target.checked = false;
      showAppNotice("Hold was not applied. Enter a reason before placing a spool on hold.");
      return;
    }
    updates.productionInfo.holdReason = reason;
  }

  await updateSavedProjectWorkflow(projectId, updates);
}

async function handleMaterialChecklistFieldChange(field) {
  const projectId = field.dataset.projectId;
  const itemId = field.dataset.materialItemId;
  const key = field.dataset.materialCheckField;
  const project = projectLibraryProjects.find((item) => item.id === projectId);
  if (!project || !itemId || !["status", "note"].includes(key)) return;
  if (!projectPermission(project).canManageProduction) {
    showAppNotice(roleRequirementText("production"));
    renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
    return;
  }
  const checklist = materialChecklistForState(savedProjectState(project));
  const item = checklist.items.find((entry) => entry.id === itemId);
  if (!item) return;
  item[key] = key === "status" ? normalizeMaterialCheckStatus(field.value) : String(field.value ?? "").trim().slice(0, 180);
  checklist.checkedAt = "";
  checklist.checkedBy = "";
  checklist.overrideAt = "";
  checklist.overrideBy = "";
  checklist.overrideReason = "";
  await updateSavedProjectWorkflow(projectId, { productionInfo: { materialChecklist: checklist } });
}

async function handleProjectLibraryProductionAction(actionButton) {
  const projectId = actionButton.dataset.projectId;
  if (!projectId) return;
  const action = actionButton.dataset.productionAction;
  const project = projectLibraryProjects.find((item) => item.id === projectId);
  const permission = projectPermission(project);
  if (action === "add-material-item") {
    if (!permission.canManageProduction) throw new Error(roleRequirementText("production"));
    const response = await openFieldInputDialog({
      title: "Add workshop gear",
      label: "Required item",
      value: "",
      placeholder: "Gaskets, bolts, purge gear, consumables...",
      help: "Use this for anything the drawing material take-off cannot infer.",
      submitLabel: "Add to checklist",
    });
    const label = String(response ?? "").trim().slice(0, 120);
    if (!label) return;
    const checklist = materialChecklistForState(savedProjectState(project));
    checklist.items.push({
      id: `gear-custom-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
      key: `custom:${Date.now().toString(36)}`,
      label,
      quantity: "",
      detail: "Added workshop item",
      status: "pending",
      note: "",
      custom: true,
    });
    checklist.checkedAt = "";
    checklist.overrideAt = "";
    checklist.overrideReason = "";
    await updateSavedProjectWorkflow(projectId, { productionInfo: { materialChecklist: checklist } });
    return;
  }
  if (action === "confirm-material-check") {
    if (!permission.canManageProduction) throw new Error(roleRequirementText("production"));
    const production = savedProjectProductionInfo(project);
    const checklist = materialChecklistForState(savedProjectState(project));
    const stats = materialChecklistStats(checklist);
    if (!production.assignee) throw new Error("Assign the spool before confirming its gear checklist.");
    if (!stats.total) throw new Error("Add at least one required item before confirming gear ready.");
    if (stats.pending || stats.missing) {
      throw new Error(`Resolve the gear checklist first: ${stats.pending} not checked and ${stats.missing} needing ordering.`);
    }
    const now = new Date().toISOString();
    checklist.checkedAt = now;
    checklist.checkedBy = checkerName() || production.assignee || "Team member";
    checklist.overrideAt = "";
    checklist.overrideBy = "";
    checklist.overrideReason = "";
    await updateSavedProjectWorkflow(projectId, {
      productionInfo: { materialChecklist: checklist },
      status: normalizeProjectStatus(savedProjectState(project)?.projectStatus) === "issued" ? "materialcheck" : undefined,
    });
    showAppNotice("Gear checklist confirmed. This spool is ready to start fabrication.");
    return;
  }
  if (action === "override-material-check") {
    if (!permission.canIssue) throw new Error("Only a checker or team admin can authorise starting with missing gear.");
    const response = await openFieldInputDialog({
      title: "Authorise gear-check override",
      label: "Required reason",
      value: "",
      placeholder: "Item arriving before fit-up; cutting authorised to begin...",
      help: "The reason, author and time are retained in the spool activity history.",
      submitLabel: "Record override",
      multiline: true,
    });
    const reason = String(response ?? "").trim().slice(0, 400);
    if (!reason) return;
    const checklist = materialChecklistForState(savedProjectState(project));
    checklist.overrideAt = new Date().toISOString();
    checklist.overrideBy = checkerName() || "Checker";
    checklist.overrideReason = reason;
    await updateSavedProjectWorkflow(projectId, { productionInfo: { materialChecklist: checklist } });
    showAppNotice("Gear-check override recorded.");
    return;
  }
  if (action === "add-message") {
    const card = actionButton.closest(".production-spool-card");
    const input = card?.querySelector("[data-production-message-input]");
    const body = String(input?.value ?? "").trim();
    if (!body) return;
    await updateSavedProjectWorkflow(projectId, { addMessage: body });
    return;
  }
  if (action === "complete-message") {
    await updateSavedProjectWorkflow(projectId, { completeMessageId: actionButton.dataset.messageId });
    return;
  }
  if (action === "set-status") {
    const project = projectLibraryProjects.find((item) => item.id === projectId);
    const currentStatus = normalizeProjectStatus(savedProjectState(project)?.projectStatus);
    const nextStatus = normalizeProjectStatus(actionButton.dataset.status);
    if (projectStatusAtLeast(currentStatus, "checked") && projectStatusIndex(nextStatus) < projectStatusIndex(currentStatus)) {
      showAppNotice("Open the spool and use Return for changes so the checker comment and revision are preserved.");
      return;
    }
    await updateSavedProjectWorkflow(projectId, { status: nextStatus });
    return;
  }
  if (action === "complete-spool") {
    await updateSavedProjectWorkflow(projectId, { status: "complete" });
  }
}

function handleProjectLibraryDragStart(event) {
  const card = event.target instanceof Element ? event.target.closest(".production-spool-card") : null;
  if (!card) return;
  const project = projectLibraryProjects.find((item) => item.id === card.dataset.productionProjectId);
  if (project && !projectPermission(project).canEdit) {
    event.preventDefault();
    return;
  }
  projectLibraryDrag = {
    projectId: card.dataset.productionProjectId,
    source: card.dataset.projectSource ?? projectLibrarySource,
  };
  card.classList.add("dragging");
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData("text/plain", projectLibraryDrag.projectId ?? "");
}

function handleProjectLibraryDragOver(event) {
  const lane = event.target instanceof Element ? event.target.closest("[data-production-drop-status]") : null;
  if (!lane || !projectLibraryDrag?.projectId) return;
  event.preventDefault();
  event.dataTransfer.dropEffect = "move";
  lane.classList.add("drag-over");
}

function handleProjectLibraryDragLeave(event) {
  const lane = event.target instanceof Element ? event.target.closest("[data-production-drop-status]") : null;
  if (!lane) return;
  if (event.relatedTarget instanceof Node && lane.contains(event.relatedTarget)) return;
  lane.classList.remove("drag-over");
}

function handleProjectLibraryDrop(event) {
  const lane = event.target instanceof Element ? event.target.closest("[data-production-drop-status]") : null;
  if (!lane || !projectLibraryDrag?.projectId) return;
  event.preventDefault();
  lane.classList.remove("drag-over");
  const nextStatus = lane.dataset.productionDropStatus;
  const project = projectLibraryProjects.find((item) => item.id === projectLibraryDrag.projectId);
  const currentStatus = normalizeProjectStatus(savedProjectState(project)?.projectStatus);
  if (normalizeProjectStatus(nextStatus) === "checked" && currentStatus !== "checked") {
    showAppNotice("Open the spool and use Approve drawing so the checker and comment are recorded.");
    return;
  }
  if (projectStatusAtLeast(currentStatus, "checked") && projectStatusIndex(nextStatus) < projectStatusIndex("checked")) {
    showAppNotice("Open the spool and use Return for changes so the review comment and revision are preserved.");
    return;
  }
  updateSavedProjectWorkflow(projectLibraryDrag.projectId, { status: nextStatus }).catch((error) => {
    console.warn("Production drag update failed.", error);
    showAppNotice(error?.message || "Could not move that spool.");
  });
}

function handleProjectLibraryDragEnd() {
  projectLibraryList?.querySelectorAll(".production-spool-card.dragging").forEach((card) => card.classList.remove("dragging"));
  projectLibraryList?.querySelectorAll(".production-lane.drag-over").forEach((lane) => lane.classList.remove("drag-over"));
  projectLibraryDrag = null;
}

function shouldSkipProjectLibraryActivation(key, debounceMs = 500) {
  const now = Date.now();
  if (projectLibraryLastActivation.key === key && now - projectLibraryLastActivation.at < debounceMs) {
    return true;
  }
  projectLibraryLastActivation = { key, at: now };
  return false;
}

function setupLoadPlanner() {
  loadPlanButton?.addEventListener("click", openLoadPlanDialog);
  loadPlanCloseButton?.addEventListener("click", closeLoadPlanDialog);
  loadPlanDoneButton?.addEventListener("click", closeLoadPlanDialog);
  loadPlanPlayButton?.addEventListener("click", playTruckLoadAnimation);
  loadPlanProjectList?.addEventListener("change", handleLoadPlanChoiceChange);
  loadPlanJobSelect?.addEventListener("change", () => {
    loadPlanJobKey = loadPlanJobSelect.value;
    loadPlanSelection.clear();
    currentLoadPlan = createTruckLoadPlan([]);
    renderLoadPlanProjectChoices();
  });
  loadPlanSelectAllButton?.addEventListener("click", () => setVisibleLoadPlanSelection(true));
  loadPlanDeselectAllButton?.addEventListener("click", () => setVisibleLoadPlanSelection(false));
  loadPlanLayoutButton?.addEventListener("click", () => setLoadPlanViewMode("layout"));
  loadPlanModelButton?.addEventListener("click", () => setLoadPlanViewMode("model"));
  loadPlanAnimateButton?.addEventListener("click", () => {
    if (currentLoadPlan?.placements?.length) {
      startTruckLoadAnimation(currentLoadPlan);
    }
  });
  loadPlanTraySelect?.addEventListener("change", () => {
    loadPlanTrayKey = normalizeLoadPlanTrayKey(loadPlanTraySelect.value);
    loadPlanTraySelect.value = loadPlanTrayKey;
    renderLoadPlanProjectChoices();
  });
  loadPlanRackSelect?.addEventListener("change", () => {
    loadPlanRackKey = normalizeLoadPlanRackKey(loadPlanRackSelect.value);
    loadPlanRackSelect.value = loadPlanRackKey;
    renderLoadPlanProjectChoices();
  });
  loadPlanSpinButton?.addEventListener("click", () => setLoadPlanSpin(!loadPlanThree.spinning));
  loadPlanResetButton?.addEventListener("click", () => resetLoadPlanThreeView());
  loadPlanDialog?.addEventListener("pointerdown", (event) => {
    if (event.target === loadPlanDialog) {
      closeLoadPlanDialog();
    }
  });
  loadPlanDialog?.addEventListener("click", (event) => {
    const button = event.target instanceof Element ? event.target.closest("button") : null;
    if (button?.id === "loadPlanSelectAllButton") setVisibleLoadPlanSelection(true);
    if (button?.id === "loadPlanDeselectAllButton") setVisibleLoadPlanSelection(false);
  });
}

function registerServiceWorker() {
  if (!("serviceWorker" in navigator)) return;
  if (location.protocol === "file:") return;

  window.addEventListener("load", () => {
    navigator.serviceWorker.register("./sw.js")
      .then((registration) => {
        setupServiceWorkerUpdateChecks(registration);
      })
      .catch((error) => {
        console.warn("Service worker registration failed.", error);
      });
  });
}

function setupServiceWorkerUpdateChecks(registration) {
  if (!registration) return;

  if (registration.waiting && navigator.serviceWorker.controller) {
    promptForAppUpdate(registration.waiting);
  }

  registration.addEventListener("updatefound", () => {
    const worker = registration.installing;
    if (!worker) return;
    worker.addEventListener("statechange", () => {
      if (worker.state === "installed" && navigator.serviceWorker.controller) {
        promptForAppUpdate(worker);
      }
    });
  });

  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (!appUpdateReloadPending) return;
    window.location.reload();
  });

  const checkForUpdate = () => {
    registration.update().catch((error) => {
      console.warn("Could not check for app updates.", error);
    });
  };

  setTimeout(checkForUpdate, 3000);
  setInterval(checkForUpdate, 15 * 60 * 1000);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") checkForUpdate();
  });
}

async function promptForAppUpdate(worker) {
  if (!worker || appUpdatePromptOpen || appUpdateReloadPending) return;

  appUpdatePromptOpen = true;
  const reloadNow = await confirmAppAction("A new SpoolMate update is ready. Reload now to use it?", {
    title: "Update ready",
    confirmLabel: "Reload",
    tone: "info",
  });
  appUpdatePromptOpen = false;
  if (!reloadNow) return;

  appUpdateReloadPending = true;
  worker.postMessage({ type: "SKIP_WAITING" });
  setTimeout(() => window.location.reload(), 1500);
}

function appVersionNumber(value) {
  const parts = String(value ?? "")
    .match(/\d+/g)
    ?.map((part) => Number(part))
    .filter((part) => Number.isFinite(part)) ?? [];
  const [major = 0, minor = 0, patch = 0] = parts;
  return major * 1_000_000 + minor * 1_000 + patch;
}

async function latestAvailableAppVersion() {
  if (location.protocol === "file:") return null;

  const response = await fetch(`./app.js?version-check=${Date.now()}`, {
    cache: "no-store",
  });
  if (!response.ok) return null;
  const source = await response.text();
  const match = source.match(/const\s+APP_VERSION\s*=\s*["']([^"']+)["']/);
  return match?.[1] ?? null;
}

async function checkForNewerAppVersion(options = {}) {
  try {
    const latest = await latestAvailableAppVersion();
    if (!latest || appVersionNumber(latest) <= appVersionNumber(APP_VERSION)) return false;

    const message = `SpoolMate ${latest} is available. You are using ${APP_VERSION}.`;
    if (options.autoReload) {
      showAppNotice(`${message} The app will reload before continuing.`);
      reloadToLatestApp(latest);
      return true;
    }

    updateCloudStatus(`Update ${latest} ready`, "warning");
    const reloadNow = await confirmAppAction(`${message} Reload now?`, {
      title: "Update available",
      confirmLabel: "Reload",
      tone: "info",
    });
    if (reloadNow) {
      reloadToLatestApp(latest);
    }
    return true;
  } catch (error) {
    console.warn("Could not check for latest app version.", error);
    return false;
  }
}

function reloadToLatestApp(latestVersion = "") {
  appUpdateReloadPending = true;
  const url = new URL(location.href);
  url.searchParams.set("v", String(appVersionNumber(latestVersion) || Date.now()));
  url.searchParams.set("reload", String(Date.now()));
  window.location.replace(url.toString());
}

function setupAppVersionChecks() {
  if (location.protocol === "file:") return;
  setTimeout(() => checkForNewerAppVersion(), 4500);
  setInterval(() => checkForNewerAppVersion(), VERSION_CHECK_INTERVAL_MS);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") checkForNewerAppVersion();
  });
}

async function reloadIfOutdatedBeforeAuth() {
  return checkForNewerAppVersion({ autoReload: true });
}

async function initThree() {
  renderStatus.textContent = "Canvas fallback active";
  renderFallbackPreview();

  try {
    const [THREE, controlsModule] = await Promise.all([
      import("three"),
      import("three/addons/controls/OrbitControls.js"),
    ]);
    setupThree(THREE, controlsModule.OrbitControls);
  } catch (error) {
    console.warn("Three.js failed to load; using fallback renderer.", error);
    renderStatus.textContent = "Canvas 3D preview";
    three.ready = false;
    syncPreviewCanvasVisibility();
    clear3dPipeLabels();
    renderFallbackPreview();
  }
}

function setupThree(THREE, OrbitControls) {
  three.module = THREE;
  three.OrbitControls = OrbitControls;
  three.scene = new THREE.Scene();
  three.scene.background = new THREE.Color(0xf8fbfb);

  three.camera = new THREE.OrthographicCamera(-8, 8, 6, -6, 0.1, 1000);
  three.camera.up.set(-0.5, -0.5, 1).normalize();

  three.renderer = new THREE.WebGLRenderer({
    canvas: threeCanvas,
    antialias: true,
    preserveDrawingBuffer: true,
    alpha: false,
  });
  three.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  three.renderer.shadowMap.enabled = true;
  if (THREE.PCFSoftShadowMap) three.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  three.renderer.outputColorSpace = THREE.SRGBColorSpace;
  three.renderer.toneMapping = THREE.ACESFilmicToneMapping;
  three.renderer.toneMappingExposure = 1.05;

  const ambient = new THREE.HemisphereLight(0xffffff, 0xaeb8b5, 2.15);
  three.scene.add(ambient);

  const keyLight = new THREE.DirectionalLight(0xffffff, 3.2);
  keyLight.position.set(9, -12, 13);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.set(1024, 1024);
  keyLight.shadow.camera.left = -18;
  keyLight.shadow.camera.right = 18;
  keyLight.shadow.camera.top = 18;
  keyLight.shadow.camera.bottom = -18;
  keyLight.shadow.bias = -0.0003;
  three.scene.add(keyLight);

  const fillLight = new THREE.DirectionalLight(0xe5efec, 1.15);
  fillLight.position.set(-8, 7, 8);
  three.scene.add(fillLight);

  const rimLight = new THREE.DirectionalLight(0xf7efe3, 0.9);
  rimLight.position.set(-5, 12, 6);
  three.scene.add(rimLight);

  const grid = new THREE.GridHelper(24, 24, 0x9aaaa5, 0xdce2df);
  grid.rotation.x = Math.PI / 2;
  grid.position.z = -0.02;
  three.previewGrid = grid;
  three.scene.add(grid);

  const shadowPlane = new THREE.Mesh(
    new THREE.PlaneGeometry(32, 32),
    new THREE.ShadowMaterial({ color: 0x4b5250, transparent: true, opacity: 0 }),
  );
  shadowPlane.position.z = -0.035;
  shadowPlane.receiveShadow = true;
  shadowPlane.visible = false;
  three.previewShadowPlane = shadowPlane;
  three.scene.add(shadowPlane);

  three.controls = new OrbitControls(three.camera, three.renderer.domElement);
  three.controls.enableDamping = true;
  three.controls.dampingFactor = 0.075;
  three.controls.screenSpacePanning = true;
  three.controls.enablePan = true;
  three.controls.enableZoom = true;
  three.controls.rotateSpeed = 0.58;
  three.controls.panSpeed = 0.92;
  three.controls.zoomSpeed = 0.86;
  three.controls.keyPanSpeed = 10;
  three.controls.minZoom = 0.28;
  three.controls.maxZoom = 10;
  if ("zoomToCursor" in three.controls) {
    three.controls.zoomToCursor = true;
  }
  three.controls.addEventListener("start", () => {
    three.userMovedCamera = true;
    setThreePreviewInteracting(true);
  });
  three.controls.addEventListener("end", () => {
    setThreePreviewInteracting(false);
  });
  threeCanvas?.addEventListener("contextmenu", (event) => event.preventDefault());
  applyThreeNavigationMode(three.navigationMode);

  three.ready = true;
  syncPreviewCanvasVisibility();
  renderStatus.textContent = "Drag rotate / middle pan / wheel zoom";
  resizeThree();
  update3dPreview();
  redrawLoadPlanIfOpen();
  animateThree();
}

function animateThree() {
  if (!three.ready) return;
  three.animationFrame = requestAnimationFrame(animateThree);
  syncPreviewCanvasVisibility();
  three.controls.update();
  three.renderer.render(three.scene, three.camera);
  update3dLabelPositions();
}

function setThreePreviewInteracting(active) {
  window.clearTimeout(three.interactionTimer);
  if (active) {
    three.interacting = true;
    three.labelFrameSkip = 0;
    previewStage?.classList.add("preview-interacting");
    return;
  }

  three.interactionTimer = window.setTimeout(() => {
    three.interacting = false;
    previewStage?.classList.remove("preview-interacting");
    update3dLabelPositions({ force: true });
  }, 220);
}

function setThreeNavigationMode(mode) {
  three.navigationMode = mode === "pan" ? "pan" : "orbit";
  applyThreeNavigationMode(three.navigationMode);
}

function applyThreeNavigationMode(mode = three.navigationMode) {
  if (previewStage) {
    previewStage.dataset.navMode = mode === "pan" ? "pan" : "orbit";
  }

  for (const [button, active] of [
    [previewRotateButton, mode !== "pan"],
    [previewMoveButton, mode === "pan"],
  ]) {
    if (!button) continue;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  }

  if (!three.controls || !three.module) return;
  const THREE = three.module;
  three.controls.mouseButtons = mode === "pan"
    ? {
        LEFT: THREE.MOUSE.PAN,
        MIDDLE: THREE.MOUSE.PAN,
        RIGHT: THREE.MOUSE.ROTATE,
      }
    : {
        LEFT: THREE.MOUSE.ROTATE,
        MIDDLE: THREE.MOUSE.PAN,
        RIGHT: THREE.MOUSE.PAN,
      };
  three.controls.touches = mode === "pan"
    ? {
        ONE: THREE.TOUCH.PAN,
        TWO: THREE.TOUCH.DOLLY_PAN,
      }
    : {
        ONE: THREE.TOUCH.ROTATE,
        TWO: THREE.TOUCH.DOLLY_PAN,
      };
}

function resetThreeView() {
  if (!three.ready) return;
  three.userMovedCamera = false;
  frameThreeCamera({ reset: true });
}

function resizeThree() {
  if (!three.ready) return;

  const rect = previewStage.getBoundingClientRect();
  const width = Math.max(1, Math.floor(rect.width));
  const height = Math.max(1, Math.floor(rect.height));
  three.renderer.setSize(width, height, false);
  frameThreeCamera();
  update3dLabelPositions();
}

function updateThreeSceneStyle(style) {
  if (!three.ready || !three.module) return;
  const THREE = three.module;
  three.scene.background = new THREE.Color(style.background ?? 0xf8fbfb);

  const gridMaterials = three.previewGrid
    ? (Array.isArray(three.previewGrid.material) ? three.previewGrid.material : [three.previewGrid.material])
    : [];
  const gridColors = style.gridColors ?? [0x9aaaa5, 0xdce2df];
  const gridOpacity = style.gridOpacity ?? 1;
  if (three.previewGrid) {
    three.previewGrid.visible = gridOpacity > 0.02;
  }
  for (const [index, material] of gridMaterials.entries()) {
    if (!material) continue;
    material.color?.setHex(gridColors[Math.min(index, gridColors.length - 1)]);
    material.transparent = gridOpacity < 1;
    material.opacity = gridOpacity;
    material.needsUpdate = true;
  }

  if (three.previewShadowPlane?.material) {
    const shadowOpacity = clampNumber(Number(style.contactShadowOpacity) || 0, 0, 0.28);
    three.previewShadowPlane.visible = shadowOpacity > 0.001;
    three.previewShadowPlane.material.opacity = shadowOpacity;
    three.previewShadowPlane.material.color?.setHex(style.contactShadowColor ?? 0x4b5250);
    three.previewShadowPlane.material.needsUpdate = true;
  }
}

function update3dPreview() {
  syncPreviewCanvasVisibility();
  if (!three.ready) {
    clear3dPipeLabels();
    renderFallbackPreview();
    return;
  }

  rebuildThreeSpool();
  frameThreeCamera();
}

function endpointRenderBasePoint(start, end, renderedSegment, side, clearanceMetres = 0) {
  const axis = end.clone().sub(start);
  if (axis.length() < 0.0001) return side === "start" ? start.clone() : end.clone();
  axis.normalize();

  const endpoint = side === "start" ? start : end;
  const renderedEndpoint = side === "start"
    ? (renderedSegment?.start ?? start)
    : (renderedSegment?.end ?? end);
  const existingOffset = side === "start"
    ? renderedEndpoint.clone().sub(start).dot(axis)
    : end.clone().sub(renderedEndpoint).dot(axis);
  const offset = Math.max(existingOffset, Number(clearanceMetres) || 0);
  return side === "start"
    ? start.clone().addScaledVector(axis, offset)
    : end.clone().addScaledVector(axis, -offset);
}

function setupNetworkAwareness() {
  window.addEventListener("offline", () => {
    if (cloudSaveDirty && state.projectId) queueCurrentCloudSave("offline");
    else updateCloudStatus("Offline / local projects available", "warning");
    showAppNotice("You are offline. Drawing changes stay on this device and cloud changes are queued until the connection returns.", { tone: "warning" });
  });
  window.addEventListener("online", () => {
    updateCloudStatus();
    const queued = currentCloudSaveQueueEntry();
    if (queued) {
      showAppNotice("Connection restored. Retrying the queued cloud save.", { tone: "success" });
      retryQueuedCloudSave({ automatic: true });
    } else {
      showAppNotice("Connection restored. Cloud changes can sync again.", { tone: "success" });
    }
  });
  cloudSyncStatus?.addEventListener("click", () => {
    if (currentCloudSaveQueueEntry() || cloudSaveError) {
      retryQueuedCloudSave();
      return;
    }
    showAppNotice(cloudLastSavedAt
      ? `Last saved to cloud at ${formatCloudSaveTime(cloudLastSavedAt, { full: true })}.`
      : cloudSyncStatus.title || "This drawing is currently stored on this device.");
  });
  if (!navigator.onLine) updateCloudStatus("Offline / local projects available", "warning");
}

function nodeFittingClearanceMetres(nodeIndex, segment, connections, segmentByIndex, segmentData, style) {
  const connected = connections.get(nodeIndex) ?? [];
  if (connected.length < 3) return 0;

  if (nodeConnectionType(nodeIndex) === "branch") {
    const info = branchNodeInfo(nodeIndex, connected, segmentData);
    const branchSegmentIndexes = new Set((info?.branchEntries ?? []).map((entry) => entry.segment.index));
    if (!branchSegmentIndexes.has(segment.index)) return 0;
    const radius = pipeRadiusMetres(segment);
    return style?.lineDrawing
      ? Math.max(radius * 3.1, 0.095)
      : Math.max(radius * 2.25, 0.055);
  }

  const radii = connected
    .map((connection) => segmentByIndex.get(connection.segmentIndex))
    .filter(Boolean)
    .map((connectedSegment) => pipeRadiusMetres(connectedSegment));
  const coreRadius = Math.max(radiusForNode(nodeIndex, connections, segmentByIndex), ...radii);
  return teeNodeLegLengthMetres(coreRadius, style);
}

function teeNodeLegLengthMetres(coreRadius, style = null) {
  return style?.lineDrawing
    ? Math.max(coreRadius * 3.8, 0.2)
    : Math.max(coreRadius * 3.15, 0.18);
}

function segmentEndpointClearancesMetres(segment, connections, segmentByIndex, segmentData, style) {
  return {
    start: nodeFittingClearanceMetres(segment.from, segment, connections, segmentByIndex, segmentData, style),
    end: nodeFittingClearanceMetres(segment.to, segment, connections, segmentByIndex, segmentData, style),
  };
}

function fittingRenderPosition(fitting, start, end, renderedSegment, pipeRadius, endpointClearances = null) {
  const axis = end.clone().sub(start);
  if (axis.length() < 0.0001) return start.clone();
  const segmentLengthMm = axis.length() * 1000;
  const t = endpointSnappedFittingTForLength(fitting, segmentLengthMm);
  axis.normalize();

  if (fitting.type === "threadedEnd") {
    if (t <= 0.000001) return start.clone();
    if (t >= 0.999999) return end.clone();
  }

  if (renderedSegment) {
    const startBase = endpointRenderBasePoint(start, end, renderedSegment, "start", endpointClearances?.start);
    const endBase = endpointRenderBasePoint(start, end, renderedSegment, "end", endpointClearances?.end);

    if (fitting.type === "flange") {
      if (t <= 0.000001) return startBase;
      if (t >= 0.999999) return endBase;
    }

    if (fitting.type === "rollGroove") {
      const renderedLength = renderedSegment.start.distanceTo(renderedSegment.end);
      const inset = Math.min(ROLL_GROOVE_SETBACK_MM / 1000, Math.max(0, renderedLength * 0.45));
      if (t <= 0.000001) return startBase.addScaledVector(axis, inset);
      if (t >= 0.999999) return endBase.addScaledVector(axis, -inset);
    }

    if (t <= 0.000001) return startBase;
    if (t >= 0.999999) return endBase;
  }

  if (fitting.type === "flange") {
    if (t <= 0.000001) return start.clone();
    if (t >= 0.999999) return end.clone();
  }

  return start.clone().lerp(end, t);
}

function fittingEndpointSide(fitting, segmentLengthMm = null) {
  const t = Number.isFinite(segmentLengthMm)
    ? endpointSnappedFittingTForLength(fitting, segmentLengthMm)
    : normalizeFittingPosition(fitting?.type, fitting?.t);
  if (t <= 0.000001) return "start";
  if (t >= 0.999999) return "end";
  return null;
}

function flangeNominalBore(pipeSizeOrNb) {
  if (pipeSizeOrNb && typeof pipeSizeOrNb === "object") {
    const nominalBore = Number(pipeSizeOrNb.nb);
    if (pipeSizeOrNb.kind !== "tube") return Number.isFinite(nominalBore) ? nominalBore : 15;

    const tubeOd = Number(pipeSizeOrNb.od);
    const enclosingPipe = PIPE_SIZES
      .filter((size) => size.kind !== "tube" && Number.isFinite(size.od))
      .sort((left, right) => left.od - right.od)
      .find((size) => size.od >= tubeOd - 0.01);
    return enclosingPipe?.nb ?? 300;
  }

  const nominalBore = Number(pipeSizeOrNb);
  return Number.isFinite(nominalBore) ? nominalBore : 15;
}

function flangeDrillingDimensions(flangeStandard, pipeSizeOrNb, pipeRadius) {
  const standard = normalizeFlangeStandard(flangeStandard);
  const tableKey = standard === "din10" ? "pn10" : standard === "din16" ? "pn16" : standard;
  const table = FLANGE_DRILLING_TABLES[tableKey];
  const requestedNb = flangeNominalBore(pipeSizeOrNb);
  const selectedPipeSize = pipeSizeOrNb && typeof pipeSizeOrNb === "object"
    ? pipeSizeOrNb
    : PIPE_SIZES.find((size) => size.kind !== "tube" && size.nb === requestedNb);
  const physicalPipeRadius = Number(selectedPipeSize?.od) / 2000;
  const visualScale = Number.isFinite(physicalPipeRadius) && physicalPipeRadius > 0 && Number.isFinite(pipeRadius)
    ? pipeRadius / physicalPipeRadius
    : 1;

  if (Array.isArray(table) && table.length) {
    const row = table.find((entry) => entry[0] === requestedNb)
      ?? table.find((entry) => entry[0] >= requestedNb)
      ?? table[table.length - 1];
    const [sourceNb, odMm, thicknessMm, pcdMm, holeMm, holes] = row;
    return {
      requestedNb,
      sourceNb,
      exactSize: sourceNb === requestedNb,
      odMm,
      thicknessMm,
      pcdMm,
      holeMm,
      visualScale,
      outerRadius: (odMm / 2000) * visualScale,
      plateThickness: (thicknessMm / 1000) * visualScale,
      boltCircleRadius: (pcdMm / 2000) * visualScale,
      boltHoleRadius: (holeMm / 2000) * visualScale,
      boltCount: holes,
    };
  }

  const standardInfo = flangeStandardInfo(flangeStandard);
  const radiusFactor = standardInfo.radiusFactor || 1;
  const thicknessFactor = standardInfo.thicknessFactor || 1;
  return {
    requestedNb,
    sourceNb: requestedNb,
    exactSize: false,
    odMm: (pipeRadius * 2.15 * radiusFactor * 2000) / visualScale,
    thicknessMm: (clampNumber(pipeRadius * 0.42 * thicknessFactor, 0.006, 0.0665) * 1000) / visualScale,
    pcdMm: (pipeRadius * 1.58 * radiusFactor * 2000) / visualScale,
    holeMm: (clampNumber(pipeRadius * 0.15 * Math.sqrt(radiusFactor), 0.007, 0.018) * 2000) / visualScale,
    visualScale,
    outerRadius: pipeRadius * 2.15 * radiusFactor,
    plateThickness: clampNumber(pipeRadius * 0.42 * thicknessFactor, 0.006, 0.0665),
    boltCircleRadius: pipeRadius * 1.58 * radiusFactor,
    boltHoleRadius: clampNumber(pipeRadius * 0.15 * Math.sqrt(radiusFactor), 0.007, 0.018),
    boltCount: boltCountForNb(requestedNb),
  };
}

function flangeGasketThickness(drilling) {
  const scale = Number.isFinite(drilling?.visualScale) ? drilling.visualScale : 1;
  return clampNumber(drilling.plateThickness * 0.14, 0.0015 * scale, 0.003 * scale);
}

function formatFlangeTableMm(value) {
  const rounded = Math.round(Number(value) * 10) / 10;
  if (!Number.isFinite(rounded)) return "0";
  return Number.isInteger(rounded) ? rounded.toFixed(0) : rounded.toFixed(1);
}

function flangeRenderTransform(fitting, position, direction, pipeRadius, pipeSizeOrNb = null, segmentLengthMm = null) {
  const endpointSide = fittingEndpointSide(fitting, segmentLengthMm);
  if (!endpointSide) {
    return {
      position,
      direction,
      endMount: false,
    };
  }

  const outward = endpointSide === "start"
    ? direction.clone().multiplyScalar(-1)
    : direction.clone();
  const drilling = flangeDrillingDimensions(fittingFlangeStandard(fitting), pipeSizeOrNb, pipeRadius);
  const plateThickness = drilling.plateThickness;
  const isSingle = fittingFlangeMode(fitting) === "single";
  const gasketThickness = flangeGasketThickness(drilling);
  const mountOffset = isSingle ? plateThickness * 0.5 : plateThickness + gasketThickness * 0.5;
  return {
    position: position.clone().addScaledVector(outward, mountOffset),
    direction: outward,
    endMount: true,
  };
}

function rebuildThreeSpool() {
  const THREE = three.module;
  const style = previewViewStyle();
  updateThreeSceneStyle(style);
  clear3dPipeLabels();
  if (three.spoolGroup) {
    three.scene.remove(three.spoolGroup);
    disposeObject3d(three.spoolGroup);
  }

  const group = new THREE.Group();
  const pipeMaterial = previewMaterial(style, "pipe");
  const jointMaterial = previewMaterial(style, "joint");
  const flangeMaterial = previewMaterial(style, "flange");
  const boltMaterial = previewMaterial(style, "bolt");
  const gasketMaterial = previewMaterial(style, "gasket");
  const valveMaterial = previewMaterial(style, "valve");
  const weldMaterial = previewMaterial(style, "weld");
  const reducerMaterial = previewMaterial(style, "reducer");
  const socketMaterial = previewMaterial(style, "socket");
  const grooveMaterial = previewMaterial(style, "groove");
  const illustratedSeamMaterial = style.illustrated
    ? new THREE.LineBasicMaterial({
        color: style.weldSeamColor ?? 0x343938,
        transparent: true,
        opacity: 0.88,
        depthTest: true,
      })
    : null;

  const modelPoints = state.points.map((point) => {
    const modelPoint = toModelUnits(point);
    return new THREE.Vector3(modelPoint.x, modelPoint.y, modelPoint.z);
  });
  const segmentData = segments();
  updatePreviewSizeColourLegend(segmentData);
  const connections = nodeConnections(segmentData);
  const elbowTrims = computeGraphElbowTrims(modelPoints, segmentData, connections);
  const autoReducers = autoReducerTransitions(segmentData);
  const reducerTrims = computeAutoReducerRenderTrims(autoReducers, style);
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));
  const renderedSegments = new Map();
  const threadedEndSides = new Set(
    state.fittings
      .filter((fitting) => fitting.type === "threadedEnd")
      .map((fitting) => {
        const segment = segmentByIndex.get(fitting.segmentIndex);
        const side = segment ? fittingEndpointSide(fitting, pointLength(segment.vector)) : null;
        return side ? `${fitting.segmentIndex}:${side}` : null;
      })
      .filter(Boolean),
  );
  const triColorSizeKeys = [...new Set(segmentData.map(triColorSegmentSizeKey))].sort((a, b) => a - b);
  const triColorMaterials = new Map();
  const pipeMaterialForSegment = (segment) => {
    if (!style.triColor) return pipeMaterial;
    const sizeKey = triColorSegmentSizeKey(segment);
    if (triColorMaterials.has(sizeKey)) return triColorMaterials.get(sizeKey);

    const palette = style.triColorPalette ?? [0x3c9698, 0xd19438, 0x7864a8];
    const sizeIndex = Math.max(0, triColorSizeKeys.indexOf(sizeKey));
    const color = palette[sizeIndex % palette.length];
    const material = previewMaterial({
      ...style,
      colors: {
        ...style.colors,
        pipe: color,
      },
    }, "pipe");
    triColorMaterials.set(sizeKey, material);
    return material;
  };

  for (const segment of segmentData) {
    const segmentPipeMaterial = pipeMaterialForSegment(segment);
    const segmentRadius = pipeRadiusMetres(segment);
    const start = modelPoints[segment.from].clone();
    const end = modelPoints[segment.to].clone();
    const direction = end.clone().sub(start).normalize();
    const startTrim = elbowTrims.segment.get(`${segment.index}:${segment.from}`) ?? 0;
    const endTrim = elbowTrims.segment.get(`${segment.index}:${segment.to}`) ?? 0;
    const startReducerTrim = reducerTrims.get(`${segment.index}:${segment.from}`) ?? 0;
    const endReducerTrim = reducerTrims.get(`${segment.index}:${segment.to}`) ?? 0;
    const nodeClearances = segmentEndpointClearancesMetres(segment, connections, segmentByIndex, segmentData, style);
    start.addScaledVector(direction, startTrim + Math.max(startReducerTrim, nodeClearances.start));
    end.addScaledVector(direction, -(endTrim + Math.max(endReducerTrim, nodeClearances.end)));
    const threadLength = threadedPipeEndLength(segmentRadius);
    if (threadedEndSides.has(`${segment.index}:start`)) {
      start.addScaledVector(direction, threadLength);
    }
    if (threadedEndSides.has(`${segment.index}:end`)) {
      end.addScaledVector(direction, -threadLength);
    }
    renderedSegments.set(segment.index, { start: start.clone(), end: end.clone() });

    if (start.distanceTo(end) < segmentRadius * 0.5) {
      continue;
    }

    const renderFragments = [{ t0: 0, t1: 1, pieceIndex: null }];
    const originalStart = modelPoints[segment.from];
    const originalEnd = modelPoints[segment.to];
    for (const fragment of renderFragments) {
      const fragmentStart = fragment.t0 === 0
        ? start.clone()
        : originalStart.clone().lerp(originalEnd, fragment.t0);
      const fragmentEnd = fragment.t1 === 1
        ? end.clone()
        : originalStart.clone().lerp(originalEnd, fragment.t1);
      if (fragmentStart.distanceTo(fragmentEnd) < segmentRadius * 0.25) continue;
      if (style.lineDrawing) {
        group.add(outlinePipeBetween(fragmentStart, fragmentEnd, segmentRadius, segmentPipeMaterial, {
          startCap: fragment.t0 > 0 || (connections.get(segment.from)?.length ?? 0) <= 1,
          endCap: fragment.t1 < 1 || (connections.get(segment.to)?.length ?? 0) <= 1,
        }));
      } else {
        const pipe = cylinderBetween(fragmentStart, fragmentEnd, segmentRadius, segmentPipeMaterial, 32);
        pipe.castShadow = true;
        pipe.receiveShadow = true;
        group.add(pipe);
      }
    }
  }

  for (const elbowData of elbowTrims.elbows) {
    const elbowSegment = segmentData.reduce((closest, segment) => {
      if (!closest) return segment;
      const candidateDifference = Math.abs(pipeRadiusMetres(segment) - elbowData.radius);
      const closestDifference = Math.abs(pipeRadiusMetres(closest) - elbowData.radius);
      return candidateDifference < closestDifference ? segment : closest;
    }, null);
    const elbowPipeMaterial = elbowSegment ? pipeMaterialForSegment(elbowSegment) : pipeMaterial;
    const elbow = style.lineDrawing
      ? outlineElbowBetween(
        elbowData.entry,
        elbowData.joint,
        elbowData.exit,
        elbowData.radius,
        elbowPipeMaterial,
      )
      : curvedElbowBetween(
        elbowData.entry,
        elbowData.joint,
        elbowData.exit,
        elbowData.radius,
        elbowPipeMaterial,
        32,
      );
    if (!style.lineDrawing) {
      elbow.castShadow = true;
      elbow.receiveShadow = true;
    }
    group.add(elbow);

    if (illustratedSeamMaterial) {
      const entryAxis = elbowData.joint.clone().sub(elbowData.entry);
      const exitAxis = elbowData.exit.clone().sub(elbowData.joint);
      if (entryAxis.length() > 0.0001) {
        const seam = outlineRing(
          elbowData.entry,
          entryAxis,
          elbowData.radius * 1.012,
          illustratedSeamMaterial,
        );
        seam.renderOrder = 4;
        seam.userData.illustratedWeldSeam = true;
        group.add(seam);
      }
      if (exitAxis.length() > 0.0001) {
        const seam = outlineRing(
          elbowData.exit,
          exitAxis,
          elbowData.radius * 1.012,
          illustratedSeamMaterial,
        );
        seam.renderOrder = 4;
        seam.userData.illustratedWeldSeam = true;
        group.add(seam);
      }
    }
  }

  for (const [index, point] of modelPoints.entries()) {
    if (elbowTrims.smoothNodes.has(index)) {
      continue;
    }

    const connected = connections.get(index) ?? [];
    const nodeRadius = radiusForNode(index, connections, segmentByIndex);
    if (connected.length >= 3) {
      const connectionType = nodeConnectionType(index);
      const nodeObject = connectionType === "branch"
        ? (style.lineDrawing
          ? outlineBranchMarker(index, point, connected, modelPoints, segmentData, jointMaterial)
          : branchNodeAssembly(index, point, connected, modelPoints, segmentData, jointMaterial))
        : (style.lineDrawing
          ? outlineTeeMarker(point, connected, modelPoints, nodeRadius, jointMaterial, segmentData)
          : teeNodeAssembly(point, connected, modelPoints, nodeRadius, jointMaterial, segmentData));
      group.add(nodeObject);
      continue;
    }

    if (style.lineDrawing) {
      continue;
    }

    if (connected.length <= 2) {
      continue;
    }

    const jointGeometry = new THREE.SphereGeometry(nodeRadius * 1.14, 24, 16);
    const joint = new THREE.Mesh(jointGeometry, jointMaterial);
    joint.position.copy(point);
    joint.castShadow = true;
    group.add(joint);
  }

  for (const fitting of state.fittings) {
    const segment = segmentByIndex.get(fitting.segmentIndex);
    if (!segment) continue;
    const segmentPipeMaterial = pipeMaterialForSegment(segment);
    const startModel = toModelUnits(segment.start);
    const endModel = toModelUnits(segment.end);
    const start = new THREE.Vector3(startModel.x, startModel.y, startModel.z);
    const end = new THREE.Vector3(endModel.x, endModel.y, endModel.z);
    const direction = end.clone().sub(start).normalize();
    const radius = pipeRadiusMetres(segment);
    const endpointClearances = segmentEndpointClearancesMetres(segment, connections, segmentByIndex, segmentData, style);
    const position = fittingRenderPosition(fitting, start, end, renderedSegments.get(segment.index), radius, endpointClearances);

    if (fitting.type === "flange") {
      const flangePipeSize = pipeSizeForSegment(segment);
      const flangeTransform = flangeRenderTransform(fitting, position, direction, radius, flangePipeSize, start.distanceTo(end) * 1000);
      if (style.lineDrawing) {
        group.add(outlineFlangeMarker(
          flangeTransform.position,
          flangeTransform.direction,
          radius,
          flangePipeSize,
          fittingFlangeMode(fitting),
          fittingFlangeStandard(fitting),
          flangeMaterial,
        ));
      } else {
        group.add(
          flangeAssembly(flangeTransform.position, flangeTransform.direction, radius, flangePipeSize, fittingFlangeMode(fitting), fittingFlangeStandard(fitting), {
            flange: flangeMaterial,
            bolt: boltMaterial,
            gasket: gasketMaterial,
            endMount: flangeTransform.endMount,
          }),
        );
      }
    } else if (fitting.type === "weld") {
      const weld = style.lineDrawing
        ? outlineBandMarker(position, direction, radius * 1.35, weldMaterial, 0.12)
        : cylinderBetween(
          position.clone().addScaledVector(direction, -0.035),
          position.clone().addScaledVector(direction, 0.035),
          radius * 1.25,
          weldMaterial,
          32,
        );
      group.add(weld);
    } else if (fitting.type === "valve") {
      if (style.lineDrawing) {
        group.add(outlineButterflyValveMarker(position, direction, radius, pipeSizeForSegment(segment).nb, valveMaterial));
      } else {
        group.add(butterflyValveAssembly(position, direction, radius, pipeSizeForSegment(segment).nb, valveMaterial, boltMaterial, style));
      }
    } else if (fitting.type === "reducer") {
      if (style.lineDrawing) {
        group.add(outlineReducerMarker(position, direction, radius, reducerMaterial));
      } else {
        const reducer = taperedCylinderBetween(
          position.clone().addScaledVector(direction, -0.18),
          position.clone().addScaledVector(direction, 0.18),
          radius,
          radius * 0.72,
          reducerMaterial,
          32,
        );
        reducer.castShadow = true;
        group.add(reducer);
      }
    } else if (fitting.type === "socket") {
      group.add(socketAssembly(position, direction, radius, fitting, socketMaterial, style));
    } else if (fitting.type === "rollGroove") {
      group.add(rollGrooveAssembly(position, direction, radius, grooveMaterial, style));
    } else if (fitting.type === "threadedEnd") {
      const endpointSide = fittingEndpointSide(fitting, start.distanceTo(end) * 1000);
      const outward = endpointSide === "start"
        ? direction.clone().multiplyScalar(-1)
        : direction.clone();
      group.add(threadedPipeEndAssembly(position, outward, radius, segmentPipeMaterial, grooveMaterial, style));
    }
  }

  for (const reducer of autoReducers) {
    group.add(autoReducerAssembly(reducer, modelPoints, reducerMaterial, style, elbowTrims));
  }

  const liftPoint = centreOfGravityData(quantitySummary(segmentData));
  if (state.showLiftingPoints && liftPoint) {
    const modelPoint = toModelUnits(liftPoint.point);
    group.add(liftPointMarker3d(new THREE.Vector3(modelPoint.x, modelPoint.y, modelPoint.z), style));
  }
  const lugPlan = suggestedLugPlan(quantitySummary(segmentData), liftPoint);
  if (state.showLiftingPoints && lugPlan) {
    for (const lug of lugPlan.points) {
      const modelPoint = toModelUnits(lug.point);
      group.add(lugPointMarker3d(new THREE.Vector3(modelPoint.x, modelPoint.y, modelPoint.z), style));
    }
  }

  addIllustratedModelOutlines(group, style);
  three.spoolGroup = group;
  three.scene.add(group);
  build3dPipeLabels(segmentData, modelPoints);
}

