function deleteContextMeasurement() {
  if (!ensureDrawingEditable("delete measurement")) return;
  const measurement = drawingContextTarget?.measurementHit?.measurement;
  if (!measurement) return;

  const snapshot = createUndoSnapshot();
  state.measurements = (state.measurements ?? []).filter((item) => item.id !== measurement.id);
  state.selectedMeasurement = null;
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function deleteContextPoint() {
  if (!ensureDrawingEditable("delete point")) return;
  const pointHit = drawingContextTarget?.pointHit;
  if (!pointHit || state.points.length <= 1) return;

  const connected = segments().filter((segment) => segment.from === pointHit.index || segment.to === pointHit.index);
  if (connected.length) return;

  const snapshot = createUndoSnapshot();
  state.points.splice(pointHit.index, 1);
  reindexNodeTypesAfterPointRemoval(pointHit.index);
  reindexReducerSideOverridesAfterPointRemoval(pointHit.index);
  reindexReducerTypeOverridesAfterPointRemoval(pointHit.index);
  state.selectedPoint = null;
  state.activePoint = Math.max(0, Math.min(state.activePoint, state.points.length - 1));
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function setContextPointConnectionType(type) {
  if (!ensureDrawingEditable("change connection type")) return;
  const pointHit = drawingContextTarget?.pointHit;
  if (!pointHit) return;
  const connected = segments().filter((segment) => segment.from === pointHit.index || segment.to === pointHit.index);
  if (connected.length < 3) return;
  if (nodeConnectionType(pointHit.index) === type) return;

  const snapshot = createUndoSnapshot();
  state.selectedPoint = pointHit.index;
  state.activePoint = pointHit.index;
  clearSelectedSegments();
  state.selectedFitting = null;
  state.selectedNote = null;
  setNodeConnectionType(pointHit.index, type, { update: false });
  recordHistory({ type: "snapshot", snapshot });
  updateAll();
}

function editContextSegmentLength() {
  if (!ensureDrawingEditable("edit length")) return;
  const hit = drawingContextTarget?.segmentHit;
  if (!hit) return;

  editSegmentLengthFromDimensionSource(hit.segment, {
    anchorPointIndex: hit.t < 0.5 ? hit.segment.from : hit.segment.to,
    sourceType: "context",
  });
}

async function editSegmentLengthFromDimensionSource(segment, options = {}) {
  if (!ensureDrawingEditable("edit length")) return false;
  if (!segment) return false;

  const offsetMeta = segmentOffsetMeta(segment);
  const editSet = options.sourceType === "offset-set";
  const currentLength = Math.round(pointLength(segment.vector));
  const promptLabel = offsetMeta && editSet
    ? "Offset set C/C mm"
    : offsetMeta
    ? "Offset travel C/C mm"
    : "Pipe C/C length mm";
  const currentValue = offsetMeta && editSet ? offsetMeta.setMm : currentLength;
  const text = await openFieldInputDialog({
    title: "Edit pipe length",
    label: promptLabel,
    value: String(Math.round(currentValue)),
    unit: "mm",
    type: "number",
    inputMode: "numeric",
    min: "1",
    help: offsetMeta
      ? "For offsets, use set C/C for the offset height or travel C/C for the angled run."
      : "This changes the centre-to-centre length while keeping the pipe direction locked.",
    submitLabel: "Apply length",
  });
  if (text === null) return false;

  selectSingleSegment(segment.index);
  state.selectedPoint = Number.isInteger(options.anchorPointIndex) ? options.anchorPointIndex : segment.from;
  state.activePoint = state.selectedPoint;
  state.selectedFitting = null;
  state.selectedNote = null;
  state.selectedMeasurement = null;
  if (offsetMeta && editSet) {
    const setMm = normalizeLength(text);
    const travelMm = offsetTravelLengthMm(setMm, offsetMeta.angleDeg);
    setSelectedSegmentLength(travelMm, {
      edgeMeta: {
        offsetSetMm: setMm,
        offsetTravelMm: travelMm,
        offsetAngleDeg: offsetMeta.angleDeg,
        offsetPlane: offsetMeta.plane,
        offsetDirection: offsetMeta.direction,
      },
    });
  } else {
    setSelectedSegmentLength(text);
  }
  markFirstUseGuideLearned("length");
  if (options.sourceType === "context") {
    showMobilePanel("drawing");
    showAppNotice(`Pipe length set to ${formatLength(pointLength(segments()[segment.index]?.vector ?? segment.vector))} mm.`);
  } else {
    revealInspectorForSelection();
  }
  return true;
}

async function editContextSegmentAngle() {
  if (!ensureDrawingEditable("edit bend angle")) return;
  const hit = drawingContextTarget?.segmentHit;
  if (!hit) return;

  const anchorIndex = bendEditAnchorForHit(hit);
  if (anchorIndex === null) return;

  const currentBend = bendAngleForSegmentAt(hit.segment, anchorIndex) ?? 90;
  const text = await openFieldInputDialog({
    title: "Edit bend angle",
    label: "Bend angle",
    value: formatAngle(currentBend),
    unit: "deg",
    type: "number",
    inputMode: "decimal",
    min: "1",
    help: "Change the bend angle while keeping the selected pipe connected.",
    submitLabel: "Apply angle",
  });
  if (text === null) return;

  editSegmentBendAngle(hit.segment, anchorIndex, text);
}

function contextPipeSizeDetail(segment) {
  const count = contextPipeSizeTargetIndexes(segment).length;
  const size = pipeSizeForSegment(segment);
  return count > 1 ? `${count} selected sections` : `Current ${pipeSizeDisplayLabel(size)}`;
}

function contextPipeSizeTargetIndexes(segment) {
  if (!segment) return [];
  const selected = selectedSegmentIndexes();
  const requested = selected.includes(segment.index) && selected.length > 1 ? selected : [segment.index];
  return branchMainLinkedSegmentIndexes(requested);
}

function changeContextPipeSize() {
  if (!ensureDrawingEditable("change pipe size")) return;
  const hit = drawingContextTarget?.segmentHit;
  if (!hit) return;
  renderContextPipeSizeMenu();
}

function addContextNote(point) {
  if (!ensureDrawingEditable("add note")) return;
  if (!point) return;
  promptNoteDetails({ text: noteTextInput.value, colour: noteColorInput?.value, mode: "add" })
    .then((details) => {
      if (!details) return;
      placeNote(point, details);
    });
}

function editContextNote(note) {
  if (!ensureDrawingEditable("edit note")) return;
  promptNoteDetails({ text: note.text, colour: note.colour, mode: "edit" })
    .then((details) => {
      if (!details) return;
      const nextText = details.text.slice(0, 80);
      const nextColour = normalizeNoteColour(details.colour);
      if (nextText === note.text && nextColour === normalizeNoteColour(note.colour)) return;
      const snapshot = createUndoSnapshot();
      note.text = nextText;
      note.colour = nextColour;
      noteTextInput.value = note.text;
      if (noteColorInput) noteColorInput.value = note.colour;
      state.selectedNote = note.id;
      state.selectedFitting = null;
      clearSelectedSegments();
      recordHistory({ type: "snapshot", snapshot });
      updateAll();
    });
}

function appNoticeTone(message, requested = "") {
  const tone = String(requested || "").trim().toLowerCase();
  if (["success", "warning", "danger", "error", "info"].includes(tone)) return tone === "danger" ? "error" : tone;
  const text = String(message ?? "").toLowerCase();
  if (/(failed|could not|invalid|required|not found|blocked|error|view\/comment only|read-only|must be|does not|cannot)/.test(text)) return "error";
  if (/(delete|replace|restore|overwrite|reload|warning|newer|issue|hold)/.test(text)) return "warning";
  if (/(saved|copied|imported|created|sent|opened|selected|joined|approved|ready)/.test(text)) return "success";
  return "info";
}

function appNoticeTitleForTone(tone) {
  if (tone === "success") return "Done";
  if (tone === "warning") return "Check this";
  if (tone === "error") return "Could not complete";
  return "SpoolMate";
}

function showAppNotice(message, options = {}) {
  const text = String(message ?? "").trim();
  if (!text) return null;
  const tone = appNoticeTone(text, options.tone);
  if (!appToastStack) {
    console.info(`[${tone}] ${text}`);
    return null;
  }

  const toast = document.createElement("article");
  toast.className = `app-toast ${tone}`;
  toast.setAttribute("role", tone === "error" ? "alert" : "status");

  const copy = document.createElement("div");
  const title = document.createElement("strong");
  title.textContent = options.title || appNoticeTitleForTone(tone);
  const body = document.createElement("span");
  body.textContent = text;
  copy.append(title, body);

  const closeButton = document.createElement("button");
  closeButton.type = "button";
  closeButton.setAttribute("aria-label", "Dismiss message");
  closeButton.textContent = "Close";
  closeButton.addEventListener("click", () => dismissAppToast(toast));

  toast.append(copy, closeButton);
  appToastStack.append(toast);
  while (appToastStack.children.length > 4) {
    appToastStack.firstElementChild?.remove();
  }

  const timeout = Number(options.timeoutMs) || (tone === "error" ? 7200 : tone === "warning" ? 6400 : 4200);
  window.setTimeout(() => dismissAppToast(toast), timeout);
  return toast;
}

function dismissAppToast(toast) {
  if (!toast || !toast.isConnected) return;
  toast.classList.add("leaving");
  window.setTimeout(() => toast.remove(), 180);
}

function confirmTitleForTone(tone) {
  if (tone === "error") return "Confirm action";
  if (tone === "warning") return "Check before continuing";
  return "Confirm action";
}

function confirmIconForTone(tone) {
  if (tone === "error") return "!";
  if (tone === "warning") return "!";
  return "?";
}

function confirmAppAction(message, options = {}) {
  const text = String(message ?? "").trim();
  if (!text) return Promise.resolve(false);
  if (!appConfirmDialog || !appConfirmOkButton || !appConfirmCancelButton) {
    showAppNotice(text, { tone: options.tone || "warning" });
    return Promise.resolve(false);
  }

  if (appConfirmDialogResolver) {
    closeAppConfirmDialog(false);
  }

  const tone = appNoticeTone(text, options.tone || "warning");
  closeActionMenu();
  closeDrawingContextMenu();
  closeHelpDialog();
  appConfirmDialog.dataset.tone = tone;
  if (appConfirmTitle) appConfirmTitle.textContent = options.title || confirmTitleForTone(tone);
  if (appConfirmMessage) appConfirmMessage.textContent = text;
  if (appConfirmIcon) appConfirmIcon.textContent = options.icon || confirmIconForTone(tone);
  appConfirmCancelButton.textContent = options.cancelLabel || "Cancel";
  appConfirmOkButton.textContent = options.confirmLabel || "Continue";
  appConfirmDialog.hidden = false;
  window.setTimeout(() => {
    const focusTarget = tone === "error" || tone === "warning" ? appConfirmCancelButton : appConfirmOkButton;
    focusTarget?.focus();
  }, 30);

  return new Promise((resolve) => {
    appConfirmDialogResolver = resolve;
  });
}

function closeAppConfirmDialog(result = false) {
  if (appConfirmDialog) appConfirmDialog.hidden = true;
  const resolver = appConfirmDialogResolver;
  appConfirmDialogResolver = null;
  resolver?.(result);
}

function setupAppConfirmDialog() {
  appConfirmCancelButton?.addEventListener("click", () => closeAppConfirmDialog(false));
  appConfirmOkButton?.addEventListener("click", () => closeAppConfirmDialog(true));
  appConfirmDialog?.addEventListener("pointerdown", (event) => {
    if (event.target === appConfirmDialog) closeAppConfirmDialog(false);
  });
}

function openFieldInputDialog(options = {}) {
  if (
    !fieldInputDialog ||
    !fieldInputForm ||
    !fieldInputValue ||
    !fieldInputTextArea ||
    !fieldInputSubmitButton
  ) {
    return Promise.resolve(null);
  }

  if (fieldInputDialogResolver) {
    closeFieldInputDialog(null);
  }

  const multiline = options.multiline === true;
  closeActionMenu();
  closeDrawingContextMenu();
  closeHelpDialog();
  if (fieldInputTitle) fieldInputTitle.textContent = options.title ?? "Edit value";
  if (fieldInputHelp) {
    fieldInputHelp.textContent = options.help ?? "Enter the value to apply to the drawing.";
    fieldInputHelp.hidden = !fieldInputHelp.textContent;
  }
  if (fieldInputLabel) fieldInputLabel.textContent = options.label ?? "Value";
  fieldInputSubmitButton.textContent = options.submitLabel ?? "Apply";

  fieldInputForm.classList.toggle("field-input-multiline", multiline);
  fieldInputValue.hidden = multiline;
  fieldInputTextArea.hidden = !multiline;

  const unit = String(options.unit ?? "").trim();
  fieldInputForm.classList.toggle("has-unit", Boolean(unit) && !multiline);
  if (fieldInputUnit) {
    fieldInputUnit.textContent = unit;
    fieldInputUnit.hidden = !unit || multiline;
  }

  const value = String(options.value ?? "");
  const activeControl = multiline ? fieldInputTextArea : fieldInputValue;
  fieldInputValue.value = multiline ? "" : value;
  fieldInputTextArea.value = multiline ? value : "";
  fieldInputValue.type = options.type === "number" ? "number" : "text";
  fieldInputValue.inputMode = options.inputMode ?? (options.type === "number" ? "decimal" : "text");
  fieldInputValue.placeholder = options.placeholder ?? "";
  fieldInputValue.step = options.step ?? "any";
  fieldInputValue.min = options.min ?? "";
  fieldInputTextArea.placeholder = options.placeholder ?? "";
  fieldInputTextArea.readOnly = options.readOnly === true;

  fieldInputDialog.hidden = false;
  window.setTimeout(() => {
    activeControl.focus();
    if (options.select !== false) activeControl.select?.();
  }, 30);

  return new Promise((resolve) => {
    fieldInputDialogResolver = resolve;
  });
}

function closeFieldInputDialog(result = null) {
  if (fieldInputDialog) fieldInputDialog.hidden = true;
  if (fieldInputTextArea) fieldInputTextArea.readOnly = false;
  const resolver = fieldInputDialogResolver;
  fieldInputDialogResolver = null;
  resolver?.(result);
}

function submitFieldInputDialog() {
  const multiline = fieldInputForm?.classList.contains("field-input-multiline");
  const value = multiline ? fieldInputTextArea?.value ?? "" : fieldInputValue?.value ?? "";
  closeFieldInputDialog(value);
}

function setupFieldInputDialog() {
  fieldInputCancelButton?.addEventListener("click", () => closeFieldInputDialog(null));
  fieldInputForm?.addEventListener("submit", (event) => {
    event.preventDefault();
    submitFieldInputDialog();
  });
  fieldInputDialog?.addEventListener("pointerdown", (event) => {
    if (event.target === fieldInputDialog) closeFieldInputDialog(null);
  });
  fieldInputTextArea?.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && (event.ctrlKey || event.metaKey)) {
      event.preventDefault();
      submitFieldInputDialog();
    }
  });
}

function promptNoteDetails(options = {}) {
  const defaultText = String(options.text ?? "FIELD NOTE").slice(0, 80);
  const defaultColour = normalizeNoteColour(options.colour ?? noteColorInput?.value);
  if (!noteDialog || !noteDialogText || !noteDialogSaveButton) {
    return openFieldInputDialog({
      title: options.mode === "edit" ? "Edit text note" : "Add text note",
      label: "Note text",
      value: defaultText || "FIELD NOTE",
      submitLabel: options.mode === "edit" ? "Save note" : "Add note",
    }).then((text) => {
      if (text === null) return null;
      return { text: text.replace(/\s+/g, " ").trim() || "NOTE", colour: defaultColour };
    });
  }
  closeActionMenu();
  closeDrawingContextMenu();
  closeHelpDialog();
  noteDialog.hidden = false;
  noteDialogColour = defaultColour;
  if (noteDialogTitle) noteDialogTitle.textContent = options.mode === "edit" ? "Edit text note" : "Add text note";
  noteDialogText.value = defaultText || "FIELD NOTE";
  noteDialogSaveButton.textContent = options.mode === "edit" ? "Save note" : "Add note";
  updateNoteDialogColourButtons();
  window.setTimeout(() => {
    noteDialogText.focus();
    noteDialogText.select();
  }, 30);
  return new Promise((resolve) => {
    noteDialogResolver = resolve;
  });
}

function updateNoteDialogColourButtons() {
  for (const button of noteDialogColourButtons) {
    const active = button.dataset.noteColour === noteDialogColour;
    button.classList.toggle("active", active);
    button.setAttribute("aria-checked", String(active));
    button.setAttribute("role", "radio");
  }
}

function closeNoteDialog(result = null) {
  if (noteDialog) noteDialog.hidden = true;
  const resolver = noteDialogResolver;
  noteDialogResolver = null;
  resolver?.(result);
}

function submitNoteDialog() {
  if (!noteDialogText) return closeNoteDialog(null);
  const text = noteDialogText.value.replace(/\s+/g, " ").trim() || "NOTE";
  closeNoteDialog({ text: text.slice(0, 80), colour: normalizeNoteColour(noteDialogColour) });
}

function setupNoteDialog() {
  noteDialogCancelButton?.addEventListener("click", () => closeNoteDialog(null));
  noteDialogSaveButton?.addEventListener("click", submitNoteDialog);
  noteDialog?.addEventListener("pointerdown", (event) => {
    if (event.target === noteDialog) closeNoteDialog(null);
  });
  noteDialogText?.addEventListener("keydown", (event) => {
    if ((event.ctrlKey || event.metaKey) && event.key === "Enter") {
      event.preventDefault();
      submitNoteDialog();
    }
  });
  for (const button of noteDialogColourButtons) {
    button.addEventListener("click", () => {
      noteDialogColour = normalizeNoteColour(button.dataset.noteColour);
      updateNoteDialogColourButtons();
    });
  }
}

function beginDimensionDrag(event, target, pointer) {
  if (!target || !Number.isInteger(target.segmentIndex)) return false;

  const currentOffset = dimensionOffsetForSegment(target.segmentIndex);
  dimensionDrag = {
    pointerId: event.pointerId,
    segmentIndex: target.segmentIndex,
    snapshot: createUndoSnapshot(),
    startPointer: { ...pointer },
    normal: { ...target.normal },
    side: Number(target.side) < 0 ? -1 : 1,
    startOffset: currentOffset.offset > 0.5
      ? currentOffset.offset
      : Math.max(0, (Number(target.offset) || 0) - (Number(target.baseOffset) || 0)),
    moved: false,
  };
  state.selectedNote = null;
  state.selectedFitting = null;
  state.selectedMeasurement = null;
  clearSelectedSegments();
  state.selectedPoint = null;
  cursorReadout.textContent = "Dragging dimension";
  cancelTouchContextPress();
  try {
    drawCanvas.setPointerCapture(event.pointerId);
  } catch {
    // Pointer capture is a nice-to-have for dragging outside the canvas.
  }
  event.preventDefault();
  return true;
}

function updateDimensionDrag(event) {
  if (!dimensionDrag || dimensionDrag.pointerId !== event.pointerId) return false;

  const pointer = pointerPosition(event);
  const delta = {
    x: pointer.x - dimensionDrag.startPointer.x,
    y: pointer.y - dimensionDrag.startPointer.y,
  };
  const pull = delta.x * dimensionDrag.normal.x + delta.y * dimensionDrag.normal.y;
  const offset = clampNumber(dimensionDrag.startOffset + pull, 0, 520);
  setDimensionOffsetForSegment(dimensionDrag.segmentIndex, {
    side: dimensionDrag.side,
    offset,
  });
  dimensionDrag.moved = true;
  state.pointer = pointer;
  cursorReadout.textContent = offset > 1
    ? `Dimension offset ${Math.round(offset)} px`
    : "Dimension offset reset";
  drawIso();
  event.preventDefault();
  return true;
}

function finishDimensionDrag(event) {
  if (!dimensionDrag) return false;

  try {
    drawCanvas.releasePointerCapture(dimensionDrag.pointerId);
  } catch {
    // Ignore browsers that have already released capture.
  }
  const moved = dimensionDrag.moved;
  const snapshot = dimensionDrag.snapshot;
  dimensionDrag = null;
  state.pointer = null;
  cursorReadout.textContent = formatPoint(activePoint());
  if (moved) {
    recordHistory({ type: "snapshot", snapshot });
    updateAll();
  } else {
    drawIso();
  }
  event?.preventDefault?.();
  return true;
}

function cancelDimensionDrag(options = {}) {
  if (!dimensionDrag) return;
  try {
    drawCanvas.releasePointerCapture(dimensionDrag.pointerId);
  } catch {
    // Ignore browsers that have already released capture.
  }
  dimensionDrag = null;
  if (options.redraw !== false) drawIso();
}

function beginNoteDrag(event, noteHit, pointer) {
  const note = noteHit?.note;
  if (!note) return false;

  const label = projectIso(noteLabelPoint(note));
  noteDrag = {
    pointerId: event.pointerId,
    note,
    snapshot: createUndoSnapshot(),
    z: Number(noteLabelPoint(note).z) || 0,
    offset: {
      x: pointer.x - label.x,
      y: pointer.y - label.y,
    },
    moved: false,
  };
  state.selectedNote = note.id;
  state.selectedFitting = null;
  state.selectedMeasurement = null;
  state.selectedPoint = null;
  clearSelectedSegments();
  cursorReadout.textContent = "Dragging note";
  try {
    drawCanvas.setPointerCapture(event.pointerId);
  } catch {
    // Pointer capture is a nice-to-have for dragging outside the canvas.
  }
  drawIso();
  updatePropertiesPanel();
  event.preventDefault();
  return true;
}

function updateNoteDrag(event) {
  if (!noteDrag) return false;

  const pointer = pointerPosition(event);
  const anchorPointer = {
    x: pointer.x - noteDrag.offset.x,
    y: pointer.y - noteDrag.offset.y,
  };
  noteDrag.note.labelPoint = unprojectIsoAtZ(anchorPointer, noteDrag.z, false);
  noteDrag.moved = true;
  state.pointer = pointer;
  cursorReadout.textContent = "Dragging note text";
  drawIso();
  updatePropertiesPanel();
  event.preventDefault();
  return true;
}

function finishNoteDrag(event) {
  if (!noteDrag) return false;

  try {
    drawCanvas.releasePointerCapture(noteDrag.pointerId);
  } catch {
    // Ignore browsers that have already released capture.
  }
  const moved = noteDrag.moved;
  const snapshot = noteDrag.snapshot;
  noteDrag = null;
  state.pointer = null;
  cursorReadout.textContent = formatPoint(activePoint());
  if (moved) {
    recordHistory({ type: "snapshot", snapshot });
    updateAll();
  } else {
    updateAll({ save: false });
  }
  event?.preventDefault?.();
  return true;
}

function beginSocketDrag(event, fittingHit, pointer) {
  const fitting = fittingHit?.fitting;
  const segment = fittingHit?.segmentHit?.segment ?? segments().find((item) => item.index === fitting?.segmentIndex);
  if (!fitting || fitting.type !== "socket" || !segment) return false;

  socketDrag = {
    pointerId: event.pointerId,
    fittingId: fitting.id,
    segmentIndex: segment.index,
    snapshot: createUndoSnapshot(),
    moved: false,
  };
  state.selectedFitting = fitting.id;
  state.selectedNote = null;
  state.selectedMeasurement = null;
  state.selectedPoint = null;
  selectSingleSegment(segment.index);
  cursorReadout.textContent = socketPositionReadout(segment, fitting.t);
  cancelTouchContextPress();
  try {
    drawCanvas.setPointerCapture(event.pointerId);
  } catch {
    // Pointer capture is a nice-to-have for dragging outside the canvas.
  }
  drawIso();
  updatePropertiesPanel();
  event.preventDefault();
  return true;
}

function updateSocketDrag(event) {
  if (!socketDrag) return false;

  const fitting = state.fittings.find((item) => item.id === socketDrag.fittingId);
  const segment = segments().find((item) => item.index === socketDrag.segmentIndex);
  if (!fitting || fitting.type !== "socket" || !segment) {
    socketDrag = null;
    return false;
  }

  const pointer = pointerPosition(event);
  const projection = getProjection();
  const start = projectIso(segment.start, projection);
  const end = projectIso(segment.end, projection);
  const hit = distanceToSegment(pointer, start, end);
  fitting.t = normalizeFittingPosition("socket", hit.t);
  socketDrag.moved = true;
  state.pointer = pointer;
  state.selectedFitting = fitting.id;
  cursorReadout.textContent = socketPositionReadout(segment, fitting.t);
  drawIso();
  updatePropertiesPanel();
  event.preventDefault();
  return true;
}

function finishSocketDrag(event) {
  if (!socketDrag) return false;

  try {
    drawCanvas.releasePointerCapture(socketDrag.pointerId);
  } catch {
    // Ignore browsers that have already released capture.
  }
  const moved = socketDrag.moved;
  const snapshot = socketDrag.snapshot;
  socketDrag = null;
  state.pointer = null;
  cursorReadout.textContent = formatPoint(activePoint());
  if (moved) {
    recordHistory({ type: "snapshot", snapshot });
    updateAll();
  } else {
    updateAll({ save: false });
  }
  event?.preventDefault?.();
  return true;
}

function beginBoxSelect(event, pointer) {
  boxSelectDrag = {
    pointerId: event.pointerId,
    start: { ...pointer },
    current: { ...pointer },
    addMode: event.shiftKey || event.ctrlKey || event.metaKey,
    moved: false,
  };
  state.pointer = pointer;
  state.hoveredSegment = null;
  cursorReadout.textContent = "Drag box around pipe runs";
  try {
    drawCanvas.setPointerCapture(event.pointerId);
  } catch {
    // Pointer capture is a nice-to-have for dragging outside the canvas.
  }
  drawIso();
  event.preventDefault();
  return true;
}

function updateBoxSelect(event) {
  if (!boxSelectDrag) return false;

  const pointer = pointerPosition(event);
  boxSelectDrag.current = pointer;
  boxSelectDrag.moved =
    Math.hypot(pointer.x - boxSelectDrag.start.x, pointer.y - boxSelectDrag.start.y) > 6;
  state.pointer = pointer;

  const indexes = segmentsInBoxSelect(boxSelectRect(boxSelectDrag));
  state.hoveredSegment = indexes.length ? indexes[indexes.length - 1] : null;
  cursorReadout.textContent = indexes.length
    ? `${indexes.length} run${indexes.length === 1 ? "" : "s"} inside box`
    : "Drag box around pipe runs";
  drawIso();
  event.preventDefault();
  return true;
}

function finishBoxSelect(event) {
  if (!boxSelectDrag) return false;

  const drag = boxSelectDrag;
  if (event) {
    drag.current = pointerPosition(event);
  }
  const rect = boxSelectRect(drag);
  const chosen = boxSelectSelectionFromDrag(drag, rect);

  try {
    drawCanvas.releasePointerCapture(drag.pointerId);
  } catch {
    // Ignore browsers that have already released capture.
  }

  boxSelectDrag = null;
  setSelectedSegments(chosen);
  state.selectedFitting = null;
  state.selectedNote = null;
  state.selectedMeasurement = null;
  const selectedSegments = segments().filter((segment) => chosen.includes(segment.index));
  if (selectedSegments.length) {
    const last = selectedSegments[selectedSegments.length - 1];
    state.activePoint = last.to;
    state.selectedPoint = selectedSegments.length === 1 ? last.to : null;
    revealInspectorForSelection();
  } else {
    state.selectedPoint = null;
  }
  state.pointer = null;
  state.hoveredSegment = null;
  cursorReadout.textContent = chosen.length
    ? `${chosen.length} run${chosen.length === 1 ? "" : "s"} selected`
    : "No runs selected";
  updateAll({ save: false });
  event?.preventDefault?.();
  return true;
}

function cancelBoxSelect(options = {}) {
  if (!boxSelectDrag) return;
  try {
    drawCanvas.releasePointerCapture(boxSelectDrag.pointerId);
  } catch {
    // Ignore browsers that have already released capture.
  }
  boxSelectDrag = null;
  state.pointer = null;
  state.hoveredSegment = null;
  if (options.redraw !== false) {
    drawIso();
  }
}

function boxSelectSelectionFromDrag(drag, rect) {
  const current = selectedSegmentIndexes();
  const useBox = drag.moved || rect.width > 8 || rect.height > 8;
  if (useBox) {
    const boxed = segmentsInBoxSelect(rect);
    return drag.addMode ? normalizeSelectedSegments([...current, ...boxed], state.edges.length) : boxed;
  }

  const hit = findNearestSegment(drag.current);
  if (!hit) return drag.addMode ? current : [];
  if (!drag.addMode) return [hit.segment.index];

  const selected = new Set(current);
  if (selected.has(hit.segment.index)) {
    selected.delete(hit.segment.index);
  } else {
    selected.add(hit.segment.index);
  }
  return normalizeSelectedSegments([...selected], state.edges.length);
}

function boxSelectRect(drag) {
  const left = Math.min(drag.start.x, drag.current.x);
  const top = Math.min(drag.start.y, drag.current.y);
  const right = Math.max(drag.start.x, drag.current.x);
  const bottom = Math.max(drag.start.y, drag.current.y);
  return {
    left,
    top,
    right,
    bottom,
    width: right - left,
    height: bottom - top,
  };
}

function padScreenRect(rect, amount) {
  return {
    left: rect.left - amount,
    top: rect.top - amount,
    right: rect.right + amount,
    bottom: rect.bottom + amount,
    width: rect.width + amount * 2,
    height: rect.height + amount * 2,
  };
}

function segmentsInBoxSelect(rect) {
  if (!rect) return [];
  const pickRect = padScreenRect(rect, 6);
  const projection = getProjection();
  return segments()
    .filter((segment) =>
      screenSegmentIntersectsRect(
        projectIso(segment.start, projection),
        projectIso(segment.end, projection),
        pickRect,
      ),
    )
    .map((segment) => segment.index);
}

function screenSegmentIntersectsRect(start, end, rect) {
  const segmentMinX = Math.min(start.x, end.x);
  const segmentMaxX = Math.max(start.x, end.x);
  const segmentMinY = Math.min(start.y, end.y);
  const segmentMaxY = Math.max(start.y, end.y);
  if (segmentMaxX < rect.left || segmentMinX > rect.right || segmentMaxY < rect.top || segmentMinY > rect.bottom) {
    return false;
  }

  if (screenPointInRect(start, rect) || screenPointInRect(end, rect)) return true;

  const topLeft = { x: rect.left, y: rect.top };
  const topRight = { x: rect.right, y: rect.top };
  const bottomRight = { x: rect.right, y: rect.bottom };
  const bottomLeft = { x: rect.left, y: rect.bottom };
  return (
    screenSegmentsIntersect(start, end, topLeft, topRight) ||
    screenSegmentsIntersect(start, end, topRight, bottomRight) ||
    screenSegmentsIntersect(start, end, bottomRight, bottomLeft) ||
    screenSegmentsIntersect(start, end, bottomLeft, topLeft)
  );
}

function screenPointInRect(point, rect) {
  return point.x >= rect.left && point.x <= rect.right && point.y >= rect.top && point.y <= rect.bottom;
}

function screenSegmentsIntersect(firstStart, firstEnd, secondStart, secondEnd) {
  const o1 = screenOrientation(firstStart, firstEnd, secondStart);
  const o2 = screenOrientation(firstStart, firstEnd, secondEnd);
  const o3 = screenOrientation(secondStart, secondEnd, firstStart);
  const o4 = screenOrientation(secondStart, secondEnd, firstEnd);

  if (o1 !== o2 && o3 !== o4) return true;
  if (o1 === 0 && screenPointOnSegment(secondStart, firstStart, firstEnd)) return true;
  if (o2 === 0 && screenPointOnSegment(secondEnd, firstStart, firstEnd)) return true;
  if (o3 === 0 && screenPointOnSegment(firstStart, secondStart, secondEnd)) return true;
  if (o4 === 0 && screenPointOnSegment(firstEnd, secondStart, secondEnd)) return true;
  return false;
}

function screenOrientation(a, b, c) {
  const value = (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y);
  if (Math.abs(value) < 0.001) return 0;
  return value > 0 ? 1 : 2;
}

function screenPointOnSegment(point, start, end) {
  return (
    point.x <= Math.max(start.x, end.x) + 0.001 &&
    point.x >= Math.min(start.x, end.x) - 0.001 &&
    point.y <= Math.max(start.y, end.y) + 0.001 &&
    point.y >= Math.min(start.y, end.y) - 0.001
  );
}

function drawBoxSelectOverlay(ctx) {
  if (!boxSelectDrag) return;

  const rect = boxSelectRect(boxSelectDrag);
  ctx.save();
  ctx.fillStyle = "rgba(13, 148, 136, 0.10)";
  ctx.strokeStyle = "#0f766e";
  ctx.lineWidth = 2;
  ctx.setLineDash([8, 6]);
  ctx.fillRect(rect.left, rect.top, rect.width, rect.height);
  ctx.strokeRect(rect.left + 0.5, rect.top + 0.5, rect.width, rect.height);
  ctx.setLineDash([]);

  const count = segmentsInBoxSelect(rect).length;
  if (count) {
    const label = `${count} run${count === 1 ? "" : "s"}`;
    ctx.font = "900 13px Inter, system-ui, sans-serif";
    const metrics = ctx.measureText(label);
    const width = metrics.width + 14;
    const canvasRect = drawCanvas.getBoundingClientRect();
    const x = clampNumber(rect.left, 8, Math.max(8, canvasRect.width - width - 8));
    const y = rect.top > 32 ? rect.top - 28 : rect.bottom + 8;
    ctx.fillStyle = "rgba(255, 255, 255, 0.92)";
    ctx.strokeStyle = "rgba(15, 118, 110, 0.35)";
    ctx.lineWidth = 1;
    roundRect(ctx, x, y, width, 22, 6);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#0f766e";
    ctx.fillText(label, x + 7, y + 15);
  }
  ctx.restore();
}

function socketPositionReadout(segment, t) {
  const lengthMm = pointLength(segment.vector);
  const position = normalizeFittingPosition("socket", t);
  const fromDistance = lengthMm * position;
  const toDistance = lengthMm - fromDistance;
  const useFrom = fromDistance <= toDistance;
  const referenceIndex = useFrom ? segment.from : segment.to;
  const distanceMm = useFrom ? fromDistance : toDistance;
  const label = socketReferenceLabel(referenceIndex, segment, segments()).toLowerCase();
  return `Socket ${formatLength(distanceMm)} mm from ${label}`;
}

drawCanvas.addEventListener("contextmenu", openDrawingContextMenu);

drawCanvas.addEventListener("pointermove", (event) => {
  updateTrackedTouchPointer(event);
  if (updatePinchGesture()) {
    event.preventDefault();
    return;
  }
  if (updateDrawingPan(event)) return;
  if (updateBoxSelect(event)) return;
  if (updateNoteDrag(event)) return;
  if (updateSocketDrag(event)) return;
  if (updateDimensionDrag(event)) return;
  if (updateTouchContextPress(event)) {
    event.preventDefault();
    return;
  }
  if (updatePendingDraw(event)) return;

  const pointer = pointerPosition(event);
  state.pointer = pointer;

  if (state.activeTool === "draw") {
    drawCanvas.style.cursor = "crosshair";
    state.previewCandidate = getSnappedCandidate(pointer, { shiftAngle: shouldUseShiftAngleSnap(event) });
    if (state.previewCandidate) {
      cursorReadout.textContent = state.previewCandidate.axis?.shiftAngle
        ? `${state.previewCandidate.axis.label} / ${formatPoint(state.previewCandidate.point)}`
        : formatPoint(state.previewCandidate.point);
    }
  } else {
    const noteHit = findNearestNote(pointer);
    const dimensionHit = state.activeTool === "select" ? findNearestDimensionTarget(pointer) : null;
    const measurementHit = state.activeTool === "select" ? findNearestMeasurement(pointer) : null;
    const pointHit = findNearestPoint(pointer);
    const hit = findNearestSegment(pointer);
    drawCanvas.style.cursor = dimensionHit
      ? dimensionHit.type === "dimension-key"
        ? "pointer"
        : "grab"
      : noteHit || measurementHit || pointHit || hit
      ? "pointer"
      : "";
    state.hoveredSegment = hit ? hit.segment.index : null;
    cursorReadout.textContent = noteHit
      ? "Text note"
      : dimensionHit
      ? dimensionHit.type === "dimension-key"
        ? "Dimension key - click to edit C/C"
        : "Drag dimension"
      : measurementHit
      ? "Measurement - Delete to remove"
      : pointHit
      ? `Point ${pointHit.index + 1} / tee start`
      : state.activeTool === "measure" && measurementDraft
      ? "Pick second measurement point"
      : state.activeTool === "measure"
      ? "Pick first measurement point"
      : state.activeTool === "note"
      ? "Click to place note"
      : state.activeTool === "boxSelect" && hit
      ? `Box select / run ${hit.segment.index + 1}`
      : state.activeTool === "boxSelect"
      ? "Box select"
      : (state.activeTool === "tee" || state.activeTool === "branch") && hit
      ? `${state.activeTool === "branch" ? "Branch" : "Tee"} on run ${hit.segment.index + 1}`
      : state.activeTool === "select" && hit
      ? `Run ${hit.segment.index + 1} - hold Shift for multi-select`
      : hit
      ? `Run ${hit.segment.index + 1} / ${Math.round(hit.t * 100)}%`
      : "No run";
  }

  drawIso();
});

drawCanvas.addEventListener("pointerleave", () => {
  if (noteDrag || socketDrag || dimensionDrag || pendingDraw || boxSelectDrag) return;
  cancelTouchContextPress();
  state.pointer = null;
  state.previewCandidate = null;
  state.hoveredSegment = null;
  drawCanvas.style.cursor = "";
  cursorReadout.textContent = formatPoint(activePoint());
  drawIso();
});

drawCanvas.addEventListener("pointerdown", (event) => {
  if (event.button !== 0) return;
  closeDrawingContextMenu();
  const pointer = pointerPosition(event);
  trackTouchPointer(event);
  if (pinchGesture) {
    event.preventDefault();
    return;
  }
  if (beginDrawingPan(event, pointer)) {
    event.preventDefault();
    return;
  }
  const activeEditTool = state.activeTool === "measure" ||
    state.activeTool === "note" ||
    state.activeTool === "tee" ||
    state.activeTool === "branch" ||
    FITTING_TOOLS.has(state.activeTool);
  if (activeEditTool && drawingEditLocked()) {
    ensureDrawingEditable("change it");
    event.preventDefault();
    return;
  }
  if (state.activeTool === "boxSelect") {
    beginBoxSelect(event, pointer);
    return;
  }
  const touchPressBlocksDraw = startTouchContextPress(event, pointer);
  if (touchPressBlocksDraw) {
    event.preventDefault();
    return;
  }
  if (state.activeTool === "draw") {
    startPendingDraw(event, pointer);
    return;
  }

  if (state.activeTool === "measure") {
    beginOrFinishMeasurement(pointer);
    event.preventDefault();
    return;
  }

  if (state.activeTool === "note") {
    const point = unprojectIsoGround(pointer);
    promptNoteDetails({ text: noteTextInput.value, colour: noteColorInput?.value, mode: "add" })
      .then((details) => {
        if (details) placeNote(point, details);
      });
    event.preventDefault();
    return;
  }

  if (state.activeTool === "tee" || state.activeTool === "branch") {
    const hit = findNearestSegment(pointer);
    if (!hit || hit.t <= 0.02 || hit.t >= 0.98) return;
    const splitIndex = splitSegmentAt(hit.segment.index, hit.t);
    if (splitIndex !== null) {
      setNodeConnectionType(splitIndex, state.activeTool === "branch" ? "branch" : "tee", { update: false });
    }
    setTool("draw");
    updateAll();
    return;
  }

  const noteHit = findNearestNote(pointer);
  if (noteHit && state.activeTool === "select") {
    if (drawingEditLocked()) {
      state.selectedNote = noteHit.note.id;
      state.selectedFitting = null;
      state.selectedMeasurement = null;
      clearSelectedSegments();
      updateAll({ save: false });
      revealInspectorForSelection();
      return;
    }
    cancelTouchContextPress();
    beginNoteDrag(event, noteHit, pointer);
    return;
  }

  const fittingHit = findNearestFitting(pointer);
  if (fittingHit?.fitting?.type === "socket" && state.activeTool === "select") {
    if (drawingEditLocked()) {
      state.selectedFitting = fittingHit.fitting.id;
      state.selectedNote = null;
      state.selectedMeasurement = null;
      clearSelectedSegments();
      updateAll({ save: false });
      revealInspectorForSelection();
      return;
    }
    beginSocketDrag(event, fittingHit, pointer);
    return;
  }

  const dimensionHit = findNearestDimensionTarget(pointer);
  if (dimensionHit && state.activeTool === "select") {
    if (drawingEditLocked()) {
      ensureDrawingEditable("edit dimensions");
      event.preventDefault();
      return;
    }
    if (dimensionHit.type === "dimension-key") {
      const segment = segments().find((item) => item.index === dimensionHit.segmentIndex);
      editSegmentLengthFromDimensionSource(segment, {
        sourceType: dimensionHit.sourceType,
        anchorPointIndex: segment?.from,
      });
      event.preventDefault();
      return;
    }
    beginDimensionDrag(event, dimensionHit, pointer);
    return;
  }

  const measurementHit = findNearestMeasurement(pointer);
  if (measurementHit && state.activeTool === "select") {
    state.selectedMeasurement = measurementHit.measurement.id;
    state.selectedNote = null;
    state.selectedFitting = null;
    state.selectedPoint = null;
    clearSelectedSegments();
    updateAll({ save: false });
    revealInspectorForSelection();
    return;
  }

  const pointHit = findNearestPoint(pointer);
  if (pointHit && state.activeTool === "select") {
    state.selectedPoint = pointHit.index;
    state.activePoint = pointHit.index;
    clearSelectedSegments();
    state.selectedFitting = null;
    state.selectedNote = null;
    state.selectedMeasurement = null;
    updateAll({ save: false });
    revealInspectorForSelection();
    return;
  }

  const hit = findNearestSegment(pointer);
  if (!hit) return;

  chooseSegmentFromPointer(event, hit.segment.index);
  state.selectedNote = null;
  state.selectedMeasurement = null;
  state.selectedPoint = hit.t < 0.5 ? hit.segment.from : hit.segment.to;
  state.activePoint = state.selectedPoint;
  const fittingAtHit = state.fittings.find((fitting) => {
    if (fitting.segmentIndex !== hit.segment.index) return false;
    return Math.abs(fitting.t - hit.t) < 0.06;
  });

  if (state.activeTool === "select") {
    state.selectedFitting = event.shiftKey || event.ctrlKey || event.metaKey ? null : fittingAtHit ? fittingAtHit.id : null;
    updateAll({ save: false });
    revealInspectorForSelection();
    return;
  }

  if (FITTING_TOOLS.has(state.activeTool)) {
    placeFitting(state.activeTool, hit.segment.index, snapEndpointFittingPlacementT(state.activeTool, hit, pointer));
  }
});

drawCanvas.addEventListener("pointerup", (event) => {
  if (finishPinchGestureForPointer(event)) return;
  if (finishDrawingPan(event)) {
    releaseTrackedTouchPointer(event);
    return;
  }
  if (finishBoxSelect(event)) {
    releaseTrackedTouchPointer(event);
    return;
  }
  if (finishTouchContextPress(event)) {
    releaseTrackedTouchPointer(event);
    return;
  }
  if (finishPendingDraw(event)) {
    releaseTrackedTouchPointer(event);
    return;
  }
  if (finishNoteDrag(event)) {
    releaseTrackedTouchPointer(event);
    return;
  }
  if (finishSocketDrag(event)) {
    releaseTrackedTouchPointer(event);
    return;
  }
  finishDimensionDrag(event);
  releaseTrackedTouchPointer(event);
});
drawCanvas.addEventListener("pointercancel", (event) => {
  releaseTrackedTouchPointer(event);
  finishDrawingPan(event);
  cancelTouchContextPress();
  cancelPendingDraw();
  cancelBoxSelect();
  if (pinchGesture && !pinchGesture.ids.every((id) => activeTouchPointers.has(id))) {
    pinchGesture = null;
  }
  finishNoteDrag(event);
  finishSocketDrag(event);
  finishDimensionDrag(event);
});

